"""Tests for Hunger Heroes donation graph walkers."""

import io;
import from contextlib { redirect_stdout }

test "BFS recommendation visits same donor only once via visited set" {
    rt = root;
    rt ++> Donor(name="Bob", home_zip="10001");
    rt ++> Donor(name="Bob", home_zip="10001");

    b = Donor(name="Bob", home_zip="10001");
    b ++> Donation(title="Sourdough Bread", category="bakery",
                   zip_code="10001", days_to_expiry=2);
    b ++> Donation(title="Brown Rice 5kg", category="grains",
                   zip_code="10001", days_to_expiry=10);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = rt spawn BFSRecommendation();
    }
    out = buf.getvalue();

    n_bread = out.count("Sourdough Bread");
    n_rice = out.count("Brown Rice 5kg");
    assert n_bread == 1, f"expected bread recommended once, got {n_bread}: {out}";
    assert n_rice == 1, f"expected rice recommended once, got {n_rice}: {out}";
    assert len(res.visited) == 1, f"expected visited set size 1, got {len(res.visited)}: {res.visited}";
    assert "Bob|10001" in res.visited, f"missing key in visited: {res.visited}";
}

test "CascadeInvalidate only flips donations reachable from the named donor" {
    rt = root;
    alice = Donor(name="Alice", home_zip="94110");
    bob = Donor(name="Bob", home_zip="10001");
    rt ++> alice;
    rt ++> bob;

    bread = Donation(title="Sourdough Bread", category="bakery",
                     zip_code="94110", days_to_expiry=2);
    rice = Donation(title="Brown Rice 5kg", category="grains",
                    zip_code="94110", days_to_expiry=10);
    apples = Donation(title="Organic Apples", category="produce",
                      zip_code="10001", days_to_expiry=1);

    alice +>:NearbyTo(distance_miles=2):+> bread;
    alice +>:NearbyTo(distance_miles=3):+> rice;
    bob +>:NearbyTo(distance_miles=1):+> apples;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = rt spawn CascadeInvalidate(target_name="Alice");
    }
    out = buf.getvalue();

    assert res.invalidated == 2, f"expected 2 invalidated (Alice's), got {res.invalidated}: {out}";
    assert bread.available == False, "bread (Alice's) should be invalidated";
    assert rice.available == False, "rice (Alice's) should be invalidated";
    assert apples.available == True, "apples (Bob's) must NOT be invalidated";

    assert "[INVALIDATE] Sourdough Bread" in out, f"missing bread line: {out}";
    assert "[INVALIDATE] Brown Rice 5kg" in out, f"missing rice line: {out}";
    assert "Organic Apples" not in out, f"bob's apple leaked into output: {out}";
}

test "CascadeInvalidate with empty target_name invalidates every donor's donations" {
    rt = root;
    a = Donor(name="Alice", home_zip="94110");
    b = Donor(name="Bob", home_zip="10001");
    rt ++> a;
    rt ++> b;

    bread = Donation(title="Sourdough Bread", category="bakery",
                     zip_code="94110", days_to_expiry=2);
    apples = Donation(title="Organic Apples", category="produce",
                      zip_code="10001", days_to_expiry=1);

    a +>:NearbyTo(distance_miles=2):+> bread;
    b +>:NearbyTo(distance_miles=1):+> apples;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = rt spawn CascadeInvalidate();
    }
    out = buf.getvalue();

    assert res.invalidated == 2, f"expected 2 invalidated total, got {res.invalidated}: {out}";
    assert bread.available == False, "bread must be invalidated";
    assert apples.available == False, "apples must be invalidated";
    assert "Sourdough Bread" in out, f"missing bread: {out}";
    assert "Organic Apples" in out, f"missing apples: {out}";
}

test "available=False donations are never recommended even with matching zip" {
    rt = root;
    donor = Donor(name="Alice", home_zip="94110");
    rt ++> donor;

    soup = Donation(title="Tomato Soup", category="canned",
                    zip_code="94110", days_to_expiry=30, available=False);
    bread = Donation(title="Sourdough Bread", category="bakery",
                     zip_code="94110", days_to_expiry=2);
    donor +>:NearbyTo(distance_miles=2):+> soup;
    donor +>:NearbyTo(distance_miles=3):+> bread;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = rt spawn BFSRecommendation();
    }
    out = buf.getvalue();

    assert "Tomato Soup" not in out, f"unavailable donation must not appear: {out}";
    assert "Sourdough Bread" in out, f"available donation must appear: {out}";
    assert "[RECOMMEND]" in out, f"missing recommend marker: {out}";
}

test "zip match and urgency buckets appear in recommendation line" {
    rt = root;
    donor = Donor(name="Alice", home_zip="94110");
    rt ++> donor;

    urgent = Donation(title="Organic Apples", category="produce",
                      zip_code="94110", days_to_expiry=1);
    soon = Donation(title="Sourdough Bread", category="bakery",
                    zip_code="94110", days_to_expiry=3);
    fresh = Donation(title="Brown Rice 5kg", category="grains",
                     zip_code="94110", days_to_expiry=20);
    farzip = Donation(title="Pasta Box", category="grains",
                      zip_code="10001", days_to_expiry=1);

    donor +>:NearbyTo(distance_miles=1):+> urgent;
    donor +>:NearbyTo(distance_miles=2):+> soon;
    donor +>:NearbyTo(distance_miles=3):+> fresh;
    donor +>:NearbyTo(distance_miles=10):+> farzip;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = rt spawn BFSRecommendation();
    }
    out = buf.getvalue();

    assert "+30 zip" in out, f"missing zip bonus: {out}";
    assert "+40 urgent" in out, f"missing urgent bucket: {out}";
    assert "+20 soon" in out, f"missing soon bucket: {out}";
    assert "donor=Alice (94110)" in out, f"missing donor header: {out}";
    assert res.donor_zip == "94110", f"walker donor_zip wrong: {res.donor_zip}";
    assert res.donor_name == "Alice", f"walker donor_name wrong: {res.donor_name}";
}

"""Tests for outage SLA status derivation via ComputedFor edges."""

import io;
import from contextlib { redirect_stdout }

test "exporter reports latest SLA status per outage" {
    root ++> Outage(title="API outage");
    api = [root -->][0];
    api +>:ComputedFor(computed_at="2024-05-01T10:00"):+> SLAResult(status="met", is_latest=True);
    api +>:ComputedFor(computed_at="2024-04-01T09:00"):+> SLAResult(status="breached", is_latest=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Exporter();
    }
    out = buf.getvalue();

    assert "export: API outage: met" in out, f"missing latest status line: {out}";
    assert "export: API outage: breached" not in out, f"stale status leaked into export: {out}";
    assert "skipping stale result" in out, f"expected skip notice for stale result: {out}";
}

test "exporter skips outages with no SLA results" {
    root ++> Outage(title="No SLA yet");
    lonely = [root -->][0];

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Exporter();
    }
    out = buf.getvalue();

    assert "export: No SLA yet" not in out, f"exported nothing but still printed: {out}";
    assert "export:" not in out, f"export marker should not appear when there are no SLA results: {out}";
    assert len([root -->]) == 1, "graph not built as expected";
}

test "exporter walks multiple outages and joins each to its latest result" {
    root ++> Outage(title="API outage");
    root ++> Outage(title="DB timeout");
    api = [root -->][0];
    db = [root -->][1];
    api +>:ComputedFor(computed_at="2024-05-01T10:00"):+> SLAResult(status="met", is_latest=True);
    db +>:ComputedFor(computed_at="2024-05-02T08:00"):+> SLAResult(status="breached", is_latest=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Exporter();
    }
    out = buf.getvalue();

    assert "export: API outage: met" in out, f"missing API outage status: {out}";
    assert "export: DB timeout: breached" in out, f"missing DB timeout status: {out}";
    assert out.count("export:") == 2, f"expected exactly 2 export lines, got {out}";
}

test "resolver marks outage resolved and reports SLA computation" {
    root ++> Outage(title="API outage", resolved=False);
    api = [root -->][0];
    api +>:ComputedFor(computed_at="2024-05-01T10:00"):+> SLAResult(status="met", is_latest=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Resolver();
    }
    out = buf.getvalue();

    assert api.resolved == True, f"outage should be resolved, got {api.resolved}";
    assert "resolved API outage" in out, f"missing resolution line: {out}";
    assert "computed SLA (latest): met" in out, f"missing latest compute line: {out}";
    assert "computed SLA (stale)" not in out, f"stale compute line should not appear: {out}";
}

test "stale SLA results are not exported even when present" {
    root ++> Outage(title="DB timeout");
    db = [root -->][0];
    db +>:ComputedFor(computed_at="2024-04-01T09:00"):+> SLAResult(status="breached", is_latest=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Exporter();
    }
    out = buf.getvalue();

    assert "export:" not in out, f"no export line should appear for only-stale result: {out}";
    assert "skipping stale result for DB timeout: breached" in out, f"missing stale-skip notice: {out}";
}

"""Tests for HostHealthExecutor/HealthAuditor demo (issue D7+D8)."""

import io;
import from contextlib { redirect_stdout }

test "missing check is a no-op and never caches" {
    h = Host(host_name="h2", cache_ttl_ms=1000);
    h ++> HealthCheck(name="redis", healthy=True, detail="ok", min_latency_ms=7);

    exe = HostHealthExecutor(
        check_name="database",
        host_ttl_ms=1000,
        cache={},
        concurrent_flights={},
    );
    h spawn exe;

    assert exe.measured_ms == 0, f"no duration for missing check, got {exe.measured_ms}";
    assert exe.cancelled == False, "missing check must not be reported as cancelled";
    assert exe.scope_alive == False, "scope must never come alive for missing check";
    assert exe.cache == {}, f"nothing should be cached for missing check, got {exe.cache}";
}

test "auditor visits every check exactly once and records duration" {
    h = Host(host_name="audited", cache_ttl_ms=750);
    a = HealthCheck(name="a", healthy=True, detail="ok", min_latency_ms=5);
    b = HealthCheck(name="b", healthy=True, detail="ok", min_latency_ms=11);
    c = HealthCheck(name="c", healthy=False, detail="down", min_latency_ms=33);
    h ++> a;
    h ++> b;
    h ++> c;

    buf = io.StringIO();
    auditor = HealthAuditor(host_ttl_ms=750, cache={}, concurrent_flights={});
    with redirect_stdout(buf) {
        res = h spawn auditor;
    }

    assert sorted(auditor.visited) == ["a", "b", "c"], f"visited set wrong: {auditor.visited}";
    assert len(auditor.executed) == 3, f"expected 3 executed records, got {auditor.executed}";

    by_name = {r["check"]: r for r in auditor.executed};
    assert by_name["a"]["duration_ms"] == 5, f"a duration: {by_name['a']}";
    assert by_name["b"]["duration_ms"] == 11, f"b duration: {by_name['b']}";
    assert by_name["c"]["duration_ms"] == 33, f"c duration: {by_name['c']}";
    assert by_name["c"]["healthy"] == False, "c should record as unhealthy";

    assert sorted(auditor.cache.keys()) == ["a", "b", "c"], f"cache keys: {list(auditor.cache.keys())}";
    out = buf.getvalue();
    assert "=== Auditing host audited" in out, f"missing audit banner: {out!r}";
}

test "host latency never leaks into plugin-owned detail field" {
    h = Host(host_name="isolation", cache_ttl_ms=300);
    chk = HealthCheck(name="payments", healthy=True, detail="payments-ok", min_latency_ms=99);
    h ++> chk;

    exe = HostHealthExecutor(
        check_name="payments",
        host_ttl_ms=300,
        cache={},
        concurrent_flights={},
    );
    h spawn exe;

    assert chk.detail == "payments-ok", f"plugin detail was mutated: {chk.detail}";
    assert exe.measured_ms == 99, f"host-measured duration wrong: {exe.measured_ms}";
    cached = exe.cache["payments"];
    assert cached["detail"] == "payments-ok", f"cache leaked host data into plugin detail: {cached}";
    assert cached["duration_ms"] == 99, f"wrapper missing host duration: {cached}";
}

test "single-flight: second concurrent executor on same check is cancelled" {
    h = Host(host_name="flight", cache_ttl_ms=2000);
    chk = HealthCheck(name="billing", healthy=True, detail="ok", min_latency_ms=40);
    h ++> chk;

    flights = {};
    shared_cache = {};

    first = HostHealthExecutor(
        check_name="billing",
        host_ttl_ms=2000,
        cache=shared_cache,
        concurrent_flights=flights,
    );
    h spawn first;

    second = HostHealthExecutor(
        check_name="billing",
        host_ttl_ms=2000,
        cache=shared_cache,
        concurrent_flights=flights,
    );
    h spawn second;

    assert first.cancelled == False, "first flight must complete";
    assert first.measured_ms == 40, f"first duration: {first.measured_ms}";
    assert second.cancelled == True, "second flight must be de-duplicated and cancelled";
    assert second.measured_ms == 0, f"second flight must not measure, got {second.measured_ms}";
    assert shared_cache == {"billing": first.cache["billing"]}, (
        f"cache should hold exactly the first wrapper, got {shared_cache}"
    );
    assert flights == {}, f"flight map must be released, got {flights}";
}

test "typed DependsOn edges do not confuse the executor's Host -> HealthCheck path" {
    h = Host(host_name="chain", cache_ttl_ms=900);
    n1 = HealthCheck(name="n1", healthy=True, detail="ok", min_latency_ms=7);
    n2 = HealthCheck(name="n2", healthy=True, detail="ok", min_latency_ms=13);
    h ++> n1;
    h ++> n2;
    n1 +>:DependsOn(weight=2):+> n2;
    n1 +>:ScopedService(scope_id="s1"):+> n2;

    assert len([h-->]) == 2, f"host should have 2 direct children, got {len([h-->])}";
    assert n2 in [n1 ->:DependsOn:->], "typed DependsOn edge missing";
    assert n2 in [n1 ->:ScopedService:->], "typed ScopedService edge missing";

    exe = HostHealthExecutor(
        check_name="n2",
        host_ttl_ms=900,
        cache={},
        concurrent_flights={},
    );
    h spawn exe;

    assert exe.measured_ms == 13, f"executor must still resolve n2 by name, got {exe.measured_ms}";
    assert "n2" in exe.cache, "n2 must be cached after execution";
    assert exe.cancelled == False, "n2 execution should not be cancelled";
}

"""Tests for PeakATail Stage 1d IP-filter auditor (issue #95)."""

import io;
import from contextlib { redirect_stdout }

test "plus-strand small A-run is correctly windowed" {
    # Legacy window [-10,+30) on + strand tests the downstream A-stretch.
    # A 4-A run fits well within 30, so the strand-aware window flags nothing.
    root ++> CleavageSite(
        chrom="chr1", pos=1000, strand="+",
        a_run_len=4, is_novel=False, clip_umis=120
    );
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn IPAuditor();
    }
    assert res.wrong_window_count == 0, (
        f"plus-strand a_run=4 must not be flagged, got {res.wrong_window_count}"
    );
    assert res.zero_count_dropped == 0;
    assert res.wrong_col5_count == 0;
}

test "minus-strand large A-run is wrongly tested" {
    # Legacy window [-10,+30) genomic on '-' is transcript-upstream; a genomic
    # downstream a_run of 25 (= transcript-upstream 25) is what the
    # strand-aware audit must flag as the wrong side being scanned.
    root ++> CleavageSite(
        chrom="chr2", pos=750, strand="-",
        a_run_len=25, is_novel=True, clip_umis=17
    );
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn IPAuditor();
    }
    assert res.wrong_window_count == 1, (
        f"minus-strand a_run=25 must trip the window check, got {res.wrong_window_count}"
    );
    assert any(
        "chr2:750-" in note and "[IP-WINDOW]" in note
        for note in res.audited
    ), f"missing IP-WINDOW line for minus site: {res.audited}";
}

test "atlas-novel site with a_run>=6 is flagged as possible Kinnex decoy" {
    # Section 4 addendum: 24.5% of atlas-novel, IP-filter-passing sites are
    # decoys by the tighter Kinnex rule. The legacy loose rule misses them;
    # the auditor must surface them as KINNEX-DECOY? candidates.
    root ++> CleavageSite(
        chrom="chr1", pos=2500, strand="+",
        a_run_len=8, is_novel=True, clip_umis=42
    );
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn IPAuditor();
    }
    assert any(
        "[KINNEX-DECOY?]" in note and "chr1:2500+" in note and "a_run=8" in note
        for note in res.audited
    ), f"novel + a_run>=6 must surface as KINNEX-DECOY?, got {res.audited}";
    assert res.wrong_window_count == 0;
}

test "zero-count gene-assigned PAS is flagged as dropped" {
    # Section 3.2: pasbed.bed silently drops gene-assigned PAS with zero counts
    # after the CB filter. The auditor must record exactly the zero-count ones.
    root ++> PASRecord(
        pas_id="pas:chr1:3000:+", gene="GENE_X",
        clip_umis=0, in_annotatedpas=True
    );
    root ++> PASRecord(
        pas_id="pas:chr1:3050:+", gene="GENE_X",
        clip_umis=9, in_annotatedpas=True
    );
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn IPAuditor();
    }
    assert res.zero_count_dropped == 1, (
        f"exactly one zero-count PAS expected, got {res.zero_count_dropped}"
    );
    assert any(
        "[ZERO-DROP]" in note and "pas:chr1:3000:+" in note and "GENE_X" in note
        for note in res.audited
    ), f"missing ZERO-DROP line: {res.audited}";
    assert not any(
        "pas:chr1:3050:+" in note for note in res.audited
    ), f"non-zero PAS must NOT be flagged: {res.audited}";
}

test "unified PAS where first-member count != cohort sum is flagged" {
    # Section 3.4: bedtools merge -o first emits the first merged member's
    # clip-umis as column 5 instead of the cohort sum. The auditor must
    # report every UnifiedPAS whose first_member_umis disagrees with the
    # cohort_clip_umis_sum, and must carry the any_tier1 flag in the note.
    root ++> UnifiedPAS(
        unified_id="u:chr3:4000:+",
        first_member_umis=5,
        cohort_clip_umis_sum=137,
        any_tier1=True
    );
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn IPAuditor();
    }
    assert res.wrong_col5_count == 1, (
        f"col5 mismatch must be flagged exactly once, got {res.wrong_col5_count}"
    );
    assert any(
        "[COL5-BUG]" in note
        and "u:chr3:4000:+" in note
        and "first=5" in note
        and "cohort_sum=137" in note
        and "any_tier1=True" in note
        for note in res.audited
    ), f"missing COL5-BUG line with full context: {res.audited}";
}

test "unified PAS with matching counts is NOT flagged" {
    # Sanity: when first_member_umis equals cohort_clip_umis_sum the col5
    # defect does not apply and no COL5-BUG line should be emitted.
    root ++> UnifiedPAS(
        unified_id="u:chr4:5000:+",
        first_member_umis=50,
        cohort_clip_umis_sum=50,
        any_tier1=False
    );
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn IPAuditor();
    }
    assert res.wrong_col5_count == 0, (
        f"matching counts must not flag col5, got {res.wrong_col5_count}"
    );
    assert not any("[COL5-BUG]" in note for note in res.audited);
}

"""Regression tests for the phase-loop repair-lineage clobber model.

The issue: a bounded phase-loop resume repair child recursively invoked
phase-loop resume, which launched another repair instead of reconciling
the trusted closeout. Depth > 1 must be rejected, the trusted closeout
must survive, and an interrupted repair coordinator (no repo changes)
must NOT supersede a verified terminal summary with a blocker.
"""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
# Test 1: trusted closeout survives; nested repair (depth=2) is REJECTed
# ---------------------------------------------------------------------------
test "nested repair at depth 2 is rejected and trusted closeout is preserved" {
    found = Phase(name="FOUND", status="awaiting_phase_closeout", verification="passed");
    outer_repair = Repair(label="outer", depth=1, interrupted=False);
    inner_repair = Repair(label="inner-nested", depth=2, interrupted=False);
    trusted_closeout = Closeout(
        summary="27 staged paths, 4 IF gates, valid browser evidence",
        terminal="passed",
        trusted=True,
    );

    found +>:Spawns(reason="closeout-mode push"):+> outer_repair;
    outer_repair +>:Spawns(reason="re-invoked phase-loop resume"):+> inner_repair;
    inner_repair +>:Reconciles(mode="closeout"):+> trusted_closeout;

    root ++> found;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LineageAuditor(max_repair_depth=1);
    }
    out = buf.getvalue();

    # Trusted terminal must be observed before the rejection can mean anything.
    assert res.saw_trusted, f"auditor never recorded the trusted closeout terminal; out={out}";
    assert "[trusted] phase=FOUND" in out, f"missing trusted marker for FOUND phase; out={out}";

    # The depth>1 repair must be REJECTed, not dispatched.
    assert "repair[inner-nested] depth=2" in out, f"inner repair line not printed; out={out}";
    assert "-> REJECT" in out, f"depth=2 repair was not REJECTed; out={out}";
    assert "[closeout]" in out, f"trusted closeout never reconciled; out={out}";
    assert "trusted=True" in out, f"closeout trusted flag not echoed; out={out}";

    # Graph shape: exactly one Spawns edge out of the outer repair (to inner),
    # and one Reconciles edge from inner -> closeout.
    assert len([outer_repair ->:Spawns:->]) == 1, "outer repair should have exactly one Spawns child";
    assert len([inner_repair ->:Reconciles:->]) == 1, "inner repair should have exactly one Reconciles child";
    assert trusted_closeout in [inner_repair ->:Reconciles:->], "inner repair must reconcile to trusted_closeout";
}

# ---------------------------------------------------------------------------
# Test 2: depth=1 is allowed (the legitimate single repair layer)
# ---------------------------------------------------------------------------
test "single repair at depth 1 is allowed and still reconciles to trusted closeout" {
    found = Phase(name="FOUND", status="awaiting_phase_closeout", verification="passed");
    only_repair = Repair(label="only", depth=1, interrupted=False);
    trusted_closeout = Closeout(
        summary="27 staged paths, 4 IF gates, valid browser evidence",
        terminal="passed",
        trusted=True,
    );

    found +>:Spawns(reason="closeout-mode push"):+> only_repair;
    only_repair +>:Reconciles(mode="closeout"):+> trusted_closeout;

    root ++> found;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LineageAuditor(max_repair_depth=1);
    }
    out = buf.getvalue();

    assert res.saw_trusted, f"trusted terminal not seen for depth=1 path; out={out}";
    assert "repair[only] depth=1" in out, f"depth=1 repair line missing; out={out}";
    assert "-> ALLOW" in out, f"depth=1 repair should be ALLOWed; out={out}";
    assert "[closeout]" in out, f"closeout reconciliation missing; out={out}";
    assert len([only_repair ->:Spawns:->]) == 0, "depth=1 repair must not spawn another repair";
}

# ---------------------------------------------------------------------------
# Test 3: interrupted repair coordinator must not clobber the verified terminal
# ---------------------------------------------------------------------------
test "interrupted repair coordinator does not overwrite trusted terminal summary" {
    found = Phase(
        name="FOUND",
        status="awaiting_phase_closeout",
        verification="passed",
        blocker="",
    );
    outer_repair = Repair(label="outer", depth=1, interrupted=False);
    inner_repair = Repair(label="inner-nested", depth=2, interrupted=True);  # SIGINT hit here
    trusted_closeout = Closeout(
        summary="27 staged paths, 4 IF gates, valid browser evidence",
        terminal="passed",
        trusted=True,
    );

    found +>:Spawns(reason="closeout-mode push"):+> outer_repair;
    outer_repair +>:Spawns(reason="re-invoked phase-loop resume"):+> inner_repair;
    inner_repair +>:Reconciles(mode="closeout"):+> trusted_closeout;

    root ++> found;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LineageAuditor(max_repair_depth=1);
    }
    out = buf.getvalue();

    # The audited phase must STILL be the trusted one, not a derived blocker state.
    assert res.saw_trusted, f"interrupted child must not flip trusted -> blocker; out={out}";
    assert "phase=FOUND" in out, f"FOUND phase not visited; out={out}";
    assert "verification=passed" in out, f"verification flipped away from passed; out={out}";
    assert "status=awaiting_phase_closeout" in out, f"status flipped away from trusted terminal; out={out}";
    assert "[diverged]" not in out, f"auditor reported divergence on a still-trusted phase; out={out}";

    # Nested (interrupted) dispatch must still be REJECTed, not silently allowed
    # because it was interrupted.
    assert "-> REJECT" in out, f"interrupted nested repair should still be REJECTed; out={out}";
}

# ---------------------------------------------------------------------------
# Test 4: a genuinely diverged phase is reported as such (fail-closed baseline)
# ---------------------------------------------------------------------------
test "diverged phase with repeated_verification_failure is reported as diverged" {
    broken = Phase(
        name="FOUND",
        status="blocked",
        verification="blocked",
        blocker="repeated_verification_failure",
    );
    single_repair = Repair(label="outer", depth=1, interrupted=False);

    broken +>:Spawns(reason="closeout-mode push"):+> single_repair;

    root ++> broken;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LineageAuditor(max_repair_depth=1);
    }
    out = buf.getvalue();

    assert not res.saw_trusted, "auditor must not flag a blocked phase as trusted";
    assert "[diverged]" in out, f"diverged phase not surfaced; out={out}";
    assert "status=blocked" in out, f"blocked status not echoed; out={out}";
    assert "blocker=repeated_verification_failure" in out, f"blocker reason not echoed; out={out}";
    assert "-> ALLOW" in out, f"depth=1 repair still permitted at top level; out={out}";
}

