"""Tests for DreamCo Master Upgrade backlog tracker."""

import io;
import from contextlib { redirect_stdout }

# --- Test 1: foundational goals are marked done and counted correctly ---
test "foundations goals are marked done" {
    root ++> Goal(title="Universal Verification contract + runner", done=True, category="foundations");
    root ++> Goal(title="Repository Test Matrix wired to UVE", done=True, category="foundations");
    root ++> Goal(title="Canonical bot/system deduplication contract", done=True, category="foundations");

    g1 = [root-->][?:Goal][0];
    g2 = [root-->][?:Goal][1];
    g3 = [root-->][?:Goal][2];

    assert g1.done, f"foundation goal 1 should be done: {g1.done}";
    assert g2.done, f"foundation goal 2 should be done: {g2.done}";
    assert g3.done, f"foundation goal 3 should be done: {g3.done}";
    assert g1.category == "foundations", f"expected foundations, got {g1.category}";

    found_done = 0;
    for g in [root-->][?:Goal] {
        if g.done {
            found_done += 1;
        }
    }
    assert found_done == 3, f"expected 3 done foundations, got {found_done}";
}

# --- Test 2: milestones with weight=0 are completed, weight>0 are open ---
test "milestone weight classifies done vs open" {
    foundations = Milestone(title="Foundations", weight=0);
    intelligence = Milestone(title="Shared intelligence and learning", weight=1);
    builder = Milestone(title="Builder team daily loop", weight=1);

    root ++> foundations;
    root ++> intelligence;
    root ++> builder;

    assert foundations.weight == 0, f"foundations weight should be 0, got {foundations.weight}";
    assert intelligence.weight == 1, f"intelligence weight should be 1, got {intelligence.weight}";
    assert builder.weight == 1, f"builder weight should be 1, got {builder.weight}";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn UpgradeAuditor(mode="tree", max_steps=50);
    }
    out = buf.getvalue();

    assert "[DONE] milestone: Foundations" in out, f"missing DONE Foundations marker: {out}";
    assert "[OPEN] milestone: Shared intelligence and learning" in out, f"missing OPEN intelligence marker: {out}";
    assert "[OPEN] milestone: Builder team daily loop" in in_loop_check := out, f"got: {in_loop_check}";
    assert res.complete_count == 1, f"expected complete_count=1, got {res.complete_count}";
    assert res.open_count == 2, f"expected open_count=2, got {res.open_count}";
}

# --- Test 3: tree walk tallies goals via PartOf and tracks done/open ---
test "tree walk tallies PartOf goals correctly" {
    m = Milestone(title="Active gap milestone", weight=1);
    root ++> m;

    m +>:PartOf(rank=1):+> Goal(title="open goal A", done=False, category="intelligence");
    m +>:PartOf(rank=2):+> Goal(title="done goal B", done=True, category="intelligence");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = m spawn UpgradeAuditor(mode="tree", max_steps=50);
    }
    out = buf.getvalue();

    assert "[OPEN] milestone: Active gap milestone" in out, f"missing OPEN milestone: {out}";
    assert "- [OPEN] intelligence :: open goal A" in out, f"missing open goal A: {out}";
    assert "- [DONE] intelligence :: done goal B" in out, f"missing done goal B: {out}";

    assert res.complete_count == 1, f"expected complete_count=1 (done goal), got {res.complete_count}";
    assert res.open_count == 2, f"expected open_count=2 (milestone + open goal), got {res.open_count}";
    assert len(res.cycle_hits) == 0, f"no cycle expected in tree walk, got {res.cycle_hits}";
}

# --- Test 4: cycle walk over DependsOn detects back-edges ---
test "dependency cycle is detected on DependsOn walk" {
    a = Goal(title="shared intelligence layer", done=False, category="intelligence");
    b = Goal(title="role/project memory scopes", done=False, category="intelligence");

    root ++> a;
    root ++> b;

    a +>:DependsOn:+> b;
    b +>:DependsOn:+> a;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = a spawn UpgradeAuditor(mode="cycle", max_steps=50);
    }
    out = buf.getvalue();

    assert len(res.cycle_hits) >= 1, f"expected at least 1 cycle hit, got {len(res.cycle_hits)}";
    assert "cycle reached goal" in out, f"missing cycle marker in output: {out}";

    found_back_edge = False;
    for m in res.cycle_hits {
        if "shared intelligence layer" in m {
            found_back_edge = True;
        }
    }
    assert found_back_edge, f"expected back-edge to shared intelligence layer in {res.cycle_hits}";
}

# --- Test 5: typed PartOf edges exist with rank and DependsOn edges exist ---
test "PartOf edges carry rank and DependsOn is typed" {
    m = Milestone(title="Builder team daily loop", weight=1);
    root ++> m;

    m +>:PartOf(rank=1):+> Goal(title="daily loop goal", done=False, category="builder");
    m +>:PartOf(rank=2):+> Goal(title="reconciler goal", done=False, category="builder");

    part_edges = [m ->:PartOf:->];
    assert len(part_edges) == 2, f"expected 2 PartOf edges from milestone, got {len(part_edges)}";

    first_goal = part_edges[0];
    second_goal = part_edges[1];
    assert first_goal.category == "builder", f"first goal category: {first_goal.category}";
    assert second_goal.category == "builder", f"second goal category: {second_goal.category}";

    # Wire a DependsOn and confirm it traverses in cycle walk.
    first_goal +>:DependsOn:+> second_goal;
    dep_edges = [first_goal ->:DependsOn:->];
    assert len(dep_edges) == 1, f"expected 1 DependsOn edge, got {len(dep_edges)}";
    assert dep_edges[0].title == "reconciler goal", f"dep target: {dep_edges[0].title}";

    # Force a cycle so the walk exits via disengage, leaving steps capped.
    second_goal +>:DependsOn:+> first_goal;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = first_goal spawn UpgradeAuditor(mode="cycle", max_steps=5);
    }
    out = buf.getvalue();

    assert res.steps <= 5, f"steps should be capped by max_steps, got {res.steps}";
    assert "cycle reached goal" in out, f"cycle should be reported: {out}";
}

"""Tests for the Moose attribute fact extraction walker."""

import io;
import from contextlib { redirect_stdout }


# ---- Helper to build a fresh fixture graph ------------------------------

def build_pkg_with_attrs() -> tuple {
    pkg = Package(pkg_name="MyApp::Thing", framework="Moose", version="2.2200");

    a1 = Attribute(
        attr_name="name",
        access_mode="rw",
        has_reader=True,
        has_predicate=True,
        has_builder=True,
        builder_name="_build_name",
        is_required=True,
        init_arg="full_name",
        isa_constraint="Str"
    );

    a2 = Attribute(
        attr_name="count",
        access_mode="ro",
        has_writer=True,
        is_lazy=True,
        isa_constraint="Int"
    );

    a3 = Attribute(
        attr_name="internal",
        access_mode="bare",
        has_predicate=True,
        has_clearer=True
    );

    a4 = Attribute(
        attr_name="settable",
        access_mode="rwp",
        has_writer=True,
        explicit_source=True
    );

    pkg +>:DeclaredIn:+> a1;
    pkg +>:DeclaredIn:+> a2;
    pkg +>:DeclaredIn:+> a3;
    pkg +>:DeclaredIn:+> a4;

    a1 +>:Provides:+> ProvidedMember(member_name="name", kind="reader");
    a1 +>:Provides:+> ProvidedMember(member_name="has_name", kind="predicate");
    a2 +>:Provides:+> ProvidedMember(member_name="count", kind="reader");
    a2 +>:Provides:+> ProvidedMember(member_name="_set_count", kind="writer");
    a3 +>:Provides:+> ProvidedMember(member_name="has_internal", kind="predicate");
    a3 +>:Provides:+> ProvidedMember(member_name="clear_internal", kind="clearer");

    a1 +>:HooksTo:+> Hook(hook_name="_build_name", role="builder");

    root ++> pkg;
    return (pkg, a1, a2, a3, a4);
}


# ---- Test 1: provided members are visited, hooks are NOT counted as provided
test "provided and hooks are tracked separately" {
    (pkg, a1, a2, a3, a4) = build_pkg_with_attrs();

    fe = FactExtractor();
    pkg spawn fe;

    # 3 readers (name, count) — only a1 and a2 set has_reader => 2 readers
    # but here.has_writer and here.has_predicate also count toward "provided".
    # Counts per attribute:
    #   a1: reader + predicate     -> 2
    #   a2: writer                 -> 1
    #   a3: predicate + clearer    -> 2
    #   a4: writer (but rwp -> boundary path also) -> 1
    # Plus boundary path on a4 still visits [->:Provides:->] for has_writer.
    assert fe.stats.get("provided", 0) == 6, f"expected 6 provided visits, got {fe.stats.get('provided', 0)}";
    assert fe.stats.get("hooks", 0) == 1, f"expected exactly 1 hook, got {fe.stats.get('hooks', 0)}";
}


# ---- Test 2: boundary is emitted for rwp, not a fabricated member --------
test "extension access modes emit boundary, do not fabricate member" {
    (pkg, a1, a2, a3, a4) = build_pkg_with_attrs();

    # Before spawn: a4 must have zero out-edges to Boundary
    pre_boundaries = [a4 ->:Constrains:->];
    assert len(pre_boundaries) == 0, f"a4 had {len(pre_boundaries)} boundary edges before run";

    fe = FactExtractor();
    pkg spawn fe;

    # After spawn: exactly one new Boundary node is attached to a4 via Constrains.
    post_boundaries = [a4 ->:Constrains:->];
    assert len(post_boundaries) == 1, f"expected 1 boundary on a4, got {len(post_boundaries)}";
    bd = post_boundaries[0];
    assert bd.boundary_kind == "extension_required", f"wrong boundary kind: {bd.boundary_kind}";
    assert "rwp" in bd.reason, f"reason should mention rwp: {bd.reason}";
    assert fe.stats.get("boundaries", 0) == 1, f"expected 1 boundary stat, got {fe.stats.get('boundaries', 0)}";
}


# ---- Test 3: bare access mode does NOT trigger a boundary ----------------
test "bare mode is admitted plain Moose, no boundary" {
    pkg = Package(pkg_name="Bare::Pkg", framework="Moose", version="2.0");
    a = Attribute(
        attr_name="internal",
        access_mode="bare",
        has_predicate=True,
        has_clearer=True
    );
    pkg +>:DeclaredIn:+> a;
    a +>:Provides:+> ProvidedMember(member_name="has_internal", kind="predicate");
    a +>:Provides:+> ProvidedMember(member_name="clear_internal", kind="clearer");
    root ++> pkg;

    fe = FactExtractor();
    pkg spawn fe;

    assert fe.stats.get("boundaries", 0) == 0, f"bare must not emit boundary, got {fe.stats.get('boundaries', 0)}";
    assert "boundaries" not in fe.stats or fe.stats.get("boundaries", 0) == 0, "bare boundary leakage";
    # The two provided items still counted.
    assert fe.stats.get("provided", 0) == 2, f"bare predicate+clearer count wrong: {fe.stats.get('provided', 0)}";
}


# ---- Test 4: declared isa is recorded as metadata, not classified ---------
test "declared isa constraint is counted as metadata only" {
    pkg = Package(pkg_name="Constraint::Pkg", framework="Moose", version="2.0");
    a = Attribute(
        attr_name="score",
        access_mode="rw",
        has_reader=True,
        isa_constraint="Num"
    );
    pkg +>:DeclaredIn:+> a;
    a +>:Provides:+> ProvidedMember(member_name="score", kind="reader");
    root ++> pkg;

    fe = FactExtractor();
    pkg spawn fe;

    assert fe.stats.get("constraints", 0) == 1, f"expected 1 constraint metadata, got {fe.stats.get('constraints', 0)}";
    # No boundary node should have been attached for the constraint itself.
    constraint_boundaries = [a ->:Constrains:->];
    assert len(constraint_boundaries) == 0, f"isa constraint should NOT emit boundary node, got {len(constraint_boundaries)}";
}


# ---- Test 5: stdout shows package header, distinct fact lines, and boundary
test "stdout shows package header, distinct fact lines, and the boundary marker" {
    pkg = Package(pkg_name="Visible::Pkg", framework="Moose", version="2.0");
    a_rw = Attribute(
        attr_name="name",
        access_mode="rw",
        has_reader=True,
        has_predicate=True,
        has_builder=True,
        builder_name="_build_name"
    );
    a_rwp = Attribute(
        attr_name="settable",
        access_mode="rwp",
        has_writer=True
    );
    pkg +>:DeclaredIn:+> a_rw;
    pkg +>:DeclaredIn:+> a_rwp;
    a_rw +>:Provides:+> ProvidedMember(member_name="name", kind="reader");
    a_rw +>:Provides:+> ProvidedMember(member_name="has_name", kind="predicate");
    a_rw +>:HooksTo:+> Hook(hook_name="_build_name", role="builder");
    root ++> pkg;

    buf = io.StringIO();
    fe = FactExtractor();
    with redirect_stdout(buf) {
        pkg spawn fe;
    }
    out = buf.getvalue();

    # Header printed once
    assert "== Package: Visible::Pkg (Moose 2.0) ==" in out, f"missing header: {out}";
    # Provided lines appear for reader + predicate
    assert "[provided reader] name" in out, f"missing reader line: {out}";
    assert "[provided predicate] has_name" in out, f"missing predicate line: {out}";
    # Hook line appears distinctly
    assert "[hook builder] _build_name" in out, f"missing hook line: {out}";
    # Boundary line appears for rwp and carries the reason
    assert "[BOUNDARY extension_required]" in out, f"missing boundary marker: {out}";
    assert "rwp" in out, f"boundary reason should mention rwp: {out}";
}

"""Regression tests for the test-grip summary projection walker.

Exercises the behavior the issue specifies: ordered selector traversal,
per-selector seam projection, GripFacts fingerprint folding, batch
enumeration with a hard cap, and one-to-many/many-to-one relationships.
"""

import io;
import from contextlib { redirect_stdout }

test "ordered traversal respects Selects edge order" {
    root ++> Node();

    a = AnalyzerContext(generation="g1", schema_generation="v1", mode="offline");
    s1 = Selector(name="alpha", body_id="b1");
    s2 = Selector(name="beta", body_id="b2");
    s3 = Selector(name="gamma", body_id="b3");

    a +>:Selects(order=2):+> s2;
    a +>:Selects(order=1):+> s1;
    a +>:Selects(order=3):+> s3;

    p = Projector(batch_cap=10);
    res = a spawn p;

    assert res.inspected_selectors == 3, f"expected 3 visited, got {res.inspected_selectors}";
    assert res.current == "gamma", f"traversal must end on last-ordered selector, got {res.current}";
}

test "projector counts seams visited via MapsTo" {
    root ++> Node();

    a = AnalyzerContext(generation="g1");
    sel = Selector(name="only_one", body_id="b1");
    seam = Seam(seam_id="SX", owner="core", kind="core::op");
    sel +>:MapsTo(confidence=0.8, reason="matched_expression"):+> seam;
    a +>:Selects(order=1):+> sel;

    p = Projector(batch_cap=5);
    res = a spawn p;

    assert res.inspected_seams == 1, f"seam count wrong: {res.inspected_seams}";
    assert "SX" in res.fingerprint, f"seam id must seed fingerprint, got {res.fingerprint}";
}

test "one test projects to many seams and many tests share one seam" {
    root ++> Node();

    a = AnalyzerContext(generation="g1");
    fan_out = Selector(name="fan_out_test", body_id="b1");
    fan_in = Seam(seam_id="SHARED", owner="io", kind="io::write");
    se1 = Seam(seam_id="A", owner="x", kind="x::a");
    se2 = Seam(seam_id="B", owner="y", kind="y::b");

    other_a = Selector(name="other_a", body_id="b2");
    other_b = Selector(name="other_b", body_id="b3");

    a +>:Selects(order=1):+> fan_out;
    a +>:Selects(order=2):+> other_a;
    a +>:Selects(order=3):+> other_b;

    fan_out +>:MapsTo(confidence=0.9, reason="matched_expression"):+> se1;
    fan_out +>:MapsTo(confidence=0.85, reason="matched_expression"):+> fan_in;
    other_a +>:MapsTo(confidence=0.7, reason="matched_expression"):+> fan_in;
    other_b +>:MapsTo(confidence=0.6, reason="matched_expression"):+> se2;

    p = Projector(batch_cap=10);
    res = a spawn p;

    assert res.inspected_selectors == 3, f"selectors={res.inspected_selectors}";
    assert res.inspected_seams == 4, f"seams visited={res.inspected_seams}";
}

test "grip facts fold into semantic fingerprint" {
    root ++> Node();

    a = AnalyzerContext(generation="g1");
    sel = Selector(name="t", body_id="b1");
    seam = Seam(seam_id="S", owner="o", kind="k");
    facts = GripFacts(
        relation_reason="matched_expression",
        confidence=0.9,
        grip_class="Strong",
        disposition="Covered"
    );

    a +>:Selects(order=1):+> sel;
    sel +>:MapsTo(confidence=0.9, reason="matched_expression"):+> seam;
    seam +>:AnchoredIn:+> facts;

    p = Projector(batch_cap=10);
    res = a spawn p;

    assert "S" in res.fingerprint, f"seam missing from fp: {res.fingerprint}";
    assert "Strong" in res.fingerprint, f"grip_class missing from fp: {res.fingerprint}";
    assert "Covered" in res.fingerprint, f"disposition missing from fp: {res.fingerprint}";
}

test "SummarizeBatch enforces hard cap and reports omitted count" {
    root ++> Node();

    a = AnalyzerContext(generation="g1");
    sels = [];
    i = 0;
    while i < 5 {
        sels.append(Selector(name=f"sel_{i}", body_id=f"b{i}"));
        i += 1;
    }
    j = 0;
    while j < 5 {
        a +>:Selects(order=j):+> sels[j];
        j += 1;
    }

    buf = io.StringIO();
    with redirect_stdout(buf) {
        b = SummarizeBatch(cap=3);
        res = a spawn b;
        print(f"total={res.total}, omitted={res.omitted}");
    }
    out = buf.getvalue();

    assert res.total == 5, f"total tallied wrong: {res.total}";
    assert res.omitted == 2, f"omitted must reflect cap overflow: {res.omitted}";
    assert "total=5" in out, f"missing total in stdout: {out}";
    assert "omitted=2" in out, f"missing omitted in stdout: {out}";
}

"""Regression tests for the OrphanHunter walker (maintain-wiki lint gap)."""

import io;
import from contextlib { redirect_stdout }

# Baseline: every capture is reached by at least one page, so the hunter
# reports no orphans and accumulates zero bytes.
test "all captures referenced yields empty report" {
    rt = Root();
    p1 = Page(title="p1.md", depth=1, sources=["x.md"]);
    p2 = Page(title="p2.md", depth=1, sources=["y.md"]);
    c_x = Capture(path="x.md", size_bytes=100);
    c_y = Capture(path="y.md", size_bytes=200);

    rt ++> p1 ++> p2;
    p1 +>:Source(note="ref"):+> c_x;
    p2 +>:Source(note="ref"):+> c_y;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = rt spawn OrphanHunter();
    }
    out = buf.getvalue();

    assert res.found == [], f"expected no orphans, got {res.found}";
    assert res.total_bytes == 0, f"expected 0 bytes, got {res.total_bytes}";
    assert "Unreferenced captures under raw/:" in out, f"missing header: {out}";
    assert "Total orphan bytes: 0" in out, f"missing total line: {out}";
}

# Mirrors the burbank-playfab scenario from the issue: a single capture is
# referenced, another is not; the orphan must be reported with its size.
test "single orphan reported with byte count" {
    rt = Root();
    p1 = Page(title="p1.md", depth=1, sources=["kept.md"]);
    c_kept = Capture(path="kept.md", size_bytes=1200);
    c_orphan = Capture(path="orphan.md", size_bytes=4464);

    rt ++> p1;
    p1 +>:Source(note="ref"):+> c_kept;
    rt +>:Source(note="unreferenced"):+> c_orphan;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = rt spawn OrphanHunter();
    }
    out = buf.getvalue();

    assert len(res.found) == 1, f"expected 1 orphan, got {res.found}";
    assert res.found[0]["path"] == "orphan.md", f"wrong path: {res.found}";
    assert res.found[0]["bytes"] == 4464, f"wrong bytes: {res.found}";
    assert res.total_bytes == 4464, f"expected 4464 total bytes, got {res.total_bytes}";
    assert "orphan.md (4464 bytes)" in out, f"missing orphan line: {out}";
    assert "Total orphan bytes: 4464" in out, f"missing total: {out}";
}

# Two orphans, none referenced — bytes must accumulate across both, and
# the walker only flags Capture nodes.
test "multiple orphans accumulate bytes correctly" {
    rt = Root();
    p_a = Page(title="a.md", depth=1, sources=["ref.md"]);
    c_ref = Capture(path="ref.md", size_bytes=500);
    c_o1 = Capture(path="o1.md", size_bytes=1500);
    c_o2 = Capture(path="o2.md", size_bytes=2964);

    rt ++> p_a;
    p_a +>:Source(note="ref"):+> c_ref;
    rt +>:Source(note="x"):+> c_o1;
    rt +>:Source(note="y"):+> c_o2;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = rt spawn OrphanHunter();
    }
    out = buf.getvalue();

    paths = sorted(e["path"] for e in res.found);
    assert paths == ["o1.md", "o2.md"], f"unexpected orphan paths: {paths}";
    assert res.total_bytes == 4464, f"expected 4464 total, got {res.total_bytes}";
    assert "o1.md (1500 bytes)" in out, f"missing o1 line: {out}";
    assert "o2.md (2964 bytes)" in out, f"missing o2 line: {out}";
}

# Multiple pages at different depths can all reference the same capture;
# the spec calls for resolution, not basename string-match. A single
# shared capture under a fan-out of pages must NOT be reported.
test "shared capture across multiple pages is not an orphan" {
    rt = Root();
    p_shallow = Page(title="shallow.md", depth=1, sources=["shared.md"]);
    p_mid = Page(title="mid/note.md", depth=2, sources=["../shared.md"]);
    p_deep = Page(title="a/b/c/deep.md", depth=4, sources=["../../../shared.md"]);
    c_shared = Capture(path="shared.md", size_bytes=800);
    c_lone = Capture(path="lone.md", size_bytes=999);

    rt ++> p_shallow;
    p_shallow ++> p_mid;
    p_mid ++> p_deep;
    p_shallow +>:Source(note="s"):+> c_shared;
    p_mid +>:Source(note="m"):+> c_shared;
    p_deep +>:Source(note="d"):+> c_shared;
    rt +>:Source(note="x"):+> c_lone;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = rt spawn OrphanHunter();
    }

    assert len(res.found) == 1, f"expected 1 orphan, got {res.found}";
    assert res.found[0]["path"] == "lone.md", f"wrong orphan: {res.found}";
    assert res.total_bytes == 999, f"expected 999 total, got {res.total_bytes}";
    assert len(res.seen_pages) == 3, f"expected 3 pages visited, got {len(res.seen_pages)}";
}

