"""Regression tests for the hierarchical Manager delegation demo.

Exercises the LineageAuditor and CascadeInvalidator walkers against the
delegation graph rooted at an Owner, verifying traversal order, authority
containment, cycle detection, and the cascade-revoke semantics the Issue #20
scenario relies on.
"""

import io;
import from contextlib { redirect_stdout }

test "lineage auditor walks owner manager executor reviewer in order" {
    owner = Owner(name="alice");
    a = Manager(name="A", authority="investigate-and-prepare", child_count=2);
    b = Manager(name="B", authority="investigate", child_count=1);
    c = Manager(name="C", authority="investigate", child_count=1);
    exec_b = Executor(name="ExecB", bound_task="scan-candidate");
    rev_b = Reviewer(name="RevB");
    exec_c = Executor(name="ExecC", bound_task="draft-proposal");
    rev_c = Reviewer(name="RevC");

    owner +>:Parents(lineage_ref="root"):+> a;
    a +>:Delegates(handoff="[MANAGER->MANAGER]"):+> b;
    a +>:Delegates(handoff="[MANAGER->MANAGER]"):+> c;
    b +>:BoundedTask(scope="scan"):+> exec_b;
    b +>:Reviews(stage="initial"):+> rev_b;
    c +>:BoundedTask(scope="draft"):+> exec_c;
    c +>:Reviews(stage="final"):+> rev_c;

    root ++> owner;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LineageAuditor(max_depth=8);
    }
    out = buf.getvalue();

    assert "OWNER root: alice" in out, f"owner banner missing: {out}";
    assert "Manager A [investigate-and-prepare] children=2" in out, f"A line missing: {out}";
    assert "Manager B [investigate] children=1" in out, f"B line missing: {out}";
    assert "Manager C [investigate] children=1" in out, f"C line missing: {out}";
    assert "Executor ExecB bound to: scan-candidate" in out, f"ExecB record missing: {out}";
    assert "Executor ExecC bound to: draft-proposal" in out, f"ExecC record missing: {out}";
    assert "Reviewer RevB standing by" in out, f"RevB record missing: {out}";
    assert "Reviewer RevC standing by" in out, f"RevC record missing: {out}";
}

test "authority containment is preserved across delegation" {
    owner = Owner(name="alice");
    a = Manager(name="A", authority="investigate-and-prepare", child_count=1);
    b = Manager(name="B", authority="investigate", child_count=0);
    c = Manager(name="C", authority="prepare", child_count=0);
    root ++> owner;
    owner +>:Parents(lineage_ref="root"):+> a;
    a +>:Delegates(handoff="[MANAGER->MANAGER]"):+> b;
    a +>:Delegates(handoff="[MANAGER->MANAGER]"):+> c;

    descendant_authorities = [b.authority, c.authority];
    assert a.authority in {"investigate-and-prepare"}, f"parent authority: {a.authority}";
    for auth in descendant_authorities {
        assert auth != "deploy", f"descendant illegally gained deploy authority: {auth}";
    }
    assert "deploy" not in descendant_authorities, f"containment broken: {descendant_authorities}";
}

test "cycle detection disengages on revisited manager" {
    owner = Owner(name="alice");
    a = Manager(name="A", authority="investigate", child_count=1);
    b = Manager(name="B", authority="investigate", child_count=1);
    root ++> owner;
    owner +>:Parents(lineage_ref="root"):+> a;
    a +>:Delegates(handoff="[MANAGER->MANAGER]"):+> b;
    b +>:Delegates(handoff="[MANAGER->MANAGER]"):+> a;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LineageAuditor(max_depth=8);
    }
    out = buf.getvalue();

    assert "CYCLE detected revisiting A" in out, f"cycle marker missing: {out}";
}

test "cascade invalidator revokes managers and cancels executors" {
    owner = Owner(name="alice");
    a = Manager(name="A", authority="investigate-and-prepare", child_count=1);
    b = Manager(name="B", authority="investigate", child_count=1);
    exec_b = Executor(name="ExecB", bound_task="scan-candidate");
    rev_b = Reviewer(name="RevB");
    root ++> owner;
    owner +>:Parents(lineage_ref="root"):+> a;
    a +>:Delegates(handoff="[MANAGER->MANAGER]"):+> b;
    b +>:BoundedTask(scope="scan"):+> exec_b;
    b +>:Reviews(stage="initial"):+> rev_b;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn CascadeInvalidator();
    }
    out = buf.getvalue();

    assert "OWNER alice revokes delegation chain" in out, f"owner revoke missing: {out}";
    assert "Manager A authority 'investigate-and-prepare' invalidated" in out, f"A revoke missing: {out}";
    assert "Manager B authority 'investigate' invalidated" in out, f"B revoke missing: {out}";
    assert "Executor ExecB bound task 'scan-candidate' cancelled" in out, f"exec cancel missing: {out}";
    assert "Reviewer RevB stand-down" in out, f"reviewer stand-down missing: {out}";
    assert a.authority == "revoked", f"A authority not mutated: {a.authority}";
    assert b.authority == "revoked", f"B authority not mutated: {b.authority}";
    assert exec_b.bound_task == "cancelled", f"exec task not cancelled: {exec_b.bound_task}";
    assert "A" in res.revoked and "B" in res.revoked, f"revoked list wrong: {res.revoked}";
}

test "depth cap disengages on deep delegation chain" {
    owner = Owner(name="alice");
    m1 = Manager(name="M1", authority="investigate", child_count=1);
    m2 = Manager(name="M2", authority="investigate", child_count=1);
    m3 = Manager(name="M3", authority="investigate", child_count=1);
    m4 = Manager(name="M4", authority="investigate", child_count=1);
    m5 = Manager(name="M5", authority="investigate", child_count=0);
    root ++> owner;
    owner +>:Parents(lineage_ref="root"):+> m1;
    m1 +>:Delegates(handoff="[MANAGER->MANAGER]"):+> m2;
    m2 +>:Delegates(handoff="[MANAGER->MANAGER]"):+> m3;
    m3 +>:Delegates(handoff="[MANAGER->MANAGER]"):+> m4;
    m4 +>:Delegates(handoff="[MANAGER->MANAGER]"):+> m5;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LineageAuditor(max_depth=2);
    }
    out = buf.getvalue();

    assert "DEPTH CAP" in out, f"depth cap marker missing: {out}";
}

