test "reuses hashes for an unchanged request sequence" {
    hasher = TokenHasher(chunk_size=4);
    session = Session(request_id="same-sequence");
    request = Request(rid="same-sequence", session=session, hasher=hasher);
    request +>:OwnedBy:+> hasher;
    root ++> request;

    tokens = [1, 2, 3, 4, 5, 6, 7, 8];
    res = root spawn HashReuseAuditor(
        scenario="lookup_then_store",
        lookup_tokens=tokens,
        store_tokens=tokens
    );

    assert res.report["scenario"] == "lookup_then_store", f"got {res.report}";
    assert res.report["lookup_hashes"] == 2, f"got {res.report}";
    assert res.report["hash_ops"] == 2, f"got {res.report}";
    assert res.report["store_extra_ops"] == 0, f"got {res.report}";
}

test "does not hash an incomplete trailing chunk twice" {
    hasher = TokenHasher(chunk_size=4);
    session = Session(request_id="incomplete");
    request = Request(rid="incomplete", session=session, hasher=hasher);
    request +>:OwnedBy:+> hasher;
    root ++> request;

