    assert res.report["hash_ops"] == 1, f"got {res.report}";
    assert res.report["store_extra_ops"] == 0, f"got {res.report}";
}

test "hashes only newly completed chunks on extension" {
    hasher = TokenHasher(chunk_size=4);
    session = Session(request_id="extension");
    request = Request(rid="extension", session=session, hasher=hasher);
    request +>:OwnedBy:+> hasher;
    root ++> request;

    base = [1, 2, 3, 4, 5, 6, 7, 8];
    extended = base + [9, 10, 11, 12, 13, 14, 15, 16];
    res = root spawn HashReuseAuditor(
        scenario="extension",
