"""Test annex for the Consistency Review Workbench demo.

Tests focus on the Auditor walker's behavior:
  - Counts applications, evidence, check runs, findings exactly once
    (the walker carries an explicit guard list because jac 0.36 does not
     auto-dedupe visits).
  - Detects invalid evidence vs valid evidence.
  - Tracks resolved vs unresolved findings.
  - Honors the typed edge structure (Holds, Produces, Yields).
  - Disengages cleanly when no further nodes are reachable, and does
    not invent counts for graph shapes that do not exist.
"""

import io;
import from contextlib { redirect_stdout }

test "auditor counts each node type exactly once on a single application" {
    root ++> Application(name="APP-A", state="Submitted");
    app = [root -->][0];

    ev1 = Evidence(kind="registration_cert", ref="c1", valid=True);
    ev2 = Evidence(kind="income_proof", ref="i1", valid=True);
    app +>:Holds:+> ev1;
    app +>:Holds:+> ev2;

    run1 = CheckRun(release_id="REL-A", frozen_at="2025-01-01T00:00");
    app +>:Produces(release_id="REL-A"):+> run1;

    f1 = Finding(kind="missing_page", severity="warn", resolved=False);
    run1 +>:Yields:+> f1;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Auditor();
    }

    assert res.app_count == 1, f"app_count expected 1, got {res.app_count}";
    assert res.evidence_count == 2, f"evidence_count expected 2, got {res.evidence_count}";
    assert res.invalid_evidence_count == 0, f"invalid_evidence_count expected 0, got {res.invalid_evidence_count}";
    assert res.run_count == 1, f"run_count expected 1, got {res.run_count}";
    assert res.finding_count == 1, f"finding_count expected 1, got {res.finding_count}";
    assert res.unresolved_finding_count == 1, f"unresolved_finding_count expected 1, got {res.unresolved_finding_count}";
}

test "auditor flags invalid evidence and counts it separately" {
    root ++> Application(name="APP-B", state="InReview");
    app = [root -->][0];

    good = Evidence(kind="registration_cert", ref="c2", valid=True);
    bad = Evidence(kind="id_card", ref="i2", valid=False);
    app +>:Holds:+> good;
    app +>:Holds:+> bad;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Auditor();
    }

    assert res.evidence_count == 2, f"evidence_count expected 2, got {res.evidence_count}";
    assert res.invalid_evidence_count == 1, f"invalid_evidence_count expected 1, got {res.invalid_evidence_count}";
    out = buf.getvalue();
    assert "INVALID" in out, f"missing INVALID marker in output: {out}";
    assert "VALID" in out, f"missing VALID marker in output: {out}";
}

test "auditor separates resolved and unresolved findings" {
    root ++> Application(name="APP-C", state="Submitted");
    app = [root -->][0];

    run1 = CheckRun(release_id="REL-C", frozen_at="2025-02-01T00:00");
    app +>:Produces(release_id="REL-C"):+> run1;

    f_open = Finding(kind="field_mismatch", severity="high", resolved=False);
    f_done = Finding(kind="ocr_drift", severity="info", resolved=True);
    run1 +>:Yields:+> f_open;
    run1 +>:Yields:+> f_done;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Auditor();
    }

    assert res.finding_count == 2, f"finding_count expected 2, got {res.finding_count}";
    assert res.unresolved_finding_count == 1, f"unresolved_finding_count expected 1, got {res.unresolved_finding_count}";
}

test "auditor visits multiple check runs each with their own findings" {
    root ++> Application(name="APP-D", state="Submitted");
    app = [root -->][0];

    run1 = CheckRun(release_id="REL-Q1", frozen_at="2025-03-01T10:00");
    run2 = CheckRun(release_id="REL-Q2", frozen_at="2025-06-01T10:00");
    app +>:Produces(release_id="REL-Q1"):+> run1;
    app +>:Produces(release_id="REL-Q2"):+> run2;

    f1 = Finding(kind="missing_page", severity="warn", resolved=False);
    f2 = Finding(kind="field_mismatch", severity="high", resolved=False);
    f3 = Finding(kind="ocr_drift", severity="info", resolved=True);
    run1 +>:Yields:+> f1;
    run1 +>:Yields:+> f3;
    run2 +>:Yields:+> f2;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Auditor();
    }

    assert res.run_count == 2, f"run_count expected 2, got {res.run_count}";
    assert res.finding_count == 3, f"finding_count expected 3, got {res.finding_count}";
    assert res.unresolved_finding_count == 2, f"unresolved_finding_count expected 2, got {res.unresolved_finding_count}";

    out = buf.getvalue();
    assert "REL-Q1" in out, f"missing REL-Q1 in output: {out}";
    assert "REL-Q2" in out, f"missing REL-Q2 in output: {out}";
}

test "auditor handles an application with no evidence or runs gracefully" {
    root ++> Application(name="APP-E", state="Submitted");
    app = [root -->][0];

    assert len([app ->:Holds:->]) == 0, "app should start with no Holds edges";
    assert len([app ->:Produces:->]) == 0, "app should start with no Produces edges";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Auditor();
    }

    assert res.app_count == 1, f"app_count expected 1, got {res.app_count}";
    assert res.evidence_count == 0, f"evidence_count expected 0, got {res.evidence_count}";
    assert res.invalid_evidence_count == 0, f"invalid_evidence_count expected 0, got {res.invalid_evidence_count}";
    assert res.run_count == 0, f"run_count expected 0, got {res.run_count}";
    assert res.finding_count == 0, f"finding_count expected 0, got {res.finding_count}";
    assert res.unresolved_finding_count == 0, f"unresolved_finding_count expected 0, got {res.unresolved_finding_count}";
}

"""Tests for OSINT v0.9 bounded discovery walker."""

import io;
import from contextlib { redirect_stdout }

test "walker accepts high confidence target and queues provider query" {
    root ++> Target(canonical_id="t:primary", kind="person", confidence=0.90);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Discovery(max_depth=2, max_nodes=5, min_confidence=0.4);
    }
    out = buf.getvalue();
    assert "OSINT v0.9 bounded discovery starting" in out, f"missing banner: {out}";
    assert "t:primary" in res.findings, f"expected t:primary in findings, got {res.findings}";
    assert any("accept" in d and "queue-provider-query" in d for d in res.decisions), (
        f"expected queue-provider-query decision, got {res.decisions}"
    );
    assert res.seen_count == 1, f"expected seen_count=1, got {res.seen_count}";
}

test "low confidence target is deferred not accepted" {
    root ++> Target(canonical_id="t:weak", kind="site", confidence=0.10);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Discovery(max_depth=3, max_nodes=5, min_confidence=0.35);
    }
    assert "t:weak" not in res.findings, (
        f"weak target should not be accepted, got {res.findings}"
    );
    assert any("defer-low-confidence" in d for d in res.decisions), (
        f"expected defer-low-confidence decision, got {res.decisions}"
    );
    assert res.seen_count == 0, f"expected no nodes visited, got {res.seen_count}";
}

test "already verified target does not get verification bonus" {
    root ++> Target(
        canonical_id="t:confirmed",
        kind="person",
        confidence=0.80,
        verified=True
    );
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Discovery(max_depth=2, max_nodes=5, min_confidence=0.3);
    }
    accepted = [d for d in res.decisions if "accept" in d and "t:confirmed" in d];
    assert len(accepted) == 1, f"expected one accept decision, got {accepted}";
    assert "verify-via-action" in accepted[0], (
        f"verified target should route to verify-via-action, got {accepted[0]}"
    );
    assert "gain=0.80" in accepted[0], (
        f"verified target gain should be base only (0.80), got {accepted[0]}"
    );
}

test "ineligible action is rejected and not dispatched" {
    root ++> Action(name="risky-tool", kind="verify", eligible=False);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Discovery(max_depth=2, max_nodes=5, min_confidence=0.3);
    }
    assert any("reject-ineligible" in d for d in res.decisions), (
        f"expected reject-ineligible decision, got {res.decisions}"
    );
    assert not any("dispatch" in d and "risky-tool" in d for d in res.decisions), (
        f"ineligible action should not be dispatched, got {res.decisions}"
    );
}

test "cycle back to visited target is skipped not revisited" {
    t_alice = Target(canonical_id="t:alice", kind="person", confidence=0.85);
    t_blog = Target(canonical_id="t:blog", kind="site", confidence=0.55);
    t_back = Target(canonical_id="t:back", kind="person", confidence=0.60);
    t_alice +>:Discover(rationale="seed", gain=0.9):+> t_blog;
    t_blog +>:Discover(rationale="mention", gain=0.5):+> t_back;
    t_back +>:Discover(rationale="back-edge", gain=0.1):+> t_alice;
    root ++> t_alice;
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Discovery(max_depth=4, max_nodes=10, min_confidence=0.35);
    }
    assert res.visited_ids.count("t:alice") == 1, (
        f"cycle target should be visited exactly once, got {res.visited_ids}"
    );
    assert any("skip-cycle" in d and "t:alice" in d for d in res.decisions), (
        f"expected skip-cycle decision for t:alice, got {res.decisions}"
    );
    assert res.seen_count == 3, (
        f"expected 3 unique nodes visited (alice, blog, back), got {res.seen_count}"
    );
}

