test "merged branches are classified as safe to delete" {
    rt = root;
    b1 = Branch(name="automated/firebase-optimization", last_commit="2026-05-03", verdict="merged");
    b2 = Branch(name="feature/beta-testing-workflow", last_commit="2026-02-10", verdict="merged");
