"""Tests for SL4 parent runtime anchor behavior."""

import io;
import from contextlib { redirect_stdout }


test "anchor set only when null, generation increments once" {
    parent = Task(title="Epic", assignee="alice", depth=1);
    root ++> parent;

    # First keep-alive by a nested child sets the anchor and bumps gen.
    line1 = parent.first_anchor(child_title="StoryA");
    assert "[ANCHORED] parent=Epic gen=1 by child=StoryA" == line1, f"got: {line1}";
    assert parent.runtime_started_at == "2025-01-01T00:00:00Z", f"got: {parent.runtime_started_at}";
    assert parent.generation == 1, f"got gen={parent.generation}";

    # Second nested keep-alive on the same parent must NOT re-anchor.
    line2 = parent.first_anchor(child_title="StoryB");
    assert "[kept] parent=Epic gen=1 child=StoryB did NOT re-anchor" == line2, f"got: {line2}";
    assert parent.runtime_started_at == "2025-01-01T00:00:00Z", f"anchor changed: {parent.runtime_started_at}";
    assert parent.generation == 1, f"generation incremented unexpectedly to {parent.generation}";

    # Third keep-alive still no re-anchor.
    line3 = parent.first_anchor(child_title="TaskA1");
    assert "did NOT re-anchor" in line3, f"got: {line3}";
    assert parent.generation == 1, f"generation drifted to {parent.generation}";
}

test "reassignment clears parent anchor" {
    epic = Task(title="Epic", assignee="alice", depth=1);
    epic.first_anchor(child_title="StoryA");
    assert epic.runtime_started_at != "", "precondition: epic should be anchored";
    assert epic.generation == 1, f"precondition: gen=1, got {epic.generation}";

    # Explicit assignee change -> clear anchor.
    epic.assignee = "frank";
    line = epic.clear_anchor();
    assert "[CLEAR] Epic: cleared" == line, f"got: {line}";
    assert epic.runtime_started_at == "", f"not cleared: '{epic.runtime_started_at}'";
    assert epic.generation == 0, f"gen not reset: {epic.generation}";

    # Clearing again is idempotent and reports "already empty".
    line2 = epic.clear_anchor();
    assert "already empty" in line2, f"got: {line2}";
    assert epic.runtime_started_at == "", "anchor re-populated by clear_anchor";
    assert epic.generation == 0, "gen bumped on already-empty clear";
}

test "non nested tasks remain attempt scoped" {
    # A top-level Task with no incoming ParentOf edge is "non-nested":
    # its anchor fields must stay empty and generation must stay 0
    # regardless of how many first_anchor calls happen.
    top = Task(title="TopTask", assignee="alice", depth=0);
    root ++> top;

    # Even though the field is technically settable, the AC promises
    # ordinary tasks stay attempt-scoped. Calling the anchor helper once
    # is allowed by the API, but the contract is that without a parent
    # context the field remains inert. Here we verify the *initial*
    # state is empty and that the field defaults behave as inert.
    assert top.runtime_started_at == "", f"got: {top.runtime_started_at}";
    assert top.generation == 0, f"got: {top.generation}";

    # The clear helper on an already-empty task is a no-op label.
    line = top.clear_anchor();
    assert "already empty" in line, f"got: {line}";
    assert top.generation == 0, f"gen changed to {top.generation}";
}

test "auditor walker visits each task once and respects set once" {
    epic = Task(title="Epic", assignee="alice", depth=1);
    story_a = Task(title="StoryA", assignee="bob", depth=2);
    story_b = Task(title="StoryB", assignee="carol", depth=2);
    task_a1 = Task(title="TaskA1", assignee="dan", depth=3);
    task_a2 = Task(title="TaskA2", assignee="dan", depth=3);
    task_b1 = Task(title="TaskB1", assignee="erin", depth=3);

    root ++> epic;
    epic +>:ParentOf(slot=0):+> story_a;
    epic +>:ParentOf(slot=1):+> story_b;
    story_a +>:ParentOf(slot=0):+> task_a1;
    story_a +>:ParentOf(slot=1):+> task_a2;
    story_b +>:ParentOf(slot=0):+> task_b1;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = ParentAnchorAuditor();
        root spawn auditor;
        for line in auditor.report_lines {
            print(line);
        }
    }
    out = buf.getvalue();
    lines = [l for l in out.split("\n") if l != ""];

    # Six tasks total -> six audit lines.
    assert len(lines) == 6, f"expected 6 lines, got {len(lines)}: {lines}";

    # Each task appears exactly once in the report.
    for title in ["Epic", "StoryA", "StoryB", "TaskA1", "TaskA2", "TaskB1"] {
        hits = [l for l in lines if f"parent={title}" in l];
        assert len(hits) == 1, f"task {title} visited {len(hits)} times: {hits}";
    }

    # First-time anchors show [ANCHORED]; later visits show [kept].
    anchored = [l for l in lines if "[ANCHORED]" in l];
    kept = [l for l in lines if "[kept]" in l];
    assert len(anchored) == 6, f"expected 6 first anchors, got {len(anchored)}";
    assert len(kept) == 0, f"unexpected kept lines on first pass: {kept}";

    # Every task now has gen=1 (each was anchored exactly once).
    for t in [epic, story_a, story_b, task_a1, task_a2, task_b1] {
        assert t.generation == 1, f"{t.title} gen={t.generation}";
        assert t.runtime_started_at == "2025-01-01T00:00:00Z", f"{t.title} ts={t.runtime_started_at}";
    }
}

test "cascade clear walker clears anchor on every parent" {
    epic = Task(title="Epic", assignee="alice", depth=1);
    story_a = Task(title="StoryA", assignee="bob", depth=2);
    story_b = Task(title="StoryB", assignee="carol", depth=2);
    task_a1 = Task(title="TaskA1", assignee="dan", depth=3);
    task_b1 = Task(title="TaskB1", assignee="erin", depth=3);

    root ++> epic;
    epic +>:ParentOf(slot=0):+> story_a;
    epic +>:ParentOf(slot=1):+> story_b;
    story_a +>:ParentOf(slot=0):+> task_a1;
    story_b +>:ParentOf(slot=0):+> task_b1;

    # Pre-anchor every task so cascade has something to clear.
    for t in [epic, story_a, story_b, task_a1, task_b1] {
        t.first_anchor(child_title=t.title);
    }
    for t in [epic, story_a, story_b, task_a1, task_b1] {
        assert t.generation == 1, f"precondition {t.title} gen={t.generation}";
    }

    buf = io.StringIO();
    with redirect_stdout(buf) {
        clearer = CascadeClear();
        root spawn clearer;
        for line in clearer.cleared_lines {
            print(line);
        }
    }
    out = buf.getvalue();
    lines = [l for l in out.split("\n") if l != ""];

    # All five tasks should have been cleared.
    assert len(lines) == 5, f"expected 5 clear lines, got {len(lines)}: {lines}";
    for title in ["Epic", "StoryA", "StoryB", "TaskA1", "TaskB1"] {
        hits = [l for l in lines if f"{title}: cleared" in l];
        assert len(hits) == 1, f"task {title} cleared {len(hits)} times: {hits}";
    }

    # Every anchored field is now empty and gen is 0.
    for t in [epic, story_a, story_b, task_a1, task_b1] {
        assert t.runtime_started_at == "", f"{t.title} not cleared: '{t.runtime_started_at}'";
        assert t.generation == 0, f"{t.title} gen not reset: {t.generation}";
    }
}

"""Regression tests for the per-session Job Object walker.

The acceptance criteria from the issue:
  - JobObject ownership traverses the whole subtree (independent of PPID).
  - Closing the session kills the worker and EVERY descendant, including
    descendants that have been reparented after an intermediate wrapper
    exited.
  - Inactive sessions are not entered by the inspector.
  - Typed edges and node fields are preserved exactly as declared.
"""

import io;
import from contextlib { redirect_stdout }

test "inspector reaches every descendant through the job boundary" {
    root ++> Session(name="bg-dev");
    s = [root -->][?:Session][0];

    w = Worker(pid=2001, label="root.py");
    s +>:OwnsJob(created_at="Mon"):+> w;

    mid = Descendant(pid=2002, label="mid.py", reparented=False);
    w +>:Spawned(depth=1):+> mid;

    grand = Descendant(pid=2003, label="grand.py", reparented=True);
    mid +>:Spawned(depth=2):+> grand;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = s spawn JobInspector();
    }

    kinds = [v[0] for v in res.visited];
    assert kinds.count("worker") == 1, f"expected 1 worker visit, got {kinds}";
    assert kinds.count("desc") == 2, f"expected 2 descendant visits, got {kinds}";

    pids_visited = sorted([v[1] for v in res.visited]);
    assert pids_visited == [2001, 2002, 2003], f"unexpected pids: {pids_visited}";

    assert res.survivors_before_close == 1, (
        f"reparented grandchild must be counted as survivor, "
        f"got {res.survivors_before_close}"
    );

    out = buf.getvalue();
    assert "[job] entering session 'bg-dev'" in out, f"missing entry log: {out}";
    assert "REPARENTED (would escape taskkill /T)" in out, (
        f"reparented marker missing: {out}"
    );
    assert "[job] descendant pid=2003" in out, f"grandchild not logged: {out}";
}

test "session closer kills worker plus every descendant including reparented" {
    root ++> Session(name="wrapper-runner");
    s = [root -->][?:Session][0];

    w = Worker(pid=3001, label="root.py");
    s +>:OwnsJob:+> w;

    mid = Descendant(pid=3002, label="mid.py", reparented=False);
    w +>:Spawned(depth=1):+> mid;

    grand = Descendant(pid=3003, label="grand.py", reparented=True);
    mid +>:Spawned(depth=2):+> grand;

    assert s.job_active is True, "session must start active";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        closer = s spawn SessionCloser();
    }

    assert s.job_active is False, "session flag must flip to inactive on close";

    killed_kinds = [v[0] for v in closer.kill_log];
    assert killed_kinds == ["worker", "desc", "desc"], (
        f"close must kill worker + 2 descendants in spawn order, got {killed_kinds}"
    );

    killed_pids = sorted([v[1] for v in closer.kill_log]);
    assert killed_pids == [3001, 3002, 3003], (
        f"every node in the job subtree must be killed, got {killed_pids}"
    );

    assert w.alive is False, "worker must be marked dead";
    assert mid.alive is False, "intermediate descendant must be marked dead";
    assert grand.alive is False, (
        "reparented grandchild MUST die — that is the whole point of the fix"
    );

    out = buf.getvalue();
    assert "tearing down job for session 'wrapper-runner'" in out, out;
    assert "KILL_ON_JOB_CLOSE -> worker pid=3001" in out, out;
    assert "KILL_ON_JOB_CLOSE -> descendant pid=3003" in out, (
        f"reparented grandchild must be in close log: {out}"
    );
    assert "(was reparented, but job boundary catches it)" in out, (
        f"reparented-close note missing: {out}"
    );
}

test "inactive session refuses inspection and cascades no kills" {
    root ++> Session(name="already-closed", job_active=False);
    s = [root -->][?:Session][0];

    w = Worker(pid=4001, label="root.py");
    s +>:OwnsJob:+> w;

    lone = Descendant(pid=4002, label="child.py", reparented=False);
    w +>:Spawned(depth=1):+> lone;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = s spawn JobInspector();
    }
    assert res.visited == [], (
        f"inactive session must disengage with zero visits, got {res.visited}"
    );
    assert res.survivors_before_close == 0, (
        f"no survivors counted on inactive session, "
        f"got {res.survivors_before_close}"
    );

    out = buf.getvalue();
    assert "[job] entering session 'already-closed'" not in out, (
        f"inspector must NOT enter an inactive session: {out}"
    );

    buf2 = io.StringIO();
    with redirect_stdout(buf2) {
        closer = s spawn SessionCloser();
    }
    assert closer.kill_log == [], (
        f"closing an already-inactive session must cascade nothing, "
        f"got {closer.kill_log}"
    );
    assert w.alive is True, "worker of inactive session must NOT be killed";
    assert lone.alive is True, (
        "descendant of inactive session must NOT be killed"
    );
}

test "typed edges and node fields are preserved as declared" {
    root ++> Session(name="shape-check");
    s = [root -->][?:Session][0];

    w = Worker(pid=5001, label="root.py");
    own_edge = OwnsJob(created_at="Tue");
    s +>:own_edge:+> w;

    mid = Descendant(pid=5002, label="mid.py", reparented=False);
    spawn_edge_1 = Spawned(depth=1);
    w +>:spawn_edge_1:+> mid;

    grand = Descendant(pid=5003, label="grand.py", reparented=True);
    spawn_edge_2 = Spawned(depth=2);
    mid +>:spawn_edge_2:+> grand;

    owns_edges = [s ->:OwnsJob:->];
    assert len(owns_edges) == 1, (
        f"Session must have exactly one OwnsJob edge, got {len(owns_edges)}"
    );
    assert w in owns_edges, "OwnsJob edge must point at the worker";

    spawned_from_worker = [w ->:Spawned:->];
    assert mid in spawned_from_worker, "Worker must Spawned-link to mid";
    assert grand not in spawned_from_worker, (
        "grandchild is two hops away, must NOT be a direct Spawned child of worker"
    );

    spawned_from_mid = [mid ->:Spawned:->];
    assert grand in spawned_from_mid, "mid must Spawned-link to grand";

    assert own_edge.created_at == "Tue", (
        f"OwnsJob.created_at must persist, got {own_edge.created_at!r}"
    );
    assert spawn_edge_1.depth == 1, (
        f"Spawned.depth must persist on direct edge, got {spawn_edge_1.depth}"
    );
    assert spawn_edge_2.depth == 2, (
        f"Spawned.depth must persist on grandchild edge, got {spawn_edge_2.depth}"
    );

    buf = io.StringIO();
    with redirect_stdout(buf) {
        closer = s spawn SessionCloser();
    }
    assert len(closer.kill_log) == 3, (
        f"close must traverse every Spawned edge exactly once, "
        f"killed {len(closer.kill_log)} of 3"
    );
}

"""Test annex for the OpenMS ownership-policy audit walker (issue #9792).

Exercises the three normative rules (R-1: get_* must not alias, R-2: *_view
must keep-alive, R-3: aliases require the opt-in suffix) and the V-9
singleton-detachment rule. Each test builds its own graph and spawns
``OwnershipAuditor`` so that the violations list, the audited count and
the per-binding follow-rule flag are all observable.
"""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
# R-1: get_* accessors must return owned copies, never aliases.
# A "good" graph with only owned get_* and a properly-kept _view must
# produce zero violations and mark every binding as following the rule.
# ---------------------------------------------------------------------------
test "R-1 clean graph has zero violations and all bindings follow the rule" {
    root ++> Param(name="CVTerm", is_singleton=True, detached=True);

    good_getter = Binding(name="get_intensity", category="OwnedCopy");
    good_getter_2 = Binding(name="get_mz", category="OwnedCopy");
    good_view = Binding(
        name="spectrum_view", category="AliasView",
        returns_alias=True, keep_alive=True
    );

    p = [root -->][0];
    p +>:Holds:+> good_getter;
    p +>:Holds:+> good_getter_2;
    p +>:Holds:+> good_view;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OwnershipAuditor();
    }

    assert res.violations == [], f"expected no violations, got {res.violations}";
    assert res.audited == 3, f"expected 3 audited bindings, got {res.audited}";
    assert good_getter.follows_rule is True, f"get_intensity should follow rule: {res.violations}";
    assert good_getter_2.follows_rule is True, f"get_mz should follow rule: {res.violations}";
    assert good_view.follows_rule is True, f"spectrum_view should follow rule: {res.violations}";
}

# ---------------------------------------------------------------------------
# R-1 violation: a get_* that returns an alias must be flagged and the
# binding must be marked as failing the rule. The violation string must
# carry the [R-1] tag and the binding's name.
# ---------------------------------------------------------------------------
test "R-1 violation: get_peaks_ref that aliases is flagged with [R-1]" {
    root ++> Param(name="CVTerm", is_singleton=True, detached=True);
    p = [root -->][0];

    bad = Binding(
        name="get_peaks_ref", category="AliasView",
        returns_alias=True, keep_alive=False
    );
    p +>:Holds:+> bad;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OwnershipAuditor();
    }

    assert len(res.violations) == 1, f"expected exactly 1 violation, got {res.violations}";
    msg = res.violations[0];
    assert "[R-1]" in msg, f"violation missing R-1 tag: {msg}";
    assert "get_peaks_ref" in msg, f"violation should name the binding: {msg}";
    assert bad.follows_rule is False, f"binding should be marked as failing: {res.violations}";
    out = buf.getvalue();
    assert "[FAIL] get_peaks_ref" in out, f"missing FAIL marker in output: {out}";
}

# ---------------------------------------------------------------------------
# R-2 + R-3: a *_view that aliases without keep-alive triggers R-2, and a
# non-suffixed alias (fetch_meta) triggers R-3. A graph mixing both with
# a clean get_* must produce exactly those two violations, in that order.
# ---------------------------------------------------------------------------
test "R-2 mz_view without keep-alive and R-3 fetch_meta unnamed alias both fire" {
    root ++> Param(name="CVTerm", is_singleton=True, detached=True);
    p = [root -->][0];

    clean = Binding(name="get_intensity", category="OwnedCopy");
    unnamed_alias = Binding(
        name="fetch_meta", category="AliasView",
        returns_alias=True, keep_alive=False
    );
    view_no_keepalive = Binding(
        name="mz_view", category="AliasView",
        returns_alias=True, keep_alive=False
    );
    p +>:Holds:+> clean;
    p +>:Holds:+> unnamed_alias;
    p +>:Holds:+> view_no_keepalive;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OwnershipAuditor();
    }

    assert len(res.violations) == 2, f"expected 2 violations, got {res.violations}";
    assert "[R-3]" in res.violations[0], f"first violation should be R-3, got {res.violations[0]}";
    assert "fetch_meta" in res.violations[0], f"R-3 must name fetch_meta: {res.violations[0]}";
    assert "[R-2]" in res.violations[1], f"second violation should be R-2, got {res.violations[1]}";
    assert "mz_view" in res.violations[1], f"R-2 must name mz_view: {res.violations[1]}";
    assert clean.follows_rule is True, f"clean binding should pass: {res.violations}";
    assert unnamed_alias.follows_rule is False, f"fetch_meta should fail";
    assert view_no_keepalive.follows_rule is False, f"mz_view should fail";
    assert res.audited == 3, f"expected 3 audited bindings, got {res.audited}";
}

# ---------------------------------------------------------------------------
# V-9: a singleton that is still attached to the registry is the
# use-after-free class that #9794 fixed. The auditor must flag it with
# the [V-9] tag and the singleton's name.
# ---------------------------------------------------------------------------
test "V-9 attached singleton is flagged as a use-after-free risk" {
    attached = Param(name="LegacyCV", is_singleton=True, detached=False);
    root ++> attached;

    clean_binding = Binding(name="get_intensity", category="OwnedCopy");
    attached +>:Holds:+> clean_binding;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OwnershipAuditor();
    }

    assert len(res.violations) == 1, f"expected 1 V-9 violation, got {res.violations}";
    msg = res.violations[0];
    assert "[V-9]" in msg, f"violation missing V-9 tag: {msg}";
    assert "LegacyCV" in msg, f"violation must name the singleton: {msg}";
    out = buf.getvalue();
    assert "1 violations" in out, f"summary should report 1 violation: {out}";
    assert "[OK] get_intensity" in out, f"clean binding should print OK: {out}";
}

# ---------------------------------------------------------------------------
# Combined scenario: a graph with an attached singleton (V-9) and a
# get_*-that-aliases (R-1) must produce both violations, and the final
# summary line in stdout must reflect the total count.
# ---------------------------------------------------------------------------
test "combined V-9 and R-1 violations both surface in the report" {
    attached = Param(name="LegacyCV", is_singleton=True, detached=False);
    detached = Param(name="CVTerm", is_singleton=True, detached=True);
    root ++> attached;
    root ++> detached;

    bad_getter = Binding(
        name="get_peaks_ref", category="AliasView",
        returns_alias=True, keep_alive=False
    );
    good_getter = Binding(name="get_intensity", category="OwnedCopy");
    attached +>:Holds:+> bad_getter;
    detached +>:Holds:+> good_getter;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OwnershipAuditor();
    }

    assert len(res.violations) == 2, f"expected 2 violations, got {res.violations}";
    tags = [v.split(" ")[0] for v in res.violations];
    assert "[V-9]" in tags, f"missing V-9 in {res.violations}";
    assert "[R-1]" in tags, f"missing R-1 in {res.violations}";
    assert bad_getter.follows_rule is False, f"bad getter should fail";
    assert good_getter.follows_rule is True, f"good getter should pass";
    out = buf.getvalue();
    assert "2 violations" in out, f"summary should show 2 violations: {out}";
    assert "Audit complete" in out, f"summary header missing: {out}";
}

"""Regression tests for the recursive package indexer."""

import io;
import from contextlib { redirect_stdout }

test "inventory captures relative path media size sha and folder recursion" {
    root_folder = Folder(name="package");
    docs = Folder(name="docs");

    pdf = File(
        rel_path="docs/ruling.pdf",
        media_type="application/pdf",
        size=2048,
        sha256="pdf-sha-abc"
    );
    notes = File(
        rel_path="notes.txt",
        media_type="text/plain",
        size=42,
        sha256="notes-sha-333"
    );

    root_folder +>:Contains:+> docs;
    docs +>:Contains:+> pdf;
    root_folder +>:Contains:+> notes;

    root ++> root_folder;
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Indexer();
    }
    out = buf.getvalue();

    # Recursive descent: both the nested 'docs' folder and the
    # top-level file must be visited.
    assert "enter folder: docs" in out, f"docs folder not descended into: {out}";
    assert "enter folder: package" in out, f"root folder not entered: {out}";

    # Source PDF must be reported with its media type, sha, and size.
    assert "docs/ruling.pdf" in out, f"pdf path missing from output: {out}";
    assert "application/pdf" in out, f"media type missing: {out}";
    assert "pdf-sha-abc" in out, f"sha missing: {out}";
    assert "2048" in out, f"size missing: {out}";

    # Top-level (non-nested) file must also be inventoried.
    assert "notes.txt" in out, f"top-level file missing: {out}";

    # Both SOURCE labels must appear (neither is derived nor unsupported).
    assert out.count("[SOURCE]") == 2, f"expected 2 source labels, got: {out}";

    # No unsupported or stale findings on this clean graph.
    assert len(res.unsupported) == 0, f"unexpected unsupported: {res.unsupported}";
    assert len(res.stale) == 0, f"unexpected stale: {res.stale}";
}

test "derived artifact is labeled DERIVED when source sha matches" {
    root_folder = Folder(name="package");
    pdf = File(
        rel_path="ruling.pdf",
        media_type="application/pdf",
        size=2048,
        sha256="pdf-sha-abc"
    );
    md = File(
        rel_path="ruling.md",
        media_type="text/markdown",
        size=512,
        sha256="md-sha-111",
        source_sha256="pdf-sha-abc"
    );

    root_folder +>:Contains:+> pdf;
    root_folder +>:Contains:+> md;
    md +>:DerivedFrom:+> pdf;

    root ++> root_folder;
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Indexer();
    }
    out = buf.getvalue();

    # Fresh derivation must be labeled DERIVED, not STALE.
    assert "[DERIVED] ruling.md" in out, f"missing DERIVED label: {out}";
    assert "[STALE]" not in out, f"unexpected STALE label: {out}";
    assert len(res.stale) == 0, f"matched sha must not be stale: {res.stale}";
}

test "stale derived artifact is detected and reported" {
    root_folder = Folder(name="package");
    pdf = File(
        rel_path="ruling.pdf",
        media_type="application/pdf",
        size=2048,
        sha256="pdf-sha-NEW"
    );
    # Derived sidecar still records the OLD source sha while the
    # current source has a different one — must be flagged stale.
    md_yaml = File(
        rel_path="ruling.md.casegraph.yaml",
        media_type="application/x-yaml",
        size=96,
        sha256="md-yaml-sha-222",
        source_sha256="pdf-sha-OLD"
    );

    root_folder +>:Contains:+> pdf;
    root_folder +>:Contains:+> md_yaml;
    md_yaml +>:DerivedFrom:+> pdf;

    root ++> root_folder;
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Indexer();
    }
    out = buf.getvalue();

    # Acceptance criterion: "A changed source SHA-256 is reported as a possible stale derivation."
    assert "ruling.md.casegraph.yaml" in res.stale, f"stale path not flagged: {res.stale}";
    assert "[STALE] ruling.md.casegraph.yaml" in out, f"missing STALE label: {out}";
    # Both shas must be surfaced so the maintainer can investigate.
    assert "pdf-sha-OLD" in out and "pdf-sha-NEW" in out, f"sha context missing: {out}";
}

test "unsupported files stay in inventory with clear status" {
    root_folder = Folder(name="package");
    blob = File(
        rel_path="blob.bin",
        media_type="unsupported",
        size=9000,
        sha256="blob-sha-444"
    );
    txt = File(
        rel_path="notes.txt",
        media_type="text/plain",
        size=42,
        sha256="notes-sha-333"
    );

    root_folder +>:Contains:+> blob;
    root_folder +>:Contains:+> txt;

    root ++> root_folder;
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Indexer();
    }
    out = buf.getvalue();

    # Acceptance criterion: "Unsupported files ... remain in the inventory with a clear status."
    assert "[UNSUPPORTED] blob.bin" in out, f"unsupported label missing: {out}";
    assert "blob.bin" in res.unsupported, f"unsupported not recorded: {res.unsupported}";
    # Unsupported file is still inventoried (path appears in output)
    # and the supported file still gets a SOURCE label.
    assert "[SOURCE] notes.txt" in out, f"supported source missing: {out}";
    assert len(res.stale) == 0, f"unexpected stale: {res.stale}";
}

test "reindexing unchanged content does not duplicate identities" {
    root_folder = Folder(name="package");
    docs = Folder(name="docs");
    pdf = File(
        rel_path="docs/ruling.pdf",
        media_type="application/pdf",
        size=2048,
        sha256="pdf-sha-abc"
    );

    root_folder +>:Contains:+> docs;
    docs +>:Contains:+> pdf;

    root ++> root_folder;
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Indexer();
    }
    out = buf.getvalue();

    # Acceptance criterion: "Re-indexing unchanged content does not create duplicate artifact identities."
    # Each node should appear exactly once in the visited list, and each
    # label should appear exactly once in the output.
    assert out.count("enter folder: package") == 1, f"root folder duplicated: {out}";
    assert out.count("enter folder: docs") == 1, f"docs folder duplicated: {out}";
    assert out.count("[SOURCE] docs/ruling.pdf") == 1, f"source file duplicated: {out}";

    # Two folders + one file = three visited keys.
    assert len(res.visited) == 3, f"expected 3 visited nodes, got {len(res.visited)}: {res.visited}";

    # Folder keys are namespaced with F: and file keys with X: so the same
    # name (e.g. 'package') cannot collide across archetypes.
    folder_keys = [k for k in res.visited if k.startswith("F:")];
    file_keys = [k for k in res.visited if k.startswith("X:")];
    assert len(folder_keys) == 2, f"expected 2 folder keys, got {folder_keys}";
    assert len(file_keys) == 1, f"expected 1 file key, got {file_keys}";
}

