test "walks a bounded acyclic transfer tree" {
    docs = PlanNode(path="docs", kind="dir");
    readme = PlanNode(path="docs/readme.md", kind="file");
    guide = PlanNode(path="docs/guide.md", kind="file");

    root ++> docs;
    docs ++> readme;
    docs ++> guide;

    w = TransferWalker(max_depth=64, max_entries=100);
    root spawn w;

    assert w.failure == "", f"got {w.failure}";
    assert w.truncated == False, f"got {w.truncated}";
    assert len(w.dirs) == 1, f"got {len(w.dirs)}";
    assert len(w.entries) == 2, f"got {len(w.entries)}";
}

test "fails cleanly when maximum depth is exceeded" {
