import io;
import from contextlib { redirect_stdout }

test "reuses one workspace and avoids rebuilding shared tasks" {
    gh = Executor(label="ubuntu-central", hosted=True);
    ws = Workspace(path="/workspace/src");
    compile_task = Task(name="compile", heavy=True);
    verify = Task(name="verify", heavy=False);

    root +>:RunsOn:+> gh;
    gh +>:RunsOn:+> compile_task;
    gh +>:RunsOn:+> verify;
    compile_task +>:UsesState:+> ws;
    verify +>:UsesState:+> ws;
    verify +>:DependsOn:+> compile_task;

    assert len([root-->]) == 1, f"got {len([root-->])}";
    assert gh in [root ->:RunsOn:->], f"missing root executor edge";
    assert len([gh-->]) == 2, f"got {len([gh-->])}";
    assert ws in [compile_task ->:UsesState:->], f"missing compile workspace edge";
    assert compile_task in [verify ->:DependsOn:->], f"missing dependency edge";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn BackendAuditor();
    }
    out = buf.getvalue();

    assert "executor [ubuntu-central] backend=github-hosted" in out, f"got {out}";
    assert "building compile" in out, f"got {out}";
    assert "building verify" in out, f"got {out}";
    assert "skip compile: already built (shared state reuse)" in out, f"got {out}";
    assert out.count("reusing workspace /workspace/src (no artifact round-trip)") == 2, f"got {out}";
    assert res.rebuilds_avoided == 2, f"got {res.rebuilds_avoided}";
}

test "uses organization capacity when the executor is not hosted" {
    organization_executor = Executor(label="private-capacity", hosted=False);
    ws = Workspace(path="/private/workspace");
