    assert organization_executor in [root ->:RunsOn:->], f"missing organization executor edge";
    assert release_task in [organization_executor ->:RunsOn:->], f"missing release task edge";
    assert ws in [release_task ->:UsesState:->], f"missing workspace edge";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn BackendAuditor();
    }
    out = buf.getvalue();

    assert "executor [private-capacity] backend=organization" in out, f"got {out}";
    assert "building release" in out, f"got {out}";
    assert "reusing workspace /private/workspace (no artifact round-trip)" in out, f"got {out}";
    assert res.rebuilds_avoided == 1, f"got {res.rebuilds_avoided}";
}

"""Tests for the quality-review dependency tracking demo."""

test "CascadeCloser counts every closed ReviewIssue reached" {
    root ++> ReviewIssue(number=1, title="a", wave=1, severity="task", closed=True)
        ++> ReviewIssue(number=2, title="b", wave=1, severity="task", closed=False)
        ++> ReviewIssue(number=3, title="c", wave=2, severity="task", closed=True);

    closer = CascadeCloser();
    root spawn closer;
    assert closer.closed_count == 2, f"expected 2 closed, got {closer.closed_count}";
}

test "CascadeCloser follows typed Blocks edges downstream" {
    blocker = ReviewIssue(number=10, title="blocker", wave=1, severity="Opus", closed=True);
    downstream = ReviewIssue(number=11, title="downstream", wave=1, severity="Sonnet", closed=True);
    unrelated = ReviewIssue(number=12, title="unrelated", wave=1, severity="Sonnet", closed=False);
    blocker +>:Blocks:+> downstream;
    root ++> blocker ++> downstream ++> unrelated;

    closer = CascadeCloser();
    root spawn closer;
    # Reachable: blocker (closed), downstream (closed), unrelated (closed=False)
    assert closer.closed_count == 2, f"expected 2 closed across cascade, got {closer.closed_count}";
}

test "WaveAuditor isolates open issues to the requested wave" {
    root ++> ReviewIssue(number=1, title="w1-open", wave=1, severity="task", closed=False)
        ++> ReviewIssue(number=2, title="w1-closed", wave=1, severity="task", closed=True)
        ++> ReviewIssue(number=3, title="w2-open", wave=2, severity="task", closed=False)
        ++> ReviewIssue(number=4, title="w5-open-a", wave=5, severity="Sonnet", closed=False)
        ++> ReviewIssue(number=5, title="w5-open-b", wave=5, severity="Sonnet", closed=False);

    auditor5 = WaveAuditor(wave=5);
    root spawn auditor5;
    assert len(auditor5.open_in_wave) == 2, f"expected 2 open in wave 5, got {len(auditor5.open_in_wave)}";
    assert any("#4" in s for s in auditor5.open_in_wave), f"missing #4 in {auditor5.open_in_wave}";
    assert any("#5" in s for s in auditor5.open_in_wave), f"missing #5 in {auditor5.open_in_wave}";

    auditor1 = WaveAuditor(wave=1);
    root spawn auditor1;
    assert len(auditor1.open_in_wave) == 1, f"expected 1 open in wave 1, got {len(auditor1.open_in_wave)}";
    assert "#1" in auditor1.open_in_wave[0], f"unexpected entry: {auditor1.open_in_wave[0]}";
}

test "WaveAuditor respects severity and decision_gate annotations" {
    gate = ReviewIssue(number=15, title="palette system: wire or re-document",
                       wave=4, severity="Opus", closed=True, decision_gate=True);
    plain = ReviewIssue(number=32, title="keybind config SSOT",
                        wave=4, severity="Opus", closed=True);
