test "DependsOn chain traversal reaches transitive downstream issues" {
    a = ReviewIssue(number=27, title="console verb framework", wave=3, severity="Opus", closed=True);
    b = ReviewIssue(number=28, title="console resolver", wave=3, severity="Sonnet", closed=True);
    c = ReviewIssue(number=31, title="dispatch-funnel gaps", wave=4, severity="Sonnet", closed=True);
    a +>:DependsOn:+> b;
