test "ranks slow crates and finds duplicate backend signatures" {
    syn = Crate(name="syn", version="2.0", duration=27.02, start=4.27, kind="rust");
    aws = Crate(name="aws-lc-sys", version="0.40", duration=93.86, start=16.06, kind="aws-lc");
    git = Crate(name="libgit2-sys", version="0.17", duration=71.69, start=120.0, kind="git2-c-build");
    ring = Crate(name="ring", version="0.17", duration=23.28, start=85.93, kind="tls-ring");
    ring_alt = Crate(name="ring-alt", version="0.17", duration=20.10, start=86.0, kind="tls-ring");

    root ++> syn;
    syn +>:DependsOn:+> aws;
    aws +>:DependsOn:+> git;
    git +>:DependsOn:+> ring;
    ring +>:DependsOn:+> ring_alt;

    res = root spawn BuildAuditor(top_n=3);

    assert len(res.slow) == 3, f"slow list: {res.slow}";
    assert res.slow[0].name == "aws-lc-sys", f"first: {res.slow[0].name}";
    assert res.slow[1].name == "libgit2-sys", f"second: {res.slow[1].name}";
    assert res.slow[2].name == "ring", f"third: {res.slow[2].name}";
    assert len(res.duplicates) == 1, f"duplicates: {res.duplicates}";
    assert res.duplicates[0] == "ring-alt", f"duplicate: {res.duplicates[0]}";
    assert ring_alt in [ring ->:DependsOn:->], "typed dependency direction is incorrect";
    assert ring not in [ring_alt ->:DependsOn:->], "dependency edge is reversed";
}

test "guards against dependency cycles" {
    first = Crate(name="first", duration=10.0);
    second = Crate(name="second", duration=20.0);
