test "uses the default top five limit" {
    one = Crate(name="one", duration=1.0);
    two = Crate(name="two", duration=2.0);
    three = Crate(name="three", duration=3.0);
    four = Crate(name="four", duration=4.0);
    five = Crate(name="five", duration=5.0);
    six = Crate(name="six", duration=6.0);

    root ++> one;
    one +>:DependsOn:+> two;
    two +>:DependsOn:+> three;
    three +>:DependsOn:+> four;
    four +>:DependsOn:+> five;
    five +>:DependsOn:+> six;

    res = root spawn BuildAuditor();

    assert res.top_n == 5, f"default top_n: {res.top_n}";
    assert len(res.slow) == 5, f"slow count: {len(res.slow)}";
    assert res.slow[0].name == "six", f"slowest: {res.slow[0].name}";
