"""Regression tests for the TinyChain Class-aware ORM traversal demo.

Each test builds its own graph (tests run in parallel isolated workers, so
state must not be shared) and exercises either the `Or` classification
walker or the `Cascade` invalidation walker against that graph. The demo's
`with entry` block is stripped before tests run, so all node/edge state is
constructed explicitly inside each test.
"""

import io;
import from contextlib { redirect_stdout }

# ---------- `Or` walker: classification + ordered dispatch plan ----------

test "or walker classifies each member with its writable tag" {
    root ++> ClassDef(name="Widget", base_class="");

    w_email = Member(name="email", kind="stored", writable=True);
    w_audit = Member(name="audit_id", kind="stored", writable=False);
    w_full = Member(name="full_label", kind="derived", writable=False);
    w_activate = Member(name="activate", kind="method", writable=False);

    widget = [root -->][0];
    widget +>:HasMember:+> w_email;
    widget +>:HasMember:+> w_audit;
    widget +>:HasMember:+> w_full;
    widget +>:HasMember:+> w_activate;

    backing = Collection(name="widgets", path="/tx/table/widgets");
    w_email +>:BackedBy:+> backing;
    w_audit +>:BackedBy:+> backing;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Or();
    }
