"""Test annex for the type-checker cycle detection demo."""

import io;
import from contextlib { redirect_stdout }

def build_graph {
    int_t = TypeDef(name="int", kind="primitive");
    str_t = TypeDef(name="str", kind="primitive");

    # `type A = A[]`  ->  A refers to itself.
    a = TypeDef(name="A", kind="alias");
    a +>:RefersTo(target="A"):+> a;

    # `type B = { x: C }` and `type C = { y: B }`  ->  mutual recursion.
    b = TypeDef(name="B", kind="object");
    c = TypeDef(name="C", kind="object");
    b +>:RefersTo(target="C"):+> c;
    c +>:RefersTo(target="B"):+> b;

    # `type D = { x: int }`  ->  fine, resolves through a primitive.
    d = TypeDef(name="D", kind="object");
    d +>:RefersTo(target="int"):+> int_t;

    typegraph = root;
    typegraph ++> int_t ++> str_t;
    typegraph ++> a;
    typegraph ++> b ++> c;
    typegraph ++> d;
    return typegraph;
}

test "self referential alias A reports cycle path A -> A" {
    tg = build_graph();

    resolver = TypeResolver(target="A");
    tg spawn resolver;
    path = resolver.cycle_path;

    assert resolver.found_cycle == True, "A self-reference must trip cycle detection";
    assert path == ["A", "A"], f"expected ['A', 'A'], got {path}";
}

test "mutual recursion B to C to B reports full cycle path" {
    tg = build_graph();

    resolver = TypeResolver(target="B");
    tg spawn resolver;
    path = resolver.cycle_path;

    assert resolver.found_cycle == True, "mutual recursion B<->C must be detected";
    # Cycle path should start at B and close back on B via C.
    assert len(path) >= 3, f"cycle path too short: {path}";
    assert path[0] == "B", f"cycle should start at B, got {path[0]}";
    assert path[-1] == "B", f"cycle should close on B, got {path[-1]}";
    assert "C" in path, f"C must be in cycle path, got {path}";
}

test "mutual recursion starting at C reports cycle path containing both B and C" {
    tg = build_graph();

    resolver = TypeResolver(target="C");
    tg spawn resolver;
    path = resolver.cycle_path;

    assert resolver.found_cycle == True, "starting at C must also detect the cycle";
    assert path[0] == "C", f"cycle should start at C, got {path[0]}";
    assert path[-1] == "C", f"cycle should close on C, got {path[-1]}";
    assert "B" in path, f"B must be in cycle path, got {path}";
}

test "well formed type D resolving to primitive yields empty cycle path" {
    tg = build_graph();

    resolver = TypeResolver(target="D");
    tg spawn resolver;
    path = resolver.cycle_path;

    assert resolver.found_cycle == False, "D -> int must not be flagged as cyclic";
    assert path == [], f"expected empty cycle path for D, got {path}";
}

test "diagnostic string for self reference follows issue format" {
    tg = build_graph();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        path_a = check(tg, "A");
        label_a = "infinite type: " + " -> ".join(path_a);
        print(f"diagnostic: {label_a}");
    }
    out = buf.getvalue();

    assert "infinite type: A -> A" in out, f"missing structured diagnostic, got: {out!r}";
}

"""Tests for AssetMaintainer walker: tracing, updates, dependency invalidation,
context-specific workflow suggestions."""

import io;
import from contextlib { redirect_stdout }

# ---------- Helpers ----------------------------------------------------------

def build_graph() -> dict {
    rt = Root();
    # Schemas.
    server_schema = SchemaType(type_name="Server");
    app_schema = SchemaType(type_name="Application");
    rt ++> server_schema ++> app_schema;

    # web-01 server with composition + dependency.
    web_server = AssetObject(
        name="web-01",
        object_type="Server",
        attributes={"hostname": "web-01", "rack": "R3"},
        available=True,
    );
    nic = AssetObject(
        name="nic-eth0",
        object_type="NIC",
        attributes={"mac": "aa:bb:cc:dd:ee:ff"},
        available=True,
    );
    license = AssetObject(
        name="license-acme",
        object_type="License",
        attributes={"key": "ACME-2026"},
        available=True,
    );

    rt ++> web_server;
    web_server +>:Composition(quantity=1):+> nic;
    web_server +>:Dependency(required=True):+> license;

    # db-01 server shares the same license -> cross-reference.
    db_server = AssetObject(
        name="db-01",
        object_type="Server",
        attributes={"hostname": "db-01", "rack": "R3"},
        available=True,
    );
    rt ++> db_server;
    db_server +>:Composition(quantity=1):+> AssetObject(
        name="disk-0",
        object_type="Disk",
        attributes={"size_gb": 500},
        available=True,
    );
    db_server +>:Dependency(required=True):+> license;

    # Workflow context node.
    wf = WorkflowContext(step="trace-and-update");
    rt ++> wf;

    return {
        "root": rt,
        "server_schema": server_schema,
        "app_schema": app_schema,
        "web_server": web_server,
        "nic": nic,
        "license": license,
        "db_server": db_server,
        "wf": wf,
    };
}

# ---------- Tests ------------------------------------------------------------

test "read-only trace visits composed children and dependencies" {
    g = build_graph();
    rt = g["root"];

    reader = AssetMaintainer();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        rt spawn reader;
    }
    out = buf.getvalue();

    # Read-only pass: no attribute mutation, no dependency invalidation.
    assert "updated attributes" not in out, f"unexpected update in read-only pass: {out}";
    assert "schedule dependency impact review" not in out, f"wrong suggestion for read-only: {out}";

    # Context-specific suggestion for read-only: open relationship explorer.
    assert "open relationship explorer" in out, f"missing read-only suggestion: {out}";
    assert "read-only" in out, f"missing read-only label: {out}";

    # Both servers, the NIC, and the (shared) license should appear in the trace.
    assert "'web-01'" in out, f"missing web-01 visit: {out}";
    assert "'db-01'" in out, f"missing db-01 visit: {out}";
    assert "'nic-eth0'" in out, f"missing nic-eth0 visit: {out}";
    assert "'license-acme'" in out, f"missing license visit: {out}";

    # Walker state: every distinct asset name recorded in trace_log.
    assert len(reader.ver_log) == 5, f"expected 5 trace lines, got {len(reader.ver_log)}";
    assert reader.pending_update == {}, f"pending_update should remain empty, got {reader.pending_update}";
}

test "update pass applies attribute change and invalidates dependents" {
    g = build_graph();
    rt = g["root"];
    web_server = g["web_server"];
    license = g["license"];

    updater = AssetMaintainer(
        pending_update={"hostname": "web-01-prod"},
    );
    buf = io.StringIO();
    with redirect_stdout(buf) {
        rt spawn updater;
    }
    out = buf.getvalue();

    # The pending_update must be applied to web_server.
    assert web_server.attributes["hostname"] == "web-01-prod", (
        f"hostname not updated, got {web_server.attributes}"
    );
    assert "updated attributes" in out, f"missing update log line: {out}";

    # The dependent license should appear as an invalidated downstream node.
    assert "-> dep" in out, f"missing dependency-invalidation trace: {out}";
    assert "'license-acme'" in out, f"license should be invalidated as dep: {out}";

    # Context-specific suggestion for update pass: dependency impact review.
    assert "schedule dependency impact review" in out, (
        f"missing update-pass suggestion: {out}"
    );
    assert "updated" in out, f"missing updated label: {out}";
    assert "open relationship explorer" not in out, (
        f"read-only suggestion should not appear during update pass: {out}"
    );
}

test "shared dependency license is traced once per pass and not duplicated" {
    g = build_graph();
    rt = g["root"];

    reader = AssetMaintainer();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        rt spawn reader;
    }
    out = buf.getvalue();

    # Count how many times license-acme appears in the trace log
    # (only the initial 'visited' line, not the '-> dep' line, marks it).
    license_visit_lines = [
        line for line in reader.ver_log if "'license-acme'" in line
    ];
    # license is reached once as a primary visit from web_server's deps path;
    # db_server's path should see it as already-visited and skip re-recording.
    assert len(license_visit_lines) == 1, (
        f"license should appear once in trace_log, got {len(license_visit_lines)}: "
        f"{reader.ver_log}"
    );

    # visited list dedupes by name.
    assert reader.visited.count("license-acme") == 1, (
        f"license should appear once in visited, got {reader.visited}"
    );
}

test "schema types and workflow context are indexed before asset inspection" {
    g = build_graph();
    rt = g["root"];
    wf = g["wf"];
    server_schema = g["server_schema"];
    app_schema = g["app_schema"];

    reader = AssetMaintainer();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        rt spawn reader;
    }
    out = buf.getvalue();

    # WorkflowContext and SchemaType handlers should fire.
    assert "Workflow step loaded: trace-and-update" in out, (
        f"missing workflow context log: {out}"
    );
    assert "SchemaType seen: Server" in out, (
        f"missing Server schema log: {out}"
    );
    assert "SchemaType seen: Application" in out, (
        f"missing Application schema log: {out}"
    );

    # The scan header should be the first thing printed.
    assert out.startswith("AssetMaintainer: scanning object graph from root"), (
        f"walker did not announce scan at root: {out[:80]}"
    );

    # Final summary line.
    assert "Trace complete:" in out, f"missing final summary: {out}";
    assert "Suggested next step:" in out, f"missing suggestion line: {out}";
}

