"""Test annex for the Retrieval-ADR decision walk (issue #335).

The walker models the ADR-mandated discipline: every retrieval loop must stop
via explicit verifiers, budgets, hard limits, and an observable `stop_reason`.
`loop until confident` / subjective confidence is forbidden as an exit
criterion. The Hybrid pattern selects relevant chunks under a budget; the
Corrective pattern routes through corrective edges and a CERBERUS-style
verifier; unsupported patterns fail closed.
"""

import io;
import from contextlib { redirect_stdout }

test "hybrid walk respects budget and selects relevant chunks" {
    rt = Root();

    docs = Corpus(name="docs+code");
    rt ++> docs;

    q = Query(text="how does retrieval stop?", budget=3);
    docs ++> q;

    c1 = Chunk(text="verifier-driven stop", source="doc", relevance=0.8);
    c2 = Chunk(text="search until confident", source="doc", relevance=0.2);
    c3 = Chunk(text="budget exhausted mid-walk", source="code", relevance=0.6);

    q +>:HybridEdge:+> c1;
    q +>:HybridEdge:+> c2;
    q +>:HybridEdge:+> c3;

    v = Verifier(name="CERBERUS", threshold=0.85);
    q +>:Verifies:+> v;

    auditor = RetrievalAuditor(pattern="Hybrid", query_budget=2);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = rt spawn auditor;
    }
    out = buf.getvalue();

    # The Hybrid walk must terminate via an explicit, observable stop_reason
    # (budget exhaustion), not via a subjective confidence check.
    assert res.stop_reason == "budget_exhausted", (
        f"Hybrid must stop on budget, got {res.stop_reason}"
    );
    # cost is incremented per visited chunk — must not exceed budget.
    assert res.cost >= 1 and res.cost <= 2, (
        f"Hybrid cost must respect query_budget=2, got {res.cost}"
    );
    assert res.latency == res.cost * 2, (
        f"Hybrid latency tracks per-chunk cost (2 per chunk), got {res.latency}"
    );
    # Only chunks meeting the relevance threshold are selected.
    assert "verifier-driven stop" in res.selected, (
        f"relevant chunk (0.8) must be selected, got {res.selected}"
    );
    assert "search until confident" not in res.selected, (
        f"subjective-confidence chunk (0.2) must NOT be selected, got {res.selected}"
    );
    # Output must announce pattern selection explicitly.
    assert "pattern = Hybrid" in out, f"missing pattern announcement: {out}";
}

test "corrective walk ignores hybrid edges and uses corrective edges" {
    rt = Root();

    docs = Corpus(name="docs+code");
    rt ++> docs;

    q = Query(text="compare patterns", budget=5);
    docs ++> q;

    # Hybrid-only neighbour: should be unreachable on a Corrective walk.
    hybrid_only = Chunk(text="hybrid-only chunk", source="doc", relevance=0.9);
    q +>:HybridEdge:+> hybrid_only;

    cr_c1 = Chunk(text="corrected chunk A", source="doc", relevance=0.7);
    cr_c2 = Chunk(text="corrected chunk B", source="code", relevance=0.9);
    cr_c3 = Chunk(text="low-confidence filler", source="code", relevance=0.1);

    q +>:CorrectiveEdge(confidence=0.9):+> cr_c1;
    q +>:CorrectiveEdge(confidence=0.95):+> cr_c2;
    q +>:CorrectiveEdge(confidence=0.3):+> cr_c3;

    auditor = RetrievalAuditor(pattern="Corrective", query_budget=2);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = rt spawn auditor;
    }

    # The Corrective walker must follow only CorrectiveEdge, not HybridEdge,
    # so the hybrid-only neighbour is never visited / selected.
    assert "hybrid-only chunk" not in res.selected, (
        f"Corrective walk must ignore HybridEdge neighbours, got {res.selected}"
    );
    # At least one high-relevance corrective chunk is selected.
    assert "corrected chunk A" in res.selected or "corrected chunk B" in res.selected, (
        f"at least one relevant corrective chunk must be selected, got {res.selected}"
    );
    # Budget discipline still applies.
    assert res.cost <= 2, (
        f"Corrective walk must respect query_budget=2, got {res.cost}"
    );
    # With budget=2 the walker must exit via budget_exhausted, NOT via
    # any verifier (no Verifies edge was wired in this graph).
    assert res.stop_reason == "budget_exhausted", (
        f"Corrective walk without verifier must stop on budget, got {res.stop_reason}"
    );
}

test "unsupported pattern fail-closes with explicit stop_reason" {
    rt = Root();

    docs = Corpus(name="docs+code");
    rt ++> docs;

    q = Query(text="ad-hoc graph traversal?", budget=3);
    docs ++> q;

    # Some chunks exist but the pattern name is not in the ADR candidate set.
    c1 = Chunk(text="chunk one", source="doc", relevance=0.9);
    q +>:HybridEdge:+> c1;

    # Agentic / GraphRAG / Multimodal are deferred per the ADR; the walker
    # must NOT improvise a path — it must fail closed.
    auditor = RetrievalAuditor(pattern="Agentic", query_budget=5);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = rt spawn auditor;
    }

    assert res.stop_reason == "unsupported_pattern", (
        f"deferred pattern must fail closed, got {res.stop_reason}"
    );
    # Nothing should have been selected.
    assert res.selected == [], (
        f"no selection allowed for unsupported pattern, got {res.selected}"
    );
    # No cost accrued — the walk did not run.
    assert res.cost == 0, (
        f"unsupported pattern must not consume budget, got cost={res.cost}"
    );
}

test "verifier rejection halts walk before budget is consumed" {
    rt = Root();

    docs = Corpus(name="docs+code");
    rt ++> docs;

    q = Query(text="validate retrieval", budget=10);
    docs ++> q;

    # All chunks are highly relevant — selection would otherwise blow past it.
    c1 = Chunk(text="relevant chunk one", source="doc", relevance=0.95);
    c2 = Chunk(text="relevant chunk two", source="code", relevance=0.91);
    q +>:HybridEdge:+> c1;
    q +>:HybridEdge:+> c2;

    # Threshold > 0.9 must reject the walk (CERBERUS gate).
    v = Verifier(name="CERBERUS", threshold=0.95);
    q +>:Verifies:+> v;

    auditor = RetrievalAuditor(pattern="Hybrid", query_budget=10);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = rt spawn auditor;
    }

    # Verifier rejection is an explicit, observable stop condition.
    assert res.stop_reason == "verifier_rejected", (
        f"high-threshold verifier must reject, got {res.stop_reason}"
    );
    # Selected list reflects what was visited before rejection; the budget
    # must NOT have been exhausted by the rejection path.
    assert res.cost < auditor.query_budget, (
        f"verifier rejection must short-circuit before budget burn, "
        f"cost={res.cost} budget={auditor.query_budget}"
    );
}

test "passing verifier yields explicit verifier_passed stop_reason" {
    rt = Root();

    docs = Corpus(name="docs+code");
    rt ++> docs;

    q = Query(text="trust this retrieval", budget=10);
    docs ++> q;

    c1 = Chunk(text="trusted chunk", source="doc", relevance=0.8);
    q +>:HybridEdge:+> c1;

    # Threshold <= 0.9 means the verifier passes and the loop exits with an
    # observable, non-subjective stop_reason.
    v = Verifier(name="CERBERUS", threshold=0.5);
    q +>:Verifies:+> v;

    auditor = RetrievalAuditor(pattern="Hybrid", query_budget=10);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = rt spawn auditor;
    }

    assert res.stop_reason == "verifier_passed", (
        f"passing verifier must produce explicit stop_reason, got {res.stop_reason}"
    );
    assert "verifier CERBERUS passed" in buf.getvalue(), (
        f"verifier pass message must be printed: {buf.getvalue()}"
    );
}

import io;
import from contextlib { redirect_stdout }

test "normal Node runtime executes the hook once" {
    hook = HookSpec(title="ecc-session-start");
    host = HostRuntime(
