"""Tests for the bounded SitemapReader walker: bounds, filters, cycles, dedup, staleness."""

import io;
import from contextlib { redirect_stdout }

test "inventory traversal keeps fresh in-filter URLs and drops excluded, stale, and duplicate URLs" {
    root ++> SitemapIndex(loc="https://x.test/idx.xml", depth=0)
            +>:Contains:+> UrlSet(loc="https://x.test/guide.xml", depth=1)
            +>:Lists:+> PageUrl(loc="https://x.test/guide/start", lastmod="2026-02-01", priority=0.9);
    root ++> SitemapIndex(loc="https://x.test/idx.xml", depth=0)
            +>:Contains:+> UrlSet(loc="https://x.test/guide.xml", depth=1)
            +>:Lists:+> PageUrl(loc="https://x.test/guide/start", lastmod="2026-02-01", priority=0.9);
    root ++> SitemapIndex(loc="https://x.test/idx.xml", depth=0)
            +>:Contains:+> UrlSet(loc="https://x.test/guide.xml", depth=1)
            +>:Lists:+> PageUrl(loc="https://x.test/guide/advanced", lastmod="2025-12-01", priority=0.7);
    root ++> SitemapIndex(loc="https://x.test/idx.xml", depth=0)
            +>:Contains:+> UrlSet(loc="https://x.test/archive.xml", depth=1)
            +>:Lists:+> PageUrl(loc="https://x.test/archive/2024", lastmod="2026-02-01", priority=0.3);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn SitemapReader(
            max_depth=3, max_sitemaps=10, max_urls=50,
