"""Tests for the shaded-jar leak inspector: assert the LeakHunter walker
excludes the relocated hadoop-shaded hub, totals jackson + guava per plugin,
and that WorstOffender reports the worst offender (gs) with mrj_escaped=True.
"""

import io;
import from contextlib { redirect_stdout }

test "leakhunter skips relocated hadoop-shaded hub" {
    hdfs = Plugin(name="fluss-fs-hdfs", jackson_leak=1073, guava_leak=2731, mrj_escaped=True);
    s3 = Plugin(name="fluss-fs-s3", jackson_leak=1093, guava_leak=2042, mrj_escaped=True);
    hadoop_shaded = Plugin(name="fluss-fs-hadoop-shaded", jackson_leak=0, guava_leak=1954, relocated=True);

    root ++> hdfs +>:DependsOn:+> hadoop_shaded;
    root ++> s3;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LeakHunter();
    }
    out = buf.getvalue();

    assert "[scanned] fluss-fs-hdfs" in out, f"hdfs should be scanned: {out}";
    assert "[scanned] fluss-fs-s3" in out, f"s3 should be scanned: {out}";
    assert "fluss-fs-hadoop-shaded" not in out or "skip fluss-fs-hadoop-shaded" in out, f"hub should be skipped, not scanned: {out}";
    assert "skip fluss-fs-hadoop-shaded (relocates its own jackson)" in out, f"missing skip marker: {out}";

    names = [n for (n, _score) in res.results];
