"""Tests for the Maven transitive-repository-pollution model."""

import io;
import from contextlib { redirect_stdout }

# --- Helpers ----------------------------------------------------------------

def build_demo_graph {
    app = Project(name="demo-backend", version="1.0.0-SNAPSHOT");
    user_repo = Repository(
        id="central",
        url="https://artifacts.example.com/repository/maven/",
        releases_enabled=True,
        snapshots_enabled=True,
    );

    starter = Dependency(group="org.springframework.boot",
                        artifact="spring-boot-starter-web",
                        version="2.0.0.RELEASE",
                        classifier="compile");

    parent_pom = Project(name="org.springframework.boot:spring-boot-parent",
                         version="2.0.0.RELEASE");

    bom = Project(name="org.springframework.boot:spring-boot-dependencies",
                  version="2.0.0.RELEASE");

    spring_milestone = Repository(id="spring-milestone",
                                  url="https://repo.spring.io/milestone",
                                  releases_enabled=True,
                                  snapshots_enabled=True);
    bintray_milestones = Repository(id="rabbitmq-maven-milestones",
                                    url="https://dl.bintray.com/rabbitmq/maven-milestones",
                                    releases_enabled=True,
                                    snapshots_enabled=True);

    root ++> app;

    app +>:DependsOn(scope="compile"):+> starter;
    starter +>:Inherits:+> parent_pom;
    parent_pom +>:Inherits:+> bom;

    bom +>:DeclaredIn:+> spring_milestone;
    bom +>:DeclaredIn:+> bintray_milestones;

    app +>:DeclaredIn:+> user_repo;

    return [app, user_repo, starter, parent_pom, bom, spring_milestone, bintray_milestones];
}

test "resolver picks up repos from inherited parent-poms" {
    (app, user_repo, _starter, _parent, _bom, _sm, _bm) = build_demo_graph();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        resolver = RepoResolver();
        app spawn resolver;
    }
    out = buf.getvalue();

    # The user's own central repo is found via DeclaredIn on `app`.
    user_label = f"{user_repo.id} ({user_repo.url})";
    assert user_label in resolver.scoped_repos, f"missing user repo: {resolver.scoped_repos}";

    # spring-milestone lives two hops away: app -> starter -> parent_pom -> bom.
    # The walker must still surface it (this is the bug the issue reports).
    sm_label = "spring-milestone (https://repo.spring.io/milestone)";
    assert sm_label in resolver.scoped_repos, f"missing spring-milestone: {resolver.scoped_repos}";

    # bintray-milestones lives at the same depth as spring-milestone.
    bm_label = "rabbitmq-maven-milestones (https://dl.bintray.com/rabbitmq/maven-milestones)";
    assert bm_label in resolver.scoped_repos, f"missing bintray-milestones: {resolver.scoped_repos}";

    # Resolver should annotate inherited picks.
    assert "[inherited]" in out, f"expected inherited marker in:\n{out}";
    assert "[cycle-guard]" not in out, f"linear demo graph should not trip the cycle guard:\n{out}";
}

test "auditor flags repos that are not user-approved" {
    (app, user_repo, _starter, _parent, _bom, _sm, _bm) = build_demo_graph();

    approved_label = f"{user_repo.id} ({user_repo.url})";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = RepoAuditor(user_approved=[approved_label]);
        app spawn auditor;
    }
    out = buf.getvalue();

    # Two unapproved repos must be reported as POLLUTED.
    assert "spring-milestone" in out and "POLLUTED" in out, f"missing spring-milestone flag:\n{out}";
    assert "rabbitmq-maven-milestones" in out and "POLLUTED" in out, f"missing bintray flag:\n{out}";

    # The user-approved repo must not be flagged as polluted.
    pollution_lines = [ln for ln in out.split("\n") if "POLLUTED" in ln];
    for ln in pollution_lines {
        assert "central" not in ln, f"central was incorrectly flagged: {ln}";
    }
}

test "cycle guard prevents infinite loop on cyclic parent-pom graph" {
    # Construct a cyclic graph: A inherits B inherits A. The resolver must
    # terminate, and A/B's directly-declared repos should each appear once.
    a = Project(name="alpha", version="1");
    b = Project(name="beta",  version="1");
    ra = Repository(id="alpha-repo", url="https://alpha.example/repo/", releases_enabled=True, snapshots_enabled=True);
    rb = Repository(id="beta-repo",  url="https://beta.example/repo/",  releases_enabled=True, snapshots_enabled=True);

    root ++> a;
    a +>:Inherits:+> b;
    b +>:Inherits:+> a;
    a +>:DeclaredIn:+> ra;
    b +>:DeclaredIn:+> rb;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        resolver = RepoResolver();
        a spawn resolver;
    }
    out = buf.getvalue();

    alpha_label = f"{ra.id} ({ra.url})";
    beta_label  = f"{rb.id} ({rb.url})";

    assert alpha_label in resolver.scoped_repos, f"alpha-repo missing: {resolver.scoped_repos}";
    assert beta_label  in resolver.scoped_repos, f"beta-repo missing: {resolver.scoped_repos}";
    # Each repo appears exactly once despite the cycle.
    assert resolver.scoped_repos.count(alpha_label) == 1, f"alpha-repo duplicated: {resolver.scoped_repos}";
    assert resolver.scoped_repos.count(beta_label)  == 1, f"beta-repo duplicated: {resolver.scoped_repos}";
    # The cycle guard message must have fired at least once.
    assert "[cycle-guard]" in out, f"expected cycle-guard output, got:\n{out}";
}

test "scoped_repos preserves insertion order with inherited after self" {
    # Build a fresh graph with only one Project + one DeclaredIn + one
    # inherited repo via a parent Inherits chain.
    child = Project(name="child-pom", version="1.0");
    parent = Project(name="parent-pom", version="1.0");

    self_repo = Repository(id="self-repo",  url="https://self.example/maven/",   releases_enabled=True, snapshots_enabled=True);
    inh_repo  = Repository(id="parent-repo", url="https://parent.example/maven/", releases_enabled=True, snapshots_enabled=True);

    root ++> child;
    child +>:Inherits:+> parent;
    child +>:DeclaredIn:+> self_repo;
    parent +>:DeclaredIn:+> inh_repo;

    resolver = RepoResolver();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        child spawn resolver;
    }

    self_label = f"{self_repo.id} ({self_repo.url})";
    inh_label  = f"{inh_repo.id} ({inh_repo.url})";

    assert self_label in resolver.scoped_repos, f"missing self-repo: {resolver.scoped_repos}";
    assert inh_label  in resolver.scoped_repos, f"missing parent-repo: {resolver.scoped_repos}";
    self_idx = resolver.scoped_repos.index(self_label);
    inh_idx  = resolver.scoped_repos.index(inh_label);
    assert self_idx < inh_idx, f"self should precede inherited; got {resolver.scoped_repos}";
}

test "resolver does not pollute scope when no inherited repos exist" {
    # A clean project with no Inherits and no unapproved DeclaredIn repos.
    clean = Project(name="clean-app", version="1.0");
    good_repo = Repository(id="central", url="https://artifacts.example.com/repository/maven/",
                           releases_enabled=True, snapshots_enabled=True);

    root ++> clean;
    clean +>:DeclaredIn:+> good_repo;

    resolver = RepoResolver();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        clean spawn resolver;
    }

    expected = [f"{good_repo.id} ({good_repo.url})"];
    assert resolver.scoped_repos == expected, f"expected only central, got {resolver.scoped_repos}";
    assert "[inherited]" not in buf.getvalue(), "no inherited marker expected on clean graph";
}

test "tasks wait until DependsOn prerequisites are satisfied" {
    import io;
    import from contextlib { redirect_stdout }

    alpha = Task(title="alpha", duration_min=1);
    beta = Task(title="beta", duration_min=2);
    beta +>:DependsOn:+> alpha;
    root ++> beta ++> alpha;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        first = root spawn Delivery();
    }
    out = buf.getvalue();
    assert alpha.satisfied, f"alpha should become ready with no deps: {alpha.satisfied}";
    assert not beta.satisfied, f"beta must wait for alpha on first pass: {beta.satisfied}";
    assert "waiting -> beta" in out, f"expected waiting line for beta: {out}";
    assert "ready -> alpha" in out, f"expected ready line for alpha: {out}";

    buf2 = io.StringIO();
    with redirect_stdout(buf2) {
        second = root spawn Delivery();
    }
    assert beta.satisfied, f"beta should be ready once alpha is satisfied: {beta.satisfied}";
    assert "ready -> beta" in buf2.getvalue(), f"expected ready line for beta: {buf2.getvalue()}";
    assert len(second.ready_order) == 1, f"beta recorded once on second pass: {second.ready_order}";
    assert second.ready_order[0] == "beta", f"expected beta in ready_order: {second.ready_order}";
}

test "delivery accumulates dependency-respecting execution order" {
    import io;
    import from contextlib { redirect_stdout }

    lint = Task(title="lint", duration_min=3);
    sec = Task(title="security-scan", duration_min=5);
    tst = Task(title="test", duration_min=10);
    pkg = Task(title="package", duration_min=4);

    tst +>:DependsOn:+> lint;
    tst +>:DependsOn:+> sec;
    pkg +>:DependsOn:+> tst;

    root ++> lint;
    root ++> sec;
    root ++> tst;
    root ++> pkg;

    all_ready = [];
    buf = io.StringIO();
    with redirect_stdout(buf) {
        for pass_num in [1, 2, 3] {
            w = root spawn Delivery();
            for title in w.ready_order {
                if title not in all_ready {
                    all_ready.append(title);
                }
            }
        }
    }
    out = buf.getvalue();
    assert "Delivery DAG: topologically scheduling tasks" in out, f"missing delivery banner: {out}";
    assert lint.satisfied and sec.satisfied and tst.satisfied and pkg.satisfied,
        f"all tasks should end satisfied: lint={lint.satisfied} sec={sec.satisfied} test={tst.satisfied} pkg={pkg.satisfied}";
    assert len(all_ready) == 4, f"each task ready exactly once across passes: {all_ready}";

    lint_idx = all_ready.index("lint");
    sec_idx = all_ready.index("security-scan");
    test_idx = all_ready.index("test");
    pkg_idx = all_ready.index("package");
    assert lint_idx < test_idx, f"lint must precede test: {all_ready}";
    assert sec_idx < test_idx, f"security-scan must precede test: {all_ready}";
    assert test_idx < pkg_idx, f"test must precede package: {all_ready}";
}

test "invalidator cascade clears satisfied flags on reachable tasks" {
    import io;
    import from contextlib { redirect_stdout }

    lint = Task(title="lint", duration_min=1);
    tst = Task(title="test", duration_min=2);
    tst +>:DependsOn:+> lint;
