    assert "Invalidator: cascade from root" in out, f"missing invalidator banner: {out}";
    assert "invalidating downstream of lint" in out, f"missing lint invalidate line: {out}";
    assert "invalidating downstream of test" in out, f"missing test invalidate line: {out}";
}

test "DependsOn edges link dependent to prerequisite nodes" {
    base = Task(title="base", duration_min=1);
