"""Tests for the Canvas lane control room graph walker."""

import io;
import from contextlib { redirect_stdout }

def make_graph() {
    runtime = Lane(name="Runtime");
    parser = Lane(name="Parser");
    brain = Lane(name="Brain");
    integration = Lane(name="Integration");

    parser_002 = Claim(
        task_id="PARSER-002",
        title="Parser stage hardened",
        state="IN_PROGRESS",
        board_says="IN PROGRESS",
        reality="MERGED (#500 bee67e41), NOT DEPLOYED",
        stale=True,
    );
    parser_001 = Claim(
        task_id="PARSER-001",
        title="Parser stage open PR",
        state="CLAIMED",
        board_says="CLAIMED",
        reality="OPEN PR #504, mergeable, CI dark from infra",
        stale=True,
    );
    runtime_001 = Claim(
        task_id="RUNTIME-001",
        title="Compositional runtime live",
        state="LIVE",
        board_says="LIVE",
        reality="TRUE, verified via production alias 60b1365e",
        stale=False,
    );
    brain_003 = Claim(
        task_id="BRAIN-003",
        title="Brain unblock on substrate",
        state="READY",
        board_says="BLOCKED on #496/#497",
        reality="Both merged; substrate shipped",
        stale=False,
    );
    integration_001 = Claim(
        task_id="INTEGRATION-001",
        title="Integration pass unstarted",
        state="UNSTARTED",
        board_says="IN PROGRESS / BLOCKED (self-contradictory)",
        reality="Unblocked and unstarted",
        stale=True,
    );

    parser ++> parser_002;
    parser ++> parser_001;
    runtime ++> runtime_001;
    brain ++> brain_003;
    integration ++> integration_001;

    parser_002 +>:Blocks:+> Blocker(
        task_id="PARSER-002-DEPLOY",
        summary="Vercel rate-limited; production verification blocked",
        resolved=False,
    );
    brain_003 +>:Blocks:+> Blocker(
        task_id="BRAIN-003-WAIT",
        summary="Waited on #496/#497 (causal substrate + readable perf)",
        resolved=True,
    );

    parser_001 +>:ResolvesTo:+> Handoff(
        task_id="PARSER-001",
        pr_ref="#504",
        ci_dark=True,
        local_check="2394 pass / 0 fail; tsc clean except pre-existing onnx",
    );

    root ++> runtime;
    root ++> parser;
    root ++> brain;
    root ++> integration;

    return {
        "runtime": runtime,
        "parser": parser,
        "brain": brain,
        "integration": integration,
        "parser_002": parser_002,
        "parser_001": parser_001,
        "runtime_001": runtime_001,
        "brain_003": brain_003,
        "integration_001": integration_001,
    };
}

test "auditor summary counts match the pinned reality block" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        make_graph();
        a = Auditor();
        root spawn a;
    }
    # Pin: PARSER-002, PARSER-001, INTEGRATION-001 are STALE (3).
    # BRAIN-003 is READY (1). PARSER-002-DEPLOY is OPEN (1); BRAIN-003-WAIT resolved.
    assert a.stale_count == 3, f"stale_count={a.stale_count}, want 3";
    assert a.ready_count == 1, f"ready_count={a.ready_count}, want 1";
    assert a.open_blocker_count == 1, f"open_blocker_count={a.open_blocker_count}, want 1";
    out = buf.getvalue();
    assert "[STALE] PARSER-002" in out, f"missing PARSER-002 stale verdict: {out}";
    assert "[STALE] PARSER-001" in out, f"missing PARSER-001 stale verdict: {out}";
    assert "[STALE] INTEGRATION-001" in out, f"missing INTEGRATION-001 stale verdict: {out}";
    assert "[CONFIRMED] RUNTIME-001" in out, f"missing RUNTIME-001 confirmed verdict: {out}";
    assert "[READY] BRAIN-003" in out, f"missing BRAIN-003 ready verdict: {out}";
}

test "owning edge attaches each claim to exactly one lane" {
    g = make_graph();
    assert len([g["parser"]-->]) == 2, f"parser should own 2 claims, got {len([g['parser']-->])}";
    assert len([g["runtime"]-->]) == 1, f"runtime should own 1 claim, got {len([g['runtime']-->])}";
    assert len([g["brain"]-->]) == 1, f"brain should own 1 claim, got {len([g['brain']-->])}";
    assert len([g["integration"]-->]) == 1, f"integration should own 1 claim, got {len([g['integration']-->])}";

    # The stale PARSER-002 claim is reachable from parser via the Owns edge.
    parser_children = [g["parser"]-->];
    assert g["parser_002"] in parser_children, "parser_002 should be a child of parser";
    assert g["parser_001"] in parser_children, "parser_001 should be a child of parser";
