test "blocks edge surfaces open cross-lane blockers" {
    g = make_graph();
    parser002_blockers = [g["parser_002"] ->:Blocks:->];
    brain003_blockers = [g["brain_003"] ->:Blocks:->];
    assert len(parser002_blockers) == 1, f"parser_002 should have 1 blocker, got {len(parser002_blockers)}";
    assert len(brain003_blockers) == 1, f"brain_003 should have 1 blocker, got {len(brain003_blockers)}";
    assert not parser002_blockers[0].resolved, "PARSER-002-DEPLOY blocker must be open";
    assert brain003_blockers[0].resolved, "BRAIN-003-WAIT blocker must be resolved";
