test "resolves_to edge links the ready handoff back to its claim" {
    g = make_graph();
    handoffs_from_parser_001 = [g["parser_001"] ->:ResolvesTo:->];
    assert len(handoffs_from_parser_001) == 1, f"parser_001 should resolve to 1 handoff, got {len(handoffs_from_parser_001)}";
    handoff = handoffs_from_parser_001[0];
    assert handoff.pr_ref == "#504", f"handoff pr_ref={handoff.pr_ref}, want #504";
    assert handoff.ci_dark, "PARSER-001 handoff must report ci=dark";
}

test "auditor prints handoff ci dark flag exactly" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        make_graph();
        a = Auditor();
        root spawn a;
    }
    out = buf.getvalue();
    assert "[HANDOFF] PARSER-001 -> #504 [ci=dark]" in out, f"handoff line missing or wrong: {out}";
    assert "2394 pass / 0 fail" in out, f"local check text missing: {out}";
    assert "[OPEN] blocker PARSER-002-DEPLOY" in out, f"open blocker line missing: {out}";
    assert "[CLEAR] blocker BRAIN-003-WAIT" in out, f"cleared blocker line missing: {out}";
    assert "summary: stale=3 ready=1 open_blockers=1" in out, f"summary line missing: {out}";
}

