    );
    package +>:Hosts:+> WalkCallSite(
        label="cli::scan_docs (read_dir recurse)",
        uses_read_dir_recursion=True,
        has_depth_cap=False,
        has_entry_cap=False
    );
    package +>:Hosts:+> WalkCallSite(
        label="graph::collect_nodes (read_dir recurse)",
        uses_read_dir_recursion=True,
        has_depth_cap=True,
        has_entry_cap=False
    );

    auditor = WalkSafetyAuditor();
    root spawn auditor;

    assert auditor.gate_flagged == [], f"got {auditor.gate_flagged}";
    assert "cli::inventory (WalkDir::new):entry_cap_unchecked" in auditor.gate_blind, f"got {auditor.gate_blind}";
    assert "cli::scan_docs (read_dir recurse):read_dir_recursion_invisible" in auditor.gate_blind, f"got {auditor.gate_blind}";
    assert "graph::collect_nodes (read_dir recurse):read_dir_recursion_invisible" in auditor.gate_blind, f"got {auditor.gate_blind}";
    assert "cli::inventory (WalkDir::new)" in auditor.truly_unsafe, f"got {auditor.truly_unsafe}";
    assert "cli::scan_docs (read_dir recurse)" in auditor.truly_unsafe, f"got {auditor.truly_unsafe}";
    assert "graph::collect_nodes (read_dir recurse)" in auditor.truly_unsafe, f"got {auditor.truly_unsafe}";
    assert not ("core::walk_files_bounded" in auditor.truly_unsafe), f"got {auditor.truly_unsafe}";
}

"""Test annex for the Qt-tree pre/post insert/delete notifications demo.

Each test builds a fresh graph, spawns the walker(s) from the program, and
asserts the documented behavior:
  - audit reports pre/post-delete for nodes flagged deleted
  - cascade invalidator flips deleted=True on the subtree
  - cycle policy: visited guard prevents infinite traversal
  - audit walker does not mutate state (counts are stable across runs)
"""

import io;
import from contextlib { redirect_stdout }

test "audit on clean tree emits no delete events" {
    root ++> TreeSource(name="DocsTree", label="DocsTree", row=0);
    [src] = [root-->][?:TreeSource];
    docs = TreeNode(title="docs", label="docs", row=0);
    src_f = TreeNode(title="src", label="src", row=1);
    src +>:Parent(row=0):+> docs;
    src +>:Parent(row=1):+> src_f;
    leaf = TreeNode(title="overview.txt", label="overview.txt", row=0);
    docs +>:Parent(row=0):+> leaf;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = SourceAuditor();
        res = src spawn auditor;
    }
    out = buf.getvalue();
    assert res.pre_delete_emitted == 0, f"expected 0 pre-delete on clean tree, got {res.pre_delete_emitted}";
    assert res.post_delete_emitted == 0, f"expected 0 post-delete on clean tree, got {res.post_delete_emitted}";
    assert "[source] beginning structural audit" in out, f"missing source start marker: {out}";
    assert "  [audit] docs#0" in out, f"missing audit line for docs: {out}";
    assert "  [audit] src#1" in out, f"missing audit line for src: {out}";
    assert "  [audit] overview.txt#0" in out, f"missing audit line for leaf: {out}";
}

test "audit fires pre-delete then post-delete in order for flagged nodes" {
    root ++> TreeSource(name="Src", label="Src", row=0);
    [src] = [root-->][?:TreeSource];
    child = TreeNode(title="child", label="child", row=0);
    src +>:Parent(row=0):+> child;
    child.deleted = True;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = SourceAuditor();
        res = src spawn auditor;
    }
    out = buf.getvalue();
    assert res.pre_delete_emitted == 1, f"expected 1 pre-delete, got {res.pre_delete_emitted}";
    assert res.post_delete_emitted == 1, f"expected 1 post-delete, got {res.post_delete_emitted}";
    # Pre-delete MUST come before post-delete so the Qt view can rebind
    # QModelIndex references before the structural change.
    pre_idx = out.find("[pre-delete]");
    post_idx = out.find("[post-delete]");
    assert pre_idx != -1 and post_idx != -1, f"missing markers in: {out}";
    assert pre_idx < post_idx, f"pre-delete must precede post-delete; order in: {out}";
    assert "child#0" in out, f"missing child#0 in audit output: {out}";
}

test "cascade invalidator marks descendants but not the target" {
    root ++> TreeSource(name="Src", label="Src", row=0);
    [src] = [root-->][?:TreeSource];
    docs = TreeNode(title="docs", label="docs", row=0);
    child_a = TreeNode(title="a.txt", label="a.txt", row=0);
    child_b = TreeNode(title="b.txt", label="b.txt", row=1);
    src +>:Parent(row=0):+> docs;
    docs +>:Parent(row=0):+> child_a;
    docs +>:Parent(row=1):+> child_b;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        invalidator = CascadeInvalidator(target_label="docs");
        res = docs spawn invalidator;
    }
    # Target itself is NOT marked (only its descendants are flagged for
    # deletion).
    assert "docs" not in res.marked, f"target label must not appear in marked list: {res.marked}";
    assert "a.txt" in res.marked, f"a.txt should be marked, got: {res.marked}";
    assert "b.txt" in res.marked, f"b.txt should be marked, got: {res.marked}";
    # Verify the flag was actually flipped on the descendants.
    assert child_a.deleted == True, f"a.txt.deleted should be True, got {child_a.deleted}";
    assert child_b.deleted == True, f"b.txt.deleted should be True, got {child_b.deleted}";
    # Target stays alive.
    assert docs.deleted == False, f"target docs.deleted should remain False, got {docs.deleted}";
}

test "cycle guard prevents infinite traversal" {
    # docs <-> src linked both directions forms a cycle. Without the
    # visited set in SourceAuditor, the walker would loop forever.
    root ++> TreeSource(name="CyclicSrc", label="CyclicSrc", row=0);
    [src] = [root-->][?:TreeSource];
    docs = TreeNode(title="docs", label="docs", row=0);
    src_f = TreeNode(title="src", label="src", row=1);
    src +>:Parent(row=0):+> docs;
    src +>:Parent(row=1):+> src_f;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = SourceAuditor();
        res = src spawn auditor;
    }
    # Each unique label visited exactly once: docs once, src once.
    assert "docs" in res.visited, f"docs missing from visited: {res.visited}";
    assert "src" in res.visited, f"src missing from visited: {res.visited}";
    # No duplicates (cycle was guarded).
    assert res.visited.count("docs") == 1, f"docs visited more than once: {res.visited}";
    assert res.visited.count("src") == 1, f"src visited more than once: {res.visited}";
    # No delete events on a clean cyclic tree.
    assert res.pre_delete_emitted == 0, f"expected 0 pre-delete on clean cycle, got {res.pre_delete_emitted}";
    assert res.post_delete_emitted == 0, f"expected 0 post-delete on clean cycle, got {res.post_delete_emitted}";
}

test "two-phase audit after cascade marks multiple descendants" {
    root ++> TreeSource(name="Src", label="Src", row=0);
    [src] = [root-->][?:TreeSource];
    parent = TreeNode(title="parent", label="parent", row=0);
    sibling = TreeNode(title="sibling", label="sibling", row=1);
    src +>:Parent(row=0):+> parent;
    src +>:Parent(row=1):+> sibling;
    leaf1 = TreeNode(title="leaf1", label="leaf1", row=0);
    leaf2 = TreeNode(title="leaf2", label="leaf2", row=1);
    parent +>:Parent(row=0):+> leaf1;
    parent +>:Parent(row=1):+> leaf2;

    # Step 1: cascade-mark from `parent` — leaves + sibling should be flagged,
    # parent itself should NOT.
    buf = io.StringIO();
    with redirect_stdout(buf) {
        cascade = CascadeInvalidator(target_label="parent");
        cres = parent spawn cascade;
    }
    assert "parent" not in cres.marked, f"parent should not be in marked: {cres.marked}";
    assert "leaf1" in cres.marked and "leaf2" in cres.marked, f"leaves missing from marked: {cres.marked}";
    assert leaf1.deleted == True and leaf2.deleted == True, "leaves must be flagged deleted";

    # Step 2: run the auditor over the source root; the audit walker is
    # spawned on the TreeSource. It will reach both flagged leaves and
    # unflagged sibling, emitting pre/post-delete only for the leaves.
    buf2 = io.StringIO();
    with redirect_stdout(buf2) {
        auditor = SourceAuditor();
        ares = src spawn auditor;
    }
    assert ares.pre_delete_emitted == 2, f"expected 2 pre-delete events, got {ares.pre_delete_emitted}";
    assert ares.post_delete_emitted == 2, f"expected 2 post-delete events, got {ares.post_delete_emitted}";
    # Pre/post pairs must each appear, and pre must always precede post.
    pre_count = ares.pre_delete_emitted;
    post_count = ares.post_delete_emitted;
    assert pre_count == post_count, f"pre/post counts must match, got {pre_count} vs {post_count}";
}

"""Tests for the Task dependency graph walkers.

Exercises the three behaviors the issue demands:
  1. Auto-unblock cascade: a downstream Task whose only blockers are all
     completed must transition status -> "ready" and increment
     UnblockCascade.unlocked_count.
  2. Cycle detection: CycleDetector must surface cycles introduced via
     Blocks edges, and confirm a clean DAG has no cycles.
  3. Reachability: DependencyReacher must traverse follow-Blocks edges
     and collect every dependent Task title.
"""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
test "cascade unblocks a downstream task once every blocker is completed" {
    # Fresh graph per test:
    #   blocker_a (completed) --Blocks--> dependent
    #   blocker_b (completed) --Blocks--> dependent
    # An unrelated completed sibling branch must be ignored.
    rt = root;
    a = Task(title="a-done", completed=True);
    b = Task(title="b-done", completed=True);
    dep = Task(title="dependent", completed=False);
    leaf = Task(title="leaf-done", completed=True);

    rt ++> a ++> b ++> dep ++> leaf;
    a +>:Blocks:+> dep;
    b +>:Blocks:+> dep;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = rt spawn UnblockCascade();
    }
    out = buf.getvalue();

    assert "dependent" in out, f"dependent task not visited: {out}";
    assert "'dependent' is now Ready to Work" in out, (
        f"dependent was not promoted to ready: {out}"
    );
    assert res.unlocked_count == 1, (
        f"expected exactly 1 unlocked task, got {res.unlocked_count}"
    );
    assert dep.status == "ready", f"status not updated, got {dep.status}";
    assert "leaf-done" not in res.visited_titles, (
        f"cascade should not cross a completed node, got {res.visited_titles}"
    );
}

# ---------------------------------------------------------------------------
test "cascade keeps downstream task blocked when a blocker is incomplete" {
    # block_a is completed, block_b is NOT completed. Both Blocks point to dep.
    # dep must NOT be promoted to ready, and unlocked_count must stay 0.
    rt = root;
    a = Task(title="a-done", completed=True);
    b = Task(title="b-pending", completed=False);
    dep = Task(title="still-blocked", completed=False);

    rt ++> a ++> b ++> dep;
    a +>:Blocks:+> dep;
    b +>:Blocks:+> dep;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = rt spawn UnblockCascade();
    }
    out = buf.getvalue();

    assert "still-blocked" in out, f"dependent not visited: {out}";
    assert "Ready to Work" not in out, (
        f"task was wrongly marked ready: {out}"
    );
    assert "still blocked" in out, f"missing still-blocked message: {out}";
    assert res.unlocked_count == 0, (
        f"unlocked_count must be 0, got {res.unlocked_count}"
    );
    assert dep.status == "pending", (
        f"status must stay pending, got {dep.status}"
    );
}

# ---------------------------------------------------------------------------
test "cycle detector finds a circular Blocks chain" {
    # Triangle: a --Blocks--> b --Blocks--> c --Blocks--> a.
    rt = root;
    a = Task(title="alpha");
    b = Task(title="beta");
    c = Task(title="gamma");
    rt ++> a ++> b ++> c;
    a +>:Blocks:+> b;
    b +>:Blocks:+> c;
    c +>:Blocks:+> a;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = rt spawn CycleDetector();
    }
    out = buf.getvalue();

    assert len(res.cycles_found) > 0, (
        f"expected at least one cycle, got {res.cycles_found}"
    );
    cycle_text = " -> ".join(res.cycles_found[0]);
    assert "alpha" in cycle_text and "beta" in cycle_text and "gamma" in cycle_text, (
        f"cycle missing expected nodes: {cycle_text}"
    );
    assert "Cycle detected" in out, f"missing cycle announcement: {out}";
}

# ---------------------------------------------------------------------------
test "dependency reacher follows Blocks edges and collects every dependent" {
    # Diamond: root --Blocks--> mid; mid --Blocks--> leaf1, leaf2.
    rt = root;
    mid = Task(title="mid");
    leaf1 = Task(title="leaf-1");
    leaf2 = Task(title="leaf-2");
    rt ++> mid ++> leaf1 ++> leaf2;
    rt +>:Blocks:+> mid;
    mid +>:Blocks:+> leaf1;
    mid +>:Blocks:+> leaf2;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = rt spawn DependencyReacher();
    }

    assert "mid" in res.reachable, (
        f"mid not reached, reachable={res.reachable}"
    );
    assert "leaf-1" in res.reachable, (
        f"leaf-1 not reached, reachable={res.reachable}"
    );
    assert "leaf-2" in res.reachable, (
        f"leaf-2 not reached, reachable={res.reachable}"
    );
    # Only follow Blocks edges; the generic [root-->] link to leaf2 must
    # not be followed as if it were a Blocks edge.
    assert len(res.reachable) == 3, (
        f"expected 3 reachable tasks, got {res.reachable}"
    );
}

