"""Regression tests for the API-key lifecycle auditor."""

import io;
import from contextlib { redirect_stdout }

test "active overlap and revoked counts match key states" {
    # 1 active, 1 overlap, 1 revoked -> counts must reflect each state.
    proj_a = Project(name="alpha", description="prod");
    proj_b = Project(name="beta", description="internal");

    k_act = APIKey(
        key_id="k-a-1", scope="read", fingerprint="fp:a1",
        created_at=1000, expires_at=3000, overlap_until=0
    );
    k_ov  = APIKey(
        key_id="k-a-2", scope="write", fingerprint="fp:a2",
        created_at=1500, expires_at=2000, overlap_until=2500
    );
    k_rev = APIKey(
        key_id="k-a-3", scope="admin", fingerprint="fp:a3",
        created_at=500, expires_at=1500, revoked=True
    );
    k_b   = APIKey(
        key_id="k-b-1", scope="read", fingerprint="fp:b1",
        created_at=1800, expires_at=4000, overlap_until=0
    );

    root ++> proj_a ++> proj_b;
    proj_a +>:Owns:+> k_act;
    proj_a +>:Owns:+> k_ov;
    proj_a +>:Owns:+> k_rev;
    proj_b +>:Owns:+> k_b;

    auditor = KeyAuditor();
    root spawn auditor;

    assert auditor.active_count == 2, f"active expected 2, got {auditor.active_count}";
    assert auditor.overlap_count == 1, f"overlap expected 1, got {auditor.overlap_count}";
    assert auditor.revoked_count == 1, f"revoked expected 1, got {auditor.revoked_count}";
}

test "overlap flag wins over expiry and revoked flag wins over both" {
    # A key with overlap_until > expires_at must be classified OVERLAP
    # even though it is past expires_at. A revoked key with overlap set
    # must still classify REVOKED (revoked beats overlap beats active).
    p = Project(name="p", description="d");
    p2 = Project(name="p2", description="d2");

    k_overlap = APIKey(
        key_id="ko", scope="write", fingerprint="fp:o",
        created_at=1000, expires_at=2000, overlap_until=2500
    );
    k_rev = APIKey(
        key_id="kr", scope="admin", fingerprint="fp:r",
        created_at=500, expires_at=9999, overlap_until=9999, revoked=True
    );

    root ++> p ++> p2;
    p +>:Owns:+> k_overlap;
    p2 +>:Owns:+> k_rev;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn KeyAuditor();
    }
    out = buf.getvalue();

    assert "[key OVERLAP]" in out, f"missing OVERLAP label: {out}";
    assert "[key REVOKED]" in out, f"missing REVOKED label: {out}";
    assert res.overlap_count == 1, f"overlap_count={res.overlap_count}";
    assert res.revoked_count == 1, f"revoked_count={res.revoked_count}";
    assert res.active_count == 0, f"active_count={res.active_count}";
}

test "typed Owns edge isolates per-project keys" {
    # Each project's APIKeys must be reachable only via its own Owns edge;
    # cross-project audit walk must NOT see another project's keys.
    proj_only = Project(name="only", description="d");

    k1 = APIKey(
        key_id="k1", scope="read", fingerprint="fp:1",
        created_at=1, expires_at=10, overlap_until=0
    );
    k2 = APIKey(
        key_id="k2", scope="write", fingerprint="fp:2",
        created_at=2, expires_at=20, overlap_until=0
    );

    ev1 = AuditEvent(event_id="e1", event_type="created", key_id="k1", note="n1");
    ev2 = AuditEvent(event_id="e2", event_type="created", key_id="k2", note="n2");

    root ++> proj_only;
    proj_only +>:Owns:+> k1;
    proj_only +>:Owns:+> k2;
    k1 +>:Emits:+> ev1;
    k2 +>:Emits:+> ev2;

    # Inspect graph shape directly using the typed edge.
    owned = [proj_only ->:Owns:->];
    assert len(owned) == 2, f"expected 2 owned keys, got {len(owned)}";
    assert k1 in owned and k2 in owned, f"owned keys wrong: {owned}";

    # Each key has exactly one Emits edge to its own audit event.
    for (k, expected_evt) in [(k1, ev1), (k2, ev2)] {
        events = [k ->:Emits:->];
        assert len(events) == 1, f"key {k.key_id} should have 1 event, got {len(events)}";
        assert events[0].event_id == expected_evt.event_id,
            f"key {k.key_id} event mismatch";
    }

    # Running the auditor must only see these two keys under this project.
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn KeyAuditor();
    }
    assert res.active_count == 2, f"active_count={res.active_count}";
    assert res.revoked_count == 0, f"revoked_count={res.revoked_count}";
    assert res.overlap_count == 0, f"overlap_count={res.overlap_count}";
}

test "audit events are printed via the Emits edge and union trigger" {
    # The record_event ability must fire for every AuditEvent reachable
    # via Emits from any visited APIKey — regardless of which key path
    # brought us there. The output must reference every event_type.
    p = Project(name="p", description="d");

    k = APIKey(
        key_id="k", scope="read", fingerprint="fp:k",
        created_at=1, expires_at=10, overlap_until=0
    );
    e1 = AuditEvent(event_id="e1", event_type="created", key_id="k", note="issued");
    e2 = AuditEvent(event_id="e2", event_type="rotated", key_id="k", note="overlap");
    e3 = AuditEvent(event_id="e3", event_type="revoked", key_id="k", note="manual");

    root ++> p;
    p +>:Owns:+> k;
    k +>:Emits:+> e1;
    k +>:Emits:+> e2;
    k +>:Emits:+> e3;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn KeyAuditor();
    }
    out = buf.getvalue();

    assert "[audit] created key=k" in out, f"missing created audit line: {out}";
    assert "[audit] rotated key=k" in out, f"missing rotated audit line: {out}";
    assert "[audit] revoked key=k" in out, f"missing revoked audit line: {out}";

    # Secrets must never appear — only the safe key_id and the note.
    assert "fp:k" not in out, f"fingerprint leaked into output: {out}";
}

test "rotation overlap window then revocation leaves one old and zero overlap" {
    # Simulates the documented flow: rotate an old key (overlap open) and
    # then revoke it. The auditor must report the revoked old key plus
    # the still-active new key — and the old key must NOT be counted as
    # overlap anymore once revoked=True.
    p = Project(name="p", description="d");

    k_old = APIKey(
        key_id="old", scope="read", fingerprint="fp:old",
        created_at=1, expires_at=100, overlap_until=200, revoked=True
    );
    k_new = APIKey(
        key_id="new", scope="write", fingerprint="fp:new",
        created_at=50, expires_at=500, overlap_until=0
    );

    root ++> p;
    p +>:Owns:+> k_old;
    p +>:Owns:+> k_new;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn KeyAuditor();
    }
    out = buf.getvalue();

    assert res.revoked_count == 1, f"revoked_count={res.revoked_count}";
    assert res.overlap_count == 0, f"overlap_count should be 0 after revoke, got {res.overlap_count}";
    assert res.active_count == 1, f"active_count={res.active_count}";
    assert "[key REVOKED] id=old" in out, f"missing old revoked label: {out}";
    assert "[key ACTIVE] id=new" in out, f"missing new active label: {out}";
}

