        contracts=[
            Contract(name="contract-ok", still_honored=True),
            Contract(name="contract-broken", still_honored=False),
        ],
    );

    f_guard = Fix(
        title="reorder guard",
        kind="guard",
        blast_radius_checked=False,
        guards=[Guard(name="dead-guard", previously_reachable=False)],
    );

    c.fixes = [f_sig, f_out, f_guard];
    root ++> c;

    buf = io.StringIO();
    critic = Critic();
    with redirect_stdout(buf) {
        res = root spawn critic;
    }
    out = buf.getvalue();

    assert "stale caller: caller-stale does not handle new signature" in out, (
        f"sig fix should name the stale caller: {out}"
    );
    assert "caller-ok" not in out, (
        f"caller that handles new shape should not be flagged: {out}"
    );
    assert "contract violated: contract-broken" in out, (
        f"out fix should name the broken contract: {out}"
    );
    assert "contract-ok" not in out, (
        f"honored contract should not be flagged: {out}"
    );
    assert "guard dead-guard used to be reachable, no longer is" in out, (
        f"guard fix should name the unreachable guard: {out}"
    );
}


