"""Tests for transitive skill dependency resolution with cycle/conflict guards."""

import io;
import from contextlib { redirect_stdout }

test "flat lock dedupes by git@commit:path" {
    utils = Skill(
        name="common-utils",
        git="https://git.example/common-utils",
        commit="ddd111",
        path="/"
    );
    lint = Skill(
        name="linting",
        git="https://git.example/linting",
        commit="bbb222",
        path="/skills/lint"
    );
    test_skill = Skill(
        name="testing",
        git="https://git.example/testing",
        commit="ccc333",
        path="/skills/test"
    );
    codegen = Skill(
        name="codegen",
        git="https://git.example/codegen",
        commit="aaa000",
        path="/skills/codegen"
    );
    docs = Skill(
        name="docs-helper",
        git="https://git.example/docs",
        commit="eee444",
        path="/skills/docs"
    );

    lint +>:DependsOn(spec="main"):+> utils;
    test_skill +>:DependsOn(spec="^1.0"):+> utils;
    codegen +>:DependsOn(spec="latest"):+> lint;
    codegen +>:DependsOn:+> test_skill;
    docs +>:DependsOn(spec="main"):+> utils;

    manifest = Manifest(title="project ai.json");
    root ++> manifest;
    manifest +>:ListedIn:+> codegen;
    manifest +>:ListedIn:+> docs;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn DependencyResolver();
    }
    out = buf.getvalue();

    assert "--- ai.lock (flat, deduped by git@commit:path) ---" in out
        , f"missing lock header: {out}";
    assert "common-utils: https://git.example/common-utils@ddd111:/" in out
        , f"utils line missing: {out}";
    assert "linting: https://git.example/linting@bbb222:/skills/lint" in out
        , f"linting line missing: {out}";
    assert "testing: https://git.example/testing@ccc333:/skills/test" in out
        , f"testing line missing: {out}";
    assert "codegen: https://git.example/codegen@aaa000:/skills/codegen" in out
        , f"codegen line missing: {out}";
    assert "docs-helper: https://git.example/docs@eee444:/skills/docs" in out
        , f"docs line missing: {out}";

    assert "cycle guards tripped:" not in out, f"unexpected cycles: {out}";
    assert "version conflicts" not in out, f"unexpected conflicts: {out}";

    utils_count = 0;
    for line in res.lock {
        if "common-utils:" in line {
            utils_count += 1;
        }
    }
    assert utils_count == 1, f"utils should appear exactly once in flat list, got {utils_count}";
}

