test "LoadAuditor GO verdict when thermal, gates, and fallback all clean" {
    root ++> Feed(name="epsilon", episode_quota=2);
    epsilon = [root -->][?:Feed][0];
    e1 = Episode(label="ep-1", gpu_temp_peak=68.0, gpu_util_avg=42.0, gates_pass=True);
