test "project graph contains exactly one image and two build services" {
    api = Service(name="api", kind="image", image_ref="nginx:1.27");
    worker = Service(name="worker", kind="build", context="./worker");
    web = Service(name="web", kind="build", context="./web");
    proj = Project(name="vat-compose");

    root ++> proj;
    proj +>:Expands:+> api;
    proj +>:Expands:+> worker;
    proj +>:Expands:+> web;
    api +>:DependsOn:+> worker;
    worker +>:DependsOn:+> web;

    # One Project reachable from root.
    projects = [root -->];
    assert len(projects) == 1, f"expected 1 project, got {len(projects)}";
    p = projects[0];
    assert isinstance(p, Project), f"expected Project node, got {type(p)}";

    # Three services reachable from the project via Expands.
    services = [p ->:Expands:->];
    assert len(services) == 3, f"expected 3 services via Expands, got {len(services)}";

    kinds = sorted([s.kind for s in services]);
    assert kinds == ["build", "build", "image"], f"unexpected kind distribution: {kinds}";

