    build_svcs = [s for s in services if s.kind == "build"];
    assert len(image_svcs) == 1, f"expected 1 image service, got {len(image_svcs)}";
    assert len(build_svcs) == 2, f"expected 2 build services, got {len(build_svcs)}";

