test "direct-only role returns its own permissions" {
    rt = Role(name="root", permissions=[]);
    viewer = Role(name="viewer", permissions=["read"]);
    rt ++> viewer;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        inspector = RoleInspector(role_name="viewer");
        rt spawn inspector;
    }
    assert inspector.effective == ["read"], f"got {inspector.effective}";
}

test "transitive inheritance unions all ancestor permissions" {
    rt = Role(name="root", permissions=[]);
    editor = Role(name="editor", permissions=["read", "write"]);
    author = Role(name="author", permissions=["publish"]);
    admin = Role(name="admin", permissions=["manage"]);
    rt ++> editor;
    rt ++> author;
    rt ++> admin;

    admin +>:Inherits:+> author;
    author +>:Inherits:+> editor;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        inspector = RoleInspector(role_name="admin");
        rt spawn inspector;
    }
    assert inspector.effective == ["manage", "publish", "read", "write"], (
        f"expected transitive union, got {inspector.effective}"
    );
}

test "cyclic inheritance terminates and still unions permissions" {
    rt = Role(name="root", permissions=[]);
    editor = Role(name="editor", permissions=["read", "write"]);
    author = Role(name="author", permissions=["publish"]);
    rt ++> editor;
    rt ++> author;

    editor +>:Inherits:+> author;
    author +>:Inherits:+> editor;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        inspector = RoleInspector(role_name="editor");
        rt spawn inspector;
    }
    # Cycle must terminate; both roles' permissions must be present.
    assert "read" in inspector.effective, f"missing read: {inspector.effective}";
    assert "write" in inspector.effective, f"missing write: {inspector.effective}";
    assert "publish" in inspector.effective, f"missing publish: {inspector.effective}";
    assert len(inspector.effective) == 3, f"expected 3 unique perms, got {inspector.effective}";
}

test "unknown role returns empty effective permissions" {
    rt = Role(name="root", permissions=[]);
    editor = Role(name="editor", permissions=["read"]);
    rt ++> editor;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        inspector = RoleInspector(role_name="ghost");
        rt spawn inspector;
    }
    assert inspector.effective == [], f"expected [], got {inspector.effective}";
}

test "deep chain unions all ancestor permissions without duplication" {
    rt = Role(name="root", permissions=[]);
    base = Role(name="base", permissions=["x"]);
    mid = Role(name="mid", permissions=["y"]);
    top = Role(name="top", permissions=["z"]);
    rt ++> base;
    rt ++> mid;
    rt ++> top;

    top +>:Inherits:+> mid;
    mid +>:Inherits:+> base;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        inspector = RoleInspector(role_name="top");
        rt spawn inspector;
    }
    assert inspector.effective == ["z", "y", "x"], (
        f"expected deep chain union, got {inspector.effective}"
    );
    assert len(inspector.effective) == 3, f"unexpected dupes: {inspector.effective}";
}

