test "recursive planner preserves validated dependency order" {
    sg = SubGraph(reason="recursive expansion");

    deploy = PlanTask(title="deploy", task_id=4, insert_order=1);
    compile = PlanTask(title="compile", task_id=3, insert_order=2);
    lint = PlanTask(title="lint", task_id=1, insert_order=3);
    test_task = PlanTask(title="test", task_id=2, insert_order=4);

    sg ++> deploy;
    sg ++> compile;
    sg ++> lint;
    sg ++> test_task;

    deploy +>:DependsOn:+> compile;
    compile +>:DependsOn:+> lint;
    lint +>:DependsOn:+> test_task;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = sg spawn RecursivePlanner(discard_validated=False);
    }
    out = buf.getvalue();

    assert "[FIX: returned validated fromTasks graph]" in out, f"unexpected output: {out}";
    assert out.index("-> test (insert_order=4)") < out.index("-> lint (insert_order=3)"), f"wrong dependency order: {out}";
    assert out.index("-> lint (insert_order=3)") < out.index("-> compile (insert_order=2)"), f"wrong dependency order: {out}";
    assert out.index("-> compile (insert_order=2)") < out.index("-> deploy (insert_order=1)"), f"wrong dependency order: {out}";
}

test "graph retains chain shape and typed dependency direction" {
    sg = SubGraph(reason="recursive expansion");

    deploy = PlanTask(title="deploy", task_id=4, insert_order=1);
    compile = PlanTask(title="compile", task_id=3, insert_order=2);
    lint = PlanTask(title="lint", task_id=1, insert_order=3);
    test_task = PlanTask(title="test", task_id=2, insert_order=4);

    sg ++> deploy ++> compile ++> lint ++> test_task;
    compile +>:DependsOn:+> lint;
    compile +>:DependsOn:+> test_task;
    deploy +>:DependsOn:+> compile;

    assert len([sg -->]) == 1, f"expected one direct child, got {len([sg -->])}";
    assert compile in [deploy -->], f"compile is not reachable from deploy";
    assert lint in [compile -->], f"lint is not reachable from compile";
    assert test_task in [lint -->], f"test is not reachable from lint";
    assert len([compile ->:DependsOn:->]) == 2, f"wrong dependency count";
    assert lint in [compile ->:DependsOn:->], f"compile does not depend on lint";
    assert test_task in [compile ->:DependsOn:->], f"compile does not depend on test";
    assert compile in [deploy ->:DependsOn:->], f"deploy does not depend on compile";
}

test "cycle detection fails closed" {
    sg = SubGraph(reason="cycle probe");

    task_a = PlanTask(title="task_a", task_id=10, insert_order=1);
    task_b = PlanTask(title="task_b", task_id=11, insert_order=2);

    sg ++> task_a ++> task_b;
