"""Tests for restart-warm canonical fact persistence lifecycle."""

import io;
import from contextlib { redirect_stdout }

test "warm lifecycle admits fresh and rejects stale shards" {
    root ++> proj ++> store ++> a1 ++> a2;

    proj = ProjectModel(name="perl-lsp-swarm", generation=7);
    s1 = FactShard(family="symbol_index", producer="scanner",
                   stable_identity="symidx-v3", generation=7);
    s2 = FactShard(family="outline", producer="parser",
                   stable_identity="outline-v1", generation=6, stale=True);
    s3 = FactShard(family="diagnostics", producer="typecheck",
                   stable_identity="diag-v2", generation=7);
    store = SnapshotStore(backend="directory", namespace="proj-7",
                          persisted_count=2);
    a1 = ProjectFactArtifact(family="symbol_index", identity="symidx-v3",
                             generation=7, compatible=True);
    a2 = ProjectFactArtifact(family="outline", identity="outline-v1",
                             generation=5, compatible=False);

    root ++> proj;
    proj +>:OwnsShard:+> s1;
    proj +>:OwnsShard:+> s2;
    proj +>:OwnsShard:+> s3;
    s1 +>:StoredIn:+> store;
    s2 +>:StoredIn:+> store;
    s3 +>:StoredIn:+> store;
    store +>:AdoptedFrom:+> a1;
    store +>:AdoptedFrom:+> a2;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        warm = WarmLifecycle();
        root spawn warm;
    }
    out = buf.getvalue();

    # Two non-stale shards admitted, one stale rejected.
    assert warm.admitted == 2, f"expected 2 admitted, got {warm.admitted}";
    assert warm.rejected == 1, f"expected 1 rejected (stale), got {warm.rejected}";
    assert "[admit ]" in out, f"missing admit marker: {out}";
    assert "[reject] stale shard family=outline" in out, f"missing stale reject: {out}";
}

test "snapshot store budget rejects overflow and corruption" {
    proj = ProjectModel(name="budget-test", generation=1);
    s1 = FactShard(family="symbols", producer="scanner",
                   stable_identity="s1", generation=1);
    s2 = FactShard(family="outline", producer="parser",
