    proj +>:OwnsShard:+> s1;
    proj +>:OwnsShard:+> s2;
    s1 +>:StoredIn:+> store;
    s2 +>:StoredIn:+> store;
    s1 +>:StoredIn:+> bad_store;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        warm = WarmLifecycle(checkpoint_budget=8);
        root spawn warm;
    }
    out = buf.getvalue();

    # Corrupt store contributes 1 rejection; over-budget store contributes 1 rejection.
    assert warm.rejected >= 2, f"expected at least 2 rejections, got {warm.rejected}";
    assert "over budget" in out, f"missing over-budget reject: {out}";
    assert "corrupt -> cold path" in out, f"missing corrupt reject: {out}";
}

