test "cascade invalidation marks project and dependent shards stale" {
    proj = ProjectModel(name="cascade-test", generation=5);
    s1 = FactShard(family="symbols", producer="scanner",
                   stable_identity="s1", generation=5);
    s2 = FactShard(family="outline", producer="parser",
                   stable_identity="o1", generation=5);
    s3 = FactShard(family="diagnostics", producer="typecheck",
                   stable_identity="d1", generation=5);
    store = SnapshotStore(backend="directory", namespace="ns",
                          persisted_count=3);

    root ++> proj;
    proj +>:OwnsShard:+> s1;
    proj +>:OwnsShard:+> s2;
    proj +>:OwnsShard:+> s3;
    s1 +>:StoredIn:+> store;
    s2 +>:StoredIn:+> store;
    s3 +>:StoredIn:+> store;

    cascade = CascadeInvalidate();
    root spawn cascade;

    # 1 project + 3 shards cascaded = 4 invalidations.
    assert cascade.invalidations == 4, f"expected 4 invalidations, got {cascade.invalidations}";
    assert proj.invalidated == True, f"project should be invalidated, got {proj.invalidated}";
    assert s1.stale == True, f"s1 should be stale, got {s1.stale}";
    assert s2.stale == True, f"s2 should be stale, got {s2.stale}";
    assert s3.stale == True, f"s3 should be stale, got {s3.stale}";
}

test "invalidated project causes warm shards to be rejected on re-walk" {
    proj = ProjectModel(name="rejection-test", generation=2);
    s1 = FactShard(family="symbols", producer="scanner",
                   stable_identity="s1", generation=2);
    s2 = FactShard(family="outline", producer="parser",
                   stable_identity="o1", generation=2);
    store = SnapshotStore(backend="directory", namespace="ns",
                          persisted_count=1);
    a1 = ProjectFactArtifact(family="symbols", identity="s1",
                             generation=2, compatible=True);

    root ++> proj;
    proj +>:OwnsShard:+> s1;
    proj +>:OwnsShard:+> s2;
    s1 +>:StoredIn:+> store;
    s2 +>:StoredIn:+> store;
    store +>:AdoptedFrom:+> a1;

    # Pre-invalidate the project — its shards should now be treated as stale
    # by the cascade walker, then rejected by the warm lifecycle walker.
    cascade = CascadeInvalidate();
    root spawn cascade;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        warm = WarmLifecycle();
        root spawn warm;
    }
    out = buf.getvalue();

    assert proj.invalidated == True, f"project should be invalidated, got {proj.invalidated}";
    assert s1.stale == True, f"s1 should be stale after cascade, got {s1.stale}";
    assert s2.stale == True, f"s2 should be stale after cascade, got {s2.stale}";
    # Both shards are now stale -> both rejected by warm lifecycle.
    assert warm.rejected >= 2, f"expected at least 2 rejected after cascade, got {warm.rejected}";
    assert "stale shard" in out, f"missing stale shard rejection: {out}";
}

