"""Tests for SkillTurnExecutor: budget enforcement, idempotency, and conflict detection."""

import io;
import from contextlib { redirect_stdout }

test "fresh call executes and records evidence" {
    chat = Question(thread_id="chat-A");
    turn = SkillTurn(max_calls=4, cpu_budget_ms=100, wall_budget_ms=200);
    root ++> chat;
    chat +>:Hosts:+> turn;

    call = SkillCall(
        tool_call_id="tc-1",
        fingerprint="fp-alpha",
        script_path="summarize.py",
        cpu_cost_ms=30,
        wall_cost_ms=40,
    );
    turn +>:ScheduledIn(seq=1):+> call;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn SkillTurnExecutor();
    }
    out = buf.getvalue();

    assert "[EXECUTE] tc-1 summarize.py" in out, f"missing execute line: {out}";
    assert res.executed == 1, f"expected 1 executed, got {res.executed}";
    assert res.replayed == 0, f"expected 0 replayed, got {res.replayed}";
    assert res.conflicts == 0, f"expected 0 conflicts, got {res.conflicts}";
    assert res.budget_rejects == 0, f"expected 0 rejects, got {res.budget_rejects}";
    assert turn.calls_consumed == 1, f"expected calls_consumed=1, got {turn.calls_consumed}";
    assert turn.cpu_consumed_ms == 30, f"expected cpu=30, got {turn.cpu_consumed_ms}";
    assert turn.wall_consumed_ms == 40, f"expected wall=40, got {turn.wall_consumed_ms}";
    assert len([chat->:EvidenceSlot:->]) == 1, "expected 1 evidence slot on host";
    assert len([call->:RecordedAs:->]) == 1, "expected 1 RecordedAs edge from call";
}

