    turn = SkillTurn(max_calls=1, cpu_budget_ms=1000, wall_budget_ms=2000);
    root ++> chat;
    chat +>:Hosts:+> turn;

    first = SkillCall(
        tool_call_id="tc-1",
        fingerprint="fp-a",
        script_path="a.py",
        cpu_cost_ms=10,
        wall_cost_ms=10,
    );
    second = SkillCall(
        tool_call_id="tc-2",
        fingerprint="fp-b",
        script_path="b.py",
        cpu_cost_ms=10,
        wall_cost_ms=10,
    );
    turn +>:ScheduledIn(seq=1):+> first;
    turn +>:ScheduledIn(seq=2):+> second;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn SkillTurnExecutor();
    }
    out = buf.getvalue();

    assert "[EXECUTE] tc-1 a.py" in out, f"missing first execute: {out}";
    assert "[REJECT] tc-2 call cap exceeded" in out, f"missing cap reject line: {out}";
    assert res.executed == 1, f"expected 1 executed, got {res.executed}";
    assert res.budget_rejects == 1, f"expected 1 reject, got {res.budget_rejects}";
    assert turn.calls_consumed == 1, f"calls_consumed must stay at 1, got {turn.calls_consumed}";
}

"""Tests for the ArchLinterNet attribution demo.

The issue demands a clean attribution boundary: per-process work that the
consumer's repeated-process CI shape incurs against one unchanged build.
We assert that:

  * each ProcessRun sees every Project and every Contract (no silent skip),
  * Contract evaluation actually traverses the typed edge neighborhood
    (so the per-process graph cost is observable),
  * the walker accumulates per-phase timers and a fresh per-process run
    builds its own timer list (so we can attribute phase cost per process),
  * the Attribution walker fans out to every PhaseTimer record and counts
    discovery phases correctly (so dominant hot path is visible).
"""

import io;
import from contextlib { redirect_stdout }

# ---------- ProcessRun sees every Project and every Contract ----------

test "process_run_visits_all_projects_and_contracts" {
    root ++> Project(name="P1", source_files=10, types=50);
    root ++> Project(name="P2", source_files=20, types=80);
    root ++> Contract(rule="r1", selector_cardinality=2);
    root ++> Contract(rule="r2", selector_cardinality=3);
    root ++> Contract(rule="r3", selector_cardinality=1);

    run = ProcessRun(pid=0);
    root spawn run;

    assert run.project_count == 2, f"expected 2 projects visited, got {run.project_count}";
    assert run.contract_count == 3, f"expected 3 contracts visited, got {run.contract_count}";
}

# ---------- Contract evaluation actually touches typed edges ----------

test "contract_evaluation_traverses_outgoing_edges" {
    p1 = Project(name="P1", source_files=10, types=50);
    p2 = Project(name="P2", source_files=20, types=80);
    p3 = Project(name="P3", source_files=30, types=120);
    root ++> p1;
    root ++> p2;
    root ++> p3;

    rule = Contract(rule="reach-all", selector_cardinality=5);
    root ++> rule;
    rule +>:Evaluates(mode="transitive"):+> p1;
    rule +>:Evaluates(mode="transitive"):+> p2;
    rule +>:Evaluates(mode="transitive"):+> p3;

    run = ProcessRun(pid=0);
    root spawn run;

    # 3 outgoing Evaluates edges from the Contract.
    assert run.edge_count == 3, f"expected 3 edges traversed, got {run.edge_count}";
    # findings = sum of selector_cardinality across visited contracts.
    assert run.findings == 5, f"expected 5 findings (selector_cardinality), got {run.findings}";
}

# ---------- Per-phase timer is recorded once per process run ----------

test "each_process_run_records_one_discovery_timer" {
    root ++> Project(name="Solo", source_files=1, types=1);
    root ++> Contract(rule="only", selector_cardinality=0);

    run1 = ProcessRun(pid=0);
    root spawn run1;
    run2 = ProcessRun(pid=1);
    root spawn run2;

    # Each fresh ProcessRun must build its own phase_log, not share one.
    assert len(run1.phase_log) == 1, f"run1 phase_log len={len(run1.phase_log)}";
    assert len(run2.phase_log) == 1, f"run2 phase_log len={len(run2.phase_log)}";
    assert run1.phase_log[0].phase == "discovery", f"run1 phase={run1.phase_log[0].phase}";
    assert run2.phase_log[0].phase == "discovery", f"run2 phase={run2.phase_log[0].phase}";
    # Independent timer nodes, not the same instance.
    assert run1.phase_log[0] is not run2.phase_log[0], "timers must be independent per process";
}

# ---------- Duration() math on PhaseTimer is non-negative ----------

test "phase_timer_duration_is_non_negative" {
    root ++> Project(name="P", source_files=1, types=1);
    run = ProcessRun(pid=0);
    root spawn run;
    timer = run.phase_log[0];
    d = timer.duration_ms();
    assert d >= 0.0, f"duration must be non-negative, got {d}";
    # PhaseTimer must record its own phase label.
    assert timer.phase == "discovery", f"unexpected phase label: {timer.phase}";
}

# ---------- Attribution walker observes every timer and counts discovery ----------

test "attribution_walker_observes_all_timers" {
    # 3 projects + 1 contract means each ProcessRun will plant exactly one
    # discovery timer. Three independent runs -> three timers.
    root ++> Project(name="A", source_files=1, types=1);
    root ++> Project(name="B", source_files=1, types=1);
    root ++> Project(name="C", source_files=1, types=1);
    root ++> Contract(rule="x", selector_cardinality=0);

    for i in range(3) {
        r = ProcessRun(pid=i);
        root spawn r;
    }

    buf = io.StringIO();
    with redirect_stdout(buf) {
        attr = Attribution();
        root spawn attr;
    }
    out = buf.getvalue();

    # Attribution must see 3 distinct phase records and the discovery
    # count must equal the number of process runs (one discovery each).
    assert len(attr.per_process_durations) == 3, (
        f"expected 3 phase records, got {len(attr.per_process_durations)}"
    );
    assert attr.per_process_durations.count("discovery") == 3, (
        f"expected 3 discovery labels, got {attr.per_process_durations}"
    );
    assert attr.total_findings == 3, (
        f"expected total_findings=3 (one per process), got {attr.total_findings}"
    );
    assert "Attribution:" in out, f"missing Attribution line in output: {out}";
}

test "terminal cancellation revokes awaited descendants only" {
    terminal = Run(name="run-terminal", is_terminal=True);
    worker = Session(name="worker", busy=True);
    grandchild = Session(name="grandchild");
    detached = Session(name="detached");

    terminal +>:Ask:+> worker;
    worker +>:Ask:+> grandchild;
    terminal +>:Tell:+> detached;

    worker.lease_count = 1;
    grandchild.lease_count = 1;
    root ++> terminal;

    cascade = CancelCascade();
    root spawn cascade;

    assert terminal.revoked, f"terminal revoked={terminal.revoked}";
    assert worker.revoked, f"worker revoked={worker.revoked}";
    assert grandchild.revoked, f"grandchild revoked={grandchild.revoked}";
    assert not detached.revoked, f"detached revoked={detached.revoked}";
    assert worker.lease_count == 0, f"worker leases={worker.lease_count}";
    assert grandchild.lease_count == 0, f"grandchild leases={grandchild.lease_count}";
    assert len(cascade.torn) == 3, f"torn={cascade.torn}";
}

test "remaining lease prevents child revocation" {
    terminal = Run(name="terminal", is_terminal=True);
    worker = Session(name="shared-worker");
    terminal +>:Ask:+> worker;
    worker.lease_count = 2;
    root ++> terminal;

    cascade = CancelCascade();
    root spawn cascade;

    assert terminal.revoked, f"terminal revoked={terminal.revoked}";
    assert not worker.revoked, f"worker revoked={worker.revoked}";
    assert worker.lease_count == 1, f"worker leases={worker.lease_count}";
    assert len(cascade.torn) == 1, f"torn={cascade.torn}";
}

test "fulfilled sessions reclaim gracefully and runaway sessions sweep forcefully" {
    idle = Session(name="idle-fulfilled", fulfilled=True, is_idle=True);
    busy = Session(name="busy-fulfilled", fulfilled=True, is_idle=False, busy=True);
    runaway = Session(name="runaway-zombie", is_idle=False, churn_steps=5);
    root ++> idle;
    root ++> busy;
    root ++> runaway;

    reclaimer = IdleReclaim();
    root spawn reclaimer;

    assert "idle-fulfilled" in reclaimer.fulfilled_names,
        f"fulfilled={reclaimer.fulfilled_names}";
    assert "busy-fulfilled" in reclaimer.fulfilled_names,
        f"fulfilled={reclaimer.fulfilled_names}";
    assert "runaway-zombie" in reclaimer.forceful_names,
        f"forceful={reclaimer.forceful_names}";
}

test "revoked sessions are excluded from graceful reclaim" {
    revoked = Session(name="already-revoked", fulfilled=True, revoked=True);
    healthy = Session(name="healthy", fulfilled=True, is_idle=True);
    root ++> revoked;
    root ++> healthy;

    reclaimer = IdleReclaim();
    root spawn reclaimer;

    assert not "already-revoked" in reclaimer.fulfilled_names,
        f"fulfilled={reclaimer.fulfilled_names}";
    assert not "already-revoked" in reclaimer.forceful_names,
        f"forceful={reclaimer.forceful_names}";
    assert "healthy" in reclaimer.fulfilled_names,
        f"fulfilled={reclaimer.fulfilled_names}";
}

"""Regression tests for the runtime partition kernel demo.

The issue promises runtime/source-subject partition isolation: a SourcePartition
is the semantic boundary, runtime partitions are ADMITTED into the BOM audit
while subject partitions are only OBSERVED, and projection families attached
to the runtime partition must be enumerated by a traversal that respects
the embedded/external placement edges.
"""

import io;
import from contextlib { redirect_stdout }

# ---- 1. Embedded placement: both partitions live under the dotfiles surface

test "embedded placement admits runtime and observes subject" {
    root ++> RepositorySurface(surface_name="dotfiles", vcs="embedded");

    embedded = [root -->][0];
    runtime_p = SourcePartition(partition_name="codex-runtime", role="runtime", root_path=".codex/repo-runtime/");
    subject_p = SourcePartition(partition_name="dotfiles", role="subject", root_path="./");

    embedded +>:HoldsPartition(placement="embedded"):+> runtime_p;
    embedded +>:HoldsPartition(placement="embedded"):+> subject_p;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn RuntimeBomAuditor();
    }
    out = buf.getvalue();

    assert "surface[dotfiles] vcs=embedded" in out, f"missing surface line: {out}";
    assert "partition[codex-runtime] role=runtime -> ADMITTED" in out, f"runtime not admitted: {out}";
    assert "partition[dotfiles] role=subject -> OBSERVED" in out, f"subject not observed: {out}";
    assert res.total_records == 0, f"runtime partition has no families yet, got {res.total_records}";
}

# ---- 2. External placement: runtime lives on its own surface, still admitted

test "external placement keeps runtime admitted" {
    root ++> RepositorySurface(surface_name="codex-runtime", vcs="external");

    external = [root -->][0];
    runtime_p = SourcePartition(partition_name="codex-runtime", role="runtime", root_path=".codex/repo-runtime/");

    external +>:HoldsPartition(placement="external"):+> runtime_p;
    runtime_p +>:EmitsProjection(contract="ProducerProjection/v1", admitted=True):+>
        ProjectionFamily(family_name="uv-workspace", integration="uv-projection", records=3)
        +>:BelongsToFamily(priority=1):+>
        ProjectionFamily(family_name="lock-state", integration="uv-lock-projection", records=1);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn RuntimeBomAuditor();
    }
    out = buf.getvalue();

    assert "surface[codex-runtime] vcs=external" in out, f"missing external surface line: {out}";
    assert "partition[codex-runtime] role=runtime -> ADMITTED" in out, f"runtime not admitted externally: {out}";
    assert res.total_records == 2, f"expected 2 family records, got {res.total_records}";
    assert res.observed_families == ["uv-workspace", "lock-state"], f"wrong order/contents: {res.observed_families}";

    # The families must have been mutated to observed=True exactly once.
    families = [runtime_p ->:EmitsProjection:->];
    assert all(f.observed for f in families), f"some families not observed: {[(f.family_name, f.observed) for f in families]}";
    for f in families {
        assert f.records == f.records and f.observed, f"family {f.family_name} not flagged observed";
    }
}

# ---- 3. Subject partition is never admitted even if it carries a projection edge

test "subject partition projections are not enumerated" {
    root ++> RepositorySurface(surface_name="dotfiles", vcs="embedded");

    embedded = [root -->][0];
    runtime_p = SourcePartition(partition_name="codex-runtime", role="runtime", root_path=".codex/repo-runtime/");
    subject_p = SourcePartition(partition_name="dotfiles", role="subject", root_path="./");

    embedded +>:HoldsPartition(placement="embedded"):+> runtime_p;
    embedded +>:HoldsPartition(placement="embedded"):+> subject_p;

    # Even if a subject partition somehow carries an EmitsProjection edge,
    # the auditor must only enumerate families reachable from admitted
    # (runtime) partitions — and the demo walker visits partitions via the
    # HoldsPartition edge, so subject projections on subject partitions are
    # not crossed.
    subject_p +>:EmitsProjection(contract="ProducerProjection/v1", admitted=True):+>
        ProjectionFamily(family_name="should-not-be-seen", integration="leaky", records=99);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn RuntimeBomAuditor();
    }
    out = buf.getvalue();

    assert "should-not-be-seen" not in out, f"subject projection leaked into audit: {out}";
    assert res.total_records == 0, f"subject families must not be counted, got {res.total_records}";
}

# ---- 4. Graph shape: typed edges carry the placement/contract meaning

test "edge graph structure matches the issue's two placements" {
    root ++> RepositorySurface(surface_name="dotfiles", vcs="embedded");
    embedded = [root -->][0];

    runtime_p = SourcePartition(partition_name="codex-runtime", role="runtime", root_path=".codex/repo-runtime/");
    subject_p = SourcePartition(partition_name="dotfiles", role="subject", root_path="./");

    embedded +>:HoldsPartition(placement="embedded"):+> runtime_p;
    embedded +>:HoldsPartition(placement="embedded"):+> subject_p;

    # The embedded surface must hold both partitions via HoldsPartition.
    held = [embedded ->:HoldsPartition:->];
    assert len(held) == 2, f"expected 2 held partitions, got {len(held)}";
    assert runtime_p in held and subject_p in held, f"missing partition in held: {held}";

    # Runtime partition must have no BelongsToFamily chain until we attach
    # one — the issue's runtime is initially a clean source partition.
    assert [runtime_p ->:EmitsProjection:->] == [], "runtime partition should start with no projections";
}

"""Regression tests for the FreeFlow PATH-shadow recursion model.

These tests build per-test mini-graphs that mirror the program's
demonstration, spawn the ChainInspector walker on each, and assert on the
walker.reports list — exercising the four fail-closed safeguards the
issue's "Expected behavior" list asks for:

  1. plugin must use an absolute/plugin-local entry point (no ambient PATH)
  2. hook must reap its process group on timeout/failure
  3. resolved binary must not self-delegate back to the same package
  4. descent must be bounded by the depth limit (process-tree cap)
"""

import io;
import from contextlib { redirect_stdout }

test "healthy chain descends end-to-end with no FAIL-CLOSED" {
    root ++> Plugin(
        name="@freematters/freeflow",
        hook_command="fflow _hook post-tool-use",
        absolute_entry="/opt/freeflow/dist/cli.js",
    );
    p = [root -->][?:Plugin][0];
    p ++> Hook(
        stage="post-tool-use",
        timeout_s=10,
        from_path=False,
        terminates_tree=True,
    );
    h = [p -->][?:Hook][0];
    h ++> ResolvedBinary(
        label="/opt/freeflow/dist/cli.js",
        self_delegates=False,
        terminates_tree=True,
    );
    b = [h -->][?:ResolvedBinary][0];
    b ++> Target(package="@freematters/freeflow", kind="cli-entry");

    res = root spawn ChainInspector(depth_limit=4, chain_label="healthy");
    reports = res.report;

    assert len(reports) == 4, f"healthy chain should report 4 lines, got {len(reports)}: {reports}";
    assert "deterministic=yes" in reports[0], f"plugin entry should be deterministic, got: {reports[0]}";
    assert "termination_guard=ok" in reports[1], f"hook guard should be ok, got: {reports[1]}";
    assert "self_delegates=False" in reports[2], f"binary should not self-delegate, got: {reports[2]}";
    assert "target reached" in reports[3], f"target should be reached, got: {reports[3]}";

    for line in reports {
        assert "FAIL-CLOSED" not in line, f"healthy chain must not emit FAIL-CLOSED, got: {line}";
    }
}

test "plugin with empty absolute_entry fails closed on ambient PATH" {
    root ++> Plugin(
        name="@freematters/freeflow",
        hook_command="fflow _hook post-tool-use",
        absolute_entry="",
    );

    res = root spawn ChainInspector(depth_limit=4, chain_label="path-shadow");
    reports = res.report;

    assert len(reports) == 2, f"should report plugin line + one FAIL-CLOSED, got {len(reports)}: {reports}";
    assert "deterministic=NO (PATH)" in reports[0], f"plugin should be flagged non-deterministic, got: {reports[0]}";
    assert "FAIL-CLOSED: hook uses ambient PATH, not plugin-local entry" in reports[1], f"expected PATH fail-closed, got: {reports[1]}";
}

test "hook that does not reap its process group fails closed" {
    root ++> Plugin(
        name="@freematters/freeflow",
        hook_command="fflow _hook post-tool-use",
        absolute_entry="/opt/freeflow/dist/cli.js",
    );
    p = [root -->][?:Plugin][0];
    p ++> Hook(
        stage="post-tool-use",
        timeout_s=10,
        from_path=False,
        terminates_tree=False,
    );

    res = root spawn ChainInspector(depth_limit=4, chain_label="no-reap");
    reports = res.report;

    assert any("termination_guard=weak" in line for line in reports), f"hook guard should be weak, got: {reports}";
    assert any("FAIL-CLOSED: hook does not reap its process group" in line for line in reports), f"expected process-group fail-closed, got: {reports}";
    assert not any("target reached" in line for line in reports), f"walker should disengage before reaching target, got: {reports}";
}

test "binary that self-delegates to the same package fails closed" {
    root ++> Plugin(
        name="@freematters/freeflow",
        hook_command="fflow _hook post-tool-use",
        absolute_entry="/opt/freeflow/dist/cli.js",
    );
    p = [root -->][?:Plugin][0];
    p ++> Hook(
        stage="post-tool-use",
        timeout_s=10,
        from_path=False,
        terminates_tree=True,
    );
    h = [p -->][?:Hook][0];
    h ++> ResolvedBinary(
        label="local-shim/fflow",
        self_delegates=True,
        terminates_tree=True,
    );

    res = root spawn ChainInspector(depth_limit=4, chain_label="self-loop");
    reports = res.report;

    assert any("self_delegates=True" in line for line in reports), f"binary self_delegates flag should appear, got: {reports}";
    fail_line = "FAIL-CLOSED: resolved binary 'local-shim/fflow' self-delegates to the same package";
    assert any(fail_line in line for line in reports), f"expected self-delegation fail-closed, got: {reports}";
    assert not any("target reached" in line for line in reports), f"walker should disengage at self-delegation, got: {reports}";
}

test "depth limit caps recursive descent" {
    root ++> Plugin(
        name="@freematters/freeflow",
        hook_command="fflow _hook post-tool-use",
        absolute_entry="/opt/freeflow/dist/cli.js",
    );
    p = [root -->][?:Plugin][0];

    # Chain of 6 hooks, each invoking the next — depth grows past limit (4).
    prev = p;
    for i in range(6) {
        h = Hook(
            stage=f"stage-{i}",
            timeout_s=10,
            from_path=False,
            terminates_tree=True,
        );
        prev ++> h;
        prev = h;
    }

    res = root spawn ChainInspector(depth_limit=4, chain_label="deep");
    reports = res.report;

    assert any("FAIL-CLOSED: descent exceeded depth 4 (process-tree cap)" in line for line in reports), f"expected depth-cap fail-closed, got: {reports}";
    assert not any("target reached" in line for line in reports), f"deep chain has no Target node, but walker must not visit past the cap, got: {reports}";
}

