"""Regression tests for the KV/secret-mount count collector walker.

Each block builds its own small storage tree and spawns the walker from
the program under test, capturing stdout to verify the recursive LIST
behavior the issue describes.
"""

import io;
import from contextlib { redirect_stdout }

test "single logical mount with three secrets produces one list call per node" {
    root ++> LogicalMount(mount_path="app");
    app = [root -->][0];
    app +>:NestedUnder:+> Secret(name="db/password");
    app +>:NestedUnder:+> Secret(name="api/key");
    app +>:NestedUnder:+> Secret(name="tls/cert");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        c = CountCollector();
        res = root spawn c;
    }
    out = buf.getvalue();

    # Spawn returns the walker instance — read mutated has fields off it.
    assert c.list_calls == 4, f"expected 1 (mount) + 3 (secrets) = 4 list calls, got {c.list_calls}";
    assert len(c.secrets_seen) == 3, f"expected 3 secrets tallied, got {len(c.secrets_seen)}";
    assert "billing tick: starting recursive LIST pass over storage" in out, f"missing tick banner: {out}";
    assert "LIST logical/app/metadata/  (1 ListObjectsV2)" in out, f"missing mount LIST line: {out}";
    assert "counted secret: db/password" in out, f"missing secret tally for db/password: {out}";
    assert "counted secret: api/key" in out, f"missing secret tally for api/key: {out}";
    assert "counted secret: tls/cert" in out, f"missing secret tally for tls/cert: {out}";
}

test "auth mount uses HostsSecretID edge and counts approle secret_ids" {
    root ++> AuthMount(mount_path="approle");
    approle = [root -->][0];
    approle +>:HostsSecretID:+> Secret(name="role/web/secret_id_1");
    approle +>:HostsSecretID:+> Secret(name="role/web/secret_id_2");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        c = CountCollector();
        root spawn c;
    }
    out = buf.getvalue();

    # 1 LIST for the auth mount + 1 per secret_id it hosts = 3.
    assert c.list_calls == 3, f"expected 1 (auth mount) + 2 (secret_ids) = 3 list calls, got {c.list_calls}";
    assert len(c.secrets_seen) == 2, f"expected 2 secret_ids tallied, got {len(c.secrets_seen)}";
    assert "role/web/secret_id_1" in c.secrets_seen, f"missing role/web/secret_id_1 in {c.secrets_seen}";
    assert "role/web/secret_id_2" in c.secrets_seen, f"missing role/web/secret_id_2 in {c.secrets_seen}";
    assert "LIST auth/approle/secret_id  (1 ListObjectsV2)" in out, f"missing auth LIST line: {out}";
}

test "nested mounts compound the LIST cost proportional to tree size" {
    app = LogicalMount(mount_path="app");
    team = LogicalMount(mount_path="team");
    root ++> app ++> team;

    app +>:NestedUnder:+> Secret(name="db/password");
    app +>:NestedUnder:+> Secret(name="api/key");
    team +>:NestedUnder:+> Secret(name="ci/token");
    team +>:NestedUnder:+> Secret(name="ops/ssh");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        c = CountCollector();
        root spawn c;
    }

    # 2 mounts + 4 secrets = 6 LIST calls. This is exactly the scaling
    # the issue complains about (LIST count grows with secret count).
    assert c.list_calls == 6, f"expected 2 mounts + 4 secrets = 6 list calls, got {c.list_calls}";
    assert len(c.secrets_seen) == 4, f"expected 4 distinct secrets tallied, got {len(c.secrets_seen)}";
    for s in ["db/password", "api/key", "ci/token", "ops/ssh"] {
        assert s in c.secrets_seen, f"missing secret {s} in {c.secrets_seen}";
    }
}

test "secret_ids under approle do not appear as kv secrets" {
    root ++> AuthMount(mount_path="approle");
    approle = [root -->][0];
    approle +>:HostsSecretID:+> Secret(name="role/web/secret_id_1");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        c = CountCollector();
        root spawn c;
    }

    # The secret_id is reachable via HostsSecretID; the walker visits it
    # via the AuthMount ability which only counts then continues, so the
    # secret_id is tallied (1) plus 1 for the mount itself = 2.
    assert c.list_calls == 2, f"expected mount + secret_id = 2 list calls, got {c.list_calls}";
    assert len(c.secrets_seen) == 1, f"expected 1 secret_id tallied, got {len(c.secrets_seen)}";
    assert "role/web/secret_id_1" in c.secrets_seen, f"secret_id not counted: {c.secrets_seen}";
}

test "empty mount still costs one LIST call per billing tick" {
    root ++> LogicalMount(mount_path="empty");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        c = CountCollector();
        root spawn c;
    }

    # Even with no secrets, the mount itself is LISTed — exactly the
    # baseline overhead the issue calls out as wasteful on S3.
    assert c.list_calls == 1, f"expected exactly 1 LIST call for empty mount, got {c.list_calls}";
    assert len(c.secrets_seen) == 0, f"expected no secrets tallied, got {len(c.secrets_seen)}";
}

