"""Regression tests for the Relay scoped delegation broker."""

import io;
import from contextlib { redirect_stdout }

test "default deny: spawn blocked when parent is not allowed to spawn" {
    parent = Task(
        task_id="claude",
        depth=0,
        grant_max_depth=1,
        remaining_budget=100,
        max_children=2,
        read_only=True,
        provider="claude",
        spawn_allowed=False
    );
    child = Task(
        task_id="codex",
        grant_max_depth=1,
        remaining_budget=10,
        read_only=True,
        provider="codex"
    );
    broker = DelegationBroker();
    ok = broker.authorize_spawn(parent, child, 10);
    assert not ok, "spawn must be denied when parent.spawn_allowed is False";
    assert "codex:spawn_disabled" in broker.violations, f"got {broker.violations}";
    assert len([parent -->]) == 0, "no DelegatesTo edge should be created on denial";
    assert parent.child_count == 0, "child_count must not increment on denial";
    assert parent.remaining_budget == 100, "budget must not be charged on denial";
}

test "child cannot widen its own grant: budget or readonly escalation rejected" {
    parent = Task(
        task_id="claude",
        depth=0,
        grant_max_depth=1,
        remaining_budget=50,
        max_children=2,
