        read_only=False,
        provider="codex"
    );
    broker = DelegationBroker();
    assert not broker.authorize_spawn(parent, wide_budget, 10), "budget widening must be denied";
    assert "wide:budget_widen" in broker.violations, f"got {broker.violations}";
    assert not broker.authorize_spawn(parent, writable, 10), "readonly widening must be denied";
    assert "writable:readonly_widen" in broker.violations, f"got {broker.violations}";
    assert len(broker.approvals) == 0, "no approvals expected";
    assert len([parent -->]) == 0, "no edges should exist after both denials";
}

test "depth exhaustion and fanout cap are enforced" {
    parent = Task(
        task_id="claude",
        depth=0,
        grant_max_depth=1,
        remaining_budget=100,
        max_children=2,
        read_only=True,
        provider="claude",
        spawn_allowed=True
    );
    root ++> parent;
    mid = Task(
        task_id="mid",
        grant_max_depth=1,
        remaining_budget=40,
        read_only=True,
        provider="codex"
    );
    too_deep = Task(
        task_id="too_deep",
        grant_max_depth=1,
        remaining_budget=5,
        read_only=True,
        provider="codex"
    );
    broker = DelegationBroker();
    assert broker.authorize_spawn(parent, mid, 10), "first hop must succeed";
    assert not broker.authorize_spawn(mid, too_deep, 5), "depth=2 under maxDepth=1 must fail";
    assert "too_deep:depth_violation" in broker.violations, f"got {broker.violations}";

    sib1 = Task(task_id="s1", grant_max_depth=1, remaining_budget=10, read_only=True, provider="codex");
    sib2 = Task(task_id="s2", grant_max_depth=1, remaining_budget=10, read_only=True, provider="codex");
    sib3 = Task(task_id="s3", grant_max_depth=1, remaining_budget=10, read_only=True, provider="codex");
    assert broker.authorize_spawn(parent, sib1, 10), "second child within fanout must succeed";
    assert not broker.authorize_spawn(parent, sib2, 10), "third child over fanout must fail";
    assert "s2:fanout_exceeded" in broker.violations, f"got {broker.violations}";
    assert broker.authorize_spawn(parent, sib3, 10), "after a denial no resources were consumed, retry must succeed";
    assert "s3" in broker.approvals, f"got {broker.approvals}";
}

test "revoke cascade marks all transitive descendants" {
    p = Task(
        task_id="p", depth=0, grant_max_depth=1, remaining_budget=100,
        max_children=5, read_only=True, provider="claude", spawn_allowed=True
    );
    a = Task(task_id="a", grant_max_depth=1, remaining_budget=20, read_only=True, provider="codex");
    b = Task(task_id="b", grant_max_depth=1, remaining_budget=20, read_only=True, provider="codex");
    c = Task(task_id="c", grant_max_depth=1, remaining_budget=20, read_only=True, provider="codex");
    root ++> p;
    broker = DelegationBroker();
    broker.authorize_spawn(p, a, 10);
    broker.authorize_spawn(a, b, 5);
    broker.authorize_spawn(b, c, 5);
    assert len([p ->:DelegatesTo:->]) == 1, "p should have one child";
    RevokeCascade() spawn p;
    audit = GrantAuditor();
    root spawn audit;
    assert "p" in audit.revoked_ids, f"got revoked={audit.revoked_ids}";
    assert "a" in audit.revoked_ids, "a must be revoked by cascade";
    assert "b" in audit.revoked_ids, "b must be revoked by cascade";
    assert "c" in audit.revoked_ids, "c must be revoked by cascade";
    assert len(audit.active_ids) == 0, f"no active tasks expected, got {audit.active_ids}";
}

test "siblings are isolated unless an explicit SiblingGrant connects them" {
    p = Task(
        task_id="p", depth=0, grant_max_depth=1, remaining_budget=100,
        max_children=5, read_only=True, provider="claude", spawn_allowed=True
    );
    sib_a = Task(task_id="sib_a", read_only=True);
    sib_b = Task(task_id="sib_b", read_only=True);
    root ++> p;
    p +>:DelegatesTo:+> sib_a;
    p +>:DelegatesTo:+> sib_b;
    iso = SiblingProbe();
    iso spawn sib_a;
    assert iso.visible == [], f"isolated probe must see no siblings, got {iso.visible}";

    sib_a +>:SiblingGrant:+> sib_b;
    granted = SiblingProbe();
    granted spawn sib_a;
    assert "sib_b" in granted.visible, f"granted probe must see the peer, got {granted.visible}";
    assert len(granted.visible) == 1, f"only the granted peer should be visible, got {granted.visible}";
}

"""Tests for governed loop package export: closure preview, omissions, modes, cycles."""

import io;
import from contextlib { redirect_stdout }

test "definition only mode excludes templates but includes loop revisions" {
    root ++> LoopRevision(
        title="Auth Loop v3",
        year=1,
        identity="loop-auth-v3",
        content_hash="sha256:aa11"
    );
    root ++> Template(
        title="Reusable Role Model",
        year=1,
        identity="tmpl-role-01",
        content_hash="sha256:cc33"
    );

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn ClosurePreviewer(export_mode="DefinitionOnly", max_depth=32);
    }
    out = buf.getvalue();

    assert "[INCLUDE] Auth Loop v3" in out, f"loop revision must be included: {out}";
    assert "[OMIT:mode_excluded] Reusable Role Model" in out, (
        f"template must be mode-excluded in DefinitionOnly: {out}"
    );
    assert "kind=template" in out, f"omission should report kind=template: {out}";
}

test "reusable template mode includes both loop revisions and templates" {
    root ++> LoopRevision(
