}

test "secret artifacts are policy forbidden and never included" {
    root ++> LoopRevision(
        title="Private Credential Binding",
        year=1,
        identity="loop-secret-bind",
        content_hash="sha256:RED",
        is_secret=True
    );

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn ClosurePreviewer(export_mode="PortableNonSecretBundle", max_depth=32);
    }
    out = buf.getvalue();

    assert "[OMIT:policy_forbidden] Private Credential Binding" in out, (
        f"secret must be policy_forbidden: {out}"
    );
    assert "RED" not in out, f"secret content hash must never appear in output: {out}";
