test "cycles are detected via visited ids and traversal stops at cycle back edge" {
    a = LoopRevision(title="A", year=1, identity="id-a", content_hash="sha:a");
    b = LoopRevision(title="B", year=1, identity="id-b", content_hash="sha:b");
    a +>:Required:+> b;
    b +>:Required:+> a;
    root ++> a;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn ClosurePreviewer(export_mode="ReusableTemplate", max_depth=32);
    }
    out = buf.getvalue();

    assert "[INCLUDE] A" in out, f"A must be included: {out}";
    assert "[INCLUDE] B" in out, f"B must be included: {out}";
    assert "[CYCLE] id-a" in out, f"cycle back to A must be reported: {out}";
    assert out.count("[CYCLE]") == 1, f"only one cycle should be reported, got: {out}";
}

test "unavailable and external artifacts are omitted without breaking plan completeness" {
    helper = LoopRevision(title="Helper", year=1, identity="loop-h", content_hash="sha:h");
    absent_opt = Template(
        title="Deprecated Layout",
        year=1,
        identity="tmpl-old-layout",
        content_hash="sha:old",
        available=False
    );
    ext_api = ExternalRef(
        title="External Identity Provider",
        year=1,
        identity="ext-idp",
        content_hash="sha:ext00"
    );
    helper +>:Optional:+> absent_opt;
    helper +>:Optional:+> ext_api;
    root ++> helper;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn ClosurePreviewer(export_mode="ReusableTemplate", max_depth=32);
    }
    out = buf.getvalue();

    assert "[INCLUDE] Helper" in out, f"helper must be included: {out}";
    assert "[OMIT:optional_absent] Deprecated Layout" in out, (
        f"unavailable template must be optional_absent: {out}"
    );
    assert "[OMIT:externalized_rebind] External Identity Provider" in out, (
        f"external ref must be externalized_rebind: {out}"
    );
    assert "Closure Complete:" in out, (
        f"plan must remain Complete when no required nodes are omitted: {out}"
    );
}

"""Regression tests for the inline diff review pane demo.

We test the behaviors the problem promises:
- Flow ordering walks the unit dependency DAG and emits each unit once,
  in topological order, with an explicit cycle guard.
- The reader visits every InCommit -> ChangeUnit -> DiffLine path and
  surfaces anchored observations plus the read-only Q&A thread, in the
  order the graph dictates (question before its answer).
"""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

def build_commit_graph() -> tuple {
    commit = Commit(
        sha="abc1234",
        message="Inline diff review pane with anchored observations",
    );
    u_imports = ChangeUnit(
        unit_key="imports",
        intent="Add shiki tokenizer and parse-diff imports",
    );
    u_parser = ChangeUnit(
        unit_key="hunk-parser",
        intent="Parse hunks into anchorable diff lines",
    );
    u_pane = ChangeUnit(
        unit_key="review-pane",
        intent="Present flow-ordered units in the TUI review pane",
    );
    u_pane +>:DependsOn:+> u_parser;
    u_parser +>:DependsOn:+> u_imports;
    commit +>:InCommit:+> u_imports;
    commit +>:InCommit:+> u_parser;
    commit +>:InCommit:+> u_pane;
    line = DiffLine(
        path="src/review.ts",
        side="new",
        line_num=42,
        text="visit forward else disengage on empty frontier",
    );
    u_parser +>:Touches:+> line;
    obs = Observation(body="Prefer explicit empty-frontier handling over hang.");
    line +>:AnchoredTo:+> obs;
    q = Question(text="Does visit dedupe on dependency cycles?");
    line +>:AboutLine:+> q;
    a = Answer(text="No — walkers need an explicit cycle guard.");
    q +>:ReplyTo:+> a;
    return (commit, u_imports, u_parser, u_pane, line, obs, q, a);
}

def run_walker_on_commit(commit: Commit, walker_obj) -> str {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        _ = commit spawn walker_obj;
    }
    return buf.getvalue();
}

def find_line_index(out: str, marker: str) -> int {
    lines = out.splitlines();
    found = -1;
    i = 0;
    while i < len(lines) {
        ln = lines[i];
        if ln.lstrip().startswith(marker) {
            found = i;
            i = len(lines);
        } else {
            i = i + 1;
        }
    }
    assert found >= 0, f"missing {marker!r} in output: {out!r}";
    return found;
}

