test "valid leaf through intermediate to trusted root passes" {
    root ++> ValidationPolicy(validation_time=2000, max_depth=8, search_budget=32, clock_available=True);
    ta = TrustAnchor(subject="Root CA", label="corp-root");
    root_cert = Certificate(subject="Root CA", issuer="Root CA", is_ca=True, not_before=1000, not_after=3000, sig_valid=True);
    inter = Certificate(subject="Intermediate CA", issuer="Root CA", is_ca=True, not_before=1000, not_after=3000, sig_valid=True);
    leaf = Certificate(subject="server.example", issuer="Intermediate CA", server_auth=True, is_ca=False, not_before=1000, not_after=3000, sig_valid=True);

    inter +>:Issues:+> leaf;
    leaf +>:IssuedBy:+> inter;
    inter +>:IssuedBy:+> root_cert;
    ta +>:Anchors:+> root_cert;

    root ++> ta;
    root ++> inter;
    root ++> leaf;
    root ++> root_cert;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        leaf spawn CertPathValidator(validation_time=2000, max_depth=8, budget=32, trust_subjects=["Root CA"]);
    }
    out = buf.getvalue();

    assert "PASS: chain anchors at trusted 'Root CA'" in out, f"missing PASS marker: {out}";
    assert "(revocation-not-checked)" in out, f"missing revocation-not-checked marker: {out}";
}

