test "live attempt finalizes when fence and digest match" {
    run = Run(run_id="R-live", owner_epoch=7);
    live = Attempt(
        attempt_id="A-live",
        fence_epoch=7,
        declared_digest="sha256:abc",
        verified_digest="sha256:abc",
        state="provisional"
    );
    root ++> run;
    run +>:ProducedAttempt(plan_digest="plan:v3"):+> live;

    run spawn FenceEnforcer();
    root spawn Publisher();

    assert live.is_stale == False, f"expected live attempt not stale, got is_stale={live.is_stale}";
    assert live.state == "finalized", f"expected finalized under current fence, got {live.state}";
}

test "stale attempt is aborted and cannot finalize" {
