test "CascadeGC sweeps aborted attempts and provisional artifacts" {
    run = Run(run_id="R-gc", owner_epoch=7);
    aborted = Attempt(attempt_id="A-aborted", state="aborted");
    pending = Attempt(attempt_id="A-pending", state="provisional");
    orphan = Artifact(
        artifact_id="art-orphan",
        logical_name="partial.zip",
        publication_state="provisional"
    );
    root ++> run;
    run +>:ProducedAttempt(plan_digest="plan:v3"):+> aborted;
    run +>:ProducedAttempt(plan_digest="plan:v3"):+> pending;
    aborted +>:Orphaned(reason="fence-lost"):+> orphan;

    gc_aborted = CascadeGC();
    aborted spawn gc_aborted;
    gc_pending = CascadeGC();
    pending spawn gc_pending;
    gc_orphan = CascadeGC();
    orphan spawn gc_orphan;

    collected = gc_aborted.visited + gc_pending.visited + gc_orphan.visited;
    assert "A-aborted" in collected, f"missing aborted attempt in GC sweep: {collected}";
    assert "A-pending" in collected, f"missing provisional attempt in GC sweep: {collected}";
    assert "orphan:art-orphan" in collected, f"missing provisional artifact orphan: {collected}";
}

test "ReachabilityProbe lists only reachable replica workers" {
    artifact = Artifact(
        artifact_id="art-1",
        logical_name="report.html",
        content_digest="sha256:abc",
        publication_state="final"
    );
    local_w = Worker(worker_id="W-local", reachable=True);
    remote_w = Worker(worker_id="W-remote", reachable=False);
    root ++> artifact;
    artifact +>:ServedBy(provider_kind="local"):+> local_w;
    artifact +>:ServedBy(provider_kind="s3"):+> remote_w;

    probe = ReachabilityProbe();
    root spawn probe;

    assert "W-local" in probe.reachable_workers, f"expected local worker reachable: {probe.reachable_workers}";
    assert "W-remote" not in probe.reachable_workers, f"unreachable worker must be excluded: {probe.reachable_workers}";
    assert len(probe.reachable_workers) == 1, f"expected exactly one reachable worker, got {probe.reachable_workers}";
}

