"""Regression tests for the incremental notebook reconciliation demo.

The reconciler walker traverses a chain of Cell nodes connected by typed
Edge edges and reports which cells to KEEP (matched against the server's
proposed cell-id list) and which to DELETE (not in the server list). It
prints an LCS summary. We assert on the captured stdout.
"""

import io;
import from contextlib { redirect_stdout }

# Helper: build a chain of Cells connected by Edge edges off a Root.
def build_chain(specs: list) -> tuple {
    rt = Root();
    prev = None;
    for s in specs {
        c = Cell(cell_id=s[0], source=s[1], hash=s[2], index=s[3]);
        rt +>:Edge:+> c;
        if prev is not None {
            prev +>:Edge:+> c;
        }
        prev = c;
    }
    return (rt, prev);
}

# Helper: spawn Reconciler on the root, returning captured stdout + walker.
def reconcile(rt: Root, server_ids: list) {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        r = Reconciler(server_ids=server_ids);
        rt spawn r;
        r spawn rt;
    }
    return (buf.getvalue(), r);
}

test "basic reconciliation deletes missing and keeps present cells" {
    (rt, _) = build_chain([
        ("cell-A", "x = 1", "h1", 0),
        ("cell-B", "x = 2", "h2", 1),
        ("cell-C", "x = 3", "h3", 2),
        ("cell-D", "x = 4", "h4", 3),
    ]);
    # Server proposes: B, C, D, E  (A deleted, E inserted, B/C/D kept)
    (out, r) = reconcile(rt, ["cell-B", "cell-C", "cell-D", "cell-E"]);

    # The three cells that survive must be reported as KEEP.
    assert "KEEP   #1 cell-B (h2) at server pos 0" in out, f"missing KEEP B: {out}";
    assert "KEEP   #2 cell-C (h3) at server pos 1" in out, f"missing KEEP C: {out}";
    assert "KEEP   #3 cell-D (h4) at server pos 2" in out, f"missing KEEP D: {out}";

    # cell-A is in the client but not in the server proposal => DELETE.
    assert "DELETE #0 cell-A (h1)" in out, f"missing DELETE A: {out}";

    # The walker must NOT mention the new server cell "cell-E" as a KEEP,
    # because E is not yet in the client graph.
    assert "KEEP" in out, "expected at least one KEEP op";
    keep_lines = [ln for ln in out.split("\n") if "KEEP" in ln];
    assert len(keep_lines) == 3, f"expected 3 KEEP lines, got {len(keep_lines)}: {out}";

    # LCS over server_ids vs the kept cells (B,C,D) is length 3.
    assert "LCS length = 3" in out, f"missing LCS=3 summary: {out}";
    assert "client kept 3/4 cells in place" in out, f"missing kept-summary: {out}";

    # ops field must record exactly one DELETE plus three KEEPs.
    delete_ops = [op for op in r.ops if op.startswith("DELETE")];
    keep_ops = [op for op in r.ops if op.startswith("KEEP")];
    assert len(delete_ops) == 1, f"expected 1 DELETE op, got {len(delete_ops)}";
    assert len(keep_ops) == 3, f"expected 3 KEEP ops, got {len(keep_ops)}";
}

test "every server cell present in client yields zero DELETEs and full LCS" {
    (rt, _) = build_chain([
        ("cell-A", "a", "h1", 0),
        ("cell-B", "b", "h2", 1),
        ("cell-C", "c", "h3", 2),
    ]);
    # Server proposes the exact same cells in the same order.
    (out, r) = reconcile(rt, ["cell-A", "cell-B", "cell-C"]);

    # No DELETEs since every client cell is in the server proposal.
    delete_ops = [op for op in r.ops if op.startswith("DELETE")];
    assert len(delete_ops) == 0, f"expected 0 DELETEs, got {len(delete_ops)}: {out}";

    # LCS of [A,B,C] vs [A,B,C] is 3.
    assert "LCS length = 3" in out, f"expected LCS=3, got: {out}";
    assert "client kept 3/3 cells in place" in out, f"summary wrong: {out}";

    # Server positions must be reported correctly for each kept cell.
    assert "at server pos 0" in out, f"missing server pos 0: {out}";
    assert "at server pos 1" in out, f"missing server pos 1: {out}";
    assert "at server pos 2" in out, f"missing server pos 2: {out}";
}

test "empty graph with server proposal produces no ops" {
    rt = Root();
    # No cells attached
    server = ["cell-A", "cell-B"];
    (out, r) = reconcile(rt, server);

    # No cells visited => no ops recorded.
    assert r.ops == [], f"expected no ops on empty graph, got {r.ops}";
    # Server proposal must still be echoed.
    assert f"server proposed order: {server}" in out, f"missing header: {out}";
    # Summary must report 0 cells kept out of len(server).
    assert f"client kept 0/{len(server)} cells in place" in out, f"summary wrong: {out}";
}

test "server proposal with no overlap deletes every client cell" {
    (rt, _) = build_chain([
        ("cell-A", "a", "h1", 0),
        ("cell-B", "b", "h2", 1),
    ]);
    # Server proposes entirely different ids.
    (out, r) = reconcile(rt, ["cell-X", "cell-Y", "cell-Z"]);

    # Every client cell is missing on the server => all DELETEs.
    delete_ops = [op for op in r.ops if op.startswith("DELETE")];
    keep_ops = [op for op in r.ops if op.startswith("KEEP")];
    assert len(delete_ops) == 2, f"expected 2 DELETEs, got {len(delete_ops)}: {out}";
    assert len(keep_ops) == 0, f"expected 0 KEEPs, got {len(keep_ops)}: {out}";

    # LCS over [] vs [X,Y,Z] is 0.
    assert "LCS length = 0" in out, f"expected LCS=0, got: {out}";
    assert "client kept 0/3 cells in place" in out, f"summary wrong: {out}";

    # Specific DELETE lines.
    assert "DELETE #0 cell-A (h1)" in out, f"missing DELETE A: {out}";
    assert "DELETE #1 cell-B (h2)" in out, f"missing DELETE B: {out}";
}

test "server positions reflect the server's proposed order, not the client index" {
    (rt, _) = build_chain([
        ("cell-A", "a", "h1", 0),
        ("cell-B", "b", "h2", 1),
        ("cell-C", "c", "h3", 2),
    ]);
    # Server reverses the order: C, B, A.
    (out, r) = reconcile(rt, ["cell-C", "cell-B", "cell-A"]);

    # Each kept cell must be tagged with its position in the server list.
    assert "KEEP   #2 cell-C (h3) at server pos 0" in out, f"missing C@0: {out}";
    assert "KEEP   #1 cell-B (h2) at server pos 1" in out, f"missing B@1: {out}";
    assert "KEEP   #0 cell-A (h1) at server pos 2" in out, f"missing A@2: {out}";

    # Client kept all 3, full LCS = 3 (same ids, different order).
    assert "LCS length = 3" in out, f"expected LCS=3, got: {out}";
    assert "client kept 3/3 cells in place" in out, f"summary wrong: {out}";

    # visited set must contain exactly the three cell ids.
    assert r.visited == {"cell-A", "cell-B", "cell-C"}, f"visited wrong: {r.visited}";
}

import io;
import from contextlib { redirect_stdout }

test "ready release audit counts valid artifacts" {
    release = Release(tag="v2.0.0", version="2.0.0");
    x64 = Installer(architecture="x64", url="quickmail-x64.msi",
                    silent_install_ok=True);
    arm64 = Installer(architecture="arm64", url="quickmail-arm64.msi",
                      silent_install_ok=True);
    version_manifest = Manifest(package_id="KellyLford.QuickMail",
                                kind="version", authored=True, submitted=True);
    locale_manifest = Manifest(package_id="KellyLford.QuickMail",
                               kind="defaultLocale", authored=True,
                               submitted=True);
    installer_manifest = Manifest(package_id="KellyLford.QuickMail",
                                  kind="installer", authored=True,
                                  submitted=True);
    blocker = Block(reason="ARP ownership", resolved=True);

    release +>:ProvidesInstaller(architecture="x64", url=x64.url):+> x64;
    release +>:ProvidesInstaller(architecture="arm64", url=arm64.url):+> arm64;
    release +>:TargetsManifest(manifest_kind="version"):+> version_manifest;
    release +>:TargetsManifest(manifest_kind="defaultLocale"):+> locale_manifest;
    release +>:TargetsManifest(manifest_kind="installer"):+> installer_manifest;
    release +>:BlocksRelease(reason="ARP ownership"):+> blocker;
    root ++> release;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ReleaseAuditor(release_tag="v2.0.0");
    }
    out = buf.getvalue();

    assert res.ready == True, f"expected ready, got {res.ready}";
    assert res.installer_count == 2, f"installer count was {res.installer_count}";
    assert res.manifest_count == 3, f"manifest count was {res.manifest_count}";
    assert res.blocking_count == 1, f"block count was {res.blocking_count}";
    assert "[READY for winget]" in out, f"missing ready verdict: {out}";
}

