}

"""Test annex for build-system dependency graph demo.

Covers the behaviour the issue promises:
- Dependency traversal discovers which outputs must be rebuilt based on
  source vs output timestamps.
- Cascade invalidation clears the visited flag on every reachable rule.
- Typed DependsOn edges carry a weight field used in cycle-detection /
  scoring decisions.
- Edge topology of a hand-rolled dependency graph matches expectations.
"""

import io;
import from contextlib { redirect_stdout }

test "build walker flags stale outputs and walks sources" {
    fresh_src = Source(name="fresh.c", mtime=50);
    stale_src = Source(name="stale.c", mtime=200);
    out = Output(name="bin", mtime=100);
    rule = BuildRule(label="link-bin");

    root +>:DependsOn(weight=3):+> out;
    out +>:DependsOn:+> rule;
    rule +>:DependsOn:+> fresh_src;
    rule +>:DependsOn:+> stale_src;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Build();
    }
    out_text = buf.getvalue();

    assert "Build dependency check starting from root..." in out_text, f"missing header: {out_text}";
    assert "checking output: bin (mtime=100)" in out_text, f"missing output check: {out_text}";
    assert "  rule: link-bin" in out_text, f"missing rule trace: {out_text}";
    assert "source fresh.c mtime=50 -> FRESH" in out_text, f"missing fresh source trace: {out_text}";
    assert "source stale.c mtime=200 -> STALE" in out_text, f"missing stale source trace: {out_text}";

    # The walker must have recorded which output it was checking.
    assert res.checking == "bin", f"checking not recorded, got {res.checking}";
}

test "build walker reaches every source reachable from root" {
    a = Source(name="a.c", mtime=10);
    b = Source(name="b.c", mtime=20);
    c = Source(name="c.c", mtime=30);
    out = Output(name="all.o", mtime=5);
    rule = BuildRule(label="compile-all");

    root +>:DependsOn:+> out;
    out +>:DependsOn:+> rule;
    rule +>:DependsOn:+> a;
    rule +>:DependsOn:+> b;
    rule +>:DependsOn:+> c;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Build();
    }
    out_text = buf.getvalue();

    # All three sources must show up in the traversal trace.
    assert "source a.c" in out_text, f"a.c not visited: {out_text}";
    assert "source b.c" in out_text, f"b.c not visited: {out_text}";
    assert "source c.c" in out_text, f"c.c not visited: {out_text}";
}

test "cascade invalidation clears visited flag on reachable rules" {
    out = Output(name="artifact.bin", mtime=10);
    r1 = BuildRule(label="compile");
    r2 = BuildRule(label="link");
    r1.visited = True;
    r2.visited = True;

    root +>:DependsOn:+> out;
    out +>:DependsOn:+> r1;
    r1 +>:DependsOn:+> r2;

    # A rule NOT reachable from the walk target should remain untouched.
    untouched = BuildRule(label="package", visited=True);
    # Attach the untouched rule somewhere off-graph so it has no inbound
    # path from the root we spawn Cascade on.

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Cascade();
    }
    out_text = buf.getvalue();

    assert "Cascade invalidation sweep starting..." in out_text, f"missing header: {out_text}";
    assert "invalidated rule: compile" in out_text, f"compile not invalidated: {out_text}";
    assert "invalidated rule: link" in out_text, f"link not invalidated: {out_text}";

    # Reachable rules must now report visited=False.
    assert r1.visited == False, f"r1 still visited={r1.visited}";
    assert r2.visited == False, f"r2 still visited={r2.visited}";
    # Untouched rule is unaffected.
    assert untouched.visited == True, f"unrelated rule mutated: {untouched.visited}";

    assert "compile" in res.invalidated, f"compile missing from invalidated: {res.invalidated}";
    assert "link" in res.invalidated, f"link missing from invalidated: {res.invalidated}";
}

test "depends_on edges carry the declared weight field" {
    out = Output(name="heavy.bin", mtime=0);
    rule = BuildRule(label="heavy-link");

    root +>:DependsOn(weight=7):+> out;
    out +>:DependsOn(weight=2):+> rule;

    edges_from_root = [root ->:DependsOn:->];
    edges_from_out = [out ->:DependsOn:->];

    assert len(edges_from_root) == 1, f"expected 1 edge from root, got {len(edges_from_root)}";
    assert edges_from_root[0].weight == 7, f"root edge weight wrong: {edges_from_root[0].weight}";

    assert len(edges_from_out) == 1, f"expected 1 edge from out, got {len(edges_from_out)}";
    assert edges_from_out[0].weight == 2, f"out edge weight wrong: {edges_from_out[0].weight}";
}

test "build walker traverses two independent output chains" {
    s_app = Source(name="app.c", mtime=300);
    s_util = Source(name="util.c", mtime=400);
    s_lib = Source(name="lib.c", mtime=50);
    out_app = Output(name="app.bin", mtime=100);
    out_util = Output(name="util.o", mtime=500);
    r_app = BuildRule(label="compile-app");
    r_util = BuildRule(label="compile-util");

    root +>:DependsOn:+> out_app;
    out_app +>:DependsOn:+> r_app;
    r_app +>:DependsOn:+> s_app;
    r_app +>:DependsOn:+> s_util;

    root +>:DependsOn:+> out_util;
    out_util +>:DependsOn:+> r_util;
    r_util +>:DependsOn:+> s_util;
    r_util +>:DependsOn:+> s_lib;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Build();
    }
    out_text = buf.getvalue();

    # Both outputs and both rules must appear in the trace.
    assert "checking output: app.bin" in out_text, f"app.bin missing: {out_text}";
    assert "checking output: util.o" in out_text, f"util.o missing: {out_text}";
    assert "  rule: compile-app" in out_text, f"compile-app missing: {out_text}";
    assert "  rule: compile-util" in out_text, f"compile-util missing: {out_text}";

    # The checking field tracks the most recently visited output.
    assert res.checking == "util.o", f"expected util.o as last checked, got {res.checking}";

    # Root has exactly two direct children (one per output).
    assert len([root -->]) == 2, f"expected 2 direct children of root, got {len([root -->])}";
}

"""Regression tests for the Sharkrite dep-guard deferral fix.

Each test builds its own tiny queue and spawns a fresh ``BatchDriver`` with
a hand-set ``queue_order`` so we exercise the exact PARENT_IN_QUEUE-style
membership check the issue calls for. The driver walks the graph and
records what it did into ``driver.log``; we assert on that log plus on the
final issue states.
"""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
# Fixture 1: batch `N2 N1` where N2 depends on N1, both open.
# N2 must be deferred (not dep_failed), N1 runs, then N2 runs.
# ---------------------------------------------------------------------------
test "batch N2 N1 with N2 depending on open N1 defers N2 instead of skipping" {
    n1 = Issue(number=1, title="first");
    n2 = Issue(number=2, title="second, depends on N1");
    n2 +>:DependsOn:+> n1;

    root +>:QueuedAfter:+> n2;
    n2 +>:QueuedAfter:+> n1;

    driver = BatchDriver(queue_order=[2, 1]);
    res = root spawn driver;

    # N2 was deferred, not dep_failed.
    assert n2.state == "open", f"#2 should remain open after deferral, got {n2.state}";
    assert n2.state != "dep_failed", f"#2 must NOT be dep_failed when dep is queued later, got {n2.state}";

    # N1 ran.
    assert n1.state == "open", f"#1 stays open after a plain run, got {n1.state}";

    # The deferral message must appear, and the dep_failed message must NOT.
    log_joined = "\n".join(res.log);
    assert "defer to after #1" in log_joined, f"expected deferral line in log, got: {log_joined}";
    assert "not in queue" not in log_joined, f"should not have flagged as not-in-queue, got: {log_joined}";

    # Driver bookkeeping: #2 is in the deferred set exactly once.
    assert 2 in res.deferred, f"#2 should be marked deferred, got {res.deferred}";
}

# ---------------------------------------------------------------------------
# Fixture 2: N2 depends on an OPEN issue that is NOT in the batch.
# Pinned behavior: dep_failed.
# ---------------------------------------------------------------------------
test "dep that is open but not in the batch still causes dep_failed" {
    n3 = Issue(number=3, title="third, dep not in queue");
    orphan = Issue(number=99, title="orphan dep, open");
    n3 +>:DependsOn:+> orphan;

    root +>:QueuedAfter:+> n3;

    driver = BatchDriver(queue_order=[3]);
    res = root spawn driver;

    assert n3.state == "dep_failed", f"#3 should be dep_failed, got {n3.state}";

    log_joined = "\n".join(res.log);
    assert "not in queue" in log_joined, f"expected not-in-queue line, got: {log_joined}";
    assert "-> dep_failed" in log_joined, f"expected dep_failed disposition, got: {log_joined}";

    # Must not have been deferred (it never had a chance to be).
    assert 3 not in res.deferred, f"#3 should not be in deferred set, got {res.deferred}";
}

# ---------------------------------------------------------------------------
# Fixture 3: dep already CLOSED -> run immediately. Pinned behavior.
# ---------------------------------------------------------------------------
test "closed dep lets the issue run immediately" {
    n4 = Issue(number=4, title="fourth, closed dep");
    closed_dep = ClosedIssue(number=50, title="already closed dep");
    n4 +>:DependsOn:+> closed_dep;

    root +>:QueuedAfter:+> n4;

    driver = BatchDriver(queue_order=[4]);
    res = root spawn driver;

    assert n4.state == "open", f"#4 should remain open, got {n4.state}";
    assert n4.state != "dep_failed", f"#4 must not be dep_failed, got {n4.state}";

    log_joined = "\n".join(res.log);
    assert "depends on closed #50" in log_joined, f"expected closed-dep run line, got: {log_joined}";
    assert "dep_failed" not in log_joined, f"no dep_failed should appear, got: {log_joined}";

    assert len(res.deferred) == 0, f"no deferrals expected, got {res.deferred}";
}

# ---------------------------------------------------------------------------
# Fixture 4: deferral budget. If an issue is already deferred once and we
# see the same open-and-queued-later condition again, the second pass must
# fall through to dep_failed (one-pass defer budget from the shell driver).
# We model the "second pass" by pre-seeding ``deferred`` -- the driver does
# not re-traverse on its own, but the budget check is the relevant gate.
# ---------------------------------------------------------------------------
test "deferral budget prevents a second deferral from re-deferring" {
    n5 = Issue(number=5, title="fifth, already deferred");
    n6 = Issue(number=6, title="sixth, dep queued later");
    n6 +>:DependsOn:+> n5;

    root +>:QueuedAfter:+> n6;
    n6 +>:QueuedAfter:+> n5;

    # Pre-seed the deferral budget: #6 has already used its one deferral.
    driver = BatchDriver(queue_order=[6, 5], deferred=[6]);
    res = root spawn driver;

    # The budget check fires for #6: it stays dep_failed.
    assert n6.state == "dep_failed", f"#6 should be dep_failed when defer budget is spent, got {n6.state}";

    log_joined = "\n".join(res.log);
    assert "already deferred once" in log_joined, f"expected budget message, got: {log_joined}";
    assert 6 in res.deferred, f"#6 must remain in the deferred set, got {res.deferred}";
}

# ---------------------------------------------------------------------------
# Fixture 5: full ordering of Fixture 1. Confirms N2 runs AFTER N1 once
# deferred -- i.e. the queue is actually walked in submission order and
# the deferral is observed by the second pass on N1's successor link.
# This is the integration assertion the problem's "Done Definition" calls
# out: "N2 is deferred and processed after N1, not skipped".
# ---------------------------------------------------------------------------
test "deferred N2 is processed after N1 in the run log" {
    n1 = Issue(number=1, title="first");
    n2 = Issue(number=2, title="second, depends on N1");
    n2 +>:DependsOn:+> n1;

    root +>:QueuedAfter:+> n2;
    n2 +>:QueuedAfter:+> n1;

    # Capture the driver's print output too, to prove the demo wiring
    # reports the deferred-then-run ordering, not a skip.
    buf = io.StringIO();
    with redirect_stdout(buf) {
        driver = BatchDriver(queue_order=[2, 1]);
        res = root spawn driver;
        print("=== run log ===");
        for line in res.log {
            print(line);
        }
        print("=== dispositions ===");
        print(f"#1 state = {n1.state}");
        print(f"#2 state = {n2.state}");
    }
    out = buf.getvalue();

    # Disposition lines confirm N2 survived (was not dep_failed).
    assert "#2 state = open" in out, f"#2 must be open at end, got: {out}";
    assert "#1 state = open" in out, f"#1 must be open at end, got: {out}";
    assert "dep_failed" not in out, f"no dep_failed should appear anywhere, got: {out}";

    # Ordering: the deferral line for #2 must appear before the "has no deps"
    # line for #1 (which is the only way N2 actually gets re-driven after N1
    # closes the cycle -- the driver visits [-->] from the deferred node).
    defer_idx = out.find("defer to after #1");
    n1_run_idx = out.find("#1 has no deps -> run");
    assert defer_idx != -1, f"expected deferral line in output, got: {out}";
    assert n1_run_idx != -1, f"expected N1 run line in output, got: {out}";
    assert defer_idx < n1_run_idx, (
        f"deferral for #2 should be logged before N1 runs, "
        f"got defer@{defer_idx} run@{n1_run_idx}: {out}"
    );

    # N2 must show up in deferred exactly once.
    assert 2 in res.deferred, f"#2 should be in deferred set, got {res.deferred}";
}

test "validates dependency-safe ordering" {
