"""Test annex for Chapter 7 release-cell evidence admission graph.

Tests verify the fail-closed admission gate: the EvidenceAuditor walker
must only admit a package when ALL of source_authorized, checksum_ok,
manifest_ok, portfolio_ok, role_scope_ok, review_ok, and
claim_boundary_approved are true, and downstream figures must only be
refreshed when the claim boundary is approved.
"""

import io;
import from contextlib { redirect_stdout }

# Helper to spawn the walker with stdout capture and return output.
def run_auditor(pkg, source, manifest, portfolio, scope, boundary, fig) {
    root ++> pkg;
    pkg +>:Binds(field="SHA256SUMS"):+> source;
    pkg +>:Binds(field="manifest"):+> manifest;
    pkg +>:Binds(field="portfolio"):+> portfolio;
    pkg +>:Governs(role="release-cell"):+> scope;
    pkg +>:Governs(role="claim-boundary"):+> boundary;
    pkg +>:Proves(receipt_id="ch7-evidence-admission.v2"):+> fig;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn EvidenceAuditor();
    }
    return buf.getvalue();
}

test "happy path: all gates pass, package admitted and figure refreshed" {
    pkg = EvidencePackage(
        title="ch7-evidence-admission.v2",
        sha256="a1b2c3d4e5f67890",
    );
    source = SourceArtifact(title="v1-source", sha256="a1b2c3d4", release_backed=True);
    manifest = Manifest(title="manifest.json", member_count=5);
    portfolio = PortfolioDigest(title="portfolio", selection="deterministic-v2");
    scope = Review(reviewer="domain-owner", approved=True);
    boundary = ClaimBoundary(title="ch7-claim", approved=True);
    fig = DownstreamFigure(title="figure-7-1");

    out = run_auditor(pkg, source, manifest, portfolio, scope, boundary, fig);

    assert "ADMITTED:" in out, f"expected ADMITTED marker in: {out}";
    assert "BLOCKED" not in out, f"unexpected BLOCKED in: {out}";
    assert "[refreshed] downstream figure: figure-7-1" in out, f"figure not refreshed: {out}";
    assert pkg.admitted == True, f"pkg.admitted should be True, got {pkg.admitted}";
    assert fig.refreshed == True, f"fig.refreshed should be True, got {fig.refreshed}";
}

test "fail-closed: source not release-backed blocks admission" {
    pkg = EvidencePackage(title="ch7-evidence-admission.v2", sha256="a1b2c3d4e5f6");
    source = SourceArtifact(title="v1-source", sha256="a1b2c3d4", release_backed=False);
    manifest = Manifest(title="manifest.json", member_count=5);
    portfolio = PortfolioDigest(title="portfolio", selection="deterministic-v2");
    scope = Review(reviewer="domain-owner", approved=True);
    boundary = ClaimBoundary(title="ch7-claim", approved=True);
    fig = DownstreamFigure(title="figure-7-1");

    out = run_auditor(pkg, source, manifest, portfolio, scope, boundary, fig);

    assert "BLOCKED:" in out, f"expected BLOCKED marker in: {out}";
    assert "ADMITTED:" not in out, f"unexpected ADMITTED in: {out}";
    assert pkg.admitted == False, f"pkg.admitted should be False, got {pkg.admitted}";
    assert fig.refreshed == False, f"fig.refreshed must stay False on failure, got {fig.refreshed}";
}

test "fail-closed: missing checksum (empty sha256) blocks admission" {
    pkg = EvidencePackage(title="ch7-evidence-admission.v2", sha256="");
    source = SourceArtifact(title="v1-source", sha256="a1b2c3d4", release_backed=True);
    manifest = Manifest(title="manifest.json", member_count=5);
    portfolio = PortfolioDigest(title="portfolio", selection="deterministic-v2");
    scope = Review(reviewer="domain-owner", approved=True);
    boundary = ClaimBoundary(title="ch7-claim", approved=True);
    fig = DownstreamFigure(title="figure-7-1");

    out = run_auditor(pkg, source, manifest, portfolio, scope, boundary, fig);

    assert "BLOCKED:" in out, f"expected BLOCKED for empty checksum: {out}";
    assert pkg.admitted == False, f"empty checksum must block admission, got {pkg.admitted}";
}

test "fail-closed: unapproved claim boundary blocks downstream refresh even if other gates pass" {
    pkg = EvidencePackage(title="ch7-evidence-admission.v2", sha256="a1b2c3d4e5f6");
    source = SourceArtifact(title="v1-source", sha256="a1b2c3d4", release_backed=True);
    manifest = Manifest(title="manifest.json", member_count=5);
    portfolio = PortfolioDigest(title="portfolio", selection="deterministic-v2");
    scope = Review(reviewer="domain-owner", approved=True);
    boundary = ClaimBoundary(title="ch7-claim", approved=False);
    fig = DownstreamFigure(title="figure-7-1");

    out = run_auditor(pkg, source, manifest, portfolio, scope, boundary, fig);

    assert "BLOCKED:" in out, f"unapproved boundary must block: {out}";
    assert "[withheld] downstream figure: figure-7-1" in out, f"figure must be withheld: {out}";
    assert fig.refreshed == False, f"fig.refreshed must be False, got {fig.refreshed}";
    assert pkg.admitted == False, f"pkg.admitted must be False without claim boundary, got {pkg.admitted}";
}

test "graph shape: typed edges connect pkg to source, manifest, portfolio, scope, boundary, figure" {
    root ++> EvidencePackage(title="ch7-evidence-admission.v2", sha256="abcd");
    pkg = [root -->][0];
    pkg +>:Binds(field="SHA256SUMS"):+> SourceArtifact(title="s", sha256="x", release_backed=True);
    pkg +>:Binds(field="manifest"):+> Manifest(title="m", member_count=3);
    pkg +>:Binds(field="portfolio"):+> PortfolioDigest(title="p", selection="sel");
    pkg +>:Governs(role="release-cell"):+> Review(reviewer="r", approved=True);
    pkg +>:Governs(role="claim-boundary"):+> ClaimBoundary(title="cb", approved=True);
    pkg +>:Proves(receipt_id="ch7-evidence-admission.v2"):+> DownstreamFigure(title="fig");

    binds_count = len([pkg ->:Binds:->]);
    governs_count = len([pkg ->:Governs:->]);
    proves_count = len([pkg ->:Proves:->]);
    built_from_count = len([root ->:BuiltFrom:->]);

    assert binds_count == 3, f"expected 3 Binds edges, got {binds_count}";
    assert governs_count == 2, f"expected 2 Governs edges, got {governs_count}";
    assert proves_count == 1, f"expected 1 Proves edge, got {proves_count}";
    assert built_from_count == 1, f"expected 1 BuiltFrom edge from root, got {built_from_count}";
    assert pkg in [root ->:BuiltFrom:->], f"pkg should be linked from root via BuiltFrom";
}

