    assert res.mode == RequestBodyMode.MATERIALIZE_CANONICAL, f"got {res.mode}";
    assert "defaults to canonical (no streaming contract declared)" in out, f"missing default line: {out}";
    assert "mystery-stage" in res.canonical_required_by, f"canonical_required_by={res.canonical_required_by}";
}

"""Regression tests for the Qwen M2 decode roofline demo.

