no redeclarations). Each test builds its own small graph so behavior is
observable in isolation, and captures stdout for the print-driven walkers.
"""

import io;
import from contextlib { redirect_stdout }

test "residency auditor reports pathological cap4 vs topk8 verdict" {
    pool = ResidentPool(cap_slots=4, top_k=8, assumed_slot_bytes=2147483648, actual_slot_bytes=1671168);
    e_hot = Expert(expert_id=0, resident=True);
