    assert "expert 10 (hot)" in out, f"missing hot pin line: {out!r}";
    assert "expert 11 (cold)" in out, f"missing cold pin line: {out!r}";
}

test "unfused decode: every cold expert costs an extra host sync" {
    run = DecodeRun(label="direct-apple8-m2", token_count=1);
    tok = Token(index=0);
    moe = RoutedMoELayer(stage_index=0, name="moe_r0", top_k=8);
    e0 = Expert(expert_id=0, resident=True);
    e1 = Expert(expert_id=1, resident=False);
    e2 = Expert(expert_id=2, resident=False);
    root ++> run;
    run ++> tok ++> moe;
    moe +>:Routes(gate_weight=1.0):+> e0;
    moe +>:Routes(gate_weight=0.9):+> e1;
    moe +>:Routes(gate_weight=0.8):+> e2;

    unfused = UnfusedDecode();
    root spawn unfused;

    # routed_requests counts every Expert we land on, regardless of residency.
    assert unfused.routed_requests == 3, f"expected 3 routed requests, got {unfused.routed_requests}";
    # Only e0 is resident → exactly 1 cache hit.
    assert unfused.cache_hits == 1, f"expected 1 cache hit, got {unfused.cache_hits}";
    # Both cold experts trigger a physical load.
    assert unfused.physical_loads == 2, f"expected 2 physical loads, got {unfused.physical_loads}";
    # Each MoE layer visit adds 1 host sync; each cold-expert load adds 1 more.
    # drain_moe runs once on moe (==1); cold e1 and e2 add 2; hot e0 adds 0.
    assert unfused.host_syncs == 3, (
        f"expected 3 host syncs (1 moe + 2 cold loads), got {unfused.host_syncs}"
    );
}

test "fused decode: cold experts load but do not add per-expert host syncs" {
    run = DecodeRun(label="direct-apple8-m2", token_count=1);
    tok = Token(index=0);
    moe = RoutedMoELayer(stage_index=0, name="moe_r0", top_k=8);
    e0 = Expert(expert_id=0, resident=True);
    e1 = Expert(expert_id=1, resident=False);
    e2 = Expert(expert_id=2, resident=False);
    root ++> run;
    run ++> tok ++> moe;
    moe +>:Routes(gate_weight=1.0):+> e0;
    moe +>:Routes(gate_weight=0.9):+> e1;
    moe +>:Routes(gate_weight=0.8):+> e2;

    fused = FusedDecode();
    root spawn fused;

    # Routed-request accounting is identical to unfused: 3 routed, 1 hit, 2 loads.
    assert fused.routed_requests == 3, f"expected 3 routed requests, got {fused.routed_requests}";
    assert fused.cache_hits == 1, f"expected 1 cache hit, got {fused.cache_hits}";
    assert fused.physical_loads == 2, f"expected 2 physical loads, got {fused.physical_loads}";
    # The whole point of fusion: layer_syncs == # routed MoE layers (==1 here),
    # NOT moe_visits + cold_loads. This is the 160-vs-20 sync reduction the issue demands.
    assert fused.layer_syncs == 1, (
        f"expected exactly 1 layer-level sync after fusion, got {fused.layer_syncs}"
    );
    # Sanity: fused walker must NOT carry the per-expert sync counter at all.
    assert not hasattr(fused, "host_syncs"), "FusedDecode should not track per-expert host_syncs";
}

test "gdn cost accumulates per visited GDNLayer across tokens" {
    run = DecodeRun(label="direct-apple8-m2", token_count=2);
    t0 = Token(index=0);
    t1 = Token(index=1);
    gdn_a = GDNLayer(stage_index=0, name="gdn", cost_ms=155.0);
    gdn_b = GDNLayer(stage_index=1, name="gdn", cost_ms=155.0);
    root ++> run;
    run ++> t0 ++> gdn_a ++> t1 ++> gdn_b;

    fused = FusedDecode();
    root spawn fused;

    assert fused.gdn_ms == 310.0, f"expected 310.0 ms of GDN cost (2 layers × 155), got {fused.gdn_ms}";
    assert fused.tokens_done == 2, f"expected 2 tokens completed, got {fused.tokens_done}";
}

