"""Tests for the recursive type rewrite bomb demo.

Verifies that:
 - the walker terminates within its generation budget (no OOM blow-up);
 - the cycle guard trips when a node label is revisited;
 - the Atom rewrite actually creates a new Branch quad linked by
   a `RewrittenTo` edge (so the cascade is observable as a real edge);
 - the Branch descend ability walks all four Child edges;
 - when the budget is zero the fail-open-style guard halts immediately.
"""

import io;
import from contextlib { redirect_stdout }


test "walker terminates within budget without OOM" {
    seed = Atom(kind="A", label="seed");
    root ++> seed;
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ApplyRewrite(max_generations=5);
    }
    out = buf.getvalue();
    # Budget was 5, each Atom entry consumes 1 -> exactly 5 visit lines.
    visits = [line for line in out.splitlines() if line.startswith("visiting ")];
    assert len(visits) == 5, f"expected 5 visits under budget=5, got {len(visits)}: {out}";
    # Walker field tracks how many budget remained; must be exhausted.
    assert res.max_generations == 0, f"budget should be exhausted, got {res.max_generations}";
    # Visited list matches the number of visits.
    assert len(res.visited) == 5, f"expected 5 visited labels, got {res.visited}";
    # Termination marker must appear (the depth-budget guard fired).
    assert "depth budget exhausted" in out, f"missing halt marker: {out}";
}

test "cycle guard prevents infinite revisit" {
    seed = Atom(kind="A", label="loop");
    root ++> seed;
    # Run twice from root on the same labelled graph: visited persists on
    # the walker instance, so re-entry must be caught by the cycle check.
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ApplyRewrite(max_generations=20);
    }
    out = buf.getvalue();
    # No label may appear twice in the recorded visited list.
    assert len(res.visited) == len(set(res.visited)), (
        f"visited contains duplicates (cycle guard failed): {res.visited}"
    );
    # The label "loop" must be recorded exactly once.
    assert res.visited.count("loop") == 1, f"seed label visited {res.visited.count('loop')} times: {out}";
}

test "atom rewrite produces a branch quad via RewrittenTo edge" {
    seed = Atom(kind="A", label="X");
    root ++> seed;
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn ApplyRewrite(max_generations=3);
    }
    # The rewrite ability on Atom must have produced one RewrittenTo edge
    # pointing to a freshly-built Branch quad from the seed.
    rews = [edge for edge in [seed ->:RewrittenTo:->]];
    assert len(rews) == 1, f"expected exactly 1 RewrittenTo from seed, got {len(rews)}";
    quad = rews[0];
    assert isinstance(quad, Branch), f"target must be Branch, got {type(quad).__name__}";
    # Quad must carry four child Atom nodes linked via Child edges.
    kids = [quad ->:Child:->];
    assert len(kids) == 4, f"branch quad should have 4 children, got {len(kids)}";
    # Each child must be an Atom instance.
    for k in kids {
        assert isinstance(k, Atom), f"child should be Atom, got {type(k).__name__}";
    }
}

test "branch descend traverses all four typed children" {
    # Build a Branch connected to four Atoms by hand and exercise the
    # Branch-specific `descend` ability via spawn.
    parent = Branch(label="P");
    c1 = Atom(kind="A", label="P.c1");
    c2 = Atom(kind="B", label="P.c2");
    c3 = Atom(kind="C", label="P.c3");
    c4 = Atom(kind="D", label="P.c4");
    parent +>:Child:+> c1;
    parent +>:Child:+> c2;
    parent +>:Child:+> c3;
    parent +>:Child:+> c4;
    root ++> parent;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ApplyRewrite(max_generations=10);
    }
    out = buf.getvalue();
    # Every Atom child of the Branch must appear in the visited list
    # exactly once (branch descend hits each via typed Child edge).
    for lbl in ["P.c1", "P.c2", "P.c3", "P.c4"] {
        assert lbl in res.visited, f"missing visited label {lbl} in {res.visited}: {out}";
    }
    # The parent itself must also be inspected first.
    assert "P" in res.visited, f"parent label 'P' not visited: {out}";
}

test "zero budget halts immediately (fail-closed on the depth guard)" {
    seed = Atom(kind="A", label="Z");
    root ++> seed;
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ApplyRewrite(max_generations=0);
    }
    out = buf.getvalue();
    # No visit lines, no Atom rewrite side-effects (no RewrittenTo edges).
    visits = [line for line in out.splitlines() if line.startswith("visiting ")];
    assert len(visits) == 0, f"with budget=0 nothing should be visited, got: {out}";
    assert res.visited == [], f"visited list should be empty, got {res.visited}";
    assert res.max_generations == 0, f"budget unchanged: {res.max_generations}";
    # The halt message must appear.
    assert "depth budget exhausted" in out, f"missing halt marker: {out}";
    # No cascade edges created.
    rews = [edge for edge in [seed ->:RewrittenTo:->]];
    assert len(rews) == 0, f"no rewrite should occur with budget=0, got {len(rews)} edges";
}

"""Regression tests for the TypeSpec patch-model PatchTransformer walker.

Each test builds its own graph (tests run in parallel isolated workers),
spawns the walker, and asserts on the program's promised behavior:
- properties with Lifecycle.Update visibility get flipped to optional,
- non-Update properties keep their original optional state,
- recursion descends through NestedModel edges into sub-models,
- the cycle guard prevents re-visiting a node already recorded,
- the walker only lands on Model/NestedModel archetypes (no leaking into
  Property/PropertyLeaf), and printed output reflects the flip/keep split.
"""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
test "update visibility flips to optional, others stay" {
    rt = Model(title="TopModel");

    leaf_name   = Property(name="name",     visibility="Update");
    leaf_loc    = Property(name="location", visibility="Create");
    leaf_id     = Property(name="identity", visibility="Read");
    rt +>:HasProperty:+> leaf_name;
    rt +>:HasProperty:+> leaf_loc;
    rt +>:HasProperty:+> leaf_id;

    root ++> rt;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        w = rt spawn PatchTransformer();
    }
    out = buf.getvalue();

    assert leaf_name.optional is True,  f"Update prop should flip, got {leaf_name.optional}";
    assert leaf_loc.optional  is False, f"Create prop should stay, got {leaf_loc.optional}";
    assert leaf_id.optional   is False, f"Read prop should stay, got {leaf_id.optional}";
    assert "[flip] name -> optional" in out, f"missing flip marker: {out!r}";
    assert "[keep] location" in out, f"missing keep for location: {out!r}";
    assert "[keep] identity" in out, f"missing keep for identity: {out!r}";
}

# ---------------------------------------------------------------------------
test "recursion flips nested update property" {
    rt     = Model(title="TopModel");
    inner  = Model(title="Inner");

    rt +>:HasProperty:+> Property(name="prop", visibility="Update");
    np = Property(name="properties", visibility="Update");
    rt +>:HasProperty:+> np;
    np +>:HasNested:+> NestedModel(type_name="Inner");

    inner +>:HasProperty:+> Property(name="size",    visibility="Update");
    inner +>:HasProperty:+> Property(name="image",   visibility="Create");
    inner +>:HasProperty:+> Property(name="osDisk",  visibility="Update");

    root ++> rt ++> inner;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        rt spawn PatchTransformer();
    }
    out = buf.getvalue();

    # Recursive descent must touch both models.
    assert "model: TopModel" in out, f"missing TopModel descent: {out!r}";
    assert "model: Inner" in out, f"missing Inner descent (no recursion?): {out!r}";
    assert "[flip] size" in out, f"missing nested flip: {out!r}";
    assert "[keep] image" in out, f"missing nested keep: {out!r}";
}

# ---------------------------------------------------------------------------
test "edges and direct property count on the resource" {
    rt = Model(title="R");
    a = Property(name="a", visibility="Update");
    b = Property(name="b", visibility="Read");
    c = Property(name="c", visibility="Create");
    rt +>:HasProperty:+> a;
    rt +>:HasProperty:+> b;
    rt +>:HasProperty:+> c;
    root ++> rt;

    # Graph shape sanity before traversal.
    direct_props = [rt ->:HasProperty:->];
    assert len(direct_props) == 3, f"expected 3 direct props, got {len(direct_props)}";
    assert a in direct_props and b in direct_props and c in direct_props;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        rt spawn PatchTransformer();
    }
    out = buf.getvalue();

    assert "model: R" in out, f"missing model header: {out!r}";
    # Each property should appear exactly once with its own line.
    assert "[flip] a -> optional" in out, f"missing flip a: {out!r}";
    assert "[keep] b optional=False" in out, f"missing keep b: {out!r}";
    assert "[keep] c optional=False" in out, f"missing keep c: {out!r}";
}

# ---------------------------------------------------------------------------
test "cycle guard prevents re-processing the same model" {
    rt = Model(title="Outer");

    # A property whose nested target points back at the outer model —
    # simulating the cycle scenario the issue alludes to (hand-rolled
    # graph machinery blowing up on shared substructures).
    p = Property(name="self", visibility="Update");
    rt +>:HasProperty:+> p;
    p +>:HasNested:+> NestedModel(type_name="OuterRef");

    # Make a back-edge so descending "Outer" would re-hit Outer.
    rt +>:HasProperty:+> Property(name="other", visibility="Read");

    root ++> rt;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        w = rt spawn PatchTransformer();
    }
    out = buf.getvalue();

    # The walker landed on the Outer model exactly once.
    assert out.count("model: Outer") == 1, f"Outer re-entered (cycle guard failed): {out!r}";
    # The nested marker printed once.
    assert out.count("nested: OuterRef") == 1, f"OuterRef should print once: {out!r}";
    # The Update-visibility property still flipped exactly once.
    assert out.count("[flip] self -> optional") == 1, f"self flipped twice: {out!r}";
}

# ---------------------------------------------------------------------------
test "walker counts flips and idempotency is preserved" {
    rt  = Model(title="M1");
    rt2 = Model(title="M2");

    rt +>:HasProperty:+> Property(name="a", visibility="Update");
    rt +>:HasProperty:+> Property(name="b", visibility="Create");

    rt2 +>:HasProperty:+> Property(name="x", visibility="Update");
    rt2 +>:HasProperty:+> Property(name="y", visibility="Update");

    root ++> rt ++> rt2;

    buf1 = io.StringIO();
    with redirect_stdout(buf1) {
        w1 = rt spawn PatchTransformer();
    }
    flips_first = w1.flipped;
    assert flips_first == 3, f"expected 3 flips across M1+M2, got {flips_first}";

    # All Update props are now optional=False? No — optional=True. Running
    # again must NOT re-count them.
    buf2 = io.StringIO();
    with redirect_stdout(buf2) {
        w2 = rt spawn PatchTransformer();
    }
    assert w2.flipped == 0, f"idempotent re-run should flip 0, got {w2.flipped}";
    # And the second run still descends into both models.
    out2 = buf2.getvalue();
    assert "model: M1" in out2 and "model: M2" in out2, f"missing model headers: {out2!r}";
}

