    s0 = Segment(segment_index=0, continuation_token="seg-0", artifact_id="a0", title="zero", year=2026);
    s1 = Segment(segment_index=1, continuation_token="seg-1", artifact_id="a1", title="one", year=2026);
    s2 = Segment(segment_index=2, continuation_token="seg-2", artifact_id="a2", title="two", year=2026);
    s3 = Segment(segment_index=3, continuation_token="seg-3", artifact_id="a3", title="three", year=2026);
    coll +>:Partition:+> s0 +>:Continues:+> s1 +>:Continues:+> s2 +>:Continues:+> s3;

    pass1 = CollectionAuditor(batch_quota=2);
