    assert "[INDEX] [IN] a3 three" in out, f"pass2 should index a3, got: {out}";
    assert "a0" not in out and "a1" not in out, f"pass2 must not reindex a0/a1, got: {out}";
    assert pass2.indexed_count == 2, f"pass2 indexed_count {pass2.indexed_count}";
    assert pass2.checkpoint == "seg-3", f"pass2 checkpoint {pass2.checkpoint}";
}

test "full bounded pass seals collection and indexes every segment exactly once" {
