"""Tests for the unresolved reviewer feedback backlog graph program."""

import io;
import from contextlib { redirect_stdout }

test "backlog sweep collects all unresolved threads across repos" {
    root ++> Node();
    site = Repo(name="nathanjohnpayne/nathanpaynedotcom", target_count=39);
    merger = Repo(name="nathanjohnpayne/mergepath", target_count=25);

    pr_analytics = PullRequest(title="fix(analytics): create person profiles", closed=True);
    pr_blog = PullRequest(title="feat(blog): key takeaways box and CTA", closed=True);
    pr_merge = PullRequest(title="refactor(merge): simplify path planner", closed=True);

    t_critical = ReviewThread(severity="P0", resolved=False, body="neg assertion ignore comments");
    t_yaml = ReviewThread(severity="P1", resolved=False, body="honor escaped YAML line breaks");
    t_navigation = ReviewThread(severity="P1", resolved=False, body="let nav tracks shrink below zero");
    t_schema = ReviewThread(severity="P2", resolved=False, body="document the new blog schema fields");
    t_merge_a = ReviewThread(severity="P1", resolved=False, body="handle empty input sets");
    t_merge_b = ReviewThread(severity="P2", resolved=False, body="rename internal helper");

    root +>:BelongsTo:+> site;
    root +>:BelongsTo:+> merger;

    site +>:FiledAgainst:+> pr_analytics;
    site +>:FiledAgainst:+> pr_blog;
    merger +>:FiledAgainst:+> pr_merge;

    pr_analytics +>:ThreadOn:+> t_critical;
    pr_blog +>:ThreadOn:+> t_yaml;
    pr_blog +>:ThreadOn:+> t_navigation;
    pr_blog +>:ThreadOn:+> t_schema;
    pr_merge +>:ThreadOn:+> t_merge_a;
    pr_merge +>:ThreadOn:+> t_merge_b;

    sweeper = BacklogSweeper(label="t-sweep", lookback_days=90);
    root spawn sweeper;

    unresolved = [n for n in sweeper.collected if isinstance(n, ReviewThread)];
    assert len(unresolved) == 6, f"expected 6 unresolved threads, got {len(unresolved)}";
    assert t_critical in unresolved, "P0 critical thread must be collected";
    assert t_merge_a in unresolved, "mergepath P1 thread must be collected";
}

