test "typed edge directions enforce traversal semantics" {
    root ++> Node();
    site = Repo(name="nathanjohnpayne/nathanpaynedotcom", target_count=39);
    merger = Repo(name="nathanjohnpayne/mergepath", target_count=25);

    pr_blog = PullRequest(title="feat(blog): takeaways", closed=True);
    t_yaml = ReviewThread(severity="P1", resolved=False, body="yaml breaks");

    root +>:BelongsTo:+> site;
    root +>:BelongsTo:+> merger;
    site +>:FiledAgainst:+> pr_blog;
    pr_blog +>:ThreadOn:+> t_yaml;

    sweeper = BacklogSweeper(label="edges");
    root spawn sweeper;

    repos = [n for n in sweeper.collected if isinstance(n, Repo)];
    threads = [n for n in sweeper.collected if isinstance(n, ReviewThread)];
    assert len(repos) == 2, f"both repos must be tallied via BelongsTo, got {len(repos)}";
    assert site in repos, "site repo must be reached";
    assert merger in repos, "merger repo must be reached";
    assert len(threads) == 1, f"only the one thread should be collected, got {len(threads)}";

    # PR is not in collected because audit only descends when closed and does not append.
    prs = [n for n in sweeper.collected if isinstance(n, PullRequest)];
    assert len(prs) == 0, f"PRs should not be appended to collected, got {len(prs)}";

    # Typed-edge query sanity.
    assert pr_blog in [site ->:FiledAgainst:->], "PR must be reachable via FiledAgainst from site";
    assert t_yaml in [pr_blog ->:ThreadOn:->], "thread must be reachable via ThreadOn from PR";
    assert site in [root ->:BelongsTo:->], "site must be reachable via BelongsTo from root";
}

