"""Tests for the forjar apply --plan-file confirmation model.

The issue: when `apply --plan-file` runs, it bypasses the preflight that
would normally prompt before a destructive change. The program models
this asymmetry with two walkers (NormalApply, PlanFileApply) over a
graph of ApplyConfig -> ApplyMode -> Preflight -> Plan.

These tests exercise the call-graph shape the issue calls out:
- Normal apply path: prompt fires, destructive delta halts.
- Plan-file path: preflight is never visited, plan runs unconfirmed.
- --yes flag on the plan-file path: still no prompt (the prompt is
  never reached, not skipped).
"""

import io;
import from contextlib { redirect_stdout }

test "normal apply path prompts and aborts on to_destroy > 0" {
    cfg = ApplyConfig(yes_flag=False, tty=True);
    normal_mode = ApplyMode(name="normal", calls_preflight=True);
    preflight = Preflight(confirm_destructive=True, dry_run=False);
    plan = Plan(to_destroy=3, minutes_old=0);

    cfg +>:RoutedThrough:+> normal_mode;
    normal_mode +>:RoutedThrough:+> preflight;
    preflight +>:RoutedThrough:+> plan;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = cfg spawn NormalApply();
    }
    out = buf.getvalue();

    assert res.prompted, f"expected prompt to fire on normal path, got {res.prompted}";
    assert res.aborted, f"expected abort when to_destroy>0 and no --yes, got aborted={res.aborted}";
    assert "[normal] prompt raised for to_destroy=3" in out, f"missing halt line: {out!r}";
    assert "[normal] executing plan" not in out, f"normal path should NOT execute, got: {out!r}";
}

test "plan-file apply path skips preflight and executes without prompt" {
    cfg = ApplyConfig(yes_flag=False, tty=True);
    plan_mode = ApplyMode(name="from_plan_file", calls_preflight=False);
    preflight = Preflight(confirm_destructive=True, dry_run=False);
    plan = Plan(to_destroy=3, minutes_old=0);

    cfg +>:RoutedThrough:+> plan_mode;
    plan_mode +>:RoutedThrough:+> preflight;
    preflight +>:RoutedThrough:+> plan;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = cfg spawn PlanFileApply();
    }
    out = buf.getvalue();

    assert not res.prompted, f"plan-file path must NOT prompt (the bug); got prompted={res.prompted}";
    assert not res.aborted, f"plan-file walker has no abort branch; got aborted={res.aborted}";
    assert "[plan-file] executing plan WITHOUT prompt" in out, f"missing unconfirmed execution line: {out!r}";
    assert "to_destroy=3" in out and "minutes_old=0" in out, f"plan payload not reported: {out!r}";
}

test "plan-file path is unchanged by --yes flag (prompt is unreachable, not skipped)" {
    cfg = ApplyConfig(yes_flag=True, tty=True);
    plan_mode = ApplyMode(name="from_plan_file", calls_preflight=False);
    preflight = Preflight(confirm_destructive=True, dry_run=False);
    plan = Plan(to_destroy=3, minutes_old=0);

    cfg +>:RoutedThrough:+> plan_mode;
    plan_mode +>:RoutedThrough:+> preflight;
    preflight +>:RoutedThrough:+> plan;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = cfg spawn PlanFileApply();
    }
    out = buf.getvalue();

    assert not res.prompted, f"--yes cannot suppress a prompt that never fires; got prompted={res.prompted}";
    assert res.yes_flag, f"yes_flag must propagate from ApplyConfig; got {res.yes_flag}";
    assert "[plan-file] executing plan WITHOUT prompt" in out, f"plan-file must still execute: {out!r}";
}

test "stale plan via plan-file path executes without prompt" {
    cfg = ApplyConfig(yes_flag=False, tty=True);
    plan_mode = ApplyMode(name="from_plan_file", calls_preflight=False);
    preflight = Preflight(confirm_destructive=True, dry_run=False);
    stale = Plan(to_destroy=1, minutes_old=1440);

    cfg +>:RoutedThrough:+> plan_mode;
    plan_mode +>:RoutedThrough:+> preflight;
    preflight +>:RoutedThrough:+> stale;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = cfg spawn PlanFileApply();
    }
    out = buf.getvalue();

    assert not res.prompted, "stale plan via plan-file must not prompt";
    assert "to_destroy=1" in out and "minutes_old=1440" in out, f"stale plan payload missing: {out!r}";
    assert "WITHOUT prompt" in out, f"expected the unconfirmed-execution marker: {out!r}";
}

test "dry_run on normal path lets execution proceed without prompt" {
    cfg = ApplyConfig(yes_flag=False, tty=True);
    normal_mode = ApplyMode(name="normal", calls_preflight=True);
    preflight = Preflight(confirm_destructive=True, dry_run=True);
    plan = Plan(to_destroy=3, minutes_old=0);

    cfg +>:RoutedThrough:+> normal_mode;
    normal_mode +>:RoutedThrough:+> preflight;
    preflight +>:RoutedThrough:+> plan;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = cfg spawn NormalApply();
    }
    out = buf.getvalue();

    assert not res.prompted, f"dry_run must suppress the prompt; got prompted={res.prompted}";
    assert not res.aborted, f"dry_run must not abort; got aborted={res.aborted}";
    assert "[normal] executing plan: to_destroy=3" in out, f"expected execution under dry_run: {out!r}";
}

"""Regression tests for the marshal-style nested-set walker in main.jac.

The program models cpython issue #155901: a walker traverses a chain of
nested FrozenSet nodes via ChildOf edges, computing a sort key by spawning
fresh MarshalWriter visits on every child. We verify the graph shape,
the visit counts, the deterministic sort_key format, and the multi-child
branching case."""

# ============================================================
# Test 1: linear chain shape — ChildOf edges connect outer→inner
# ============================================================
test "linear chain has correct depth and edges" {
    rt = Root();
    a = FrozenSet(label="L0", depth=0);
    b = FrozenSet(label="L1", depth=1);
    c = FrozenSet(label="L2", depth=2);
    d = FrozenSet(label="L3", depth=3);

    rt +>:ChildOf:+> a;
    a +>:ChildOf:+> b;
    b +>:ChildOf:+> c;
    c +>:ChildOf:+> d;

    # 4 ChildOf edges from root down to the innermost node
    assert len([rt ->:ChildOf:->]) == 1, "root should have 1 child";
    assert d in [c ->:ChildOf:->], "d should be child of c";
    assert c in [b ->:ChildOf:->], "c should be child of b";
    assert b in [a ->:ChildOf:->], "b should be child of a";
    assert a in [rt ->:ChildOf:->], "a should be child of root";

    # Depth labels preserved
    assert a.depth == 0 and d.depth == 3, f"got depths {a.depth}, {d.depth}";
}

# ============================================================
# Test 2: walker visits every node exactly once on a linear chain
# (the buggy C code would touch inner nodes multiple times because the
# sort-key walk re-marshals each child; in this Jac version each child
# is spawned once and `visit` moves forward, so total touches == nodes)
# ============================================================
test "linear chain: each node visited exactly once" {
    import io;
    import from contextlib { redirect_stdout }

    rt = Root();
    n0 = FrozenSet(label="L0", depth=0);
    n1 = FrozenSet(label="L1", depth=1);
    n2 = FrozenSet(label="L2", depth=2);
    n3 = FrozenSet(label="L3", depth=3);
    n4 = FrozenSet(label="L4", depth=4);

    rt +>:ChildOf:+> n0;
    n0 +>:ChildOf:+> n1;
    n1 +>:ChildOf:+> n2;
    n2 +>:ChildOf:+> n3;
    n3 +>:ChildOf:+> n4;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = rt spawn MarshalWriter();
    }
    out = buf.getvalue();

    # Every depth from 0..4 must appear in the output exactly once
    for d in range(5) {
        needle = f"depth={d} ";
        count = out.count(needle);
        assert count == 1, f"depth={d} appeared {count} times in: {out!r}";
    }

    # times_visited dictionary: every label touched exactly once
    tv = res.times_visited;
    assert len(tv) == 5, f"expected 5 distinct labels visited, got {len(tv)}";
    for lbl in ["L0", "L1", "L2", "L3", "L4"] {
        assert tv[lbl] == 1, f"label {lbl} visited {tv[lbl]} times, expected 1";
    }
}

# ============================================================
# Test 3: sort_key uses children's labels joined with '|',
# in sorted order (the whole point of the re-marshal pass
# in the C code is determinism).
# ============================================================
test "sort_key joins children labels with pipe in sorted order" {
    import io;
    import from contextlib { redirect_stdout }

    rt = Root();
    parent = FrozenSet(label="P", depth=0);
    # Children in NON-sorted insertion order — the sort_key must sort them
    c1 = FrozenSet(label="charlie", depth=1);
    c2 = FrozenSet(label="alpha", depth=1);
    c3 = FrozenSet(label="bravo", depth=1);
    # Parent has no children itself — just to give children a parent link
    leaf = FrozenSet(label="zeta", depth=2);

    rt +>:ChildOf:+> parent;
    parent +>:ChildOf:+> c1;
    parent +>:ChildOf:+> c2;
    parent +>:ChildOf:+> c3;
    c2 +>:ChildOf:+> leaf;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = rt spawn MarshalWriter();
    }
    out = buf.getvalue();

    # The parent line must show the sorted, pipe-joined children
    # Expected children-of-parent: charlie, alpha, bravo  → sorted: alpha|bravo|charlie
    assert "sort_key='alpha|bravo|charlie'" in out, f"missing expected sort_key, got: {out}";
    # No UnsortedForm should leak through
    assert "sort_key='charlie|alpha|bravo'" not in out, f"sort_key not sorted: {out}";
    # The parent depth line must appear
    assert "depth=0 label=P" in out, f"parent depth line missing in: {out}";
}

# ============================================================
# Test 4: branching fan-out — a node with multiple children triggers
# multiple recursive spawns; each child still produces exactly one
# visit line.
# ============================================================
test "branching graph: each node touched once despite fan-out" {
    import io;
    import from contextlib { redirect_stdout }

    rt = Root();
    hub = FrozenSet(label="HUB", depth=0);
    # Three independent subtrees branching from the hub
    sa = FrozenSet(label="A", depth=1);
    sb = FrozenSet(label="B", depth=1);
    sc = FrozenSet(label="C", depth=1);
    sa_leaf = FrozenSet(label="A-end", depth=2);
    sb_leaf = FrozenSet(label="B-end", depth=2);

    rt +>:ChildOf:+> hub;
    hub +>:ChildOf:+> sa;
    hub +>:ChildOf:+> sb;
    hub +>:ChildOf:+> sc;
    sa +>:ChildOf:+> sa_leaf;
    sb +>:ChildOf:+> sb_leaf;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = rt spawn MarshalWriter();
    }
    out = buf.getvalue();

    # The hub must report three children joined by '|', sorted
    assert "label=HUB sort_key='A|B|C'" in out, f"hub sort_key wrong, got: {out}";

    # Every label should appear exactly once in times_visited
    tv = res.times_visited;
    expected_labels = ["HUB", "A", "B", "C", "A-end", "B-end"];
    assert len(tv) == len(expected_labels), f"expected {len(expected_labels)} visited, got {len(tv)}: {tv}";
    for lbl in expected_labels {
        assert tv[lbl] == 1, f"label {lbl} visited {tv[lbl]} times, expected 1. tv={tv}";
    }

    # 6 nodes → 6 visit lines
    visit_lines = [ln for ln in out.splitlines() if ln.startswith("depth=")];
    assert len(visit_lines) == 6, f"expected 6 visit lines, got {len(visit_lines)}: {out}";
}

# ============================================================
# Test 5: deterministic output — running the walker twice on the
# same graph yields byte-identical stdout. (This is what marshalling
# a nested frozenset should give: a stable byte stream.)
# ============================================================
test "deterministic output across runs" {
    import io;
    import from contextlib { redirect_stdout }

    def build_and_run() -> str {
        rt = Root();
        n0 = FrozenSet(label="X0", depth=0);
        n1 = FrozenSet(label="X1", depth=1);
        n2 = FrozenSet(label="X2", depth=2);
        rt +>:ChildOf:+> n0;
        n0 +>:ChildOf:+> n1;
        n1 +>:ChildOf:+> n2;
        buf = io.StringIO();
        with redirect_stdout(buf) {
            rt spawn MarshalWriter();
        }
        return buf.getvalue();
    }

    out1 = build_and_run();
    out2 = build_and_run();
    assert out1 == out2, f"non-deterministic output:\n--- run1 ---\n{out1}\n--- run2 ---\n{out2}";
    # Sanity: must contain all three depth lines
    assert "depth=0 label=X0" in out1;
    assert "depth=1 label=X1" in out1;
    assert "depth=2 label=X2" in out1;
}

"""Regression tests for the RecursionError / cycle-guard demo.

These tests exercise the behaviors the program promises:

  * The walker descends the typed ``DependsOn`` edge chain.
  * Without the cycle guard it would loop forever (we model "without guard"
    by setting ``depth_budget`` huge, but we still rely on the visited
    set to terminate on the cycle and observe the [CYCLE] marker).
  * With a small budget it disengages on the budget check and emits the
    [RecursionError] marker before any cycle re-entry.
  * Node shape: exactly one Root, one A->B->C->A cycle, plus a Leaf
    reachable from B.
"""

import io;
import from contextlib { redirect_stdout }

test "walker reports the cycle instead of recursing forever" {
    root ++> Type(name="A", is_alias=True);
    a = [root -->][?:Type][0];
    b = Type(name="B", is_alias=True);
    c = Type(name="C", is_alias=True);
    leaf = Type(name="Leaf", is_alias=False);
    a +>:DependsOn(note="unfolds to"):+> b;
    b +>:DependsOn(note="concatenate"):+> c;
    c +>:DependsOn(note="recursive ref"):+> a;
    b +>:DependsOn(note="base case"):+> leaf;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn DependencyAnalyzer(depth_budget=1000);
    }
    out = buf.getvalue();

    assert "[CYCLE] re-entered A" in out, f"expected cycle marker on A, got: {out}";
    # A, B, C are each visited exactly once before the cycle re-entry.
    assert out.count("[CYCLE]") == 1, f"expected exactly one cycle stop, got: {out}";
    # All three alias types appear in the resolution trace.
    assert "resolving alias type A" in out, f"missing A in trace: {out}";
    assert "resolving alias type B" in out, f"missing B in trace: {out}";
    assert "resolving alias type C" in out, f"missing C in trace: {out}";
    # The walker must terminate cleanly (no hang) and never report RecursionError here.
    assert "[RecursionError]" not in out, f"unexpected budget trip: {out}";
    assert res.depth_budget == 1000, f"walker state corrupted: {res.depth_budget}";
}

test "small depth budget disengages before the cycle closes" {
    root ++> Type(name="A", is_alias=True);
    a = [root -->][?:Type][0];
    b = Type(name="B", is_alias=True);
    c = Type(name="C", is_alias=True);
    leaf = Type(name="Leaf", is_alias=False);
    a +>:DependsOn(note="unfolds to"):+> b;
    b +>:DependsOn(note="concatenate"):+> c;
    c +>:DependsOn(note="recursive ref"):+> a;
    b +>:DependsOn(note="base case"):+> leaf;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn DependencyAnalyzer(depth_budget=2);
    }
    out = buf.getvalue();

    # With budget 2 the walker can only record two nodes before disengaging.
    assert "[RecursionError]" in out, f"budget guard failed to fire: {out}";
    # We must NOT have seen the cycle in this run.
    assert "[CYCLE]" not in out, f"cycle fired before budget guard: {out}";
    # Depth check fires on the 3rd entry attempt (after recording two names).
    assert len(res.visited) <= 2, f"visited exceeded budget: {res.visited}";
}

test "graph shape: cycle plus terminating leaf branch" {
    root ++> Type(name="A", is_alias=True);
    a = [root -->][?:Type][0];
    b = Type(name="B", is_alias=True);
    c = Type(name="C", is_alias=True);
    leaf = Type(name="Leaf", is_alias=False);
    a +>:DependsOn(note="unfolds to"):+> b;
    b +>:DependsOn(note="concatenate"):+> c;
    c +>:DependsOn(note="recursive ref"):+> a;
    b +>:DependsOn(note="base case"):+> leaf;

    # Root is the only thing hanging off the entry.
    assert len([root -->]) == 1, f"root should have exactly one Type child, got {len([root -->])}";
    rt = [root -->][?:Type][0];
    assert rt.name == "A", f"expected A under root, got {rt.name}";
    assert rt.is_alias, "A should be flagged as an alias type";

    # A depends on exactly B (and only B).
    a_deps = [a ->:DependsOn:->];
    assert len(a_deps) == 1, f"A should have one DependsOn, got {len(a_deps)}";
    assert a_deps[0].name == "B", f"A's dependency should be B, got {a_deps[0].name}";

    # B has two outgoing deps: C (cycle leg) and Leaf (terminator).
    b_deps = [b ->:DependsOn:->];
    assert len(b_deps) == 2, f"B should have two DependsOn edges, got {len(b_deps)}";
    b_targets = {d.name for d in b_deps};
    assert b_targets == {"C", "Leaf"}, f"B should target {{C, Leaf}}, got {b_targets}";

    # C points back to A, closing the cycle.
    c_deps = [c ->:DependsOn:->];
    assert len(c_deps) == 1, f"C should have one DependsOn, got {len(c_deps)}";
    assert c_deps[0].name == "A", f"C's dependency should be A, got {c_deps[0].name}";

    # Leaf is terminal: no outgoing DependsOn.
    assert len([leaf ->:DependsOn:->]) == 0, "Leaf should have no outgoing dependencies";

    # Round-trip reachability: Leaf is reachable from A via B.
    assert leaf in [a ->:DependsOn:-> ->:DependsOn:->], "Leaf not reachable from A through B";
}

test "is_alias flag distinguishes recursive aliases from concrete types" {
    alias_node = Type(name="Rec", is_alias=True);
    concrete_node = Type(name="Concrete", is_alias=False);
    root ++> alias_node;
    root ++> concrete_node;

    assert alias_node.is_alias is True, "alias node must carry is_alias=True";
    assert concrete_node.is_alias is False, "concrete node must carry is_alias=False";

    # The walker labels them differently in its trace.
    a = [root -->][?:Type][?name=="Rec"][0];
    leaf = [root -->][?:Type][?name=="Concrete"][0];
    a +>:DependsOn(note="self-ref"):+> a;
    leaf +>:DependsOn(note="link"):+> alias_node;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn DependencyAnalyzer(depth_budget=50);
    }
    out = buf.getvalue();

    assert "resolving alias type Rec" in out, f"alias label missing: {out}";
    assert "resolving concrete type Concrete" in out, f"concrete label missing: {out}";
    # Self-loop on Rec still produces a single [CYCLE] marker.
    assert out.count("[CYCLE]") == 1, f"expected one cycle stop on self-loop, got: {out}";
}

"""Test annex for the ontology shortest-path finder."""

import io;
import from contextlib { redirect_stdout }

# Helper used across tests to assemble the demo ontology from main.jac.
def build_demo() {
    cat_node = ClassNode(name="Cat", label="Cat");
    animal_node = ClassNode(name="Animal", label="Animal");
    dog_node = ClassNode(name="Dog", label="Dog");
    person_node = ClassNode(name="Person", label="Person");
    human_node = ClassNode(name="Human", label="Human");
    concept_node = SKOSNode(name="Concept", pref_label="Concept");
    isolated_node = ClassNode(name="Unrelated", label="Unrelated");

    root ++> cat_node
        +>:SubClassOf:+> animal_node
        +>:SubClassOf:+> dog_node
        +>:SubClassOf:+> person_node
        +>:EquivalentTo:+> human_node
        +>:RelatedTo:+> concept_node;
    root ++> isolated_node;
}

test "shortest path Cat to Person is 3 hops through Animal and Dog" {
    build_demo();
    finder = PathFinder(source="Cat", target="Person");
    res = root spawn finder;

    assert res.found, "Cat -> Person must be reachable in demo graph";
    assert res.hops == 3, f"expected 3 hops, got {res.hops}";
    assert res.trail == ["Cat", "Animal", "Dog", "Person"],
        f"unexpected trail: {res.trail}";
}

test "disconnected target reports no path and leaves hops at -1" {
    build_demo();
    finder = PathFinder(source="Cat", target="Unrelated");
    res = root spawn finder;

    assert not res.found,
        "Unrelated sits in its own component, walker must report no path";
    assert res.hops == -1,
        f"hops must stay at -1 when no path exists, got {res.hops}";
}

test "demo entry block prints the path then the disconnected warning" {
    # Build the same graph the demo wires so stdout reflects main.jac's
    # two-case demo run end-to-end.
    cat_node = ClassNode(name="Cat", label="Cat");
    animal_node = ClassNode(name="Animal", label="Animal");
    dog_node = ClassNode(name="Dog", label="Dog");
    person_node = ClassNode(name="Person", label="Person");
    human_node = ClassNode(name="Human", label="Human");
    concept_node = SKOSNode(name="Concept", pref_label="Concept");
    isolated_node = ClassNode(name="Unrelated", label="Unrelated");
    root ++> cat_node
        +>:SubClassOf:+> animal_node
        +>:SubClassOf:+> dog_node
        +>:SubClassOf:+> person_node
        +>:EquivalentTo:+> human_node
        +>:RelatedTo:+> concept_node;
    root ++> isolated_node;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        f1 = PathFinder(source="Cat", target="Person");
        root spawn f1;
        if f1.found {
            print(f"Path: {' -> '.join(f1.trail)} ({f1.hops} hops)");
        } else {
            print("no path found");
        }

        f2 = PathFinder(source="Cat", target="Unrelated");
        root spawn f2;
        if f2.found {
            print(f"Path: {' -> '.join(f2.trail)}");
        } else {
            print(f"no path between {f2.source} and {f2.target} "
                  f"(disconnected components)");
        }
    }
    out = buf.getvalue();

    assert "Cat -> Animal -> Dog -> Person" in out,
        f"missing shortest path line in demo output: {out!r}";
    assert "3 hops" in out,
        f"missing hop count in demo output: {out!r}";
    assert "no path between Cat and Unrelated" in out,
        f"missing disconnected-components message: {out!r}";
}

test "cycle guard prevents infinite re-entry on a self loop" {
    # A direct SubClassOf from Cat back to itself. Without the visited
    # set the walker would loop forever; with it the trail terminates
    # cleanly and reports a single hop.
    cat = ClassNode(name="LoopCat", label="LoopCat");
    prey = ClassNode(name="Prey", label="Prey");
    root ++> cat +>:SubClassOf:+> prey +>:SubClassOf:+> cat;
    # Add a genuine tail so the target exists somewhere reachable.
    prey +>:SubClassOf:+> ClassNode(name="Target", label="Target");

    finder = PathFinder(source="LoopCat", target="Target");
    res = root spawn finder;

    assert res.found, "Target must be reachable despite the loop";
    assert res.hops >= 2, f"need at least 2 hops, got {res.hops}";
    assert res.trail[0] == "LoopCat", f"trail should start at source: {res.trail}";
    assert res.trail[-1] == "Target", f"trail should end at target: {res.trail}";
    # Visited set must contain no duplicates, proving the cycle guard fired.
    assert len(set(res.visited)) == len(res.visited),
        f"visited set has duplicates, cycle guard failed: {res.visited}";
}

test "max_depth bounds the search and prevents runaway on a long chain" {
    # 25-node chain; with max_depth=3 the walker must give up before
    # reaching the target and report hops=-1.
    head = ClassNode(name="Head", label="Head");
    prev = head;
    for i in range(0, 24) {
        n = ClassNode(name=f"N{i}", label=f"N{i}");
        prev +>:SubClassOf:+> n;
        prev = n;
    }
    tail = ClassNode(name="Tail", label="Tail");
    prev +>:SubClassOf:+> tail;

    finder = PathFinder(source="Head", target="Tail", max_depth=3);
    res = root spawn finder;

    assert not res.found,
        f"max_depth=3 must cap search, but walker reported a path: {res.trail}";
    assert res.hops == -1,
        f"hops must remain -1 when depth cap is hit, got {res.hops}";
    assert len(res.trail) <= 4,
        f"trail should respect max_depth, got {len(res.trail)} entries";
}

import io;
import from contextlib { redirect_stdout }

test "cycle reports a clear diagnostic" {
    rootR = Row(title="Root", track_by="r1");
    cycleNode = Row(title="Cycle", track_by="c1");

    root ++> rootR;
    rootR +>:ChildOf:+> cycleNode;
    cycleNode +>:ChildOf:+> rootR;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Flatten();
    }
    out = buf.getvalue();

    assert res.rows == ["r1", "c1"], f"rows: {res.rows}";
    assert len(res.visited) == 2, f"visited: {res.visited}";
    assert res.dup_count == 1, f"duplicates: {res.dup_count}";
    assert "[cycle detected]" in out, f"missing cycle diagnostic: {out}";
}

test "invalid empty row is reported without crashing" {
    parent = Row(title="Parent", track_by="p1");
    invalid = Row(title="", track_by="");

    root ++> parent;
    parent +>:ChildOf:+> invalid;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Flatten();
    }
    out = buf.getvalue();

    assert res.rows == ["p1"], f"rows: {res.rows}";
    assert len(res.visited) == 1, f"visited: {res.visited}";
    assert res.dup_count == 0, f"duplicates: {res.dup_count}";
    assert "[invalid node]" in out, f"missing invalid-node diagnostic: {out}";
}

test "shared child is visited once and flagged as duplicate" {
    anchor = Row(title="Anchor", track_by="a1");
    first = Row(title="First Parent", track_by="p1", expanded=True);
    second = Row(title="Second Parent", track_by="p2", expanded=True);
    leaf = Row(title="Shared Leaf", track_by="l1");

    root ++> anchor;
    anchor +>:ChildOf:+> first;
    anchor +>:ChildOf:+> second;
    first +>:ChildOf:+> leaf;
    second +>:ChildOf:+> leaf;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Flatten();
    }
    out = buf.getvalue();

    assert len(res.rows) == 4, f"rows: {res.rows}";
    assert len(res.visited) == 4, f"visited: {res.visited}";
    assert res.dup_count == 1, f"duplicates: {res.dup_count}";
    assert res.rows[0] == "a1", f"first row: {res.rows}";
    assert res.rows[1] == "p1", f"first parent order: {res.rows}";
    assert res.rows[2] == "l1", f"leaf order: {res.rows}";
    assert "Shared Leaf" in out, f"missing shared leaf output: {out}";
}

test "full verification covers every consumer" {
    shared = Artifact(name="shared-workflow", kind="workflow", consumed_by_repos=2);
    first = Consumer(repo="acme/one", surface="workflow_call");
    second = Consumer(repo="acme/two", surface="workflow_call");
    full = CIRun(job="ci/full", selection="full");

    first +>:ConsumedBy(via="workflow_call"):+> shared;
    second +>:ConsumedBy(via="workflow_call"):+> shared;
    full +>:Reaches(coverage="all"):+> shared;
    root ++> shared;

    assert len([root-->]) == 1, f"got {len([root-->])}";
    assert shared in [first ->:ConsumedBy:->], f"missing first consumer edge";
    assert shared in [second ->:ConsumedBy:->], f"missing second consumer edge";
    assert shared in [full ->:Reaches:->], f"missing reach edge";

    res = root spawn ReachAuditor();

    assert len(res.verdicts) == 1, f"got {res.verdicts}";
    assert res.verdicts[0]["artifact"] == "shared-workflow", f"got {res.verdicts}";
    assert res.verdicts[0]["radius"] == 2, f"got {res.verdicts}";
    assert res.verdicts[0]["covered"] == 2, f"got {res.verdicts}";
    assert res.verdicts[0]["verdict"] == "SAFE", f"got {res.verdicts}";
}

