import io;
import from contextlib { redirect_stdout }

test "run historian flags 3 consecutive reds with correct drift window" {
    `root = Root();

    last_green = WorkflowRun(
        commit_sha="b828fcf6",
        run_time="2026-07-06T03:51",
        conclusion="success"
    );
    red1 = WorkflowRun(
        commit_sha="f3bdee41",
        run_time="2026-07-13T03:20",
        conclusion="failure"
    );
    red2 = WorkflowRun(
        commit_sha="7bc77da4",
        run_time="2026-07-20T03:28",
        conclusion="failure"
    );
    red3 = WorkflowRun(
        commit_sha="ce501063",
        run_time="2026-07-27T03:29",
        conclusion="failure"
    );
    `root ++> last_green +>:Chronological:+> red1 +>:Chronological:+> red2
        +>:Chronological:+> red3;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = `root spawn RunHistorian();
    }
    out = buf.getvalue();

    assert "[ OK ] 2026-07-06T03:51 head=b828fcf6" in out, f"missing green line: {out}";
    assert "[FAIL] 2026-07-13T03:20 head=f3bdee41 (week 1 unobserved red)" in out, f"missing first red: {out}";
    assert "[FAIL] 2026-07-20T03:28 head=7bc77da4 (week 2 unobserved red)" in out, f"missing second red: {out}";
    assert "[FAIL] 2026-07-27T03:29 head=ce501063 (week 3 unobserved red)" in out, f"missing third red: {out}";
    assert "streak summary: 3 consecutive failure(s) after last green b828fcf6" in out, f"missing streak summary: {out}";
    assert "baseline drift window: b828fcf6 (green) -> f3bdee41 (first red)" in out, f"missing drift window: {out}";
    assert res.consecutive_failures == 3, f"got {res.consecutive_failures}";
    assert res.first_red_sha == "f3bdee41", f"got first_red {res.first_red_sha}";
    assert res.last_green_sha == "b828fcf6", f"got last_green {res.last_green_sha}";
}

test "consumer doctor only inspects the failing step and cites every violation" {
    `root = Root();

    audit = EscalationAudit(job_name="escalation-audit");
    status = ConsumerCheck(step_name="HELIX status and continuation", passed=True);
    packet = ConsumerCheck(step_name="HELIX completion decision packet", passed=True);
    bundle = ConsumerCheck(step_name="HELIX completion review bundle", passed=True);
    doctor = ConsumerCheck(step_name="HELIX consumer doctor", passed=False);
    `root ++> audit;
    audit +>:Executes:+> status +>:Executes:+> packet +>:Executes:+> bundle
        +>:Executes:+> doctor;

    doctor +>:Reports:+> Violation(
        consumer_id="consumer-claude-adapter",
        detail="Claude hooks JSON/schema baseline incomplete"
    );
    doctor +>:Reports:+> Violation(
        consumer_id="consumer-codex-adapter",
        detail="Codex hooks/config JSON/schema baseline incomplete"
    );
    doctor +>:Reports:+> Violation(
        consumer_id="consumer-escalation-workflow",
        detail="unexpectedTriggers=workflow_dispatch tokenWrite=false"
    );

    buf = io.StringIO();
    with redirect_stdout(buf) {
        `root spawn ConsumerDoctor();
    }
    out = buf.getvalue();

    assert "job: escalation-audit" in out, f"missing job line: {out}";
    assert "  [OK] HELIX status and continuation" in out, f"missing status step: {out}";
    assert "  [OK] HELIX completion decision packet" in out, f"missing packet step: {out}";
    assert "  [OK] HELIX completion review bundle" in out, f"missing bundle step: {out}";
    assert "  [X] HELIX consumer doctor" in out, f"missing doctor step: {out}";
    assert "    doctor: consumer-claude-adapter - violation Claude hooks JSON/schema baseline incomplete" in out, f"missing claude violation: {out}";
    assert "    doctor: consumer-codex-adapter - violation Codex hooks/config JSON/schema baseline incomplete" in out, f"missing codex violation: {out}";
    assert "    doctor: consumer-escalation-workflow - violation unexpectedTriggers=workflow_dispatch tokenWrite=false" in out, f"missing escalation violation: {out}";

    passing_count = out.count("  [OK]");
