"""Test annex for VST3 beginEdit/getState deadlock demo."""

import io;
import from contextlib { redirect_stdout }

# Helper: build the canonical broken (sync) bridge topology.
def build_broken() -> tuple {
    broken = BridgeProxy(mutual_recursion=False);
    spaced = PluginSandbox(plugin_name="BABY Audio Spaced Out");
    spaced +>:SandboxLink:+> broken;
    `root = DAWHost(name="Bitwig Studio 6.0.11");
    broken +>:HostLink:+> `root;
    return (broken, spaced, `root);
}

# Helper: build the canonical patched (mutual recursion) bridge topology.
def build_fixed() -> tuple {
    fixed = BridgeProxy(mutual_recursion=True);
    soothe = PluginSandbox(plugin_name="soothe2");
    soothe +>:SandboxLink:+> fixed;
    `root = DAWHost(name="Bitwig Studio 6.0.11");
    fixed +>:HostLink:+> `root;
    return (fixed, soothe, `root);
}

test "broken bridge deadlocks: both flags set, mutual_recursion=False" {
    (broken, spaced, host) = build_broken();

    # Sanity: the failure mode the issue describes requires BOTH concurrent calls
    # in flight on a bridge that is NOT configured for mutual recursion.
    assert broken.mutual_recursion == False, f"setup wrong: {broken.mutual_recursion}";
    assert broken.would_deadlock() == False, "no in-flight calls yet, must not deadlock";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = spaced spawn EditStateRace(target_param_id=1810360849);
    }
    out = buf.getvalue();

    assert res.outcome == "DEADLOCK", f"expected DEADLOCK, got {res.outcome}";
    assert spaced.editor_frozen == True, "sandbox must be marked editor_frozen on deadlock";
    assert "[bridge] beginEdit sent via synchronous send_message()" in out, out;
    assert "IComponentHandler::beginEdit" in out, out;
    assert "IComponent,IEditController::getState" in out, out;
    assert "neither callback returns" in out, out;
    # After the synchronous deadlock, the re-entry back to PluginSandbox must
    # record the editor-frozen failure and disengage.
    assert "editor frozen" in out, out;
}

test "fixed bridge returns kResultOk: mutual_recursion=True" {
    (fixed, soothe, host) = build_fixed();

    assert fixed.mutual_recursion == True, f"setup wrong: {fixed.mutual_recursion}";
    # Even with both flags notionally set, mutual_recursion=True must
    # fail-open (would_deadlock returns False).
    fixed.begin_edit_in_flight = True;
    fixed.get_state_in_flight = True;
    assert fixed.would_deadlock() == False, "mutual_recursion must prevent deadlock flag";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = soothe spawn EditStateRace(target_param_id=280860833);
    }
    out = buf.getvalue();

    assert res.outcome == "kResultOk", f"expected kResultOk, got {res.outcome}";
    assert soothe.editor_frozen == False, "patched run must NOT freeze the editor";
    assert "send_mutually_recursive_message" in out, out;
    assert "kResultOk, IBStream bytes=2656" in out, out;
    # The patched path must not emit the deadlock trace line.
    assert "neither callback returns" not in out, out;
    assert "editor frozen" not in out, out;
    # Flags must be cleared once the reentrant sequence completes.
    assert fixed.begin_edit_in_flight == False, "begin_edit_in_flight not cleared";
    assert fixed.get_state_in_flight == False, "get_state_in_flight not cleared";
}

test "would_deadlock truth table: flags AND mutual_recursion" {
    # Plain BridgeProxy, no edges — pure logic test of the predicate.
    b = BridgeProxy();

    # Case 1: no flags set -> never deadlock regardless of mode.
    b.mutual_recursion = False;
    assert b.would_deadlock() == False, "no flags must not deadlock (sync)";
    b.mutual_recursion = True;
    assert b.would_deadlock() == False, "no flags must not deadlock (mutual)";

    # Case 2: only one flag -> never deadlock (no concurrency).
    b = BridgeProxy(mutual_recursion=False, begin_edit_in_flight=True);
    assert b.would_deadlock() == False, "only beginEdit in flight must not deadlock";

    b = BridgeProxy(mutual_recursion=False, get_state_in_flight=True);
    assert b.would_deadlock() == False, "only getState in flight must not deadlock";

    # Case 3: both flags + sync -> DEADLOCK.
    b = BridgeProxy(
        mutual_recursion=False,
        begin_edit_in_flight=True,
        get_state_in_flight=True
    );
    assert b.would_deadlock() == True, "sync + both flags must deadlock";

    # Case 4: both flags + mutual recursion -> safe (this is the fix).
    b = BridgeProxy(
        mutual_recursion=True,
        begin_edit_in_flight=True,
        get_state_in_flight=True
    );
    assert b.would_deadlock() == False, "mutual recursion must break the predicate";
}

test "graph topology: sandbox -> bridge -> host with typed edges" {
    (fixed, soothe, host) = build_fixed();
    soothe +>:ParameterLink:+> VstParameter(param_id=280860833, label="mixer anchor");

    # PluginSandbox has exactly one SandboxLink child (the bridge).
    children = [soothe ->:SandboxLink:->];
    assert len(children) == 1, f"expected 1 SandboxLink child, got {len(children)}";
    assert children[0] == fixed, "SandboxLink must point at the bridge";

    # Bridge has exactly one HostLink child (the host).
    bridge_children = [fixed ->:HostLink:->];
    assert len(bridge_children) == 1, f"expected 1 HostLink child, got {len(bridge_children)}";
    assert bridge_children[0] == host, "HostLink must point at the host";

    # ParameterLink is an outbound edge on the sandbox (a parameter node, not
    # a host-side hop), so the walker should NOT traverse it.
    params = [soothe ->:ParameterLink:->];
    assert len(params) == 1, f"expected 1 ParameterLink, got {len(params)}";
}

test "race trace records beginEdit AND concurrent getState" {
    `root = DAWHost(name="Bitwig Studio");
    broken = BridgeProxy(mutual_recursion=False);
    spaced = PluginSandbox(plugin_name="BABY Audio Spaced Out");
    spaced +>:SandboxLink:+> broken +>:HostLink:+> `root;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = spaced spawn EditStateRace(target_param_id=1810360849);
    }
    out = buf.getvalue();

    # The two specific call sites from the failing trace in the issue must
    # both appear in chronological order.
    i_begin = out.find("IComponentHandler::beginEdit");
    i_get = out.find("IComponent,IEditController::getState");
    assert i_begin >= 0, f"missing beginEdit in trace: {out}";
    assert i_get >= 0, f"missing getState in trace: {out}";
    assert i_begin < i_get, "beginEdit must precede getState in the trace";
}

"""Regression tests for skill-sniffer `--follow-refs` model."""

import io;
import from contextlib { redirect_stdout }

# Helper: build the issue's acceptance-test fixture (clean SKILL.md
# that references a script containing a secret) plus the other
# fixtures the program needs to exercise.
def make_fixture {
    skill = Skill(name="setup-helper", score=100, findings=[]);
    root ++> skill;

    bad_script = Script(path="scripts/setup.sh", kind="shell",
                    findings=[], suspicious=True);
    ref_doc = ReferenceDoc(path="references/api.md", findings=[],
                       suspicious=False);
    secret_script = Script(path="scripts/secret-loader.sh", kind="shell",
                       findings=[], suspicious=False);

    skill +>:BundledRef(rel_path="scripts/setup.sh"):+> bad_script;
    skill +>:BundledRef(rel_path="references/api.md"):+> ref_doc;
    skill +>:BundledRef(rel_path="scripts/secret-loader.sh"):+> secret_script;
    ref_doc +>:BundledRef:+> skill;

    return (skill, bad_script, ref_doc, secret_script);
}

test "clean SKILL.md with secret-bearing script becomes non-clean" {
    # Issue acceptance criterion: a clean SKILL.md that references a
    # script containing a secret must yield a non-clean result.
    (skill, _, _, secret_script) = make_fixture();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn FollowRefs(max_depth=5);
    }
    out = buf.getvalue();

    # The referenced script's finding must roll up into the parent
    # skill's report.
    assert any(
        "SECRET" in n and "secret-loader.sh" in n for n in skill.findings
    ), f"expected SECRET finding rolled up to parent; got {skill.findings}";

    # Score must drop from the clean 100 because of the bundled finding.
    assert skill.score < 100, f"score should drop below 100, got {skill.score}";

    # Find the specific rollup log line for the secret script.
    assert "secret-loader.sh" in out, f"expected secret-loader.sh in output; got {out}";
    assert "score now" in out, f"expected rollup line in output; got {out}";
}

test "rollup aggregates findings from every bundled file" {
    # The walker must visit every BundledRef off the skill and fold
    # each payload's findings into the parent's findings list.
    (skill, bad_script, ref_doc, secret_script) = make_fixture();

    with redirect_stdout(io.StringIO()) {
        res = root spawn FollowRefs(max_depth=5);
    }

    # INJECTION from setup.sh (suspicious .sh payload).
    assert any(
        "INJECTION" in n and "setup.sh" in n for n in skill.findings
    ), f"expected INJECTION rollup from setup.sh; got {skill.findings}";

    # SECRET from secret-loader.sh (path contains "secret").
    assert any(
        "SECRET" in n and "secret-loader.sh" in n for n in skill.findings
    ), f"expected SECRET rollup from secret-loader.sh; got {skill.findings}";

    # api.md has no markers, so no findings from it.
    assert len(ref_doc.findings) == 0, f"clean ref doc should be clean; got {ref_doc.findings}";
}

test "score is recomputed as 100 minus 10 per finding, floored at 0" {
    (skill, _, _, _) = make_fixture();

    with redirect_stdout(io.StringIO()) {
        res = root spawn FollowRefs(max_depth=5);
    }

    expected = 100 - 10 * len(skill.findings);
    if expected < 0 {
        expected = 0;
    }
    assert skill.score == expected, (
        f"expected score {expected} for {len(skill.findings)} findings, got {skill.score}"
    );
}

test "cycle guard prevents re-auditing a revisited path" {
    # ref_doc -> skill is the back-edge in the fixture. The cycle
    # guard must fire on the second visit; without it the walker
    # would loop forever.
    (skill, _, ref_doc, _) = make_fixture();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn FollowRefs(max_depth=5);
    }
    out = buf.getvalue();

    assert "[cycle]" in out, f"expected cycle guard to fire; got {out}";

    # The walked-once script should NOT be re-audited: its finding
    # list is whatever scan() produced exactly once.
    assert len(ref_doc.findings) <= 1, (
        f"ref_doc should be scanned at most once, got {len(ref_doc.findings)} findings"
    );
}

test "depth cap disengages when max_depth is exceeded" {
    # Build a deep chain: skill -> script_a -> script_b -> script_c
    # and ask the walker to audit everything. With max_depth=1 only
    # the first hop off the skill should be visited; deeper hops
    # must trigger the depth-cap branch.
    skill = Skill(name="deep-skill", score=100, findings=[]);
    root ++> skill;

    a = Script(path="scripts/a.sh", kind="shell", findings=[], suspicious=True);
    b = Script(path="scripts/b.sh", kind="shell", findings=[], suspicious=True);
    c = Script(path="scripts/c.sh", kind="shell", findings=[], suspicious=True);

    skill +>:BundledRef:+> a;
    a +>:BundledRef:+> b;
    b +>:BundledRef:+> c;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn FollowRefs(max_depth=1);
    }
    out = buf.getvalue();

    # a.sh is at depth 1 (within cap), should contribute findings.
    assert any(
        "a.sh" in n for n in skill.findings
    ), f"a.sh finding should roll up at depth=1; got {skill.findings}";

    # b.sh / c.sh are at depth >= 2, beyond cap -> disengage fires.
    assert "[depth-cap]" in out, f"expected depth-cap to fire; got {out}";

    # b.sh must not have been audited; no findings on it.
    assert len(b.findings) == 0, f"b.sh should be untouched by cap; got {b.findings}";
    assert len(c.findings) == 0, f"c.sh should be untouched by cap; got {c.findings}";
}

"""Tests for the agent-session refactor demo.

Covers:
- Session tree navigation: cycle detection and depth-cap guards
- Event routing: facade dispatches once per active controller
- Dispose cascade: invalidates all controllers, fail-closed re-dispatch
"""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
# Test 1: cycle detection — revisiting a branch label disengages the walker.
# ---------------------------------------------------------------------------
test "cycle detection blocks revisit in session tree" {
    root +>:ChildBranch:+> SessionBranch(label="A", turn_budget=10);
    a = [root-->][?:SessionBranch][0];
    root +>:ChildBranch:+> SessionBranch(label="B", turn_budget=10);
    b = [root-->][?:SessionBranch][1];
    a +>:ChildBranch:+> b;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn SessionNavigator();
    }
    out = buf.getvalue();
    assert "[nav d=0] A (active, budget=10)" in out, f"missing A line: {out}";
    assert "[nav d=1] B (active, budget=10)" in out, f"missing B line: {out}";
    assert "[CYCLE] blocked revisit of B at depth 2" in out, f"missing cycle line: {out}";
}

# ---------------------------------------------------------------------------
# Test 2: depth cap — walker disengages when max_depth is exceeded.
# ---------------------------------------------------------------------------
test "depth cap disengages navigation at configured max_depth" {
    root +>:ChildBranch:+> SessionBranch(label="L0", turn_budget=5);
    l0 = [root-->][?:SessionBranch][0];
    l0 +>:ChildBranch:+> SessionBranch(label="L1", turn_budget=5);
    l1 = [l0 -->][?:SessionBranch][0];
    l1 +>:ChildBranch:+> SessionBranch(label="L2", turn_budget=5);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn SessionNavigator(max_depth=1);
    }
    out = buf.getvalue();
    assert "[nav d=0] L0 (active, budget=5)" in out, f"missing L0: {out}";
    assert "[nav d=1] L1 (active, budget=5)" in out, f"missing L1: {out}";
    assert "[nav] depth cap 1 at L1" in out, f"missing depth cap line: {out}";
    assert "L2" not in out, f"should not reach L2: {out}";
    assert res.depth == 1, f"walker depth should cap at 1, got {res.depth}";
}

# ---------------------------------------------------------------------------
# Test 3: abandoned branches report their state distinctly.
# ---------------------------------------------------------------------------
test "abandoned branch is marked in navigation output" {
    root +>:ChildBranch:+> SessionBranch(label="keep", turn_budget=8);
    keep = [root-->][?:SessionBranch][0];
    root +>:ChildBranch:+> SessionBranch(label="drop", turn_budget=8, abandoned=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn SessionNavigator();
    }
    out = buf.getvalue();
    assert "(abandoned, budget=8)" in out, f"missing abandoned status: {out}";
    assert "(active, budget=8)" in out, f"missing active status: {out}";
}

# ---------------------------------------------------------------------------
# Test 4: event router dispatches to every active controller exactly once
# and increments per-controller handled counts.
# ---------------------------------------------------------------------------
test "event router dispatches to all active controllers and increments handled" {
    facade = AgentSessionFacade(session_id="sess-rt");
    root ++> facade;
    facade +>:DelegatesTo(priority=1):+> LifecycleController(name="Lifecycle", domain="event_routing");
    facade +>:DelegatesTo(priority=2):+> CompactionController(name="Compaction", domain="overflow_recovery");
    facade +>:DelegatesTo(priority=3):+> SettleController(name="Settle", domain="continuation_enforcement");
    facade +>:DelegatesTo(priority=4):+> ToolDispatchController(name="ToolDispatch", domain="tool_security");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = facade spawn EventRouter();
    }
    out = buf.getvalue();
    assert "[router] -> Lifecycle" in out, f"missing Lifecycle: {out}";
    assert "[router] -> Compaction" in out, f"missing Compaction: {out}";
    assert "[router] -> Settle" in out, f"missing Settle: {out}";
    assert "[router] -> ToolDispatch" in out, f"missing ToolDispatch: {out}";
    assert res.route_count == 4, f"expected 4 routes, got {res.route_count}";

    controllers = [facade ->:DelegatesTo:->];
    for c in controllers {
        assert c.handled == 1, f"{c.name} handled should be 1, got {c.handled}";
    }
}

# ---------------------------------------------------------------------------
# Test 5: dispose cascade deactivates all controllers and blocks re-routing.
# ---------------------------------------------------------------------------
test "dispose cascade deactivates controllers and blocks re-dispatch" {
    facade = AgentSessionFacade(session_id="sess-die");
    root ++> facade;
    facade +>:DelegatesTo(priority=1):+> LifecycleController(name="Lifecycle", domain="event_routing");
    facade +>:DelegatesTo(priority=2):+> CompactionController(name="Compaction", domain="overflow_recovery");
    facade +>:DelegatesTo(priority=3):+> SettleController(name="Settle", domain="continuation_enforcement");
    facade +>:DelegatesTo(priority=4):+> ToolDispatchController(name="ToolDispatch", domain="tool_security");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        facade spawn DisposeCascade();
    }
    out = buf.getvalue();
    assert "[dispose] tearing down sess-die" in out, f"missing teardown: {out}";
    assert "[dispose] Lifecycle: deactivated" in out, f"Lifecycle not deactivated: {out}";
    assert "[dispose] Compaction: deactivated" in out, f"Compaction not deactivated: {out}";
    assert "[dispose] Settle: deactivated" in out, f"Settle not deactivated: {out}";
    assert "[dispose] ToolDispatch: deactivated" in out, f"ToolDispatch not deactivated: {out}";
    assert facade.disposed == True, f"facade should be disposed, got {facade.disposed}";

    controllers = [facade ->:DelegatesTo:->];
    for c in controllers {
        assert c.active == False, f"{c.name} should be inactive, got {c.active}";
    }

    # Re-routing after disposal must be fail-closed: no dispatch.
    buf2 = io.StringIO();
    with redirect_stdout(buf2) {
        res2 = facade spawn EventRouter();
    }
    out2 = buf2.getvalue();
    assert "disposed — no dispatch" in out2, f"missing disposed block: {out2}";
    assert res2.route_count == 0, f"post-dispose route_count should be 0, got {res2.route_count}";
    assert "[router] -> Lifecycle" not in out2, f"should not route after dispose: {out2}";

    # Re-disposal reports already-inactive.
    buf3 = io.StringIO();
    with redirect_stdout(buf3) {
        facade spawn DisposeCascade();
    }
    out3 = buf3.getvalue();
    assert "already inactive" in out3, f"missing already-inactive report: {out3}";
}

"""Regression tests for the provenance-aware BoefjeFindings walker.

Covers the core behaviors the issue requires: transitive reachability
through inference chains, deduplication on shared nodes, isolation from
unrelated boefjes, and correct ordering of visited sets when seeding
starts from a boefje vs. an origin/result.
"""

import io;
import from contextlib { redirect_stdout }

test "direct normalizer finding is attributed" {
    buf = io.StringIO();
    root ++> Boefje(name="ssl");
    boef = [root-->][?:Boefje][0];
    o = Origin(method="normalizer", task_id="n1");
    r = Result(kind="observation");
    f = Finding(severity="high");
    boef +>:ProducedBy(boefje_name="ssl"):+> o;
    o +>:ResultOf:+> r;
    r +>:Flagged:+> f;

    with redirect_stdout(buf) {
        res = root spawn BoefjeFindings(target_name="ssl");
    }
    out = buf.getvalue();
    assert "Collecting findings contributed by boefje 'ssl'" in out, f"missing header: {out}";
    assert "Total attributable findings: 1" in out, f"expected 1 finding, got: {out}";
    assert "[high/open]" in out, f"expected high/open line: {out}";
    assert len(res.findings_seen) == 1, f"findings_seen len={len(res.findings_seen)}";
}

test "transitive bit chain via ResultOf and InferenceOrigin" {
    root ++> Boefje(name="dns");
    boef = [root-->][?:Boefje][0];
    o_norm = Origin(method="normalizer", task_id="n2");
    o_bit_a = InferenceOrigin(method="bit-a");
    o_bit_b = InferenceOrigin(method="bit-b");
    o_param = OriginParameter(key="src");
    r1 = Result(kind="observation");
    r2 = Result(kind="declaration");
    r3 = Result(kind="declaration");
    r4 = Result(kind="affirmation");
    f1 = Finding(severity="high");
    f2 = Finding(severity="medium", muted=True);
    f3 = Finding(severity="low");

    boef +>:ProducedBy(boefje_name="dns"):+> o_norm;
    o_norm +>:ResultOf:+> r1;
    r1 +>:ResultOf:+> o_bit_a;
    o_bit_a +>:ResultOf:+> r2;
    o_bit_a +>:InputOf:+> o_param;
    o_param +>:Flagged:+> r1;
    r2 +>:SourcedFrom:+> o_bit_b;
    o_bit_b +>:ResultOf:+> r3;
    r3 +>:ResultOf:+> r4;
    r1 +>:Flagged:+> f1;
    r2 +>:Flagged:+> f2;
    r4 +>:Flagged:+> f3;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn BoefjeFindings(target_name="dns");
    }
    out = buf.getvalue();
    assert "Total attributable findings: 3" in out, f"expected 3 transitive findings, got: {out}";
    assert "[high/open]" in out, f"missing f1 line: {out}";
    assert "[medium/muted]" in out, f"missing f2 line: {out}";
    assert "[low/open]" in out, f"missing f3 line: {out}";
    assert len(res.findings_seen) == 3, f"findings_seen={len(res.findings_seen)}";
    assert len(res.origins_seen) >= 3, f"origins_seen={len(res.origins_seen)}";
    assert len(res.results_seen) >= 4, f"results_seen={len(res.results_seen)}";
}

test "unrelated boefje's findings are excluded" {
    root ++> Boefje(name="alpha");
    target = [root-->][?:Boefje][0];
    o_target = Origin(method="normalizer", task_id="na");
    r_target = Result(kind="observation");
    f_target = Finding(severity="medium");

    other = Boefje(name="beta");
    o_other = Origin(method="normalizer", task_id="nb");
    r_other = Result(kind="observation");
    f_other = Finding(severity="critical");

    target +>:ProducedBy(boefje_name="alpha"):+> o_target;
    o_target +>:ResultOf:+> r_target;
    r_target +>:Flagged:+> f_target;
    other +>:ProducedBy(boefje_name="beta"):+> o_other;
    o_other +>:ResultOf:+> r_other;
    r_other +>:Flagged:+> f_other;
    root ++> other;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn BoefjeFindings(target_name="alpha");
    }
    out = buf.getvalue();
    assert "Total attributable findings: 1" in out, f"other's finding leaked: {out}";
    assert "[medium/open]" in out, f"missing own finding: {out}";
    assert "[critical/open]" not in out, f"unrelated critical finding should not appear: {out}";
}

test "unknown boefje name disengages without visiting" {
    root ++> Boefje(name="real");
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn BoefjeFindings(target_name="ghost");
    }
    out = buf.getvalue();
    assert "No boefje named ghost" in out, f"missing not-found message: {out}";
    assert "Total attributable findings" not in out, f"should not summarize when disengaged: {out}";
    assert len(res.findings_seen) == 0, f"findings_seen should stay empty: {len(res.findings_seen)}";
}

test "shared findings are deduplicated across paths" {
    root ++> Boefje(name="dup");
    boef = [root-->][?:Boefje][0];
    o = Origin(method="normalizer", task_id="d1");
    r1 = Result(kind="observation");
    r2 = Result(kind="declaration");
    f_shared = Finding(severity="high");

    boef +>:ProducedBy(boefje_name="dup"):+> o;
    o +>:ResultOf:+> r1;
    r1 +>:ResultOf:+> r2;
    r1 +>:Flagged:+> f_shared;
    r2 +>:Flagged:+> f_shared;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn BoefjeFindings(target_name="dup");
    }
    out = buf.getvalue();
    assert "Total attributable findings: 1" in out, f"shared finding counted twice: {out}";
    assert len(res.findings_seen) == 1, f"findings_seen not deduped: {len(res.findings_seen)}";
}

"""Tests for the CI baseline repair propagation walker."""

import io;
import from contextlib { redirect_stdout }

test "master release line reports red baseline" {
    root ++> ReleaseLine(
        name="master",
        head_sha="40e9c06d4ab76217c3ef277dd539d3b5580e2bb8",
        baseline_passing=False
    );

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn PropagateFix();
    }
    out = buf.getvalue();

    assert "release line master" in out, f"missing master mention: {out}";
    assert "CI RED" in out, f"expected RED baseline on master: {out}";
    assert res.patch_lines == 0, f"master alone has no patch: {res.patch_lines}";
}

test "develop release line has green baseline and no patch is applied" {
    root ++> ReleaseLine(
        name="develop",
        head_sha="5444081aba7adafb17822cb17fe67e6326828a79",
        baseline_passing=True
    );

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn PropagateFix();
    }
    out = buf.getvalue();

    assert "release line develop" in out, f"missing develop mention: {out}";
    assert "CI GREEN" in out, f"expected GREEN baseline on develop: {out}";
    assert res.patch_lines == 0, f"develop alone does not trigger a patch: {res.patch_lines}";
    assert res.changelog_lines == 0, f"develop alone does not trigger a changelog: {res.changelog_lines}";
}

test "cycle guard disengages when revisiting a release line" {
    a = ReleaseLine(name="master", head_sha="a" * 40, baseline_passing=False);
    b = ReleaseLine(name="develop", head_sha="b" * 40, baseline_passing=True);
    root ++> a;
    a +>:Runs(run_id="x"):+> b;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn PropagateFix();
    }
    out = buf.getvalue();

    assert "cycle hit on master" in out, f"expected cycle guard message: {out}";
}

test "unreviewed or unmerged fix is skipped and patch never applies" {
    develop = ReleaseLine(name="develop", head_sha="d" * 40, baseline_passing=True);
    bad_fix = RepairCommit(
        sha="f" * 40,
        summary="draft, not yet reviewed",
        reviewed=False,
        merged=False
    );
    develop +>:HasFix:+> bad_fix;
    root ++> develop;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn PropagateFix();
    }
    out = buf.getvalue();

    assert "skipping un-reviewed/un-merged commit" in out, f"expected skip message: {out}";
    assert res.patch_lines == 0, f"unreviewed fix must not apply: {res.patch_lines}";
    assert res.changelog_lines == 0, f"unreviewed fix must not add changelog: {res.changelog_lines}";
}

test "full master -> develop -> reviewed fix -> patch propagation" {
    master  = ReleaseLine(name="master",  head_sha="m" * 40, baseline_passing=False);
    develop = ReleaseLine(name="develop", head_sha="d" * 40, baseline_passing=True);

    master_fail = LintCheck(
        toolchain_version="1.98",
        rule="clippy::useless_format",
        outcome="FAIL",
        blob_sha="b" * 40
    );
    develop_pass = LintCheck(
        toolchain_version="1.98",
        rule="clippy::useless_format",
        outcome="PASS",
        blob_sha="b" * 40
    );

    reviewed_fix = RepairCommit(
        sha="f" * 40,
        summary="drop redundant format!() wrappers in three test asserts",
        reviewed=True,
        merged=True
    );

    master_patch = Patch(
        source_sha="b" * 40,
        target_sha="f" * 40,
        rationale="reuse the already-reviewed three-line correction"
    );

    root +>:Runs(run_id="r-master-01"):+>  master;
    root +>:Runs(run_id="r-develop-01"):+> develop;
    master  +>:InspectedBy(run_id="33182671533"):+> master_fail;
    develop +>:InspectedBy(run_id="33182671534"):+> develop_pass;
    develop +>:HasFix:+> reviewed_fix;
    reviewed_fix +>:CherryPicks:+> master_patch;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn PropagateFix();
    }
    out = buf.getvalue();

    assert "release line master" in out, f"missing master: {out}";
    assert "CI RED" in out, f"master should be RED: {out}";
    assert "release line develop" in out, f"missing develop: {out}";
    assert "CI GREEN" in out, f"develop should be GREEN: {out}";
    assert "lint clippy 1.98 on clippy::useless_format -> broken" in out, f"master lint should be broken: {out}";
    assert "lint clippy 1.98 on clippy::useless_format -> ok" in out, f"develop lint should be ok: {out}";
    assert "authoritative fix" in out, f"authoritative fix line missing: {out}";
    assert "applying patch" in out, f"patch application line missing: {out}";

    assert res.patch_lines == 3, f"three reviewed lines must be applied: {res.patch_lines}";
    assert res.changelog_lines == 1, f"exactly one changelog entry: {res.changelog_lines}";

    assert len([root->:Runs:->]) == 2, "two release lines run by root";
    assert master in [develop ->:HasFix:->] == False, "develop has the fix, not master";
    assert len([develop ->:HasFix:->]) == 1, "develop has exactly one HasFix edge";
    assert len([master ->:InspectedBy:->]) == 1, "master has exactly one InspectedBy edge";
    assert len([reviewed_fix ->:CherryPicks:->]) == 1, "fix has exactly one CherryPicks edge";
}

"""Tests for reviewed reachability effect summaries.

Covers the acceptance criteria from issue #105:
- one-hop complete caller omitting a callee effect fails with canonical witness
- adding the reachable effect to the caller removes the completeness diagnostic
- missing grant fails even through a wrapper
- forbidden effect behind wrapper still fails
- multiple callees contribute union of effects
- diamond paths produce one obligation / one witness
- reachable unknown propagates to upstream complete caller
- self / mutual recursion terminates
"""

import io;
import from contextlib { redirect_stdout }

test "one-hop caller omitting reachable effect fails with canonical witness" {
    root ++> caller ++> wrapper ++> leaf_write;
    caller +>:Invokes:+> wrapper;
    wrapper +>:Invokes:+> leaf_write;

    buf = io.StringIO();
    rev = Reviewer();
    with redirect_stdout(buf) {
        rev = root spawn Reviewer();
    }
    msgs = buf.getvalue();
    assert "caller missing reviewed effect 'write_disk'" in msgs, f"missing effect diagnostic not raised: {msgs}";
    assert "via leaf_write" in msgs, f"missing canonical witness leaf_write: {msgs}";
    assert "forbidden effect" not in msgs, f"should not raise forbid: {msgs}";
}

test "adding reachable effect to caller summary removes completeness diagnostic" {
    root ++> caller ++> wrapper ++> leaf_write;
    caller +>:Invokes:+> wrapper;
    wrapper +>:Invokes:+> leaf_write;
    caller.local_effects = caller.local_effects + ["write_disk"];
    caller.grants = caller.grants + ["write_disk"];

    buf = io.StringIO();
    with redirect_stdout(buf) {
        rev = root spawn Reviewer();
    }
    msgs = buf.getvalue();
    assert "missing reviewed effect" not in msgs, f"unexpected missing diagnostic: {msgs}";
    assert "caller passes reviewed reachability" in msgs, f"expected pass message: {msgs}";
}

test "caller without corresponding grant fails through wrapper" {
    root ++> caller ++> wrapper ++> leaf_write;
    caller +>:Invokes:+> wrapper;
    wrapper +>:Invokes:+> leaf_write;
    # caller has 'log'/'write_disk' effect but no 'write_disk' grant.
    caller.local_effects = caller.local_effects + ["write_disk"];

    buf = io.StringIO();
    with redirect_stdout(buf) {
        rev = root spawn Reviewer();
    }
    msgs = buf.getvalue();
    # Reachability surfaces the missing-effect diagnostic; the grant check is
    # policy on top, but the wrapper path must still raise a failure here.
    assert "missing reviewed effect 'write_disk'" in msgs or "forbidden effect 'write_disk'" in msgs or "passes reviewed reachability" not in msgs, (
        f"caller without grant should fail through wrapper: {msgs}"
    );
}

test "forbidden effect behind reviewed wrapper still fails" {
    root ++> caller ++> wrapper ++> leaf_write;
    caller +>:Invokes:+> wrapper;
    wrapper +>:Invokes:+> leaf_write;
    caller.forbids = caller.forbids + ["write_disk"];

    buf = io.StringIO();
    with redirect_stdout(buf) {
        rev = root spawn Reviewer();
    }
    msgs = buf.getvalue();
    assert "forbidden effect 'write_disk' reached via wrapper" in msgs, f"forbidden effect not flagged: {msgs}";
    assert "passes reviewed reachability" not in msgs, f"forbidden behind wrapper wrongly passed: {msgs}";
}

test "multiple callees contribute union of effects to caller requirement" {
    root ++> caller ++> wrapper1;
    root ++> wrapper2;
    caller +>:Invokes:+> wrapper1;
    caller +>:Invokes:+> wrapper2;
    wrapper1 +>:Invokes:+> leaf_write;
    wrapper2 +>:Invokes:+> leaf_read;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        rev = root spawn Reviewer();
    }
    msgs = buf.getvalue();
    assert "missing reviewed effect 'write_disk'" in msgs, f"union missing write_disk: {msgs}";
    assert "missing reviewed effect 'read_db'" in msgs, f"union missing read_db: {msgs}";
}

test "diamond paths produce one obligation and one witness" {
    # caller -> wrapper_a -> leaf   and   caller -> wrapper_b -> leaf
    leaf = Function(name="diamond_leaf", local_effects=["write_disk"], grants=["write_disk"]);
    wrapper_a = Function(name="wrapper_a", local_effects=[]);
    wrapper_b = Function(name="wrapper_b", local_effects=[]);
    root ++> caller ++> wrapper_a;
    root ++> wrapper_b;
    caller +>:Invokes:+> wrapper_a;
    caller +>:Invokes:+> wrapper_b;
    wrapper_a +>:Invokes:+> leaf;
    wrapper_b +>:Invokes:+> leaf;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        rev = root spawn Reviewer();
    }
    msgs = buf.getvalue();
    occurrences = msgs.count("missing reviewed effect 'write_disk'");
    assert occurrences == 1, f"diamond produced {occurrences} diagnostics, want 1: {msgs}";
    # Canonical witness should be the leaf by shortest-then-name order.
    assert "via diamond_leaf" in msgs, f"canonical witness missing: {msgs}";
}

test "reachable effects unknown propagates to upstream complete caller" {
    # leaf has effects_known=False; wrapper invokes it; caller invokes wrapper.
    leaf = Function(
        name="opaque_leaf",
        local_effects=["write_disk"],
        grants=["write_disk"],
        is_complete=False,
        effects_known=False
    );
    wrapper = Function(name="wrapper_opaque", local_effects=[]);
    root ++> caller ++> wrapper ++> leaf;
    caller +>:Invokes:+> wrapper;
    wrapper +>:Invokes:+> leaf;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        rev = root spawn Reviewer();
    }
    msgs = buf.getvalue();
    assert "reachable effects unknown" in msgs, f"unknown propagation missing: {msgs}";
    assert "passes reviewed reachability" not in msgs, f"upstream wrongly passed under unknown: {msgs}";
}

test "self recursion and mutual recursion terminate" {
    # Self-recursion: a -> a (single node, no infinite loop).
    self_fn = Function(name="self_fn", local_effects=["log"], grants=["log"]);
    root ++> self_fn;
    self_fn +>:Invokes:+> self_fn;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        rev = root spawn Reviewer();
    }
    msgs = buf.getvalue();
    # Should not hang and should still surface local effect (it is in summary).
    assert "passes reviewed reachability" in msgs, f"self recursion wrongly failed: {msgs}";

    # Mutual recursion: a -> b -> a.
    a = Function(name="mut_a", local_effects=["log"], grants=["log"]);
    b = Function(name="mut_b", local_effects=["read_db"], grants=["read_db"]);
    root ++> a;
    root ++> b;
    a +>:Invokes:+> b;
    b +>:Invokes:+> a;

    buf2 = io.StringIO();
    with redirect_stdout(buf2) {
        rev2 = root spawn Reviewer();
    }
    msgs2 = buf2.getvalue();
    assert "missing reviewed effect 'read_db'" in msgs2, f"mutual recursion didn't propagate: {msgs2}";
}

test "type-ahead returns unique matching tag paths" {
    trips = Tag(name="trips", path="trips");
    iceland = Tag(name="iceland", path="trips/iceland");
    japan = Tag(name="japan", path="trips/japan");
    root ++> trips;
    trips +>:Parent:+> iceland;
    root ++> japan;

    f1 = File(title="one.jpg", tag_names=["trips/iceland"]);
    f2 = File(title="two.jpg", tag_names=["trips/iceland", "trips/japan"]);
    root ++> f1;
    root ++> f2;

    res = root spawn TypeAhead(prefix="trips/ic");
    assert len(res.results) == 1, f"got {res.results}";
    assert res.results[0] == "trips/iceland", f"got {res.results}";
}

test "rename updates the tag and every referencing file" {
    tag = Tag(name="iceland", path="trips/iceland");
    root ++> tag;

    f1 = File(title="one.jpg", tag_names=["trips/iceland", "2024"]);
    f2 = File(title="two.jpg", tag_names=["trips/iceland"]);
    root ++> f1;
    root ++> f2;

    res = root spawn TagManager(
        op="rename",
        target="iceland",
        replacement="iceland-v2"
    );

    assert tag.name == "iceland-v2", f"got {tag.name}";
    assert tag.path == "iceland-v2", f"got {tag.path}";
    assert f1.tag_names == ["iceland-v2", "2024"], f"got {f1.tag_names}";
    assert f2.tag_names == ["iceland-v2"], f"got {f2.tag_names}";
    assert "iceland-v2" in res.affected, f"got {res.affected}";
    assert "one.jpg" in res.affected, f"got {res.affected}";
    assert "two.jpg" in res.affected, f"got {res.affected}";
}

test "merge invalidates the old tag and retargets files" {
    old_tag = Tag(name="japan", path="japan");
    root ++> old_tag;

    f1 = File(title="one.jpg", tag_names=["japan", "2024"]);
    f2 = File(title="two.jpg", tag_names=["japan"]);
    root ++> f1;
    root ++> f2;

    res = root spawn TagManager(
        op="merge",
        target="japan",
        replacement="trips/japan"
    );

    assert old_tag.alive == False, f"got {old_tag.alive}";
    assert f1.tag_names == ["trips/japan", "2024"], f"got {f1.tag_names}";
    assert f2.tag_names == ["trips/japan"], f"got {f2.tag_names}";
    assert "japan" in res.affected, f"got {res.affected}";
    assert "one.jpg" in res.affected, f"got {res.affected}";
    assert "two.jpg" in res.affected, f"got {res.affected}";
}

test "cycle probe detects repeated tag reachability" {
    a = Tag(name="a", path="a");
    b = Tag(name="b", path="b");
    root ++> a;
    a +>:Parent:+> b;
    b +>:Parent:+> a;

    res = root spawn CycleProbe();

    assert len(res.cycle) == 2, f"got {res.cycle}";
    assert res.cycle[0] == "a", f"got {res.cycle}";
    assert res.cycle[1] == "b", f"got {res.cycle}";
}

import io;
import from contextlib { redirect_stdout }

test "move rewrites source and all descendant paths" {
    intro = Document(doc_id="i", title="Intro", slug="intro",
                     path="guides/intro", is_folder=True);
    overview = Document(doc_id="o", title="Overview", slug="overview",
                        path="guides/intro/overview");
    setup = Document(doc_id="s", title="Setup", slug="setup",
                     path="guides/intro/setup");
    unrelated = Document(doc_id="u", title="Other", slug="other",
                         path="docs/other");

    root +>:ChildOf:+> intro +>:ChildOf:+> overview;
    intro +>:ChildOf:+> setup;
    root +>:ChildOf:+> unrelated;

    mover = MoveDocument(old_prefix="guides/intro",
                         new_prefix="docs/getting-started");
    intro spawn mover;

    assert "i" in mover.rewritten, f"missing i in {mover.rewritten}";
    assert "o" in mover.rewritten, f"missing o in {mover.rewritten}";
    assert "s" in mover.rewritten, f"missing s in {mover.rewritten}";
    assert len(mover.rewritten) == 3, f"expected 3 rewrites, got {mover.rewritten}";

    assert intro.path == "docs/getting-started",
        f"intro path not rewritten: {intro.path}";
