test "recovers safe nodes and skips unsafe replay" {
    graph = WorkflowGraph(name="Recovery", version=2, generation=4);
    root ++> graph;

    prerequisite = WorkflowNode(label="prerequisite", status="succeeded");
    recoverable = WorkflowNode(label="recoverable", status="failed", retry_count=1);
    checkpointed = WorkflowNode(
        label="checkpointed",
        status="failed",
        uncertain_effects=True
    );
    no_checkpoint = WorkflowNode(
        label="no_checkpoint",
        status="failed",
        uncertain_effects=True
    );
    exhausted = WorkflowNode(
        label="exhausted",
        status="failed",
        retry_count=2,
        max_retries=2
    );
    dependency_wait = WorkflowNode(label="dependency_wait", status="failed");
    failed_prerequisite = WorkflowNode(label="failed_prerequisite", status="failed");
    checkpoint = Checkpoint(checkpoint_id="cp-1", captured_at="now");

    graph +>:MemberOf:+> prerequisite;
    graph +>:MemberOf:+> recoverable;
    graph +>:MemberOf:+> checkpointed;
    graph +>:MemberOf:+> no_checkpoint;
    graph +>:MemberOf:+> exhausted;
    graph +>:MemberOf:+> dependency_wait;
    graph +>:MemberOf:+> failed_prerequisite;

    recoverable +>:DependsOn:+> prerequisite;
    checkpointed +>:DependsOn:+> prerequisite;
    no_checkpoint +>:DependsOn:+> prerequisite;
    exhausted +>:DependsOn:+> prerequisite;
    dependency_wait +>:DependsOn:+> failed_prerequisite;
    checkpointed +>:CheckpointedAt:+> checkpoint;

    res = root spawn RecoveryAuditor();

    assert res.resume_count == 2, f"expected two recovered nodes, got {res.resume_count}";
    assert res.skip_count == 3, f"expected three skipped nodes, got {res.skip_count}";
    assert recoverable.status == "recovered", f"recoverable status is {recoverable.status}";
    assert checkpointed.status == "recovered", f"checkpointed status is {checkpointed.status}";
    assert recoverable.resume_safe == True, f"resume flag is {recoverable.resume_safe}";
    assert checkpointed.resume_safe == True, f"resume flag is {checkpointed.resume_safe}";
    assert no_checkpoint.status == "failed", f"uncertain node was replayed: {no_checkpoint.status}";
    assert exhausted.status == "failed", f"exhausted node changed: {exhausted.status}";
    assert dependency_wait.status == "failed", f"blocked node changed: {dependency_wait.status}";
}

