"""Test annex for the Velero storage-full deadlock model."""

import io;
import from contextlib { redirect_stdout }

def root_factory() -> Root {
    return Root();
}

# ---------------------------------------------------------------
# 1. StorageAuditor under store_full=True: every reachable node
#    must end up non-terminal with its _blocked_phase() value,
#    and the auditor must record each visited name in `deadlocked`.
# ---------------------------------------------------------------
test "store_full blocks every write and deadlocked names are recorded" {
    rt = root_factory();
    b1 = Backup(name="backup1", phase="Completed", terminal=True, store_free_mb=541);
    u = DataUpload(name="b1-u1", phase="Completed", terminal=True);
    rt ++> b1;
    b1 +>:OwnsUpload:+> u;

    auditor = StorageAuditor(store_full=True, retry_limit=10);
    res = rt spawn auditor;

    # The walker uses the union ability on every node, so each must
    # be flipped to non-terminal with the kind-specific blocked phase.
    assert b1.terminal == False, f"backup1 should be non-terminal when store is full, got {b1.terminal}";
    assert b1.phase == "FinalizingPartiallyFailed", f"backup1 blocked phase, got {b1.phase}";
    assert u.terminal == False, f"DataUpload should be non-terminal when store is full, got {u.terminal}";
    assert u.phase == "Failed", f"DataUpload blocked phase, got {u.phase}";
    assert b1.write_attempts == 1, f"backup1 write_attempts, got {b1.write_attempts}";
    assert u.write_attempts == 1, f"DataUpload write_attempts, got {u.write_attempts}";
    assert "backup1" in res.deadlocked, f"backup1 missing from deadlocked: {res.deadlocked}";
    assert "b1-u1" in res.deadlocked, f"b1-u1 missing from deadlocked: {res.deadlocked}";
}

# ---------------------------------------------------------------
# 2. StorageAuditor under store_full=False: every reachable node
#    must transition to terminal=True with phase="Completed".
# ---------------------------------------------------------------
test "store not full finalizes every reachable node cleanly" {
    rt = root_factory();
    b1 = Backup(name="backup1", phase="Completed", terminal=True, store_free_mb=541);
    b5 = Backup(name="backup5", phase="FinalizingPartiallyFailed", terminal=False, store_free_mb=541);
    u = DataUpload(name="b1-u1", phase="Completed", terminal=True);
    dr = DeleteRequest(name="del-backup4", phase="InProgress", terminal=False, frees_mb=12000);

    rt ++> b1 ++> b5;
    b1 +>:OwnsUpload:+> u;
    b1 +>:NeedsFinalizeWrite:+> b5;
    dr +>:TargetsBackup:+> b4_dummy();
    rt +>:MaintainsRepo:+> RepoMaintenance(name="kopia-maintenance", phase="Failed", terminal=False);

    auditor = StorageAuditor(store_full=False, retry_limit=10);
    res = rt spawn auditor;

    assert b1.terminal == True, f"backup1 terminal under free store, got {b1.terminal}";
    assert b1.phase == "Completed", f"backup1 phase under free store, got {b1.phase}";
    assert u.terminal == True, f"upload terminal under free store, got {u.terminal}";
    assert u.phase == "Completed", f"upload phase under free store, got {u.phase}";
    assert len(res.deadlocked) == 0, f"nothing should be deadlocked, got {res.deadlocked}";
}

def b4_dummy() -> Backup {
    return Backup(name="backup4-target", phase="Completed", terminal=True, store_free_mb=541);
}

# ---------------------------------------------------------------
# 3. DeleteCascade: spawned at a DeleteRequest, walks TargetsBackup
#    then OwnsUpload and reports the chain via stdout.
# ---------------------------------------------------------------
test "DeleteCascade walks DeleteRequest -> Backup -> DataUploads" {
    rt = root_factory();
    b4 = Backup(name="backup4", phase="Completed", terminal=True, store_free_mb=541);
    u1 = DataUpload(name="b4-u1", phase="Completed", terminal=True);
    u2 = DataUpload(name="b4-u2", phase="Completed", terminal=True);
    del4 = DeleteRequest(name="del-backup4", phase="InProgress", terminal=False, frees_mb=12000);

    rt ++> del4;
    del4 +>:TargetsBackup:+> b4;
    b4 +>:OwnsUpload:+> u1;
    b4 +>:OwnsUpload:+> u2;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = rt spawn DeleteCascade();
    }
    out = buf.getvalue();

    assert "del-backup4" in out, f"delete header missing: {out}";
    assert "backup4" in out, f"backup hop missing: {out}";
    assert "b4-u1" in out, f"upload b4-u1 missing: {out}";
    assert "b4-u2" in out, f"upload b4-u2 missing: {out}";
}

# ---------------------------------------------------------------
# 4. Typed edges preserve direction: TargetsBackup only goes from
#    DeleteRequest -> Backup, not the other way around.
# ---------------------------------------------------------------
test "TargetsBackup is a directed edge from DeleteRequest to Backup" {
    rt = root_factory();
    del4 = DeleteRequest(name="del-backup4", phase="InProgress", terminal=False, frees_mb=12000);
    b4 = Backup(name="backup4", phase="Completed", terminal=True, store_free_mb=541);
    rt ++> del4;
    del4 +>:TargetsBackup:+> b4;

    targets = [del4 ->:TargetsBackup:->];
    assert len(targets) == 1, f"expected 1 target, got {len(targets)}";
    assert targets[0].name == "backup4", f"target name, got {targets[0].name}";

    # Reverse direction must not yield anything.
    reverse = [b4 ->:TargetsBackup:->];
    assert len(reverse) == 0, f"backup should not have TargetsBackup outgoing, got {len(reverse)}";
}

# ---------------------------------------------------------------
# 5. Multiple concurrent walks on independent graphs must each see
#    their own results -- exercises the `has` field isolation on
#    walker instances (deadlocked list is per-walker).
# ---------------------------------------------------------------
test "two auditors on separate graphs see separate deadlocked sets" {
    rt1 = root_factory();
    b1a = Backup(name="backup1", phase="Completed", terminal=True, store_free_mb=541);
    rt1 ++> b1a;

    rt2 = root_factory();
    b1b = Backup(name="backup1", phase="Completed", terminal=True, store_free_mb=541);
    rt2 ++> b1b;

    a1 = StorageAuditor(store_full=True, retry_limit=3);
    a2 = StorageAuditor(store_full=False, retry_limit=3);
    res1 = rt1 spawn a1;
    res2 = rt2 spawn a2;

    assert "backup1" in res1.deadlocked, f"first auditor should record backup1, got {res1.deadlocked}";
    assert len(res2.deadlocked) == 0, f"second auditor should record nothing, got {res2.deadlocked}";
    assert b1a.terminal == False, f"graph-1 backup terminal, got {b1a.terminal}";
    assert b1b.terminal == True, f"graph-2 backup terminal, got {b1b.terminal}";
}

