"""Tests for the fuel-cost model mutual-recursion auditor.

Each test builds its OWN small call graph (tests run in isolated workers)
and spawns the FuelAuditor walker on it, capturing stdout and the walker's
mutated state (cycles_found, total_fuel) to verify the diagnostic behavior
the M3 issue promises:

  1. The walker visits every reachable Routine once via Calls edges.
  2. Mutual-recursion cycles are detected (cycles_found >= 1) and produce
     a "[CYCLE a->b->a]" diagnostic.
  3. Acyclic call graphs produce NO cycle diagnostic.
  4. Self-recursion (A -> A) is detected as a cycle too.
  5. Declared bounds accumulate into total_fuel for every entered node,
     and the visited flag prevents double-counting the cycle member.
"""

import io;
import from contextlib { redirect_stdout }

test "mutual recursion A->B->A emits a->b->a cycle diagnostic" {
    main = Routine(name="main", declared_bound=1);
    a_node = Routine(name="A", declared_bound=5);
    b_node = Routine(name="B", declared_bound=7);

    root ++> main;
    main +>:Calls(call_site="main->A"):+> a_node;
    a_node +>:Calls(call_site="A->B"):+> b_node;
    b_node +>:Calls(call_site="B->A"):+> a_node;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = FuelAuditor();
        root spawn auditor;
    }
    out = buf.getvalue();

    # The mutual recursion cycle must be reported with the a->b->a label.
    assert "[CYCLE a->b->a]" in out, f"missing mutual-cycle marker: {out!r}";
    # The auditor counts it.
    assert auditor.cycles_found >= 1, f"cycles_found={auditor.cycles_found}";
    # Each Routine in the reachable set was entered at least once; bounds
    # charged into total_fuel. main(1) + A(5) + B(7) + A-revisit(5) = 18
    # under the broken "charge declared bound on re-entry" model.
    assert auditor.total_fuel == 18, f"total_fuel={auditor.total_fuel}";
    # Sanity: no self-cycle label emitted for a mutual one.
    assert "[CYCLE self]" not in out, f"wrong label for mutual cycle: {out!r}";
}

test "acyclic call graph produces zero cycle reports" {
    main = Routine(name="main", declared_bound=1);
    a_node = Routine(name="A", declared_bound=5);
    leaf = Routine(name="leaf", declared_bound=2);

    root ++> main;
    main +>:Calls(call_site="main->A"):+> a_node;
    main +>:Calls(call_site="main->leaf"):+> leaf;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = FuelAuditor();
        root spawn auditor;
    }
    out = buf.getvalue();

    assert "[CYCLE" not in out, f"unexpected cycle output in DAG: {out!r}";
    assert auditor.cycles_found == 0, f"cycles_found={auditor.cycles_found}";
    # Sum of declared bounds for the three entered Routines.
    assert auditor.total_fuel == 1 + 5 + 2, f"total_fuel={auditor.total_fuel}";
    # Each entered node appears in the enter-log once.
    assert out.count("[enter] main") == 1, f"main entered: {out!r}";
    assert out.count("[enter] A") == 1, f"A entered: {out!r}";
    assert out.count("[enter] leaf") == 1, f"leaf entered: {out!r}";
}

test "self recursion A->A is reported as a self cycle" {
    a_node = Routine(name="A", declared_bound=5);

    root ++> a_node;
    a_node +>:Calls(call_site="A->A"):+> a_node;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = FuelAuditor();
        root spawn auditor;
    }
    out = buf.getvalue();

    assert "[CYCLE self]" in out, f"missing self-cycle marker: {out!r}";
    assert auditor.cycles_found >= 1, f"cycles_found={auditor.cycles_found}";
    # First enter charges +5, re-entry charges declared bound again +5 = 10.
    assert auditor.total_fuel == 10, f"total_fuel={auditor.total_fuel}";
}

test "visited flag prevents entering a Routine more than once per spawn" {
    # Linear chain: main -> A -> B -> C. None revisited; total = sum.
    main = Routine(name="main", declared_bound=1);
    a_node = Routine(name="A", declared_bound=5);
    b_node = Routine(name="B", declared_bound=7);
    c_node = Routine(name="C", declared_bound=3);

    root ++> main;
    main +>:Calls(call_site="main->A"):+> a_node;
    a_node +>:Calls(call_site="A->B"):+> b_node;
    b_node +>:Calls(call_site="B->C"):+> c_node;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = FuelAuditor();
        root spawn auditor;
    }
    out = buf.getvalue();

    assert auditor.cycles_found == 0, f"cycles_found={auditor.cycles_found}";
    assert auditor.total_fuel == 1 + 5 + 7 + 3, f"total_fuel={auditor.total_fuel}";
    # Each node's visited flag should now be True (mutated by the walker).
    assert main.visited is True, "main not marked visited";
    assert a_node.visited is True, "A not marked visited";
    assert b_node.visited is True, "B not marked visited";
    assert c_node.visited is True, "C not marked visited";
}

test "typed Calls edges carry call_site metadata end-to-end" {
    # The walker traverses via the Calls edge type specifically; an edge
    # of a different type must NOT be followed by the walker.
    main = Routine(name="main", declared_bound=1);
    via_calls = Routine(name="via_calls", declared_bound=4);
    via_other = Routine(name="via_other", declared_bound=99);

    root ++> main;
    main +>:Calls(call_site="main->via_calls"):+> via_calls;
    # An untyped (generic) edge from main to via_other must NOT be visited
    # because the walker only follows [->:Calls:->].
    main +>:GenericEdge():+> via_other;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = FuelAuditor();
        root spawn auditor;
    }
    out = buf.getvalue();

    assert auditor.cycles_found == 0, f"cycles_found={auditor.cycles_found}";
    assert auditor.total_fuel == 1 + 4, f"total_fuel={auditor.total_fuel}";
    assert via_calls.visited is True, "Calls-edge target not visited";
    assert via_other.visited is False, "non-Calls edge was incorrectly followed";
}

