test "full audit graph: visitor set covers every archetype exactly once" {
    alice = User(username="alice", credential="sha256:aaaa", role="admin", active=True);
    doc = Document(title="brief.md", body="...", access_policy="public_read");
    repo = Repository(name="primary_db", engine="postgres", reachable=True);
    policy = PolicyDecision(decision="ALLOW", reason="public_read policy");

    root +>:Owns(granted_at="2026-01-15"):+> alice;
    alice +>:Owns(granted_at="2026-02-01"):+> doc;
    doc +>:Authorizes(via="policy_engine"):+> policy;
    doc +>:PersistsTo(commit="sha1"):+> repo;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = root spawn Auditor();
    }
    out = buf.getvalue();

    assert "alice" in auditor.visited, f"user not visited: {auditor.visited}";
    assert "brief.md" in auditor.visited, f"doc not visited: {auditor.visited}";
    assert "primary_db" in auditor.visited, f"repo not visited: {auditor.visited}";
    assert "policy:ALLOW" in auditor.visited, f"policy not visited: {auditor.visited}";

    # visited list must contain each entry exactly once (no double counts).
    assert auditor.visited.count("alice") == 1, f"alice visited twice: {auditor.visited}";
    assert auditor.visited.count("brief.md") == 1, f"brief.md visited twice: {auditor.visited}";
    assert auditor.visited.count("primary_db") == 1, f"primary_db visited twice: {auditor.visited}";
    assert auditor.visited.count("policy:ALLOW") == 1, f"policy visited twice: {auditor.visited}";

    assert len(auditor.findings) == 4, f"expected 4 findings (user/doc/repo/policy), got {len(auditor.findings)}: {auditor.findings}";
}

