"""Tests for startup reliability orchestration: phased bootstrap, compatibility admission, and bounded recovery."""

import io;
import from contextlib { redirect_stdout }

test "orchestrator admits compatible base but rejects stale and unavailable" {
    rt = Root();
    id_node = CompatIdentity(
        title="0.9.0",
        r_version="4.4.1",
        arch="aarch64",
        cache_digest="sha256:abc"
    );
    cold = StartupPhase(title="COLD", year=1);
    discovering = StartupPhase(title="DISCOVERING", year=2);
    compat_check = StartupPhase(title="COMPATIBILITY_CHECK", year=3);
    base_ready = StartupPhase(title="BASE_RUNTIME_READY", year=4);
    workbench = StartupPhase(title="WORKBENCH_READY", year=5);

    base_r = RuntimeComponent(title="BaseR", lane="base", compat_status="compatible");
    ark = RuntimeComponent(title="Ark", lane="base", compat_status="compatible");
    stale = RuntimeComponent(title="Stale", lane="agent", compat_status="stale");
    prov = RuntimeComponent(title="Provider", lane="provider", compat_status="compatible", available=False);

    rt ++> id_node;
    rt ++> cold ++> discovering ++> compat_check ++> base_ready ++> workbench;
    compat_check +>:RequiresCompat(expected_digest="sha256:abc"):+> id_node;
    base_ready +>:RequiresCompat(expected_digest="sha256:abc"):+> id_node;

    base_r +>:DependsOn:+> ark;
    ark +>:DependsOn:+> stale;
    rt ++> base_r ++> ark ++> stale;
    rt ++> prov;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        orch = StartupOrchestrator();
        rt spawn orch;
    }
    out = buf.getvalue();

    assert "[BASE] BaseR: ADMIT (compatible)" in out, f"base should be admitted: {out}";
    assert "[AGENT] Stale: REJECT (cache_stale)" in out, f"stale should be rejected: {out}";
    assert "[PROVIDER] Provider: REJECT (requires_user_action)" in out, f"unavailable should require user action: {out}";
    assert orch.workbench_ready, "orchestrator should reach WORKBENCH_READY";
    assert base_r.admitted, "BaseR should be admitted";
    assert not stale.admitted, "Stale component should not be admitted";
    assert not prov.admitted, "Unavailable provider should not be admitted";
}

test "orchestrator halts when required compat identity is missing" {
    rt = Root();
    cold = StartupPhase(title="COLD", year=1);
    discovering = StartupPhase(title="DISCOVERING", year=2);
    compat_check = StartupPhase(title="COMPATIBILITY_CHECK", year=3);

    rt ++> cold ++> discovering ++> compat_check;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        orch = StartupOrchestrator();
        rt spawn orch;
    }
    out = buf.getvalue();

    assert "[COMPATIBILITY_CHECK] entering" in out, f"should enter compat phase: {out}";
    assert "compat identity" not in out, f"no identity should be visited: {out}";
    assert not orch.workbench_ready, "should NOT reach WORKBENCH_READY when compat identity missing";
    assert orch.phases_done < 5, f"should halt before completing all phases: {orch.phases_done}";
}

test "recovery patrol counts repair steps and halts on exhausted" {
    rt = Root();
    a = RuntimeComponent(title="A", compat_status="repairable");
    b = RuntimeComponent(title="B", compat_status="repairable");
    exhausted = RuntimeComponent(title="Exhausted", compat_status="exhausted");

    rt ++> a ++> b ++> exhausted;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        patrol = RecoveryPatrol();
        rt spawn patrol;
    }
    out = buf.getvalue();

    assert "[REPAIR] A (step 1)" in out, f"A should be repaired: {out}";
    assert "[REPAIR] B (step 2)" in out, f"B should be repaired: {out}";
    assert "[STOP] Exhausted recovery exhausted" in out, f"should stop on exhausted: {out}";
    assert patrol.halted, "patrol should be halted";
    assert patrol.recovery_steps == 2, f"expected 2 repair steps, got {patrol.recovery_steps}";
}

test "recovery patrol detects repair cycle and halts" {
    rt = Root();
    cache = RuntimeComponent(title="Cache", compat_status="repairable");
    bridge = RuntimeComponent(title="Bridge", compat_status="repairable");

    rt ++> cache;
    cache +>:RepairLink:+> bridge;
    bridge +>:RepairLink:+> cache;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        patrol = RecoveryPatrol();
        rt spawn patrol;
    }
    out = buf.getvalue();

    assert "[HALT] cycle detected at Cache" in out, f"cycle on cache should halt: {out}";
    assert patrol.halted, "patrol should halt on cycle";
