}

test "recovery patrol skips non-repairable components" {
    rt = Root();
    healthy = RuntimeComponent(title="Healthy", compat_status="compatible");
    bad_arch = RuntimeComponent(title="BadArch", compat_status="mismatch");

    rt ++> healthy ++> bad_arch;

