    assert "[SKIP] BadArch not repairable" in out, f"mismatch should be skipped: {out}";
    assert not patrol.halted, "patrol should not halt on skips";
    assert patrol.recovery_steps == 0, f"no repairs should happen, got {patrol.recovery_steps}";
