"""Tests for release-cut traceability walker."""

import io;
import from contextlib { redirect_stdout }

test "MISSING when fix is reachable from HEAD but no enclosing tag" {
    root ++> Tag(label="v4.8.6", date="2024-10-30", version="4.8.6");
    head = Commit(sha="HEAD", summary="HEAD snapshot");
    c1 = Commit(sha="c0001", summary="docs");
    c2 = Commit(sha="c0002", summary="perf: implicit searches", is_fix=True);
    c3 = Commit(sha="c0003", summary="ci");
    c4 = Commit(sha="c0004", summary="refactor");
    root ++> head;
    head +>:ParentOf(order=1):+> c1;
    c1 +>:ParentOf(order=2):+> c2;
    c2 +>:ParentOf(order=3):+> c3;
    c3 +>:ParentOf(order=4):+> c4;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ReleaseAuditor();
    }
    out = buf.getvalue();
    assert "RECOMMENDATION: cut a new release" in out, f"missing release recommendation: {out}";
    assert "found motivating fix: c0002" in out, f"fix not reported: {out}";
    assert "tag 4.8.6 (2024-10-30): fix MISSING" in out, f"MISSING verdict absent: {out}";
    assert "audit complete: 5 commits traversed" in out, f"unexpected traversal count: {out}";
    assert res.found_in_tag == "MISSING", f"verdict field: {res.found_in_tag}";
    assert res.fix_sha == "c0002", f"fix_sha: {res.fix_sha}";
}

test "CONTAINED when the existing tag Cuts a descendant of the fix" {
