test "secure reservation rejects raced bundle symlink" {
    sentinel = Sentinel(label="outside-sentinel", touched=False);
    release = ReleaseRoot(bound_path="/miner-release", custody_bound=True);
    root +>:UnderRelease:+> release;
    release +>:OutsideBoundary:+> sentinel;

    slot = BundleSlot(
        platform="linux-amd64",
        pathname="/miner-release/linux-amd64"
    );
    release +>:UnderRelease:+> slot;

    trap = SymlinkTrap(
        path="/miner-release/linux-amd64",
        outside_target="/tmp/evil-sentinel"
    );
    slot +>:MaterializedAs(exclusive=False):+> trap;
    trap +>:QueuedWrite:+> PackageWrite(
        op="writeFile",
        rel_segment="outside-sentinel"
    );

    res = root spawn BundleReserver();

    assert res.custody_ok, f"custody was not bound: {res.custody_ok}";
    assert res.fail_closed, f"raced trap was not rejected: {res.fail_closed}";
    assert not res.reserved, f"conflicting trap was reserved: {res.reserved}";
    assert not sentinel.touched, f"sentinel was touched: {sentinel.touched}";
}

test "secure reservation creates a real bundle directory" {
    sentinel = Sentinel(label="outside-sentinel", touched=False);
    release = ReleaseRoot(bound_path="/miner-release", custody_bound=True);
    root +>:UnderRelease:+> release;
    release +>:OutsideBoundary:+> sentinel;

    slot = BundleSlot(
        platform="darwin-arm64",
        pathname="/miner-release/darwin-arm64"
    );
    release +>:UnderRelease:+> slot;
    slot +>:QueuedWrite:+> PackageWrite(
        op="cp",
        rel_segment="miner-runtime/bin"
    );

    res = root spawn BundleReserver();
    materialized = [slot ->:MaterializedAs:->];

    assert res.custody_ok, f"custody was not bound: {res.custody_ok}";
    assert res.reserved, f"bundle was not reserved: {res.reserved}";
    assert not res.fail_closed, f"clean bundle failed closed: {res.fail_closed}";
    assert slot.phase == "reserved", f"unexpected phase: {slot.phase}";
    assert len(materialized) == 1, f"materialized count: {len(materialized)}";
    assert materialized[0].is_directory(), "reserved object is not a directory";
    assert not sentinel.touched, f"sentinel was touched: {sentinel.touched}";
}

test "pathname packager follows raced trap" {
    sentinel = Sentinel(label="outside-sentinel", touched=False);
    release = ReleaseRoot(bound_path="/miner-release", custody_bound=True);
    root +>:UnderRelease:+> release;
    release +>:OutsideBoundary:+> sentinel;

    slot = BundleSlot(
        platform="linux-amd64",
        pathname="/miner-release/linux-amd64"
    );
    release +>:UnderRelease:+> slot;

    trap = SymlinkTrap(
        path="/miner-release/linux-amd64",
        outside_target="/tmp/evil-sentinel"
    );
    slot +>:MaterializedAs:+> trap;
    trap +>:QueuedWrite:+> PackageWrite(
        op="writeFile",
        rel_segment="outside-sentinel"
    );

    res = root spawn PathnamePackager();
    sentinel.touched = res.leaked_outside;

    assert res.leaked_outside, "pathname traversal did not expose the trap";
    assert sentinel.touched, f"sentinel was not marked touched: {sentinel.touched}";
}

test "pre-existing conflicting bundle object fails closed" {
    sentinel = Sentinel(label="outside-sentinel", touched=False);
    release = ReleaseRoot(bound_path="/miner-release", custody_bound=True);
    root +>:UnderRelease:+> release;
    release +>:OutsideBoundary:+> sentinel;

    slot = BundleSlot(
        platform="windows-amd64",
        pathname="/miner-release/windows-amd64"
    );
    release +>:UnderRelease:+> slot;

    conflict = SymlinkTrap(
        path="/miner-release/windows-amd64",
        outside_target="C:/evil-sentinel"
    );
    slot +>:MaterializedAs(exclusive=False):+> conflict;
    conflict +>:QueuedWrite:+> PackageWrite(
