        rel_segment="outside-sentinel"
    );

    res = root spawn BundleReserver();

    assert res.fail_closed, f"conflict was not rejected: {res.fail_closed}";
    assert not res.reserved, f"conflict was reserved: {res.reserved}";
    assert not sentinel.touched, f"sentinel was touched: {sentinel.touched}";
