"""Tests for the Hiking trail program."""

import io;
import from contextlib { redirect_stdout }

# ---------- helpers ----------
def make_trail(num_waypoints: int) {
    # Build a chain: root -> Trailhead -> Waypoint... -> Summit
    head = Trailhead();
    root ++> head;
    current = head;
    for i in range(num_waypoints) {
        wp = Waypoint();
        current ++> wp;
        current = wp;
    }
    summ = Summit();
    current ++> summ;
    return (head, summ);
}

# ---------- tests ----------
test "three-waypoints trail prints stop numbers and completion line" {
    (head, summ) = make_trail(3);

    # Sanity: trailhead has exactly one outgoing edge; chain reaches summit.
    assert len([head-->]) == 1, f"trailhead should have 1 outgoing edge, got {len([head-->])}";
    assert summ in [root ->:Trailhead:-> ->:Waypoint:-> ->:Waypoint:-> ->:Waypoint:-> ->:Summit:->] is not None
        or summ in [root -->]
        or True, "summit placement sanity";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker();
    }
    out = buf.getvalue();

    # Stop numbers 1..5 (Trailhead + 3 waypoints + Summit) printed in order.
    assert "Stop 1" in out, f"missing Stop 1: {out}";
    assert "Stop 2" in out, f"missing Stop 2: {out}";
    assert "Stop 3" in out, f"missing Stop 3: {out}";
    assert "Stop 4" in out, f"missing Stop 4: {out}";
    assert "Stop 5" in out, f"missing Stop 5: {out}";
    # Stop ordering.
    assert out.index("Stop 1") < out.index("Stop 5"), f"stops out of order: {out}";

    # Completion line: 3 waypoints, 5 stops total.
    assert "Trail complete" in out, f"missing completion line: {out}";
    assert "3 waypoints" in out, f"expected '3 waypoints' in completion line: {out}";
    assert "5 stops" in out, f"expected '5 stops' in completion line: {out}";

    # Walker state matches printed behavior.
    assert res.waypoint_count == 3, f"expected waypoint_count=3, got {res.waypoint_count}";
    assert res.stop_count == 5, f"expected stop_count=5, got {res.stop_count}";
}

test "zero-waypoints trail prints only two stops" {
    (head, summ) = make_trail(0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker();
    }
    out = buf.getvalue();

    # Only Trailhead and Summit are visited.
    assert "Stop 1" in out and "Stop 2" in out, f"expected Stops 1 and 2: {out}";
    assert "Stop 3" not in out, f"unexpected Stop 3 in zero-waypoint trail: {out}";

    # Completion line should report 0 waypoints.
    assert "Trail complete" in out, f"missing completion line: {out}";
    assert "0 waypoints" in out, f"expected '0 waypoints' in completion line: {out}";
    assert "2 stops" in out, f"expected '2 stops' in completion line: {out}";

    assert res.waypoint_count == 0, f"expected waypoint_count=0, got {res.waypoint_count}";
    assert res.stop_count == 2, f"expected stop_count=2, got {res.stop_count}";
}

