    assert res.stop_count == 3, f"expected stop_count=3, got {res.stop_count}";
}

test "trail shape is a linear chain under root" {
    (head, summ) = make_trail(4);

    # Root -> Trailhead is the only direct edge from root.
    root_kids = [root-->];
    assert len(root_kids) == 1, f"root should have exactly 1 direct child, got {len(root_kids)}";
    assert root_kids[0] == head, "root's direct child must be the trailhead";

    # Chain length: 1 trailhead + 4 waypoints + 1 summit = 6 nodes total.
    # Collect every node reachable from root via forward edges.
    seen: list = [];
    stack: list = [root];
    while len(stack) > 0 {
        n = stack.pop();
        if n in seen {
            continue;
        }
        seen.append(n);
        for k in [n-->] {
            stack.append(k);
        }
    }
    # root + trailhead + 4 waypoints + summit = 6
    assert len(seen) == 6, f"expected 6 nodes in chain, got {len(seen)}";

    # Trailhead has exactly one outgoing child.
    assert len([head-->]) == 1, "trailhead should have 1 outgoing edge";

    # The summit's parent is some waypoint (it has no outgoing edges).
    out_of_summit = [summ-->];
    assert len(out_of_summit) == 0, "summit must be terminal (no outgoing edges)";
}

test "hiker disengages after completion and does not revisit" {
    (head, summ) = make_trail(2);

