"""Tests for FlightLeg edges and Scout walker behavior."""

import io;
import from contextlib { redirect_stdout }

# ---------- Test: fraction_of_max math against known top fare ----------

test "fraction_of_max computes correct ratios against known top fare" {
    # Build a tiny network with known prices: 100, 200, 400 (top = 400).
    a1 = Airport(code="A1");
    a2 = Airport(code="A2");
    a3 = Airport(code="A3");

    leg_a = FlightLeg(price=100.0, label="A");
    a1 +>:leg_a:+> a2;

    leg_b = FlightLeg(price=200.0, label="B");
    a2 +>:leg_b:+> a3;

    leg_c = FlightLeg(price=400.0, label="C");
    a3 +>:leg_c:+> a1;

    top = 400.0;

    # 100/400 = 0.25, 200/400 = 0.50, 400/400 = 1.00
    assert leg_a.fraction_of_max(top) == 0.25, (
        f"leg A should be 0.25, got {leg_a.fraction_of_max(top)}"
    );
    assert leg_b.fraction_of_max(top) == 0.50, (
        f"leg B should be 0.50, got {leg_b.fraction_of_max(top)}"
    );
    assert leg_c.fraction_of_max(top) == 1.00, (
        f"leg C should be 1.00, got {leg_c.fraction_of_max(top)}"
    );

    # The most expensive leg in the network MUST be exactly 1.00 of the top fare.
    assert leg_c.price == top, "top fare assumption broken";
}

# ---------- Test: fraction_of_max is fail-closed on non-positive top fare ----------

test "fraction_of_max returns 0.0 when top fare is zero or negative" {
    a = Airport(code="A");
    b = Airport(code="B");
    leg = FlightLeg(price=250.0, label="A-B");
    a +>:leg:+> b;

    # Per the implementation: any top_fare <= 0.0 must yield 0.0 (fail-closed).
    assert leg.fraction_of_max(0.0) == 0.0, "top=0 should fail closed to 0.0";
    assert leg.fraction_of_max(-10.0) == 0.0, (
        f"negative top should fail closed, got {leg.fraction_of_max(-10.0)}"
    );

    # And it must not divide — confirm price field is untouched.
    assert leg.price == 250.0, "fraction_of_max must not mutate the leg's price";
}

# ---------- Test: Scout collects every FlightLeg price exactly once ----------

test "Scout collects every FlightLeg price and finds the correct peak" {
    # Build a 4-airport square: JFK-LAX-ORD-DEN-JFK with distinct prices.
    jfk = Airport(code="JFK");
    lax = Airport(code="LAX");
    ord_node = Airport(code="ORD");
    den = Airport(code="DEN");

    leg1 = FlightLeg(price=450.0, label="JFK-LAX");
    jfk +>:leg1:+> lax;

    leg2 = FlightLeg(price=380.0, label="LAX-ORD");
    lax +>:leg2:+> ord_node;

    leg3 = FlightLeg(price=520.0, label="ORD-DEN");
    ord_node +>:leg3:+> den;

    leg4 = FlightLeg(price=310.0, label="DEN-JFK");
    den +>:leg4:+> jfk;

    root ++> jfk;
    root ++> lax;

    res = root spawn Scout();

    # Scout must have recorded exactly one entry per FlightLeg in the graph.
    assert len(res.prices) == 4, (
        f"Scout should collect 4 fares, got {len(res.prices)}: {res.prices}"
    );

    # The set of collected prices must equal the set of leg prices.
    assert sorted(res.prices) == [310.0, 380.0, 450.0, 520.0], (
        f"Scout prices mismatch: {res.prices}"
    );

    # Peak fare must be the maximum of those prices.
    assert res.max_fare == 520.0, (
        f"Scout peak should be 520.0, got {res.max_fare}"
    );

    # Each recorded price must be strictly positive (real money).
    for p in res.prices {
        assert p > 0.0, f"unexpected non-positive fare: {p}";
    }
}

# ---------- Test: Scout.report() string reports count and peak ----------

test "Scout report summarizes count and peak fare" {
    jfk = Airport(code="JFK");
    lax = Airport(code="LAX");
    ord_node = Airport(code="ORD");

    leg1 = FlightLeg(price=450.0, label="JFK-LAX");
