    root ++> jfk;

    res = root spawn Scout();
    msg = res.report();

    # The report must include the number of fares seen and the peak fare value.
    assert "2" in msg, f"report should mention 2 fares, got: {msg}";
    assert "450.00" in msg or "$450.00" in msg or "450" in msg, (
        f"report should mention peak fare 450, got: {msg}"
    );
    assert "Scout" in msg, f"report should be attributed to Scout, got: {msg}";
}

# ---------- Test: end-to-end stdout matches problem promise ----------

test "end-to-end run prints all four leg fractions with percent formatting" {
    jfk = Airport(code="JFK");
    lax = Airport(code="LAX");
    ord_node = Airport(code="ORD");
    den = Airport(code="DEN");

    leg_jfk_lax = FlightLeg(price=450.0, label="JFK-LAX");
    jfk +>:leg_jfk_lax:+> lax;
    leg_lax_ord = FlightLeg(price=380.0, label="LAX-ORD");
    lax +>:leg_lax_ord:+> ord_node;
    leg_ord_den = FlightLeg(price=520.0, label="ORD-DEN");
    ord_node +>:leg_ord_den:+> den;
    leg_den_jfk = FlightLeg(price=310.0, label="DEN-JFK");
    den +>:leg_den_jfk:+> jfk;

    root ++> jfk;
    root ++> lax;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        scout = Scout();
        root spawn scout;
        print(scout.report());
        for leg in [leg_jfk_lax, leg_lax_ord, leg_ord_den, leg_den_jfk] {
            share = leg.fraction_of_max(scout.max_fare);
            print(f"{leg.label}: ${leg.price:.2f} is {share:.2%} of top fare");
        }
    }
    out = buf.getvalue();

    # The output must contain a Scout summary line and a line per leg.
    assert "Scout logged 4 fares" in out, (
        f"missing Scout summary line, got: {out}"
    );
    assert "$520.00" in out, f"missing peak fare in output, got: {out}";

    # Each leg label must appear with a percent-formatted share.
    assert "JFK-LAX:" in out and "100.00%" in out, (
        f"top fare should print 100.00%, got: {out}"
    );
    assert "LAX-ORD:" in out and "73.08%" in out, (
        f"380/520 should be 73.08%, got: {out}"
    );
    assert "ORD-DEN:" in out and "100.00%" in out, (
        f"520/520 should be 100.00%, got: {out}"
    );
    assert "DEN-JFK:" in out and "59.62%" in out, (
        f"310/520 should be 59.62%, got: {out}"
    );

    # The printed shares, taken at face value, must equal the math.
    assert abs(leg_lax_ord.fraction_of_max(scout.max_fare) - (380.0 / 520.0)) < 1e-9, (
        "LAX-ORD share inconsistent between print and math"
    );
    assert abs(leg_den_jfk.fraction_of_max(scout.max_fare) - (310.0 / 520.0)) < 1e-9, (
        "DEN-JFK share inconsistent between print and math"
    );
}

