# ---------- Test 2: round with all pets needing a shot ----------
test "vet counts shots and records every patient" {
    root ++> Pet(name="Mochi", species="cat", needs_vaccine=True);
    root ++> Pet(name="Rex", species="dog", needs_vaccine=True);
    root ++> Pet(name="Hopper", species="rabbit", needs_vaccine=True);
    root ++> Pet(name="Nimbus", species="parrot", needs_vaccine=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Vet();
    }
    vet = res;

    assert len(vet.patients) == 4, f"expected 4 patients, got {len(vet.patients)}";
    assert vet.shots_given == 4, f"expected 4 shots, got {vet.shots_given}";
    assert set(vet.patients) == {"Mochi", "Rex", "Hopper", "Nimbus"}, f"patients wrong: {vet.patients}";

    # every pet should now be flagged up-to-date
    for p in [root-->] {
        assert p.needs_vaccine is False, f"{p.name} still needs vaccine after round";
    }

    out = buf.getvalue();
    assert "Vet starting the clinic round" in out, f"missing start line: {out}";
    assert "Examining Mochi the cat" in out, f"missing Mochi exam: {out}";
    assert "Examining Rex the dog" in out, f"missing Rex exam: {out}";
    assert "Examining Hopper the rabbit" in out, f"missing Hopper exam: {out}";
    assert "Examining Nimbus the parrot" in out, f"missing Nimbus exam: {out}";
    assert "gave Mochi a vaccine" in out, f"missing Mochi shot: {out}";
    assert "gave Rex a vaccine" in out, f"missing Rex shot: {out}";
}

# ---------- Test 3: mixed needs_vaccine flags ----------
test "vet skips pets that are already up to date" {
    root ++> Pet(name="Mochi", species="cat", needs_vaccine=True);
    root ++> Pet(name="Rex", species="dog", needs_vaccine=False);
    root ++> Pet(name="Hopper", species="rabbit", needs_vaccine=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Vet();
    }
    vet = res;

    assert len(vet.patients) == 3, f"should visit all 3, got {len(vet.patients)}";
    assert vet.shots_given == 2, f"only Mochi and Hopper need shots, got {vet.shots_given}";

    out = buf.getvalue();
    assert "Rex is up to date" in out, f"missing up-to-date note for Rex: {out}";
    assert "gave Mochi a vaccine" in out, f"missing Mochi shot: {out}";
    assert "gave Hopper a vaccine" in out, f"missing Hopper shot: {out}";

    # Rex's flag must remain False; the two needy ones flipped to False
    pets = [root-->];
    rex = [p for p in pets if p.name == "Rex"][0];
    assert rex.needs_vaccine is False, "Rex flag should be untouched";
}

