# ---------- Test 5: spawned walker instance carries its own state ----------
test "two spawns do not share state" {
    root ++> Pet(name="A", species="cat", needs_vaccine=True);
    root ++> Pet(name="B", species="dog", needs_vaccine=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        v1 = root spawn Vet();
    }
    assert v1.shots_given == 2, f"first round shots: {v1.shots_given}";
    assert "A" in v1.patients and "B" in v1.patients, f"first round patients: {v1.patients}";

    # second spawn on the same root -- pets are now flagged False by first round
    buf2 = io.StringIO();
    with redirect_stdout(buf2) {
        v2 = root spawn Vet();
    }
    assert len(v2.patients) == 2, f"second round still visits all: {len(v2.patients)}";
    assert v2.shots_given == 0, f"second round should give 0 shots, got {v2.shots_given}";

    out2 = buf2.getvalue();
    assert "A is up to date" in out2, f"missing A up-to-date: {out2}";
    assert "B is up to date" in out2, f"missing B up-to-date: {out2}";

    # v1 state untouched by second walk
    assert v1.shots_given == 2, f"v1 state was mutated: {v1.shots_given}";
}

