        ++> Station(name="B", location="East",  celsius=20.0)
        ++> Station(name="C", location="West",  celsius=30.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        sweep = WeatherSweep();
        root spawn sweep;
    }
    out = buf.getvalue();

    # Each station should have been announced.
    assert "reading 10.0C at A (North)" in out, f"missing A: {out}";
    assert "reading 20.0C at B (East)"  in out, f"missing B: {out}";
    assert "reading 30.0C at C (West)"  in out, f"missing C: {out}";

    # Three readings were recorded in traversal order.
    assert len(sweep.readings) == 3, f"expected 3 readings, got {len(sweep.readings)}}";
    assert sweep.readings[0][0] == "A", f"first name wrong: {sweep.readings[0]}";
    assert sweep.readings[1][0] == "B", f"second name wrong: {sweep.readings[1]}";
    assert sweep.readings[2][0] == "C", f"third name wrong: {sweep.readings[2]}";

    # Tuples must carry (name, location, celsius).
    assert sweep.readings[0][1] == "North", f"loc wrong: {sweep.readings[0]}";
    assert sweep.readings[0][2] == 10.0,     f"temp wrong: {sweep.readings[0]}";
    assert sweep.readings[2][2] == 30.0,     f"temp wrong: {sweep.readings[2]}";
}

test "walker visits all direct children in one sweep" {
