# ---------------------------------------------------------------------------
# Test 1: Hunter walks the chain and disengages AT the vault (3 rooms seen,
# trap room never visited).
# ---------------------------------------------------------------------------
test "hunter disengages at treasure and never enters rooms past vault" {
    foyer = Room(name="Foyer");
    armory = Room(name="Armory");
    library = Room(name="Library");
    vault = Room(name="Vault", has_treasure=True);
    trap = Room(name="Trap Room");

    root ++> foyer ++> armory ++> library ++> vault ++> trap;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hunter();
    }
    out = buf.getvalue();

    # Hunter entered the dungeon.
    assert "Hunter enters the dungeon" in out, f"missing entry line: {out}";

    # Foyer and Library are the non-treasure rooms visited along the chain.
    assert "Inspected 'Foyer'" in out, f"missing foyer inspection: {out}";
    assert "Inspected 'Library'" in out, f"missing library inspection: {out}";

    # The vault is the 3rd room inspected and the hunter announces it.
    assert "Treasure found in 'Vault' after inspecting 3 room(s)" in out, (
        f"missing vault line: {out}"
    );

    # Rooms past the vault must NEVER appear in the walk's output.
    assert "Trap Room" not in out, (
        f"hunter must never visit rooms past the vault: {out}"
    );

    # The walker's own counter agrees.
    assert res.rooms_seen == 3, f"expected 3 rooms seen, got {res.rooms_seen}";

    # The trap room is still attached to the vault in the chain; the hunter
    # just didn't traverse past the disengage.
    names = [];
    cur = [root -->][0] if len([root -->]) > 0 else None;
    while cur is not None {
        names.append(cur.name);
        nxt = [cur -->];
        cur = nxt[0] if len(nxt) > 0 else None;
    }
    assert names == ["Foyer", "Armory", "Library", "Vault", "Trap Room"], (
        f"graph chain should be intact, got {names}"
    );
}

