"""Tests for the tiny dungeon crawler.

Verifies the Hunter walker:
- inspects chained rooms in order while counting them,
- terminates the search as soon as it enters the vault,
- never visits rooms past the vault,
- prints the expected inspection messages and the found/not-found outcome.
"""

import io;
import from contextlib { redirect_stdout }

# --- 1. Vault in the middle: hunter must stop at the vault and skip the rest. ---
test "stops at vault and skips rooms after it" {
    root ++> Room(name="Entrance")
        ++> Room(name="Antechamber")
        ++> Room(name="Guardroom")
        ++> Room(name="Vault", has_treasure=True)
        ++> Room(name="Hidden Alcove")
        ++> Room(name="Back Exit");

    hunter = Hunter();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn hunter;
    }
    out = buf.getvalue();

    # The vault and the two rooms before it were inspected (3 total).
    assert hunter.rooms_inspected == 3, (
        f"expected 3 rooms inspected before disengage, got {hunter.rooms_inspected}"
    );

    # Inspection messages for the visited rooms appear, in order.
    assert "Inspecting room #1: Entrance" in out, f"missing Entrance line: {out!r}";
    assert "Inspecting room #2: Antechamber" in out, f"missing Antechamber line: {out!r}";
    assert "Inspecting room #3: Guardroom" in out, f"missing Guardroom line: {out!r}";

    # Vault message and success outcome printed.
    assert "Treasure found in 'Vault'!" in out, f"missing treasure line: {out!r}";
    assert "Search ends." in out, f"missing 'Search ends.' line: {out!r}";

    # Rooms past the vault must never be reported on.
    assert "Hidden Alcove" not in out, f"post-vault room 'Hidden Alcove' was visited: {out!r}";
    assert "Back Exit" not in out, f"post-vault room 'Back Exit' was visited: {out!r}";
}

# --- 2. Same shape, but the demo's trailing summary print is NOT produced by
#        the spawn itself — the program only prints it inside `with entry`.
#        Here we rely solely on output produced by the walker.
test "total inspected count equals number of rooms before the vault" {
    root ++> Room(name="A")
        ++> Room(name="B")
        ++> Room(name="Vault", has_treasure=True)
        ++> Room(name="C");

    hunter = Hunter();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn hunter;
    }
    out = buf.getvalue();

    # Two rooms (A, B) walked before the vault triggered disengage.
    assert hunter.rooms_inspected == 2, (
        f"expected 2 rooms inspected, got {hunter.rooms_inspected}"
    );
    assert "Inspecting room #1: A" in out, f"missing room A inspection: {out!r}";
    assert "Inspecting room #2: B" in out, f"missing room B inspection: {out!r}";
    assert "Treasure found in 'Vault'!" in out, f"missing treasure line: {out!r}";
    assert "C" not in out, f"post-vault room C was visited: {out!r}";
}

# --- 3. No vault anywhere: hunter must walk every room and end gracefully. ---
test "without a vault the hunter walks every room and exits cleanly" {
    root ++> Room(name="R1")
        ++> Room(name="R2")
        ++> Room(name="R3");

    hunter = Hunter();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn hunter;
    }
    out = buf.getvalue();

    # All three rooms inspected.
    assert hunter.rooms_inspected == 3, (
        f"expected all 3 rooms inspected, got {hunter.rooms_inspected}"
    );
    assert "Inspecting room #1: R1" in out, f"missing R1: {out!r}";
    assert "Inspecting room #2: R2" in out, f"missing R2: {out!r}";
    assert "Inspecting room #3: R3" in out, f"missing R3: {out!r}";
    # No treasure line should be emitted when there is no vault.
    assert "Treasure found" not in out, f"unexpected treasure line: {out!r}";
}

# --- 4. Vault is the very first room: hunter disengages after one step. ---
test "vault as first room disengages after inspecting only the vault" {
    root ++> Room(name="Vault", has_treasure=True)
        ++> Room(name="Second")
        ++> Room(name="Third");

    hunter = Hunter();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn hunter;
    }
    out = buf.getvalue();

    assert hunter.rooms_inspected == 1, (
        f"expected 1 room inspected (the vault itself), got {hunter.rooms_inspected}"
    );
    assert "Inspecting room #1: Vault" in out, f"missing vault inspection: {out!r}";
    assert "Treasure found in 'Vault'!" in out, f"missing treasure line: {out!r}";
    # Second and Third must not appear in output at all.
    assert "Second" not in out, f"post-vault room 'Second' was visited: {out!r}";
    assert "Third" not in out, f"post-vault room 'Third' was visited: {out!r}";
}

