"""Tests for the order audit walker — verifies skip vs disengage behavior."""

import io;
import from contextlib { redirect_stdout }

test "fraud flag halts entire audit immediately" {
    root ++> Order(order_id="B-1001", amount=10.00)
        ++> Order(order_id="B-1002", amount=20.00, flagged_fraud=True)
        ++> Order(order_id="B-1003", amount=30.00)
        ++> Order(order_id="B-1004", amount=40.00);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Auditor();
    }
    out = buf.getvalue();

    # The fraudulent order prints its halt line.
    assert "B-1002: FRAUD FLAG - halting the whole audit" in out, f"missing fraud halt line: {out}";
    # No orders after the fraud flag are touched.
    assert "B-1003" not in out, f"B-1003 should not be visited after disengage: {out}";
    assert "B-1004" not in out, f"B-1004 should not be visited after disengage: {out}";
    # The pre-fraud ok line still fires (continuation was queued before disengage).
    assert "B-1001: ok" in out, f"missing B-1001 ok line: {out}";
    # Exactly one order completed before the halt.
    assert res.audited == 1, f"expected 1 audited before halt, got {res.audited}";
}

test "invalid order is skipped but audit continues" {
    root ++> Order(order_id="C-1001", amount=5.00)
        ++> Order(order_id="C-1002", amount=15.00, valid=False)
        ++> Order(order_id="C-1003", amount=25.00);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Auditor();
    }
    out = buf.getvalue();

    # The invalid order prints its skip line.
    assert "C-1002: invalid, skipping just this order" in out, f"missing skip line: {out}";
    # Skipping does NOT count it as audited.
    assert res.audited == 2, f"expected 2 audited (skip doesn't count), got {res.audited}";
    # Audit continued past the invalid one.
    assert "C-1003: ok" in out, f"C-1003 should be audited after skip: {out}";
    assert "C-1001: ok" in out, f"missing C-1001 ok line: {out}";
    # No fraud message anywhere.
    assert "FRAUD FLAG" not in out, f"unexpected fraud message in non-fraud run: {out}";
}

test "fraud flag fires before validity check even when both flags set" {
    # Order is both invalid AND fraudulent. The program checks fraud first,
    # so we expect the FRAUD line, not the invalid line, and the walker halts.
    root ++> Order(order_id="D-1001", amount=7.00)
        ++> Order(order_id="D-1002", amount=77.00, valid=False, flagged_fraud=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Auditor();
    }
    out = buf.getvalue();

    assert "D-1002: FRAUD FLAG - halting the whole audit" in out, f"missing fraud halt line: {out}";
    assert "invalid, skipping" not in out, f"fraud should preempt skip branch: {out}";
    assert res.audited == 1, f"expected 1 audited (D-1001 only), got {res.audited}";
}

test "all valid orders with no fraud audits every one" {
    root ++> Order(order_id="E-1001", amount=1.00)
        ++> Order(order_id="E-1002", amount=2.00)
        ++> Order(order_id="E-1003", amount=3.00);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Auditor();
    }
    out = buf.getvalue();

    assert "Audit started" in out, f"missing start banner: {out}";
    assert "E-1001: ok ($1.00)" in out, f"missing E-1001 ok line: {out}";
    assert "E-1002: ok ($2.00)" in out, f"missing E-1002 ok line: {out}";
    assert "E-1003: ok ($3.00)" in out, f"missing E-1003 ok line: {out}";
    assert "FRAUD FLAG" not in out, f"unexpected fraud message: {out}";
    assert "invalid, skipping" not in out, f"unexpected skip message: {out}";
    assert res.audited == 3, f"expected all 3 audited, got {res.audited}";
    # Graph has all orders reachable from root.
