test "skip and disengage coexist across a mixed batch" {
    # Mix: ok, invalid (skip), ok, fraud (disengage), ok (never reached).
    root ++> Order(order_id="F-1001", amount=10.00)
        ++> Order(order_id="F-1002", amount=20.00, valid=False)
        ++> Order(order_id="F-1003", amount=30.00)
        ++> Order(order_id="F-1004", amount=999.99, flagged_fraud=True)
        ++> Order(order_id="F-1005", amount=40.00);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Auditor();
    }
    out = buf.getvalue();

    # Each mechanism's signature line is present.
    assert "F-1002: invalid, skipping just this order" in out, f"missing skip line: {out}";
    assert "F-1004: FRAUD FLAG - halting the whole audit" in out, f"missing fraud halt: {out}";
    # F-1005 (after fraud) is never reached.
    assert "F-1005" not in out, f"F-1005 must not be visited after disengage: {out}";
    # Audited count: F-1001 yes, F-1002 no (skipped), F-1003 yes, F-1004 no (halted before count), F-1005 no.
    assert res.audited == 2, f"expected 2 audited, got {res.audited}";
    # Order of lines matters: skip line precedes the subsequent ok line.
    skip_idx = out.index("F-1002: invalid");
    f1003_idx = out.index("F-1003: ok");
    fraud_idx = out.index("F-1004: FRAUD FLAG");
    assert skip_idx < f1003_idx, f"skip should appear before F-1003 ok: {out}";
    assert f1003_idx < fraud_idx, f"F-1003 ok should appear before fraud halt: {out}";
}

