    assert "++ APPROVED 'OK-1' amount=50.00 running_total=50.00" in out, f"missing OK-1: {out}";
    assert "++ APPROVED 'OK-2' amount=25.00 running_total=75.00" in out, f"OK-2 total must skip invalid amount: {out}";

    # the skip line itself must not print a running total
    skip_line = [l for l in out.splitlines() if "BAD-INVALID" in l][0];
    assert "running_total" not in skip_line, f"skip line should not show running_total: {skip_line}";

    assert res.total == 75.0, f"invalid amount must not contribute, got {res.total}";
}


# -------------------------------------------------------------------------
# Test 3: Fraud-flagged order HALTS the entire walk — no later orders visited
# -------------------------------------------------------------------------
