    root ++> Order(label="GOOD-1", amount=100.00)
        ++> Order(label="GOOD-2", amount=50.00)
        ++> Order(label="FRAUD-X", amount=500.00, flagged_fraud=True)
        ++> Order(label="NEVER-SEEN", amount=10.00)
        ++> Order(label="NEVER-SEEN-2", amount=20.00);

