    assert "++ APPROVED 'GOOD-2' amount=50.00 running_total=150.00" in out, f"missing GOOD-2: {out}";
    assert "!! FRAUD HALT on 'FRAUD-X' (amount=500.00) — stopping audit" in out, f"missing fraud halt: {out}";

    # later orders must never appear — walk disengaged on FRAUD-X
    assert "NEVER-SEEN" not in out, f"walk continued past fraud, output: {out}";
    assert "NEVER-SEEN-2" not in out, f"walk continued past fraud, output: {out}";
    assert "++ APPROVED 'FRAUD-X'" not in out, f"fraud order must not be approved: {out}";

    # fraud amount must not be added to the total
    assert res.total == 150.0, f"fraud amount must not contribute, got {res.total}";
}


# -------------------------------------------------------------------------
# Test 4: Combined — skip then fraud — confirms both early-return flavors
#         cooperate in the right order
# -------------------------------------------------------------------------
test "skip then fraud both fire correctly in one walk" {
