    assert "-- SKIP invalid order 'BAD-SKIP' — continuing audit" in out, f"missing skip: {out}";
    assert "++ APPROVED 'OK-B' amount=20.00 running_total=30.00" in out, f"missing OK-B: {out}";
    assert "!! FRAUD HALT on 'FRAUD-Z'" in out, f"missing fraud halt: {out}";
    assert "AFTER-FRAUD" not in out, f"walk continued past fraud: {out}";
    assert res.total == 30.0, f"only OK-A + OK-B should count, got {res.total}";
}


# -------------------------------------------------------------------------
# Test 5: Fraud on the very first order — nothing approved, total stays 0
# -------------------------------------------------------------------------
test "fraud on first order halts immediately" {
    root ++> Order(label="FRAUD-FIRST", amount=1000.00, flagged_fraud=True)
