"""Tests for OrderAuditor: skip (continue) and disengage (break) semantics."""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
# Test 1: A mixed chain exercises BOTH early-return flavors in a single walk.
# Expected print order:
#   [OK]   A: ...
#   [SKIP] B: ...
#   [HALT] C: ...
# After the HALT, D must NOT be visited.
# ---------------------------------------------------------------------------
test "mixed chain: skip continues, disengage halts" {
    root ++> Order(label="A", amount=10.00, valid=True)
        ++> Order(label="B", amount=20.00, valid=False)
        ++> Order(label="C", amount=30.00, valid=True, fraud=True)
        ++> Order(label="D", amount=40.00, valid=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();

    # OK branch fires on A.
    assert "[OK]   A:" in out, f"A should be OK, got: {out!r}";
    # SKIP branch fires on B (invalid, not fraud).
    assert "[SKIP] B:" in out, f"B should be SKIPped, got: {out!r}";
    # HALT branch fires on C (fraud takes precedence over validity).
    assert "[HALT] C:" in out, f"C should be HALTed, got: {out!r}";
    # disengage must stop the whole walk -- D never visited.
    assert "D" not in out, f"D traversed after disengage: {out!r}";
    # OK must NOT fire on the fraud node.
    assert "[OK]   C" not in out, f"OK should not fire on fraud node: {out!r}";
    # SKIP must NOT fire on the fraud node -- fraud check comes first.
    assert "[SKIP] C" not in out, f"SKIP should not fire on fraud node: {out!r}";
}

# ---------------------------------------------------------------------------
# Test 2: A pure-OK chain with no flags -- every node prints [OK] in order.
# ---------------------------------------------------------------------------
test "all valid: every order prints OK" {
    root ++> Order(label="X1", amount=1.00, valid=True)
        ++> Order(label="X2", amount=2.00, valid=True)
        ++> Order(label="X3", amount=3.00, valid=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert "[OK]   X1:" in out, f"X1 missing: {out!r}";
    assert "[OK]   X2:" in out, f"X2 missing: {out!r}";
    assert "[OK]   X3:" in out, f"X3 missing: {out!r}";
    assert "[SKIP]" not in out, f"unexpected SKIP: {out!r}";
    assert "[HALT]" not in out, f"unexpected HALT: {out!r}";

    # Confirm traversal order is left-to-right along the chain.
    i1 = out.index("[OK]   X1:");
    i2 = out.index("[OK]   X2:");
    i3 = out.index("[OK]   X3:");
    assert i1 < i2 < i3, f"wrong traversal order: {out!r}";
}

# ---------------------------------------------------------------------------
# Test 3: Pure SKIP chain -- invalid nodes are skipped, walk keeps going.
# No HALT, no OK on any invalid node.
# ---------------------------------------------------------------------------
test "all invalid: skip fires on every node, walk continues" {
    root ++> Order(label="S1", amount=5.00, valid=False)
        ++> Order(label="S2", amount=6.00, valid=False)
        ++> Order(label="S3", amount=7.00, valid=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert "[SKIP] S1:" in out, f"S1 missing: {out!r}";
    assert "[SKIP] S2:" in out, f"S2 missing: {out!r}";
    assert "[SKIP] S3:" in out, f"S3 missing: {out!r}";
    assert "[OK]" not in out, f"OK fired on invalid node: {out!r}";
    assert "[HALT]" not in out, f"unexpected HALT: {out!r}";
}

# ---------------------------------------------------------------------------
# Test 4: Fraud on the FIRST node -- disengage fires immediately, nothing
# else prints.
# ---------------------------------------------------------------------------
test "fraud on first node halts before any other order prints" {
    root ++> Order(label="FIRST", amount=99.99, valid=True, fraud=True)
        ++> Order(label="NEVER1", amount=1.00, valid=True)
        ++> Order(label="NEVER2", amount=2.00, valid=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert "[HALT] FIRST:" in out, f"FIRST should HALT, got: {out!r}";
    assert "NEVER1" not in out, f"NEVER1 visited after halt: {out!r}";
    assert "NEVER2" not in out, f"NEVER2 visited after halt: {out!r}";
    assert "[SKIP]" not in out, f"unexpected SKIP: {out!r}";
}

# ---------------------------------------------------------------------------
# Test 5: A fraud node placed AFTER several OKs -- OKs print, then HALT,
# remaining nodes never print.
# ---------------------------------------------------------------------------
test "fraud mid-chain: prior OKs print, post nodes are not visited" {
    root ++> Order(label="OK-A", amount=10.00, valid=True)
        ++> Order(label="OK-B", amount=20.00, valid=True)
        ++> Order(label="BAD", amount=30.00, valid=True, fraud=True)
        ++> Order(label="AFTER-1", amount=40.00, valid=True)
        ++> Order(label="AFTER-2", amount=50.00, valid=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
