    assert "[OK]   OK-A:" in out, f"OK-A missing: {out!r}";
    assert "[OK]   OK-B:" in out, f"OK-B missing: {out!r}";
    assert "[HALT] BAD:" in out, f"BAD should HALT, got: {out!r}";
    assert "AFTER-1" not in out, f"AFTER-1 visited after halt: {out!r}";
    assert "AFTER-2" not in out, f"AFTER-2 visited after halt: {out!r}";
    # BAD should not also be reported as OK.
    assert "[OK]   BAD" not in out, f"BAD printed as OK: {out!r}";
