"""Tests for OrderAuditor: skip invalid (continue), halt on fraud (disengage)."""

import io;
import from contextlib { redirect_stdout }

def _run_auditor_on(r) -> str {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        _ = r spawn OrderAuditor();
    }
    return buf.getvalue();
}

test "mixed orders: skips invalid, halts on fraud, never visits later orders" {
    r = root ++> Order(amount=100.0, valid=True)
        ++> Order(amount=250.0, valid=False)
        ++> Order(amount=75.5, valid=True)
        ++> Order(amount=900.0, valid=True, fraud=True)
        ++> Order(amount=42.0, valid=True);

    out = _run_auditor_on(r);

    # Header from start ability
    assert "Starting order audit" in out, f"missing header: {out!r}";

    # First valid order processed normally
    assert "OK    amount=100.0" in out, f"missing OK 100.0: {out!r}";

    # Invalid order is skipped with the SKIP label and continuation note
    assert "SKIP" in out, f"missing SKIP marker: {out!r}";
    assert "amount=250.0" in out, f"missing amount 250.0: {out!r}";
    assert "continuing" in out, f"missing continuing note: {out!r}";

    # Walk continues past the skipped order to the next valid one
    assert "amount=75.5" in out, f"walk did not continue past skip: {out!r}";

    # Fraud order triggers FRAUD label and halts
    assert "FRAUD" in out, f"missing FRAUD marker: {out!r}";
    assert "amount=900.0" in out, f"missing fraud amount: {out!r}";
    assert "halting audit" in out, f"missing halting note: {out!r}";

    # After fraud disengage, the trailing order must NEVER appear
    assert "amount=42.0" not in out, f"auditor did not stop on fraud: {out!r}";

    # And we should never reach the empty-report branch
    assert "No orders to audit" not in out, f"unexpected empty branch: {out!r}";
}

test "all valid orders: every order prints OK in chain order" {
    r = root ++> Order(amount=10.0, valid=True)
        ++> Order(amount=20.0, valid=True)
        ++> Order(amount=30.0, valid=True);

    out = _run_auditor_on(r);

    assert "OK    amount=10.0" in out, f"missing 10.0: {out!r}";
    assert "OK    amount=20.0" in out, f"missing 20.0: {out!r}";
    assert "OK    amount=30.0" in out, f"missing 30.0: {out!r}";

    # Order of appearance matches traversal order
    i10 = out.index("amount=10.0");
    i20 = out.index("amount=20.0");
    i30 = out.index("amount=30.0");
    assert i10 < i20 < i30, f"out of order: {out!r}";

    # No fraud / skip messages on a clean chain
    assert "FRAUD" not in out, f"unexpected FRAUD: {out!r}";
    assert "SKIP" not in out, f"unexpected SKIP: {out!r}";
    assert "halting audit" not in out, f"unexpected halt: {out!r}";
}

test "all invalid orders: every SKIP appears, no OK, no halt" {
    r = root ++> Order(amount=5.0, valid=False)
        ++> Order(amount=6.0, valid=False)
        ++> Order(amount=7.0, valid=False);

    out = _run_auditor_on(r);

    # Header still printed
    assert "Starting order audit" in out, f"missing header: {out!r}";

    # Each invalid order should be SKIP'd with the continuing note
    assert "amount=5.0" in out and "continuing" in out, f"missing 5.0 skip: {out!r}";
    assert "amount=6.0" in out, f"missing 6.0: {out!r}";
    assert "amount=7.0" in out, f"missing 7.0: {out!r}";

    # No valid orders -> no OK labels, no fraud
    assert "OK    amount" not in out, f"unexpected OK label: {out!r}";
    assert "FRAUD" not in out, f"unexpected FRAUD: {out!r}";
    assert "halting audit" not in out, f"unexpected halt: {out!r}";
}

test "fraud first: halts immediately, nothing else audited" {
    r = root ++> Order(amount=999.0, valid=True, fraud=True)
        ++> Order(amount=1.0, valid=True)
        ++> Order(amount=2.0, valid=True);

    out = _run_auditor_on(r);

    assert "Starting order audit" in out, f"missing header: {out!r}";
    assert "FRAUD" in out and "amount=999.0" in out, f"missing fraud on first: {out!r}";
    assert "halting audit" in out, f"missing halt note: {out!r}";

    # Nothing past the first fraud should ever be visited
    assert "amount=1.0" not in out, f"visited past fraud: {out!r}";
    assert "amount=2.0" not in out, f"visited past fraud: {out!r}";
    assert "OK" not in out, f"unexpected OK before fraud halt: {out!r}";
}

test "empty graph: start ability reports no orders and disengages" {
    out = _run_auditor_on(root);

    assert "Starting order audit" in out, f"missing header: {out!r}";
    assert "No orders to audit" in out, f"missing empty branch: {out!r}";
    # And naturally no per-order messages
    assert "FRAUD" not in out and "SKIP" not in out and "OK" not in out, f"unexpected order messages: {out!r}";
}

