"""Test annex for OrderAuditor — two flavors of early return side by side."""

import io;
import from contextlib { redirect_stdout }


def run_auditor_on(chain_tail_nodes: list) {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        # Build the chain on the fly: root -> first -> second -> ...
        root ++> chain_tail_nodes[0];
        for i in range(len(chain_tail_nodes) - 1) {
            chain_tail_nodes[i] ++> chain_tail_nodes[i + 1];
        }
        auditor = OrderAuditor();
        root spawn auditor;
    }
    return (buf.getvalue(), auditor);
}


test "skip continues past invalid order to later valid ones" {
    o1 = Order(order_id="S-1", amount=10.0, valid=True);
    o2 = Order(order_id="S-2", amount=20.0, valid=False);   # skip this one
    o3 = Order(order_id="S-3", amount=30.0, valid=True);    # must still be audited
    o4 = Order(order_id="S-4", amount=40.0, valid=True);

    (out, auditor) = run_auditor_on([o1, o2, o3, o4]);

    # Skip did NOT halt the walk.
    assert auditor.halted == False, f"skip should not halt; got halted={auditor.halted}";
    assert auditor.audited_count == 3, f"expected 3 audits, got {auditor.audited_count}";
    assert auditor.skipped_count == 1, f"expected 1 skip, got {auditor.skipped_count}";

    # Per-order action lines.
    assert "[AUDIT] order=S-1 amount=10.0" in out, f"missing S-1 audit line: {out}";
    assert "[SKIP]  order=S-2 amount=20.0 invalid" in out, f"missing S-2 skip line: {out}";
    assert "[AUDIT] order=S-3 amount=30.0" in out, f"missing S-3 audit line (proves continuation): {out}";
    assert "[AUDIT] order=S-4 amount=40.0" in out, f"missing S-4 audit line (proves continuation): {out}";

    # No halt marker should appear on a pure-skip chain.
    assert "[HALT]" not in out, f"unexpected halt on skip-only chain: {out}";
}

test "fraud disengage halts the whole walk immediately" {
    o1 = Order(order_id="F-1", amount=10.0, valid=True);
    o2 = Order(order_id="F-2", amount=20.0, valid=True);
    o3 = Order(order_id="F-3", amount=9999.99, valid=True, fraud_flag=True);  # HALT
    o4 = Order(order_id="F-4", amount=40.0, valid=True);   # must NOT be reached
    o5 = Order(order_id="F-5", amount=50.0, valid=True);   # must NOT be reached

    (out, auditor) = run_auditor_on([o1, o2, o3, o4, o5]);

    # Disengage fired.
    assert auditor.halted == True, f"fraud should set halted=True; got {auditor.halted}";
    assert "[HALT]  order=F-3 amount=9999.99 fraud flagged" in out, f"missing halt line: {out}";

    # Earlier valid orders still got audited before the halt.
    assert auditor.audited_count == 2, f"expected 2 audits before halt, got {auditor.audited_count}";

    # Nothing after the fraud order should be printed or counted.
    assert "order=F-4" not in out, f"F-4 should be unreachable post-disengage: {out}";
    assert "order=F-5" not in out, f"F-5 should be unreachable post-disengage: {out}";
}

test "skip then later fraud: skipped one is skipped, fraud one halts" {
    # Mix: valid, invalid (skip), valid, fraud (halt), valid (unreachable).
    o1 = Order(order_id="M-1", amount=11.0, valid=True);
    o2 = Order(order_id="M-2", amount=22.0, valid=False);                   # SKIP
    o3 = Order(order_id="M-3", amount=33.0, valid=True);
    o4 = Order(order_id="M-4", amount=4444.0, valid=True, fraud_flag=True);  # HALT
    o5 = Order(order_id="M-5", amount=55.0, valid=True);                     # unreachable

    (out, auditor) = run_auditor_on([o1, o2, o3, o4, o5]);

    assert auditor.halted == True, f"final halted flag should be True; got {auditor.halted}";
    assert auditor.audited_count == 2, f"expected 2 audits (M-1, M-3), got {auditor.audited_count}";
    assert auditor.skipped_count == 1, f"expected 1 skip (M-2), got {auditor.skipped_count}";

    # Ordering: skip line must precede audit/halt lines for downstream orders.
    assert "[SKIP]  order=M-2 amount=22.0 invalid" in out, f"missing M-2 skip: {out}";
    assert "[AUDIT] order=M-1 amount=11.0" in out, f"missing M-1 audit: {out}";
    assert "[AUDIT] order=M-3 amount=33.0" in out, f"missing M-3 audit (proves skip continued): {out}";
    assert "[HALT]  order=M-4 amount=4444.0 fraud flagged" in out, f"missing M-4 halt: {out}";
    assert "order=M-5" not in out, f"M-5 must be unreachable after disengage: {out}";
}

test "all-invalid chain completes with every order skipped and no halt" {
    o1 = Order(order_id="I-1", amount=1.0, valid=False);
    o2 = Order(order_id="I-2", amount=2.0, valid=False);
