    assert "[SKIP]  order=I-2 amount=2.0 invalid" in out, f"missing I-2 skip: {out}";
    assert "[SKIP]  order=I-3 amount=3.0 invalid" in out, f"missing I-3 skip: {out}";
    assert "[HALT]" not in out, f"unexpected halt on all-skip chain: {out}";
}

test "first node itself is fraud: zero audits, immediate halt" {
    o1 = Order(order_id="Z-1", amount=7.0, valid=True, fraud_flag=True);  # HALT immediately
    o2 = Order(order_id="Z-2", amount=8.0, valid=True);
