"""Test annex for Order auditor program.

Verifies:
  * `continue`-style skip: invalid orders are skipped, walk proceeds to later orders.
  * `disengage`-style halt: fraud-flagged orders terminate the walk immediately.
  * Counter and halted-order bookkeeping on the walker.
"""

import io;
import from contextlib { redirect_stdout }

test "healthy chain audits every order and reports no halt" {
    root ++> Order(order_id="H-001", amount=10.00, valid=True)
        ++> Order(order_id="H-002", amount=20.00, valid=True)
        ++> Order(order_id="H-003", amount=30.00, valid=True);

    auditor = OrderAuditor();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn auditor;
    }
    out = buf.getvalue();

    assert res.audited_count == 3, f"expected 3 audits, got {res.audited_count}";
    assert res.halted_on_fraud is False, f"halted_on_fraud should be False; got {res.halted_on_fraud}";
    assert res.halted_order_id == "", f"halted_order_id should be empty; got {res.halted_order_id}";
    assert "[AUDIT] H-001" in out, f"H-001 must be audited: {out}";
    assert "[AUDIT] H-002" in out, f"H-002 must be audited: {out}";
    assert "[AUDIT] H-003" in out, f"H-003 must be audited: {out}";
    assert "[SKIP]" not in out, f"no skips expected on a healthy chain: {out}";
    assert "[HALT-FRAUD]" not in out, f"no fraud halt expected on a healthy chain: {out}";
}

test "skip keeps walking past invalid orders" {
    root ++> Order(order_id="S-001", amount=100.00, valid=True)
        ++> Order(order_id="S-002", amount=0.00, valid=False)
        ++> Order(order_id="S-003", amount=250.00, valid=True);

    auditor = OrderAuditor();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn auditor;
    }
    out = buf.getvalue();

    assert res.audited_count == 2, f"expected 2 audits (S-001, S-003); got {res.audited_count}";
    assert res.halted_on_fraud is False, f"halted_on_fraud should be False; got {res.halted_on_fraud}";
    assert "[AUDIT] S-001" in out, f"S-001 must be audited: {out}";
    assert "[SKIP] S-002" in out, f"S-002 must be skipped: {out}";
    assert "[AUDIT] S-003" in out, f"S-003 must be audited after skip: {out}";
    assert "[HALT-FRAUD]" not in out, f"no fraud halt expected here: {out}";
}

test "fraud disengages immediately and halts the walk" {
    root ++> Order(order_id="F-001", amount=50.00, valid=True)
        ++> Order(order_id="F-002", amount=9999.99, valid=True, fraud_flagged=True)
        ++> Order(order_id="F-003", amount=75.00, valid=True)
        ++> Order(order_id="F-004", amount=80.00, valid=True);

    auditor = OrderAuditor();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn auditor;
    }
    out = buf.getvalue();

    assert res.halted_on_fraud is True, f"halted_on_fraud should be True; got {res.halted_on_fraud}";
    assert res.halted_order_id == "F-002", f"halted_order_id should be F-002; got {res.halted_order_id}";
    assert res.audited_count == 2, f"expected 2 audits (F-001, F-002); got {res.audited_count}";
    assert "[AUDIT] F-001" in out, f"F-001 must be audited before halt: {out}";
    assert "[HALT-FRAUD] F-002" in out, f"F-002 must trigger fraud halt: {out}";
    assert "[AUDIT] F-003" not in out, f"F-003 must NOT be audited after disengage: {out}";
    assert "[AUDIT] F-004" not in out, f"F-004 must NOT be audited after disengage: {out}";
}

test "fraud as the very first order still records the halt" {
    root ++> Order(order_id="Z-000", amount=1.00, valid=True, fraud_flagged=True)
        ++> Order(order_id="Z-001", amount=2.00, valid=True);

    auditor = OrderAuditor();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn auditor;
    }
    out = buf.getvalue();

    assert res.halted_on_fraud is True, f"halted_on_fraud should be True; got {res.halted_on_fraud}";
    assert res.halted_order_id == "Z-000", f"halted_order_id should be Z-000; got {res.halted_order_id}";
    assert res.audited_count == 1, f"expected exactly 1 audit (Z-000); got {res.audited_count}";
    assert "[HALT-FRAUD] Z-000" in out, f"Z-000 must trigger fraud halt: {out}";
    assert "[AUDIT] Z-001" not in out, f"Z-001 must NOT be audited: {out}";
}

