"""Tests for the restaurant recommender's Finder walker with a spawn-time minimum rating."""

node Restaurant {
    has name: str = "";
    has cuisine: str = "";
    has rating: float = 0.0;
}

walker Finder {
    has min_rating: float = 0.0;
    has found: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can hunt with Restaurant entry {
        if here.rating >= self.min_rating {
            self.found.append(f"{here.name} ({here.cuisine}, {here.rating})");
        }
        visit [-->];
    }
}

import io;
import from contextlib { redirect_stdout }

test "date night at 4.5+ only top restaurants" {
    root ++> Restaurant(name="La Trattoria", cuisine="Italian", rating=4.7)
        ++> Restaurant(name="Sakura", cuisine="Japanese", rating=4.6)
        ++> Restaurant(name="Burger Barn", cuisine="American", rating=3.8)
        ++> Restaurant(name="Spice Route", cuisine="Indian", rating=4.2)
        ++> Restaurant(name="Cafe Olive", cuisine="Mediterranean", rating=3.6);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        date_night = Finder(min_rating=4.5);
        res = root spawn date_night;
    }
    out = buf.getvalue();

    # Only the two 4.5+ restaurants should be reported, in walk order.
    assert len(res.found) == 2, f"expected 2 date-night picks, got {len(res.found)}: {res.found}";
    assert "La Trattoria (Italian, 4.7)" in res.found, f"missing La Trattoria in {res.found}";
    assert "Sakura (Japanese, 4.6)" in res.found, f"missing Sakura in {res.found}";

    # Below-threshold restaurants must not appear.
    assert not any("Burger Barn" in p for p in res.found), f"Burger Barn leaked: {res.found}";
    assert not any("Spice Route" in p for p in res.found), f"Spice Route leaked: {res.found}";
    assert not any("Cafe Olive" in p for p in res.found), f"Cafe Olive leaked: {res.found}";

    # The walker's own min_rating should still be what we set it to.
    assert res.min_rating == 4.5, f"min_rating mutated to {res.min_rating}";

    # Stdout should announce the threshold and list the picks.
    assert "Date night picks (>= 4.5)" in out, f"missing header: {out}";
    assert "La Trattoria (Italian, 4.7)" in out, f"missing printed pick: {out}";
    assert "Sakura (Japanese, 4.6)" in out, f"missing printed pick: {out}";
}

