test "threshold parameter controls who qualifies" {
    # Same graph, two spawns with different thresholds => strictly nested result sets.
    root ++> Restaurant(name="A", cuisine="X", rating=4.9)
        ++> Restaurant(name="B", cuisine="X", rating=4.5)
        ++> Restaurant(name="C", cuisine="X", rating=4.0)
        ++> Restaurant(name="D", cuisine="X", rating=3.5)
        ++> Restaurant(name="E", cuisine="X", rating=3.0);

    strict = Finder(min_rating=4.5);
    sres = root spawn strict;
    assert len(sres.found) == 2, f"strict pass expected 2, got {len(sres.found)}: {sres.found}";
    assert "A (X, 4.9)" in sres.found;
    assert "B (X, 4.5)" in sres.found;
    assert not any("C" in p or "D" in p or "E" in p for p in sres.found), f"strict leaked: {sres.found}";

    lenient = Finder(min_rating=3.5);
    lres = root spawn lenient;
    assert len(lres.found) == 4, f"lenient pass expected 4, got {len(lres.found)}: {lres.found}";
    assert "A (X, 4.9)" in lres.found;
    assert "B (X, 4.5)" in lres.found;
    assert "C (X, 4.0)" in lres.found;
    assert "D (X, 3.5)" in lres.found;
    assert not any("E" in p for p in lres.found), f"lenient leaked E: {lres.found}";

    # The lenient set must strictly contain the strict set.
    assert set(sres.found).issubset(set(lres.found)), f"strict {sres.found} not subset of lenient {lres.found}";
}

test "boundary rating is inclusive, below-threshold is excluded" {
    # The filter uses >=, so a restaurant exactly at the threshold should match,
    # and one strictly below it should not.
    root ++> Restaurant(name="Exact", cuisine="X", rating=4.0)
        ++> Restaurant(name="Below", cuisine="X", rating=3.99)
        ++> Restaurant(name="Above", cuisine="X", rating=4.01);

    finder = Finder(min_rating=4.0);
    res = root spawn finder;

    assert "Exact (X, 4.0)" in res.found, f"boundary restaurant excluded: {res.found}";
    assert not any("Below" in p for p in res.found), f"below-threshold leaked: {res.found}";
    assert "Above (X, 4.01)" in res.found, f"above-threshold missing: {res.found}";
    assert len(res.found) == 2, f"expected 2 matches at boundary, got {len(res.found)}: {res.found}";
}

