"""Tests for main.jac: mutual buddy edges, two greeters reach each other,
and the `met` list prevents infinite bouncing."""

import io;
import from contextlib { redirect_stdout }


test "single buddy edge creates links in both directions" {
    root ++> House(owner="Ana");
    root ++> House(owner="Leo");
    ana = [root -->][0];
    leo = [root -->][1];

    ana <+: Buddy(since=2023) :+> leo;

    # Bidirectional: forward traversal from Ana reaches Leo AND from Leo reaches Ana.
    assert len([ana -->]) == 1, f"Ana should have 1 outgoing Buddy, got {len([ana -->])}";
    assert len([leo -->]) == 1, f"Leo should have 1 outgoing Buddy, got {len([leo -->])}";
    assert leo in [ana -->], "Ana must reach Leo via forward traversal";
    assert ana in [leo -->], "Leo must reach Ana via forward traversal (bidirectional)";
}


test "greeter spawned at Ana reaches Leo via forward traversal only" {
    root ++> House(owner="Ana");
    root ++> House(owner="Leo");
    ana = [root -->][0];
    leo = [root -->][1];
    ana <+: Buddy() :+> leo;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        ana spawn Greeter(who="Ana");
    }
    out = buf.getvalue();

    assert "Ana waves hello to Leo's house" in out, f"Ana should greet Leo, got: {out}";
}


test "greeter spawned at Leo reaches Ana via forward traversal only" {
    root ++> House(owner="Ana");
    root ++> House(owner="Leo");
    ana = [root -->][0];
    leo = [root -->][1];
    ana <+: Buddy() :+> leo;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        leo spawn Greeter(who="Leo");
    }
    out = buf.getvalue();

    assert "Leo waves hello to Ana's house" in out, f"Leo should greet Ana, got: {out}";
}


test "both greeters see each other, met list stops infinite bouncing" {
    root ++> House(owner="Ana");
    root ++> House(owner="Leo");
    ana = [root -->][0];
    leo = [root -->][1];
    ana <+: Buddy() :+> leo;

    ana_buf = io.StringIO();
    with redirect_stdout(ana_buf) {
        ana_res = ana spawn Greeter(who="Ana");
    }
    leo_buf = io.StringIO();
    with redirect_stdout(leo_buf) {
        leo_res = leo spawn Greeter(who="Leo");
    }

    # Each walker reports exactly the OTHER house, not itself.
    assert ana_res.reports == ["Leo"], f"Ana's reports should be ['Leo'], got {ana_res.reports}";
    assert leo_res.reports == ["Ana"], f"Leo's reports should be ['Ana'], got {leo_res.reports}";

    # Without the `met` guard, each side could bounce across the bidirectional
    # edge forever. Each greeter must terminate with exactly one new house met.
    assert len(ana_res.met) == 1, f"Ana met should have 1 entry, got {ana_res.met}";
    assert len(leo_res.met) == 1, f"Leo met should have 1 entry, got {leo_res.met}";

    # The wave should fire exactly once per direction -- no echo loop.
    assert ana_buf.getvalue().count("waves hello to") == 1, f"Ana's wave should print once, got: {ana_buf.getvalue()}";
    assert leo_buf.getvalue().count("waves hello to") == 1, f"Leo's wave should print once, got: {leo_buf.getvalue()}";
}


test "greeter does not revisit its own starting house" {
    root ++> House(owner="Solo");
    solo = [root -->][0];

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = solo spawn Greeter(who="Solo");
    }

    # No outgoing edges means nothing to greet; the walker must not
    # "greet" its own starting house (owner already in `met`).
    assert res.reports == [], f"Solo with no neighbors should report nothing, got {res.reports}";
    assert buf.getvalue() == "", f"No output expected, got: {buf.getvalue()}";
}

