"""Tests for mutual friendships: bidirectional Buddy edges and non-infinite Greeter traversal."""

import io;
import from contextlib { redirect_stdout }

test "each house has the expected number of buddies via direct edges" {
    alice = House(name="Alice's House", occupant="Alice");
    bob = House(name="Bob's House", occupant="Bob");
    carol = House(name="Carol's House", occupant="Carol");

    alice +>:Buddy:+> bob;
    bob +>:Buddy:+> alice;
    bob +>:Buddy:+> carol;
    carol +>:Buddy:+> bob;
    alice +>:Buddy:+> carol;
    carol +>:Buddy:+> alice;

    root ++> alice;

    # Each house is the explicit source of its own Buddy edges; only OUTGOING
    # edges count here, mirroring how the program builds them (one statement
    # per direction).
    alice_out = [alice ->:Buddy:->];
    bob_out = [bob ->:Buddy:->];
    carol_out = [carol ->:Buddy:->];

    assert len(alice_out) == 2, f"alice should have 2 outgoing buddies, got {len(alice_out)}";
    assert len(bob_out) == 2, f"bob should have 2 outgoing buddies, got {len(bob_out)}";
    assert len(carol_out) == 2, f"carol should have 2 outgoing buddies, got {len(carol_out)}";

    # Bidirectional proof: from each side, the other side is reachable by
    # following outgoing Buddy edges.
    bobs_from_alice = [alice ->:Buddy:->];
    alices_from_bob = [bob ->:Buddy:->];
    carols_from_bob = [bob ->:Buddy:->];
    bobs_from_carol = [carol ->:Buddy:->];
    alices_from_carol = [carol ->:Buddy:->];
    carols_from_alice = [alice ->:Buddy:->];

    assert bob in bobs_from_alice, "alice should reach bob via Buddy edge";
    assert alice in alices_from_bob, "bob should reach alice via Buddy edge";
    assert carol in carols_from_bob, "bob should reach carol via Buddy edge";
    assert bob in bobs_from_carol, "carol should reach bob via Buddy edge";
    assert alice in alices_from_carol, "carol should reach alice via Buddy edge";
    assert carol in carols_from_alice, "alice should reach carol via Buddy edge";
}

test "greeter from alice reaches bob with forward-only traversal and terminates" {
    alice = House(name="Alice's House", occupant="Alice");
    bob = House(name="Bob's House", occupant="Bob");
    carol = House(name="Carol's House", occupant="Carol");

    alice +>:Buddy:+> bob;
    bob +>:Buddy:+> alice;
    bob +>:Buddy:+> carol;
    carol +>:Buddy:+> bob;
    alice +>:Buddy:+> carol;
    carol +>:Buddy:+> alice;

    root ++> alice;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        # Spawn from Root (same as the program's "From Alice's House" demo).
        # Greeter's Root entry will visit [-->] which is alice, then continue
        # forward only.
        res = root spawn Greeter();
    }
    out = buf.getvalue();

    # Alice must have been visited (she is root's direct child).
    assert "Alice's House" in out, f"alice should be greeted, got: {out}";

    # The walker visited some houses and then STOPPED — it must not loop
    # forever. With visited-tracking on forward traversal only over a 3-node
    # graph (alice <-> bob <-> carol, alice <-> carol), at most 3 houses get
    # greeted.
    assert len(res.seen) <= 3, f"greeter should visit at most 3 houses, saw {res.seen}";

    # Bob must be reachable from alice via forward Buddy traversal.
    bob_names = [b ->:Buddy:->];
    assert bob in bob_names, "alice's outgoing Buddy edges should include bob";
    res_b = bob spawn Greeter();
    assert "Bob's House" in res_b.seen, f"bob should appear when greeted from bob, saw {res_b.seen}";
}

test "greeter spawned directly at bob sees bob and terminates" {
    alice = House(name="Alice's House", occupant="Alice");
    bob = House(name="Bob's House", occupant="Bob");
    carol = House(name="Carol's House", occupant="Carol");

    alice +>:Buddy:+> bob;
    bob +>:Buddy:+> alice;
    bob +>:Buddy:+> carol;
    carol +>:Buddy:+> bob;
    alice +>:Buddy:+> carol;
    carol +>:Buddy:+> alice;

    root ++> alice;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = bob spawn Greeter();
    }
    out = buf.getvalue();

    assert "Bob's House" in out, f"bob should be greeted when spawning on bob, got: {out}";
    assert len(res.seen) <= 3, f"greeter from bob should visit at most 3 houses, saw {res.seen}";
    # Each name in seen appears at most once — the visited set prevents loops.
    assert len(res.seen) == len(set(res.seen)), f"greeter should never revisit a house, saw {res.seen}";
}

test "greeter cannot bounce back and forth between two mutually-linked houses" {
    # Minimal case that would loop forever if the visited check were absent:
    # two houses with Buddy edges in both directions, only forward traversal.
    a = House(name="House A", occupant="A");
    b = House(name="House B", occupant="B");

    a +>:Buddy:+> b;
    b +>:Buddy:+> a;

    root ++> a;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Greeter();
    }

    # With the `if nxt.name not in self.seen` guard, the walker visits A,
    # then follows to B, then stops because B's only Buddy neighbor (A) is
    # already in `seen`. Without that guard it would oscillate forever.
    assert len(res.seen) == 2, f"expected exactly 2 visits, got {res.seen}";
    assert "House A" in res.seen and "House B" in res.seen, f"both houses should be seen, got {res.seen}";
    # B's only forward Buddy neighbor is A, which is already visited —
    # confirm the loop is genuinely terminated, not just lucky.
    a_neighbors = [a ->:Buddy:->];
    assert len(a_neighbors) == 1 and a_neighbors[0].name == "House B", "a should have exactly one buddy: b";
}

