"""Regression tests for bug-tracker connect-and-grab behavior."""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
# Test 1: Connect-and-grab in a single expression.
#
# `fresh :=` inside the `++>` chain MUST yield the actual node returned by the
# connection, so we can read `fresh.title` / `fresh.priority` WITHOUT doing a
# follow-up lookup query.
# ---------------------------------------------------------------------------
test "fresh capture equals graph node and exposes title+priority" {
    root ++> Project(name="Aurora")
        ++> (fresh := Ticket(title="Login button unresponsive", priority="high"))
        ++> (fresh := Ticket(title="Typo on landing page", priority="low"))
        ++> (fresh := Ticket(title="Crash on save", priority="critical"));

    # The "filed" tickets are reachable directly off root via two hops.
    project = [root -->][?:Project][0];
    assert project.name == "Aurora", f"expected project Aurora, got {project.name}";

    # All tickets reached off the project.
    tickets = [project -->][?:Ticket];
    assert len(tickets) == 3, f"expected 3 tickets, got {len(tickets)}";

    titles = sorted([t.title for t in tickets]);
    assert titles == [
        "Crash on save",
        "Login button unresponsive",
        "Typo on landing page",
    ], f"unexpected ticket titles: {titles}";

    priorities = sorted([t.priority for t in tickets]);
    assert priorities == ["critical", "high", "low"], f"unexpected priorities: {priorities}";

    # No separate lookup: `fresh` already refers to the LAST node assigned
    # in the chain (the "Crash on save" / critical ticket).
    assert fresh.title == "Crash on save", f"fresh.title should be last assigned, got {fresh.title}";
    assert fresh.priority == "critical", f"fresh.priority should be critical, got {fresh.priority}";

    # That same node must be reachable in the graph (identity, not just equality).
    assert fresh in tickets, "captured fresh must be one of the graph-resident tickets";

    # Direct membership at root level: `root..->fresh` via the same node identity.
    reachable = [root --> -->];
    assert fresh in reachable, "fresh must be reachable from root via two hops";
}

