    assert p_idx < first_ticket_idx, "project line must precede ticket lines";

    # The "connect and print" promise: no follow-up query, just the captured
    # node's title and priority.
    assert "Filed tickets (captured at connect time):" in out, f"missing banner: {out!r}";
    assert "high     -> Login button unresponsive" in out, f"missing captured-title line: {out!r}";
    assert "priority -> critical" in out, f"missing captured-priority line: {out!r}";
}

# ---------------------------------------------------------------------------
# Test 4: Multiple sibling projects, each carrying exactly one fresh ticket.
# Confirms the connect-and-grab works per-project without cross-talk.
# ---------------------------------------------------------------------------
test "fresh is scoped per-project when several projects are connected" {
    p1 = Project(name="Alpha");
    p2 = Project(name="Beta");
    root ++> p1 ++> (fresh_alpha := Ticket(title="alpha bug", priority="high"));
    root ++> p2 ++> (fresh_beta := Ticket(title="beta bug", priority="low"));

    projects = [root -->][?:Project];
    assert len(projects) == 2, f"expected 2 projects, got {len(projects)}";

    for p in projects {
        tickets = [p -->][?:Ticket];
        assert len(tickets) == 1, f"project {p.name} should have 1 ticket, has {len(tickets)}";
    }

    assert fresh_alpha.title == "alpha bug", f"fresh_alpha.title: {fresh_alpha.title}";
    assert fresh_alpha.priority == "high", f"fresh_alpha.priority: {fresh_alpha.priority}";
    assert fresh_beta.title == "beta bug", f"fresh_beta.title: {fresh_beta.title}";
    assert fresh_beta.priority == "low", f"fresh_beta.priority: {fresh_beta.priority}";

    # Identity: each captured fresh must be the ticket under its own project.
    alpha_tickets = [[p -->][?:Ticket][0] for p in projects if p.name == "Alpha"];
    beta_tickets = [[p -->][?:Ticket][0] for p in projects if p.name == "Beta"];
    assert len(alpha_tickets) == 1 and len(beta_tickets) == 1, "could not locate alpha/beta tickets";
    assert fresh_alpha == alpha_tickets[0], "fresh_alpha must equal its graph node";
    assert fresh_beta == beta_tickets[0], "fresh_beta must equal its graph node";
}

"""Tests for bug tracker: connect-and-grab pattern with immediate use."""

import io;
import from contextlib { redirect_stdout }

test "connect and grab returns the fresh ticket node" {
    # Walrus inside ++> binds the newly created ticket; t is the actual
    # node returned by the connection, not a lookup.
    root ++> (t := Ticket(title="Crash on save", priority=1));
    assert t is not None, "walrus did not capture the fresh node";
    assert isinstance(t, Ticket), f"expected Ticket, got {type(t)}";
    assert t.title == "Crash on save", f"title not bound: {t.title}";
    assert t.priority == 1, f"priority not bound: {t.priority}";
    # The captured node is the same one linked off root (no copy).
    children = [root-->];
    assert len(children) == 1, f"expected 1 child, got {len(children)}";
    assert children[0] == t, "captured node is not the linked node";
}

test "captured reference usable without re-querying the graph" {
    # Build several tickets via connect-and-grab, then read fields directly
    # from the captured locals — no traversal/lookup involved.
    root ++> (t1 := Ticket(title="Login broken", priority=1));
    root ++> (t2 := Ticket(title="404 on /reports", priority=2));
    root ++> (t3 := Ticket(title="Typo in footer", priority=3, available=False));

    assert t1.title == "Login broken" and t1.priority == 1, "t1 fields wrong";
    assert t2.title == "404 on /reports" and t2.priority == 2, "t2 fields wrong";
    assert t3.title == "Typo in footer" and t3.priority == 3, "t3 fields wrong";
    assert t3.available == False, f"t3.available should be False, got {t3.available}";

    # And they really are the nodes hanging off root.
    kids = [root-->];
    assert len(kids) == 3, f"expected 3 children, got {len(kids)}";
    assert t1 in kids and t2 in kids and t3 in kids, "captured nodes not linked";
}

test "triage walker prints each filed ticket with status and priority" {
    root ++> (t1 := Ticket(title="Login broken", priority=1));
    root ++> (t2 := Ticket(title="404 on /reports", priority=2));
    root ++> (t3 := Ticket(title="Typo in footer", priority=3, available=False));

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Triage(project_name="WebApp");
    }
    out = buf.getvalue();

    # Header line first, then one line per ticket in visit order.
    assert "Filing tickets on project: WebApp" in out, f"missing header: {out}";
    assert "[OPEN] Login broken (priority 1)" in out, f"missing t1 line: {out}";
    assert "[OPEN] 404 on /reports (priority 2)" in out, f"missing t2 line: {out}";
    assert "[CLOSED] Typo in footer (priority 3)" in out, f"missing t3 closed line: {out}";
}

test "triage status reflects available flag per ticket" {
    # available=True -> OPEN; available=False -> CLOSED. Same priority so
    # the only thing that can flip the status is the availability flag.
    root ++> (a := Ticket(title="open-one", priority=5, available=True));
    root ++> (c := Ticket(title="closed-one", priority=5, available=False));

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Triage(project_name="Defaults");
    }
    out = buf.getvalue();

    assert f"[OPEN] {a.title} (priority {a.priority})" in out, f"OPEN missing: {out}";
    assert f"[CLOSED] {c.title} (priority {c.priority})" in out, f"CLOSED missing: {out}";
    # Sanity: the CLOSED line should not be mis-tagged as OPEN.
    assert f"[OPEN] {c.title}" not in out, f"closed ticket mis-printed: {out}";
}

test "triage defaults and visit order across multiple spawns" {
    # project_name defaults to "Default" when omitted.
    root ++> (t1 := Ticket(title="alpha", priority=1));
    root ++> (t2 := Ticket(title="beta", priority=2));

