    # Both tickets must appear; visit order follows the linked order.
    p1 = out.find("alpha");
    p2 = out.find("beta");
    assert p1 != -1 and p2 != -1, f"both tickets should appear: {out}";
    assert p1 < p2, f"expected alpha before beta, got: {out}";
}

"""Tests for the Bug Tracker: connect-and-grab ticket node in one expression, then announce it."""

import io;
import from contextlib { redirect_stdout }

node Project {
    has name: str = "";
}

node Ticket {
    has title: str = "";
    has priority: str = "low";

    def announce -> str {
        return f"Ticket '{self.title}' filed with priority {self.priority}";
    }
}

edge HangsOff {}

walker Filer {
    has pending: list = [];

    can start with Root entry {
        root ++> (project := Project(name="Jaseci"));
        project ++> (t1 := Ticket(title="NullPointer in walker", priority="high"));
        project ++> (t2 := Ticket(title="Typo in docs", priority="low"));
        print(t1.announce());
        print(t2.announce());
        self.pending.append(t1.announce());
        self.pending.append(t2.announce());
        visit [-->];
    }

    can catalog with Project entry {
        visit [-->];
    }

    can file with Ticket entry {
        self.pending.append(here.announce());
        visit [-->];
    }
}

test "connect-and-grab returns the fresh ticket and announces it" {
    root ++> (project := Project(name="Jaseci"));
    project ++> (t := Ticket(title="NullPointer in walker", priority="high"));

    captured = io.StringIO();
    with redirect_stdout(captured) {
        print(t.announce());
    }
    out = captured.getvalue();

    assert isinstance(t, Ticket), f"connect-and-grab did not yield a Ticket, got {type(t)}";
    assert t.title == "NullPointer in walker", f"unexpected title: {t.title}";
    assert t.priority == "high", f"unexpected priority: {t.priority}";
    assert "Ticket 'NullPointer in walker' filed with priority high" in out, f"missing announce output: {out}";
}

test "ticket is actually attached to the project via HangsOff edge" {
    root ++> (project := Project(name="Jaseci"));
    project ++> (t1 := Ticket(title="NullPointer in walker", priority="high"));
    project ++> (t2 := Ticket(title="Typo in docs", priority="low"));

    hangs = [project ->:HangsOff:->];
    assert len(hangs) == 2, f"expected 2 HangsOff edges, got {len(hangs)}";

    titles = [t.title for t in hangs];
    assert "NullPointer in walker" in titles, f"missing high-priority ticket on project: {titles}";
    assert "Typo in docs" in titles, f"missing low-priority ticket on project: {titles}";

    root_children = [root -->];
    assert len(root_children) == 1, f"root should have exactly one direct child (the project), got {len(root_children)}";
}

test "Filer prints announcements and collects them in pending in order" {
    root ++> (project := Project(name="Jaseci"));
    project ++> (t1 := Ticket(title="NullPointer in walker", priority="high"));
    project ++> (t2 := Ticket(title="Typo in docs", priority="low"));

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Filer();
    }
    out = buf.getvalue();

    assert "Ticket 'NullPointer in walker' filed with priority high" in out, f"missing first announce in stdout: {out!r}";
    assert "Ticket 'Typo in docs' filed with priority low" in out, f"missing second announce in stdout: {out!r}";

    assert len(res.pending) == 4, f"Filer.pending should have 4 entries (2 prints + 2 file visits), got {len(res.pending)}";
    assert res.pending[0] == "Ticket 'NullPointer in walker' filed with priority high", f"unexpected pending[0]: {res.pending[0]!r}";
    assert res.pending[1] == "Ticket 'Typo in docs' filed with priority low", f"unexpected pending[1]: {res.pending[1]!r}";
    assert res.pending[2] == "Ticket 'NullPointer in walker' filed with priority high", f"unexpected pending[2]: {res.pending[2]!r}";
    assert res.pending[3] == "Ticket 'Typo in docs' filed with priority low", f"unexpected pending[3]: {res.pending[3]!r}";
}

test "Ticket.announce default priority is low when not overridden" {
    root ++> (project := Project(name="Jaseci"));
    project ++> (t := Ticket(title="Cosmetic glitch"));

    captured = io.StringIO();
    with redirect_stdout(captured) {
        print(t.announce());
    }
    out = captured.getvalue();

    assert t.priority == "low", f"default priority should be 'low', got {t.priority!r}";
    assert "Ticket 'Cosmetic glitch' filed with priority low" in out, f"default-priority announce missing: {out!r}";
}

"""Test annex for gallery security console.

Covers the promise:
  - Every visitor triggers a generic room log via log_entry.
  - A curator (and only a curator) additionally triggers record_inspection
    and increments the curator's inspections counter.
  - rooms_visited counts both rooms for either archetype; inspections
    counts only curator visits and only when the curator visits a Room.
"""

import io;
import from contextlib { redirect_stdout }

test "tourist visits two rooms: logs only, no inspections" {
    root ++> Room(name="Gallery A") ++> Room(name="Gallery B");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Tourist(name="Alex");
    }
    out = buf.getvalue();

    # Both rooms produced a generic [log] line for the tourist.
    assert "[log] Tourist entered Gallery A" in out, f"missing A log: {out}";
    assert "[log] Tourist entered Gallery B" in out, f"missing B log: {out}";
    # Tourist must NOT trigger the curator-specific inspection ability.
    assert "[inspection]" not in out, f"tourist should not inspect: {out}";

    # Tourist walked both rooms but accumulated zero inspections.
    assert res.rooms_visited == 2, f"tourist rooms_visited={res.rooms_visited}";
    assert res.inspections == 0, f"tourist inspections={res.inspections}";
}

test "curator visits two rooms: logs plus one inspection per room" {
    root ++> Room(name="Gallery A") ++> Room(name="Gallery B");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Curator(name="Dr. Bell");
    }
    out = buf.getvalue();

    # Generic log fires for the curator too (VisitorWalker base behavior).
    assert "[log] Curator entered Gallery A" in out, f"missing A log: {out}";
    assert "[log] Curator entered Gallery B" in out, f"missing B log: {out}";
    # And the curator-specific inspection fires on every room visited.
    assert "[inspection] Dr. Bell inspected Gallery A (#1)" in out, f"missing A insp: {out}";
    assert "[inspection] Dr. Bell inspected Gallery B (#2)" in out, f"missing B insp: {out}";

    assert res.rooms_visited == 2, f"curator rooms_visited={res.rooms_visited}";
    assert res.inspections == 2, f"curator inspections={res.inspections}";
}

test "inspections are recorded per room, not just once" {
    # Fresh chain: the curator must NOT carry state from any other test.
    root ++> Room(name="North Wing") ++> Room(name="South Wing")
        ++> Room(name="East Wing");

    res = root spawn Curator(name="Dr. Bell");

    assert res.rooms_visited == 3, f"curator rooms_visited={res.rooms_visited}";
    assert res.inspections == 3, f"curator inspections={res.inspections}";
}

test "tourist and curator on identical graph differ only in inspections" {
    root ++> Room(name="Gallery A") ++> Room(name="Gallery B");

    t = root spawn Tourist(name="Alex");

    # Build a second identical graph for the curator so the spawn is fresh.
    root2 = Root();
    root2 ++> Room(name="Gallery A") ++> Room(name="Gallery B");
    c = root2 spawn Curator(name="Dr. Bell");

    # Both archetypes visit every reachable room.
    assert t.rooms_visited == c.rooms_visited, (
        f"rooms_visited mismatch: tourist={t.rooms_visited} "
        f"curator={c.rooms_visited}"
    );
    # Only the curator accumulates inspections.
    assert t.inspections == 0, f"tourist inspections={t.inspections}";
    assert c.inspections == 2, f"curator inspections={c.inspections}";
}

test "disengages after last room: no extra log for empty successor list" {
    # Single-room chain so the walker's `visit [-->] else { disengage }`
    # branch fires after the only room. The curator still inspects once.
    root ++> Room(name="Solo Gallery");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Curator(name="Dr. Bell");
    }
    out = buf.getvalue();

    # Exactly one log and one inspection line — no spurious extras.
    assert out.count("[log]") == 1, f"expected 1 log, got: {out}";
    assert out.count("[inspection]") == 1, f"expected 1 inspection, got: {out}";

    assert res.rooms_visited == 1, f"rooms_visited={res.rooms_visited}";
    assert res.inspections == 1, f"inspections={res.inspections}";
}

