"""Tests for gallery security console."""

node Room {
    has name: str = "";
    has visitor_log: list[str] = [];
    has inspections: list[str] = [];
}

walker Tourist {
    can start with Root entry {
        visit [-->];
    }

    can enter with Room entry {
        here.visitor_log.append("Tourist");
        print(f"Tourist entered {here.name}");
        visit [-->];
    }
}

walker Curator {
    has curator_name: str = "";
