    can enter with Room entry {
        here.visitor_log.append(f"Curator:{self.curator_name}");
        here.inspections.append(self.curator_name);
        self.rooms_inspected += 1;
        print(f"Curator {self.curator_name} inspected {here.name}");
        visit [-->];
    }
}

