"""Test annex for the gallery security console.

These tests verify the program spec:
- Every visitor (tourist or curator) logs the general entry on a Room.
- A curator additionally triggers an official inspection on the Room,
  recording their badge as `last_inspector` and incrementing their
  `rooms_inspected` counter.
- A tourist does NOT trigger an inspection and does NOT have an
  inspection count field.

Each test builds its own isolated graph so the parallel workers are
independent. We spawn walkers on roots we construct and capture the
print output to assert against the structured log lines the walkers
emit."""

import io;
import from contextlib { redirect_stdout }

test "tourist logs general entry but never triggers inspection" {
    # Build a minimal graph: Root -> Room A -> Room B.
    room_a = Room(room_name="Gallery A");
    room_b = Room(room_name="Gallery B");
    root ++> room_a ++> room_b;

    # A tourist walks both rooms.
    tourist = Tourist(badge="T-7");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn tourist;
    }
    out = buf.getvalue();

    # The tourist must produce a general-log line for each room.
    assert "Tourist T-7 entered Gallery A (general log)" in out, (
        f"missing general log for room A; got: {out}"
    );
    assert "Tourist T-7 entered Gallery B (general log)" in out, (
        f"missing general log for room B; got: {out}"
    );

    # The tourist must NOT produce any official-inspection line.
    assert "Official inspection" not in out, (
        f"tourist triggered an official inspection line: {out}"
    );

    # Rooms must record the tourist as the general visitor.
    assert room_a.last_visitor == "T-7", (
        f"room A last_visitor: {room_a.last_visitor}"
    );
    assert room_b.last_visitor == "T-7", (
        f"room B last_visitor: {room_b.last_visitor}"
    );

    # Crucially, rooms must NOT have any inspector set by a tourist.
    assert room_a.last_inspector == "", (
        f"tourist set room A last_inspector to '{room_a.last_inspector}'"
    );
    assert room_b.last_inspector == "", (
        f"tourist set room B last_inspector to '{room_b.last_inspector}'"
    );

    # Tourists do not carry an inspection counter.
    assert tourist.rooms_inspected == 0, (
        f"tourist rooms_inspected should be 0, got {tourist.rooms_inspected}"
    );
}

test "curator logs general entry AND triggers official inspection in each room" {
    # Build the same two-room graph.
    room_a = Room(room_name="Gallery A");
    room_b = Room(room_name="Gallery B");
    root ++> room_a ++> room_b;

    # One curator walks both rooms.
    curator = Curator(badge="C-1");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn curator;
    }
    out = buf.getvalue();

    # The curator's general log must fire for both rooms.
    assert "Curator C-1 entered Gallery A (general log)" in out, (
        f"missing general log for room A; got: {out}"
    );
    assert "Curator C-1 entered Gallery B (general log)" in out, (
        f"missing general log for room B; got: {out}"
    );

    # The curator's inspection log must ALSO fire for both rooms.
    assert "Official inspection by C-1 in Gallery A" in out, (
        f"missing inspection line for room A; got: {out}"
    );
    assert "Official inspection by C-1 in Gallery B" in out, (
        f"missing inspection line for room B; got: {out}"
    );

    # Each room must record the curator as both visitor and inspector.
    assert room_a.last_visitor == "C-1", (
        f"room A last_visitor: {room_a.last_visitor}"
    );
    assert room_a.last_inspector == "C-1", (
        f"room A last_inspector: {room_a.last_inspector}"
    );
    assert room_b.last_visitor == "C-1", (
        f"room B last_visitor: {room_b.last_visitor}"
    );
    assert room_b.last_inspector == "C-1", (
        f"room B last_inspector: {room_b.last_inspector}"
    );

    # The curator's counter must equal the number of rooms they inspected.
    assert curator.rooms_inspected == 2, (
        f"curator rooms_inspected: {curator.rooms_inspected}"
    );
}

test "curator inspection count matches number of rooms visited" {
    # Build a graph with three rooms to verify the counter scales.
    room_a = Room(room_name="A");
    room_b = Room(room_name="B");
    room_c = Room(room_name="C");
    root ++> room_a ++> room_b ++> room_c;

