"""Test annex for the warehouse packing line walker."""

import io;
import from contextlib { redirect_stdout }

test "OrderAuditor tallies boxes and stops on a three-station line" {
    # Build the three-station line exactly as the spec describes.
    s1 = Station(name="S1");
    s2 = Station(name="S2");
    s3 = Station(name="S3");
    root ++> s1 ++> s2 ++> s3;

    # Robot R1 serves stations S1 and S2.
    s1 +>:Serves(robot_name="R1"):+> Robot(name="R1");
    s2 +>:Serves(robot_name="R1"):+> Robot(name="R1");

    # Robot R2 serves station S3.
    s3 +>:Serves(robot_name="R2"):+> Robot(name="R2");

    # Robots also announce their own stops back at the stations.
    s1 +>:StopsAt(station_name="S1"):+> Robot(name="R1");
    s2 +>:StopsAt(station_name="S2"):+> Robot(name="R1");
    s3 +>:StopsAt(station_name="S3"):+> Robot(name="R2");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();

    # Walker visits S1 -> R1(serves) -> R1(stopsAt) -> S2 -> R1(serves) -> R1(stopsAt) -> S3 -> R2(serves) -> R2(stopsAt).
    # Expected tallies: S1=1, S2=1, S3=1 (each station visited once);
    #                  R1 stops=2 (served at S1, S2),
    #                  R2 stops=1 (served at S3).
    assert "Station S1 packed a box (total 1)" in out, f"missing S1 tally: {out}";
    assert "Station S2 packed a box (total 1)" in out, f"missing S2 tally: {out}";
    assert "Station S3 packed a box (total 1)" in out, f"missing S3 tally: {out}";
    assert "Robot R1 made a stop (total 1)" in out, f"missing R1 first stop: {out}";
    assert "Robot R1 made a stop (total 2)" in out, f"missing R1 second stop: {out}";
    assert "Robot R2 made a stop (total 1)" in out, f"missing R2 stop: {out}";
}

test "Union trigger dispatches on node type" {
    # Minimal graph: one station, one robot reached via Serves.
    s1 = Station(name="S1");
    r1 = Robot(name="R1");
    root ++> s1;
    s1 +>:Serves(robot_name="R1"):+> r1;

    buf = io.StringIO();
