        root spawn OrderAuditor();
    }
    out = buf.getvalue();

    # Station branch prints the station tally line.
    assert "Station S1 packed a box" in out, f"station branch did not fire: {out}";
    # Robot branch prints the robot tally line.
    assert "Robot R1 made a stop" in out, f"robot branch did not fire: {out}";
    # No "Cannot" / type-mismatch noise from a correct union dispatch.
    assert "Type is Unknown" not in out, f"unknown-type noise: {out}";
}

test "Station tally increments on each visit" {
