test "mixed fleet totals correctly" {
    root ++> Vehicle(kind="car")
        ++> Vehicle(kind="truck", tons=3.0)
        ++> Vehicle(kind="motorcycle")
        ++> Vehicle(kind="car")
        ++> Vehicle(kind="truck", tons=1.5)
        ++> Vehicle(kind="truck", tons=8.0)
        ++> Vehicle(kind="motorcycle");
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn TollCollector(gate="G-4");
    }
    out = buf.getvalue();
    # 2 cars @ 2.50 = 5.00
    # 3.0t truck = 4.00, 1.5t truck = 3.25, 8.0t truck = 6.50 -> 13.75
    # 2 motorcycles @ 1.00 = 2.00
    # total = 5.00 + 13.75 + 2.00 = 20.75
    assert "$20.75" in out, f"expected total $20.75, got: {out!r}";
    assert out.count("CAR ->") == 2, f"expected 2 car lines, got: {out!r}";
    assert out.count("TRUCK,") == 3, f"expected 3 truck lines, got: {out!r}";
    assert out.count("MOTORCYCLE ->") == 2, f"expected 2 motorcycle lines, got: {out!r}";
    # Sweep header + revenue footer must bracket the per-vehicle lines.
    start_idx = out.index("=== Toll booth G-4 sweep starting ===");
    end_idx = out.index("=== Gate G-4 revenue: $20.75 ===");
    assert start_idx < end_idx, "sweep header should precede revenue footer";
    # Each payment line appears between header and footer.
    car_idx = out.index("CAR ->");
    bike_idx = out.index("MOTORCYCLE ->");
    assert start_idx < car_idx < end_idx, "car line should be between header and footer";
    assert start_idx < bike_idx < end_idx, "motorcycle line should be between header and footer";
}

