test "books report title and author" {
    root ++> Book(title="The Hobbit", author="Tolkien")
        ++> Book(title="Dune", author="Herbert");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Auditor();
    }
    out = buf.getvalue();

    assert res.total == 2, f"total should be 2, got {res.total}";
    assert res.defaulted == 0, f"defaulted should be 0, got {res.defaulted}";
    assert "[BOOK] The Hobbit by Tolkien" in out, f"missing Hobbit line: {out}";
    assert "[BOOK] Dune by Herbert" in out, f"missing Dune line: {out}";
    assert "[DVD]" not in out, f"unexpected DVD line: {out}";
    assert "[?]" not in out, f"unexpected default line: {out}";
}

test "dvds report title and runtime" {
    root ++> DVD(title="Inception", runtime=148)
        ++> DVD(title="Spirited Away", runtime=125);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Auditor();
    }
