    assert "[DVD]  Inception (148 min)" in out, f"missing Inception line: {out}";
    assert "[DVD]  Spirited Away (125 min)" in out, f"missing Spirited Away line: {out}";
    assert "[BOOK]" not in out, f"unexpected BOOK line: {out}";
    assert "[?]" not in out, f"unexpected default line: {out}";
}

test "unclassified reels fall through to default handler" {
