test "mixed shelf counts all items and only defaults" {
    root ++> Book(title="The Hobbit", author="Tolkien")
        ++> DVD(title="Inception", runtime=148)
        ++> Book(title="Dune", author="Herbert")
        ++> Reel(title="Archive Reel 7", format="film")
