    root ++> Book(title="Dune", author="Herbert", year=1965, available=False);
    root ++> Book(title="Neuromancer", author="Gibson", year=1984);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Auditor();
    }
    out = buf.getvalue();

