    assert "[ARCHIVE]" not in out, f"archive/default marker leaked into book-only shelf: {out}";

    assert res.total == 3, f"expected 3 items audited, got {res.total}";
    assert res.default_count == 0, f"expected 0 defaults on book-only shelf, got {res.default_count}";
}

