    out_buf = io.StringIO();
    auditor = Auditor();
    with redirect_stdout(out_buf) {
        root spawn auditor;
    }
    auditor_out = out_buf.getvalue();

    # Auditor should pick up exactly the 4 classified items.
    assert auditor.total == 4, f"auditor expected 4 classified items, got {auditor.total}";
    assert "[BOOK] 'Dune' by Frank Herbert" in auditor_out, f"missing Dune: {auditor_out}";
    assert "[BOOK] 'Circe' by Madeline Miller" in auditor_out, f"missing Circe: {auditor_out}";
