    assert "[DVD]  'Arrival' (116 min)" in auditor_out, f"missing Arrival: {auditor_out}";
    # Reel is unclassified — should never appear in the auditor's output.
    assert "[DEFAULT]" not in auditor_out, f"DEFAULT must not appear in auditor output: {auditor_out}";
    assert "Reel #47" not in auditor_out, f"unclassified item leaked into auditor output: {auditor_out}";

    handler_buf = io.StringIO();
    handler = DefaultHandler();
    with redirect_stdout(handler_buf) {
        root spawn handler;
    }
    handler_out = handler_buf.getvalue();

    # Handler traverses every shelved item; only the defaulted one is counted as defaulted.
    assert handler.total == 5, f"handler total expected 5 (all items), got {handler.total}";
    assert handler.default_count == 1, f"handler default_count expected 1, got {handler.default_count}";
    assert "[DEFAULT] 'Reel #47' (unclassified archive)" in handler_out, f"missing default line: {handler_out}";
    # Classified items must NOT show up in default output.
    assert "[BOOK]" not in handler_out, f"BOOK leaked into default output: {handler_out}";
    assert "[DVD]" not in handler_out, f"DVD leaked into default output: {handler_out}";
}


