test "audits classified books and DVDs, counts totals" {
    root ++> Book(title="The Hobbit", author="Tolkien", available=True)
        ++> Book(title="Dune", author="Herbert", available=False)
        ++> DVD(title="Inception", runtime=148, available=True)
        ++> DVD(title="Blade Runner", runtime=117, available=True);

    auditor = Auditor();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn auditor;
    }
    out = buf.getvalue();

    assert res.total == 4, f"expected 4 items audited, got {res.total}";
    assert res.default_count == 0, f"expected 0 default path, got {res.default_count}";
    assert "Starting shelf audit..." in out, f"missing start line: {out}";
    assert "[IN] Book: The Hobbit by Tolkien" in out, f"missing Book IN line: {out}";
    assert "[OUT] Book: Dune by Herbert" in out, f"missing Book OUT line: {out}";
    assert "[IN] DVD: Inception (148 min)" in out, f"missing DVD IN line: {out}";
    assert "[IN] DVD: Blade Runner (117 min)" in out, f"missing DVD IN line: {out}";
    assert "[DEFAULT]" not in out, f"unexpected DEFAULT marker: {out}";
}

test "routes unclassified reels through the default path" {
    root ++> Reel(title="Archive-1972", format="16mm", available=False)
        ++> Reel(title="Old-Promo", format="8mm", available=True);

    auditor = Auditor();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn auditor;
    }
    out = buf.getvalue();

    assert res.total == 2, f"expected 2 items audited, got {res.total}";
    assert res.default_count == 2, f"expected 2 default path, got {res.default_count}";
    assert "[DEFAULT] Archive-1972 (reel, 16mm) - unclassified" in out, f"missing reel 1: {out}";
    assert "[DEFAULT] Old-Promo (reel, 8mm) - unclassified" in out, f"missing reel 2: {out}";
}

test "mixed shelf: classified items shelved, reels defaulted" {
    root ++> Book(title="Dune", author="Herbert", available=False)
        ++> DVD(title="Inception", runtime=148, available=True)
