    assert "[DEFAULT] Untitled Reel (unclassified archive reel)" in out, f"missing second default line: {out}";

    # Totals: 6 items visited, 2 routed through the default (ArchiveReel) path.
    assert "--- Audit summary: 6 items, 2 needed the default path ---" in out, f"wrong summary: {out}";
