        ++> Sensor(zone="Zone-A", reading=82.0, kind="temp", limit=75.0)
        ++> Sensor(zone="Zone-A", reading=42.0, kind="smoke", limit=50.0)
        ++> Sensor(zone="Zone-B", reading=55.5, kind="smoke", limit=50.0)
        ++> Sensor(zone="Zone-B", reading=71.2, kind="temp", limit=75.0)
        ++> Sensor(zone="Zone-B", reading=90.0, kind="smoke", limit=50.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Patrol();
    }
    out = buf.getvalue();

    # Temperature alert (above 75 C) should fire
    assert "Zone-A temp: 82.0 C (limit 75.0 C)" in out, f"missing Zone-A temp alert: {out}";
    assert "[ALERT] Zone-A temp" in out, f"missing ALERT marker for Zone-A temp: {out}";

    # Smoke alert (above 50 ppm) should fire
    assert "Zone-B smoke: 55.5 ppm (limit 50.0 ppm)" in out, f"missing Zone-B smoke alert: {out}";
    assert "Zone-B smoke: 90.0 ppm (limit 50.0 ppm)" in out, f"missing 90 ppm alert: {out}";
    assert "[ALERT] Zone-B smoke" in out, f"missing ALERT marker for Zone-B smoke: {out}";

    # Nominal readings should not be flagged
    assert "[nominal] Zone-A temp: 68.5 C" in out, f"missing nominal Zone-A temp: {out}";
    assert "[nominal] Zone-A smoke: 42.0 ppm" in out, f"missing nominal Zone-A smoke: {out}";
    assert "[nominal] Zone-B temp: 71.2 C" in out, f"missing nominal Zone-B temp: {out}";

    # Exactly 3 alerts expected: two smoke in Zone-B, one temp in Zone-A
    assert "Total alerts: 3" in out, f"expected 3 alerts, got: {out}";

    # Patrol start banner and summary header
    assert "Starting factory zone patrol..." in out, f"missing start banner: {out}";
    assert "=== Patrol Summary ===" in out, f"missing summary header: {out}";
}

