"""Tests for the factory Patrol walker."""

import io;
import from contextlib { redirect_stdout }

def make_fleet() -> dict {
    zone_a = Zone(name="Assembly Line A");
    zone_b = Zone(name="Packaging Hall B");
    root ++> zone_a;
    root ++> zone_b;

    zone_a ++> TempSensor(label="T-101", celsius=68.0);
    zone_a ++> SmokeSensor(label="S-201", ppm=72.5);
    zone_a ++> TempSensor(label="T-102", celsius=91.5);

    zone_b ++> SmokeSensor(label="S-202", ppm=12.0);
    zone_b ++> TempSensor(label="T-103", celsius=80.0);
    zone_b ++> SmokeSensor(label="S-203", ppm=55.0);

    return {"a": zone_a, "b": zone_b};
}

test "patrol prints header and zone entries" {
    make_fleet();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Patrol();
    }
    out = buf.getvalue();
    assert "Patrol starting across factory zones" in out, f"missing start banner: {out!r}";
    assert "Entering zone: Assembly Line A" in out, f"missing zone A line: {out!r}";
    assert "Entering zone: Packaging Hall B" in out, f"missing zone B line: {out!r}";
}

test "each sensor prints a verdict line with correct threshold logic" {
    make_fleet();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Patrol();
    }
    out = buf.getvalue();

    # Temperature > 75 C alerts; 68 stays nominal.
    assert "[nominal] TempSensor T-101 reading 68.0 C" in out, f"T-101 nominal missing: {out!r}";
    assert "[ALERT] TempSensor T-102 reading 91.5 C" in out, f"T-102 alert missing: {out!r}";
    assert "[ALERT] TempSensor T-103 reading 80.0 C" in out, f"T-103 alert missing: {out!r}";

    # Smoke > 50 ppm alerts; 12 stays nominal.
    assert "[nominal] SmokeSensor S-202 reading 12.0 ppm" in out, f"S-202 nominal missing: {out!r}";
    assert "[ALERT] SmokeSensor S-201 reading 72.5 ppm" in out, f"S-201 alert missing: {out!r}";
    assert "[ALERT] SmokeSensor S-203 reading 55.0 ppm" in out, f"S-203 alert missing: {out!r}";
}

test "boundary thresholds - exactly 75 C and 50 ppm are not alerts" {
    zone_a = Zone(name="Boundary Zone");
