    assert "[nominal] SmokeSensor S-edge reading 50.0 ppm" in out, f"50.0 ppm must be nominal (strict >): {out!r}";
}

test "walker counters match number of sensors scanned" {
    make_fleet();
    res = root spawn Patrol();
    assert res.total == 6, f"expected 6 sensors scanned, got {res.total}";
    assert len(res.alerts) == 4, f"expected 4 alerts, got {len(res.alerts)}: {res.alerts}";
    # The four alerts correspond to T-102, T-103, S-201, S-203.
    joined = " | ".join(res.alerts);
    assert "T-102" in joined, f"T-102 alert missing from list: {res.alerts}";
    assert "T-103" in joined, f"T-103 alert missing from list: {res.alerts}";
    assert "S-201" in joined, f"S-201 alert missing from list: {res.alerts}";
    assert "S-203" in joined, f"S-203 alert missing from list: {res.alerts}";
}

test "summary footer reports totals and replays alert log" {
    make_fleet();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Patrol();
    }
    out = buf.getvalue();

    assert "Patrol complete: 6 sensors scanned, 4 alerts" in out, f"summary line wrong: {out!r}";

    # Every alert entry must appear in the ALERT LOG replay.
    alert_log_lines = [ln for ln in out.splitlines() if ln.startswith("ALERT LOG: ")];
    assert len(alert_log_lines) == 4, f"expected 4 ALERT LOG lines, got {len(alert_log_lines)}: {alert_log_lines}";
    blob = "\n".join(alert_log_lines);
    for label in ["T-102", "T-103", "S-201", "S-203"] {
        assert label in blob, f"{label} missing from alert log replay: {blob}";
    }
    for label in ["T-101", "S-202"] {
        assert label not in blob, f"nominal {label} should not appear in alert log: {blob}";
    }
}

