    with redirect_stdout(buf) {
        res = root spawn Maintainer();
    }
    out = buf.getvalue();

    # 4 device log lines, one per node visited in chain order.
    assert "[DIESEL_PUMP] idle for 12h -> serviced, counter reset" in out, f"missing diesel log: {out}";
    assert "[ROTOR_SPRINKLER] idle for 5h -> serviced, counter reset" in out, f"missing rotor log: {out}";
    assert "[SOLAR_PUMP] idle for 8h -> serviced, counter reset" in out, f"missing solar log: {out}";
