    # Starting banner is printed.
    assert "Starting orchard maintenance tour..." in out, f"missing start banner: {out}";

    # Summary printed exactly once with correct serviced count.
    assert "--- Tour complete: 4 devices serviced ---" in out, f"missing summary: {out}";
    assert res.serviced == 4, f"expected 4 serviced, got {res.serviced}";
}

test "counters are reset after servicing" {
    a = Pump(kind="diesel_pump", idle_hours=12);
    b = Sprinkler(kind="rotor_sprinkler", idle_hours=5);
    c = Pump(kind="solar_pump", idle_hours=8);
    root ++> a ++> b ++> c;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Maintainer();
    }

    # Every visited node's idle counter must be reset to 0.
    assert a.idle_hours == 0, f"diesel pump not reset: {a.idle_hours}";
    assert b.idle_hours == 0, f"rotor sprinkler not reset: {b.idle_hours}";
