}

test "idle hours are accumulated per device kind on the walker" {
    root ++> Pump(kind="diesel_pump", idle_hours=12)
        ++> Sprinkler(kind="rotor_sprinkler", idle_hours=5)
        ++> Pump(kind="solar_pump", idle_hours=8)
        ++> Sprinkler(kind="drip_sprinkler", idle_hours=3);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Maintainer();
    }

    # pump_hours sums only Pump idle hours: 12 + 8 = 20.
