    # Pump summary uses self.pump_hours; total = 12 + 8 = 20.
    assert "Pumps:     0 handled, 20h total idle" in out, f"missing/incorrect pump summary: {out}";
    # Sprinkler summary uses self.sprinkler_hours; total = 5 + 3 = 8.
    assert "Sprinklers handled, 8h total idle" in out, f"missing/incorrect sprinkler summary: {out}";
