    assert alpha.reputation == 10, f"alpha reputation must be unchanged, got {alpha.reputation}";
    assert beta.reputation == 4, f"beta reputation must be unchanged, got {beta.reputation}";
    assert chief.reputation == 55, f"chief reputation must be 55, got {chief.reputation}";
    assert chief.available == True, f"admin available flag preserved, got {chief.available}";

    # Confirm edge directions: desk -> alpha -> beta forms a chain
    assert desk in [rt -->], f"desk must be a direct child of root";
    assert chief in [rt -->], f"chief must be a direct child of root";
    assert alpha in [desk -->], f"alpha must be a child of desk";
    assert beta in [alpha -->], f"beta must be a child of alpha";
    assert len([desk -->]) == 1, f"desk must have exactly 1 child, got {len([desk -->])}";
    assert len([alpha -->]) == 1, f"alpha must have exactly 1 child, got {len([alpha -->])}";
}

