"""Tests for the game account moderation sweep."""

import io;
import from contextlib { redirect_stdout }

# ---------- Helpers ----------

def make_world {
    root ++> Member(label="alice", joined=2021)
        ++> Member(label="bob", joined=2022)
        ++> Admin(label="carol", clearance="high")
        ++> Bot(serial="BX-001");

    desk = WelcomeDesk();
    root ++> desk ++> Bot(serial="BX-002");
    return desk;
}

def run_moderator {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Moderator();
    }
    return buf.getvalue();
}

def run_greeter {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Greeter();
    }
    return buf.getvalue();
}

# ---------- Tests ----------

test "moderator audits members and boosts admins" {
    make_world();
    out = run_moderator();

    # Both members are audited with their starting reputation of 0.
    assert "audit: alice (rep=0)" in out, f"alice audit missing: {out}";
    assert "audit: bob (rep=0)" in out, f"bob audit missing: {out}";

    # Admin gets the +5 boost (0 -> 5).
    assert "admin pass: carol rep boosted to 5" in out, f"admin boost missing: {out}";

    # Sweep banner is emitted.
    assert "Moderation sweep begins..." in out, f"banner missing: {out}";
}

test "moderator greets every bot it reaches" {
    make_world();
    out = run_moderator();

    # Both bots (BX-001 reachable from root, BX-002 reachable via desk)
    # get a welcome message printed by the Moderator's Bot ability.
    assert "welcome bot BX-001!" in out, f"BX-001 greet missing: {out}";
    assert "welcome bot BX-002!" in out, f"BX-002 greet missing: {out}";
}

test "greeter only handles bots via union trigger on welcome desk" {
    make_world();
    out = run_greeter();

    # Greeter's own Bot ability fires for the bot reachable from root.
    assert "hello, bot BX-001!" in out, f"greeter BX-001 missing: {out}";

    # WelcomeDesk's union ability fires for the Greeter, greeting BX-002.
    assert "welcome desk greets the incoming visitor" in out, f"desk greet missing: {out}";
    assert "Greeter is at the welcome desk." in out, f"greeter banner missing: {out}";
}

test "welcome desk fires for moderator as well" {
    make_world();
    out = run_moderator();

    # The union trigger on WelcomeDesk matches Moderator too, so when the
    # Moderator reaches the desk, the desk greets them.
    assert "welcome desk greets the incoming visitor" in out, f"desk not triggered by Moderator: {out}";
}

test "moderator does not mutate member reputation and boosts admin by exactly 5" {
    make_world();
    out = run_moderator();

    # Grab the live nodes by walking from root and inspect post-state.
    children = [root-->];
    member_alice = children[0];
    member_bob = children[1];
    admin_carol = children[2];

    # Members are audited but their reputation is unchanged.
