    assert riley.packages == 40, f"expected 40 parcels total (doubled), got {riley.packages}";
}


test "express courier moves exactly twice as many parcels as the standard one over the same chain" {
    build_depot_chain();

    sam = Courier(name="Sam");
    sam = root spawn sam;

    riley = ExpressCourier(name="Riley");
    riley = root spawn riley;

    assert riley.packages == 2 * sam.packages, (
        f"express should double standard total: sam={sam.packages}, riley={riley.packages}"
    );
    assert sam.packages == 20 and riley.packages == 40, (
        f"expected sam=20 and riley=40, got sam={sam.packages}, riley={riley.packages}"
    );
}


test "depot chain has exactly three depots in order and no other children of root" {
