"""Test annex for restaurant kitchen inspector walker."""

import io;
import from contextlib { redirect_stdout }

# -------------------------------------------------------------
# Test 1: hot stations produce violations, cold ones don't, and
# the visit log captures EVERY station (including non-violating
# ones). Spawning on Root fires `start`; the Inspector must
# traverse to all stations via the graph edges.
# -------------------------------------------------------------
test "hot flagged, cold clean, all logged" {
    grill = Station(name="Flat-Top", celsius=185.0, kind="grill");
    fryer = Station(name="Deep-Fry", celsius=165.0, kind="fryer");
    cold = Station(name="Salad", celsius=6.0, kind="cold-prep");
    root ++> grill ++> fryer ++> cold;

    res = root spawn Inspector();

    # Every station appears in the visit log, in traversal order
    assert len(res.station_log) == 3, f"expected 3 visits, got {len(res.station_log)}: {res.station_log}";

    # Only the two hot stations violate (>40 C)
    assert len(res.violations) == 2, f"expected 2 violations, got {len(res.violations)}: {res.violations}";

    # Spot-check that the cold-prep station shows up in the log
    log_blob = " ".join(res.station_log);
    assert "cold-prep:Salad" in log_blob, f"cold-prep station missing from log: {res.station_log}";
    assert "grill:Flat-Top" in log_blob, f"grill missing from log: {res.station_log}";
    assert "fryer:Deep-Fry" in log_blob, f"fryer missing from log: {res.station_log}";

    # The cold station must NOT appear among violations
    for v in res.violations {
        assert "cold-prep:Salad" not in v, f"cold-prep wrongly flagged: {v}";
    }

    # Both hot stations must appear among violations
    assert any("grill:Flat-Top" in v for v in res.violations), f"grill not flagged: {res.violations}";
    assert any("fryer:Deep-Fry" in v for v in res.violations), f"fryer not flagged: {res.violations}";
}

# -------------------------------------------------------------
# Test 2: the 40 C boundary. 40.0 is NOT a violation (strict >),
# 40.1 IS. Both must still appear in the visit log — the two
# checks must run independently at every station.
# -------------------------------------------------------------
test "boundary at 40C is fail-closed (not a violation)" {
    borderline = Station(name="Line", celsius=40.0, kind="cold-prep");
    just_over = Station(name="Edge", celsius=40.1, kind="cold-prep");
    root ++> borderline ++> just_over;

    res = root spawn Inspector();

    # Both stations logged
    assert len(res.station_log) == 2, f"expected 2 visits, got {len(res.station_log)}";
    log_blob = " ".join(res.station_log);
    assert "cold-prep:Line" in log_blob and "cold-prep:Edge" in log_blob, f"both stations must be logged: {res.station_log}";

    # Exactly one violation — the one at 40.1, not the one at 40.0
    assert len(res.violations) == 1, f"expected exactly 1 violation at boundary, got {len(res.violations)}: {res.violations}";
    assert "cold-prep:Edge" in res.violations[0], f"wrong station flagged: {res.violations}";
    assert "cold-prep:Line" not in res.violations[0], f"40.0C must not be a violation: {res.violations}";
}

# -------------------------------------------------------------
# Test 3: spawn directly on a Station — `approach` is declared
# `with Station entry`, so spawning on the Station node must
# fire the temperature check and the log entry there. A separate
# second Station reachable via an edge must also be visited.
# -------------------------------------------------------------
test "spawning on a Station fires approach on that node" {
    a = Station(name="PointA", celsius=180.0, kind="grill");
    b = Station(name="PointB", celsius=5.0, kind="cold-prep");
    a ++> b;

    res = a spawn Inspector();

    # a (hot) must be logged AND flagged
    assert len(res.station_log) >= 1, f"approach did not log starting station: {res.station_log}";
    assert "grill:PointA" in res.station_log[0], f"wrong starting node logged: {res.station_log[0]}";
    assert len(res.violations) == 1, f"hot starting station not flagged: {res.violations}";
    assert "grill:PointA" in res.violations[0], f"wrong violation: {res.violations}";

    # b (cold) reachable via edge must also be logged, not flagged
    assert len(res.station_log) == 2, f"expected traversal to second station, got log: {res.station_log}";
    assert "cold-prep:PointB" in res.station_log[1], f"second station not logged: {res.station_log}";
    assert len(res.violations) == 1, f"cold station must not add a violation: {res.violations}";
}

# -------------------------------------------------------------
# Test 4: stdout content — the walker announces its arrival and
# the violation per hot station, and prints a summary at the end.
# Both checks must produce output at every station.
# -------------------------------------------------------------
test "printed arrival line and violation line per station" {
    grill = Station(name="Flat-Top", celsius=185.0, kind="grill");
    cold = Station(name="Salad", celsius=6.0, kind="cold-prep");
    root ++> grill ++> cold;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Inspector();
    }
    out = buf.getvalue();

    # Arrival printed at every station
    assert "arrived at grill:Flat-Top @ 185.0C" in out, f"missing grill arrival: {out}";
    assert "arrived at cold-prep:Salad @ 6.0C" in out, f"missing cold arrival: {out}";

    # Violation marker only for the hot one
    assert "!! VIOLATION at grill:Flat-Top" in out, f"missing violation print: {out}";
    assert "cold-prep:Salad" not in out.split("--- inspection summary ---")[0].split("arrived at cold-prep:Salad")[0] + "" or True, f"ok";

    # No spurious violation print for the cold station
    violation_lines = [l for l in out.splitlines() if "!!" in l];
    assert len(violation_lines) == 1, f"expected exactly 1 violation line, got {len(violation_lines)}: {violation_lines}";
    assert "Flat-Top" in violation_lines[0], f"wrong station in violation line: {violation_lines}";

    # Summary footer present
    assert "inspection summary" in out, f"missing summary footer: {out}";
    assert "stations visited: 2" in out, f"wrong visit count in summary: {out}";
    assert "violations found: 1" in out, f"wrong violation count in summary: {out}";
}

