"""Tests for Kitchen health inspection walker."""

node Station {
    has name: str = "";
    has temperature: float = 0.0;
}

walker Inspector {
    has violation_count: int = 0;
    has visits: int = 0;

    can start with Root entry {
        print("Inspector beginning kitchen walk-through");
        visit [-->];
    }

    can advance with Station entry {
        visit [-->];
    }

    can check_temperature with Station entry {
        self.visits += 1;
        if here.temperature > 40.0 {
            self.violation_count += 1;
            print(f"  VIOLATION: {here.name} at {here.temperature} C exceeds 40 C");
        } else {
            print(f"  OK: {here.name} at {here.temperature} C");
        }
    }

    can log_visit with Station entry {
        print(f"  LOG: visited station '{here.name}'");
    }
}

