"""Tests for the kitchen line health inspection walkers."""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
# TempInspector: every station gets a line printed with OK/VIOLATION based
# on whether celsius > 40.0, and the violation status must match that rule.
# ---------------------------------------------------------------------------
test "temp inspector flags hot stations only" {
    root ++> Station(name="grill",     celsius=180.0)
          ++> Station(name="fryer",    celsius=165.0)
          ++> Station(name="cold prep", celsius=4.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn TempInspector();
    }
    out = buf.getvalue();

    # Hot stations are violations, cold prep is not.
    assert "[VIOLATION] grill: 180.0 C" in out, f"grill missing violation: {out!r}";
    assert "[VIOLATION] fryer: 165.0 C" in out, f"fryer missing violation: {out!r}";
    assert "[OK] cold prep: 4.0 C" in out, f"cold prep should be OK: {out!r}";

    # Exactly one printed line per station — nothing extra, nothing missing.
    lines = [ln for ln in out.strip().splitlines() if ln];
    assert len(lines) == 3, f"expected 3 station lines, got {len(lines)}: {lines}";
}

# ---------------------------------------------------------------------------
# Boundary check: a station sitting exactly at 40.0 C is NOT a violation
# (the rule is strictly greater-than), and 40.1 C IS a violation.
# ---------------------------------------------------------------------------
test "temp inspector threshold is strictly above 40" {
    root ++> Station(name="at_limit",  celsius=40.0)
          ++> Station(name="over_limit", celsius=40.1);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn TempInspector();
    }
    out = buf.getvalue();

    assert "[OK] at_limit: 40.0 C" in out, f"40.0 C must be OK, got: {out!r}";
    assert "[VIOLATION] over_limit: 40.1 C" in out, f"40.1 C must be VIOLATION, got: {out!r}";
}

# ---------------------------------------------------------------------------
# VisitLogger: the walker's `log` list (in spawn order) must contain every
# station name exactly once, and each visit must emit a "logged visit" line.
# ---------------------------------------------------------------------------
test "visit logger records every station in traversal order" {
    grill = Station(name="grill", celsius=180.0);
    fryer = Station(name="fryer", celsius=165.0);
    cold  = Station(name="cold prep", celsius=4.0);
    root ++> grill ++> fryer ++> cold;

    buf = io.StringIO();
    logger = VisitLogger();
    with redirect_stdout(buf) {
        root spawn logger;
    }
    out = buf.getvalue();

    # Every station appears in the walker's log.
    assert len(logger.log) == 3, f"expected 3 visits, got {logger.log}";
    assert set(logger.log) == {"grill", "fryer", "cold prep"},
        f"missing some station in log: {logger.log}";

    # And every station also produced a stdout line.
    assert "logged visit to grill" in out, f"grill log line missing: {out!r}";
    assert "logged visit to fryer" in out, f"fryer log line missing: {out!r}";
    assert "logged visit to cold prep" in out, f"cold prep log line missing: {out!r}";
}

# ---------------------------------------------------------------------------
# Both checks together: running BOTH walkers on the same graph must produce
# the violation lines AND the visit lines for every station — neither
# walker may skip a station.
# ---------------------------------------------------------------------------
test "both walkers visit every station independently" {
    root ++> Station(name="grill",     celsius=180.0)
          ++> Station(name="fryer",    celsius=165.0)
          ++> Station(name="cold prep", celsius=4.0);

    buf = io.StringIO();
    logger = VisitLogger();
    with redirect_stdout(buf) {
        root spawn TempInspector();
        root spawn logger;
    }
    out = buf.getvalue();

    # Every station appears in the violation report...
    for pair in [
        ("[VIOLATION] grill: 180.0 C",     "grill violation"),
        ("[VIOLATION] fryer: 165.0 C",    "fryer violation"),
        ("[OK] cold prep: 4.0 C",         "cold prep OK"),
    ] {
        assert pair[0] in out, f"{pair[1]} line missing: {out!r}";
    }

    # ...and every station appears in the visit log.
    for name in ["grill", "fryer", "cold prep"] {
        assert f"logged visit to {name}" in out, f"visit line for {name} missing: {out!r}";
        assert name in logger.log, f"{name} not in walker log: {logger.log}";
    }

    # 3 violation lines + 3 visit lines = 6 non-empty output lines.
    lines = [ln for ln in out.strip().splitlines() if ln];
    assert len(lines) == 6, f"expected 6 lines total, got {len(lines)}: {lines}";
}

