"""Test annex for the restaurant kitchen health-inspection walker."""

import io;
import from contextlib { redirect_stdout }

# --- Helpers ------------------------------------------------------------

def build_line {
    grill = Grill(station_name="Grill", temperature=85.0);
    fryer = Fryer(station_name="Fryer", temperature=180.0);
    cold_prep = ColdPrep(station_name="Cold Prep", temperature=4.0);
    root ++> grill ++> fryer ++> cold_prep;
    return [grill, fryer, cold_prep];
}

def run_inspector -> tuple {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        inspector = root spawn HealthInspector();
    }
    return (buf.getvalue(), inspector);
}

# --- Tests --------------------------------------------------------------

test "hot stations are flagged as violations and printed" {
    grill = Grill(station_name="Grill", temperature=85.0);
    fryer = Fryer(station_name="Fryer", temperature=180.0);
    root ++> grill ++> fryer;

    (out, inspector) = run_inspector();

    assert grill.violation is True, "grill > 40 C must be flagged";
    assert fryer.violation is True, "fryer > 40 C must be flagged";
    assert "VIOLATION at Grill: 85.0 C exceeds 40 C" in out, (
        f"missing grill violation line: {out}"
    );
    assert "VIOLATION at Fryer: 180.0 C exceeds 40 C" in out, (
        f"missing fryer violation line: {out}"
    );
    assert "OK at" not in out, f"hot stations should not print OK: {out}";
}

test "cold stations are not flagged and print OK" {
    cold_prep = ColdPrep(station_name="Cold Prep", temperature=4.0);
    root ++> cold_prep;

    (out, inspector) = run_inspector();

    assert cold_prep.violation is False, (
        "cold prep at 4 C must NOT be a violation"
    );
    assert "OK at Cold Prep: 4.0 C" in out, f"missing OK line: {out}";
    assert "VIOLATION" not in out, (
        f"no violations expected on a cold line: {out}"
    );
}

test "boundary at exactly 40 C is not a violation" {
    borderline = Grill(station_name="Borderline", temperature=40.0);
    root ++> borderline;

    (out, inspector) = run_inspector();

    assert borderline.violation is False, (
        "temperature equal to 40 C is NOT above the threshold"
    );
    assert "VIOLATION" not in out, (
        f"40 C must not trip the violation message: {out}"
    );
    assert "OK at Borderline: 40.0 C" in out, (
        f"borderline station should report OK: {out}"
    );
}

test "every station visit is logged regardless of temperature" {
    stations = build_line();

    (out, inspector) = run_inspector();

    assert len(inspector.log) == 3, (
        f"expected 3 log entries (one per station), got {len(inspector.log)}: "
        f"{inspector.log}"
    );
    assert inspector.visited_count == 3, (
        f"visited_count must equal number of stations, got "
        f"{inspector.visited_count}"
    );
    assert "Visit #1: Grill" in inspector.log[0], (
        f"first log entry must be grill, got {inspector.log[0]}"
    );
    assert "Visit #2: Fryer" in inspector.log[1], (
        f"second log entry must be fryer, got {inspector.log[1]}"
    );
    assert "Visit #3: Cold Prep" in inspector.log[2], (
        f"third log entry must be cold prep, got {inspector.log[2]}"
    );
    # Both checks must fire per station: each station produces one
    # temperature line AND appears in the visit log.
    for s in stations {
        assert s.station_name in out, (
            f"{s.station_name} missing from inspector output: {out}"
        );
        assert s.station_name in "\n".join(inspector.log), (
            f"{s.station_name} missing from visit log: {inspector.log}"
        );
    }
}

test "full mixed line: violation flags, visit log, and exit message" {
    stations = build_line();

    (out, inspector) = run_inspector();

    # Two stations above 40 C -> two violation flags set on those nodes.
    flagged = [s for s in stations if s.violation];
    clean = [s for s in stations if not s.violation];
    assert len(flagged) == 2, (
        f"expected exactly 2 flagged stations, got {len(flagged)}: "
        f"{[s.station_name for s in flagged]}"
    );
    assert len(clean) == 1, (
        f"expected exactly 1 clean station, got {len(clean)}"
    );
    assert clean[0].station_name == "Cold Prep", (
        f"only cold prep should be clean, got {clean[0].station_name}"
    );

    # Both checks ran on every station: visit log covers all three.
    assert inspector.visited_count == 3, (
        f"visited_count must be 3, got {inspector.visited_count}"
    );
    assert len(inspector.log) == 3, (
        f"log must have 3 entries, got {len(inspector.log)}"
    );

    # Starting message confirms the walker entered the line.
    assert "Health inspector starting kitchen walkthrough" in out, (
        f"missing starting message: {out}"
    );
}

"""Test annex: clearance walkthrough enforcement."""

import io;
import from contextlib { redirect_stdout }

node TestServerRoom {
    has name: str = "";
    has required_level: int = 0;
}

node TestCorridor {
    has label: str = "";
}

test "tech with exact matching clearance reaches all rooms" {
    root ++> TestCorridor(label="Outer Hall")
        ++> TestServerRoom(name="Lobby Server Closet", required_level=1)
        ++> TestServerRoom(name="Mail Server Room", required_level=2)
        ++> TestServerRoom(name="App Server Room", required_level=3)
        ++> TestServerRoom(name="DB Server Room", required_level=4)
        ++> TestServerRoom(name="Root Datacenter", required_level=5);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Technician(name="Senior", clearance=5);
    }
    out = buf.getvalue();
    assert "Technician Senior reached 5 room(s) (completed full walk)" in out, f"missing summary: {out}";
    assert res.outcome == 5, f"outcome={res.outcome}";
    assert "GRANTED [5>=1]" in out and "GRANTED [5>=5]" in out, f"missing grants: {out}";
    assert "DENIED" not in out, f"unexpected denial: {out}";
}

test "junior tech denied at second room stops immediately" {
    root ++> TestCorridor(label="Outer Hall")
        ++> TestServerRoom(name="Lobby Server Closet", required_level=1)
        ++> TestServerRoom(name="Mail Server Room", required_level=2)
        ++> TestServerRoom(name="App Server Room", required_level=3)
        ++> TestServerRoom(name="DB Server Room", required_level=4)
        ++> TestServerRoom(name="Root Datacenter", required_level=5);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Technician(name="Alice", clearance=1);
    }
    out = buf.getvalue();
    assert "Technician Alice reached 2 room(s) (DENIED mid-walk)" in out, f"missing denial summary: {out}";
    assert res.outcome == 2, f"expected 2 rooms, got {res.outcome}";
    assert "GRANTED [1>=1] -> Lobby Server Closet" in out, f"first room not granted: {out}";
    assert "DENIED  [1<2] -> Mail Server Room" in out, f"second room denial missing: {out}";
    # Deeper rooms must NOT appear — walk ends on denial.
    assert "App Server Room" not in out, f"deeper room reached after denial: {out}";
    assert "DB Server Room" not in out, f"deeper room reached after denial: {out}";
    assert "Root Datacenter" not in out, f"deeper room reached after denial: {out}";
}

test "mid clearance tech reaches exactly the rooms allowed" {
