    assert "Technician Bob reached 4 room(s) (DENIED mid-walk)" in out, f"wrong summary: {out}";
    assert res.outcome == 4, f"expected 4, got {res.outcome}";
    assert "GRANTED [3>=1]" in out and "GRANTED [3>=3]" in out, f"grants missing: {out}";
    assert "DENIED  [3<4] -> DB Server Room" in out, f"4th room denial missing: {out}";
    # DB and Root must not be visited after the stop.
    assert "Root Datacenter" not in out, f"root room reached after denial: {out}";
}

test "denial flag is set only when denial happens" {
    # Full clearance: should NOT set denied_here.
    root ++> TestCorridor(label="Hall")
        ++> TestServerRoom(name="A", required_level=1)
        ++> TestServerRoom(name="B", required_level=1);
    buf = io.StringIO();
    with redirect_stdout(buf) {
