"""Tests for data center clearance enforcement.

Builds a corridor of ServerRooms with increasing required levels, then spawns
Technicians with various clearance levels to verify they are granted access to
consecutive rooms, denied at the first room exceeding their clearance, and
disengage immediately without reaching any deeper rooms.
"""

import io;
import from contextlib { redirect_stdout }

def make_corridor {
    rooms = [
        ServerRoom(name="Lobby", required_level=1),
        ServerRoom(name="Ops Floor", required_level=2),
        ServerRoom(name="Cold Archive", required_level=3),
        ServerRoom(name="Crypto Vault", required_level=5),
    ];
    root ++> rooms[0] ++> rooms[1] ++> rooms[2] ++> rooms[3];
    return rooms;
}

test "corridor is built as a chain from root" {
    rooms = make_corridor();
    assert len([root-->]) == 1, f"root should have 1 direct child, got {len([root-->])}";
    lobby = [root -->][0];
    assert lobby.name == "Lobby", f"first room should be Lobby, got {lobby.name}";
    ops = [lobby -->][0];
    assert ops.name == "Ops Floor", f"second room should be Ops Floor, got {ops.name}";
}

test "junior technician with clearance 1 only reaches first room" {
    rooms = make_corridor();
    tech = Technician(badge="J-1", clearance=1);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn tech;
    }
    out = buf.getvalue();
    assert tech.rooms_reached == 1, f"junior should reach 1 room, got {tech.rooms_reached}";
    assert "[GRANTED] J-1 entered Lobby" in out, f"missing Lobby grant: {out}";
    assert "[DENIED] J-1 blocked at Ops Floor" in out, f"missing Ops denial: {out}";
    assert "Crypto Vault" not in out, f"junior must never see Crypto Vault: {out}";
    assert "Cold Archive" not in out, f"junior must never reach Cold Archive: {out}";
}

test "senior technician with clearance 4 reaches three rooms then is denied" {
    rooms = make_corridor();
    tech = Technician(badge="S-4", clearance=4);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn tech;
    }
    out = buf.getvalue();
    assert tech.rooms_reached == 3, f"senior should reach 3 rooms, got {tech.rooms_reached}";
    assert "[GRANTED] S-4 entered Lobby" in out, f"missing Lobby grant: {out}";
    assert "[GRANTED] S-4 entered Ops Floor" in out, f"missing Ops grant: {out}";
    assert "[GRANTED] S-4 entered Cold Archive" in out, f"missing Cold Archive grant: {out}";
    assert "[DENIED] S-4 blocked at Crypto Vault" in out, f"missing Vault denial: {out}";
}

test "admin technician with clearance 5 reaches all four rooms" {
    rooms = make_corridor();
    tech = Technician(badge="A-5", clearance=5);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn tech;
    }
    out = buf.getvalue();
    assert tech.rooms_reached == 4, f"admin should reach all 4 rooms, got {tech.rooms_reached}";
    assert "[DENIED]" not in out, f"admin must not be denied anywhere: {out}";
    for room_name in ["Lobby", "Ops Floor", "Cold Archive", "Crypto Vault"] {
        assert f"[GRANTED] A-5 entered {room_name}" in out, f"missing grant for {room_name}: {out}";
    }
}

test "denied technician disengages immediately and skips deeper rooms" {
    rooms = make_corridor();
    tech = Technician(badge="Z-0", clearance=0);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn tech;
    }
    out = buf.getvalue();
    assert tech.rooms_reached == 0, f"clearance 0 must reach 0 rooms, got {tech.rooms_reached}";
    assert "[DENIED] Z-0 blocked at Lobby (needed 1)" in out, f"missing Lobby denial: {out}";
    assert "Ops Floor" not in out, f"denied tech must not see Ops Floor: {out}";
    assert "Crypto Vault" not in out, f"denied tech must not see Crypto Vault: {out}";
    assert "Cold Archive" not in out, f"denied tech must not see Cold Archive: {out}";
}

test "clearance equal to required level is sufficient" {
    rooms = make_corridor();
    tech = Technician(badge="E-2", clearance=2);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn tech;
    }
    out = buf.getvalue();
    assert tech.rooms_reached == 2, f"clearance 2 should pass Lobby+Ops, got {tech.rooms_reached}";
    assert "[GRANTED] E-2 entered Ops Floor (needed 2)" in out, f"missing Ops grant: {out}";
    assert "[DENIED] E-2 blocked at Cold Archive (needed 3)" in out, f"missing Cold Archive denial: {out}";
}

"""Tests for theme park operations capstone.

Each test builds its own graph (since tests run in isolated workers)
and spawns the Rider walker on it. The Rider walker mutates `has` fields
on itself (`fun_points`, `purchases`, `spend`) which we read back from
the returned walker instance. We also capture stdout so we can assert
on the printed ride/shop messages.
"""

import io;
import from contextlib { redirect_stdout }

test "tall rider rides coasters and water rides" {
    midway = Attraction(name="Midway");
    root ++> midway;

    viper = RollerCoaster(name="Viper", min_height_cm=130, thrill=9);
    midway ++> viper;

    logflume = WaterRide(name="Log Flume", splash_level=7);
    viper ++> logflume;

    ivy = Rider(rider_name="Ivy", height_cm=155);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = midway spawn ivy;
    }
    out = buf.getvalue();

    assert res.fun_points == (9 * 10) + (7 * 5), f"got {res.fun_points}";
    assert res.purchases == 0, f"got {res.purchases}";
    assert res.spend == 0, f"got {res.spend}";
    assert "rides Viper" in out, f"missing Viper ride: {out}";
    assert "+90 fun" in out, f"missing Viper fun points: {out}";
    assert "gets soaked on Log Flume" in out, f"missing Log Flume: {out}";
    assert "+35 fun" in out, f"missing Log Flume fun points: {out}";
    assert "TOO SHORT" not in out, f"tall rider should not be too short: {out}";
}

test "short rider is turned away from Viper and stops exploring" {
    midway = Attraction(name="Midway");
    root ++> midway;

    viper = RollerCoaster(name="Viper", min_height_cm=130, thrill=9);
    midway ++> viper;

    logflume = WaterRide(name="Log Flume", splash_level=7);
    viper ++> logflume;

    bo = Rider(rider_name="Bo", height_cm=118);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = midway spawn bo;
    }
    out = buf.getvalue();

    assert res.fun_points == 0, f"short rider should earn no fun: got {res.fun_points}";
    assert res.purchases == 0, f"got {res.purchases}";
    assert res.spend == 0, f"got {res.spend}";
    assert "TOO SHORT" in out, f"missing too-short message: {out}";
    assert "Bo is TOO SHORT for Viper" in out, f"missing Viper too-short message: {out}";
    # disengage must stop further traversal — Log Flume (a child of Viper) is never visited
    assert "gets soaked" not in out, f"disengage should stop walk: {out}";
    assert "rides Viper" not in out, f"short rider must not ride Viper: {out}";
}

