test "adult human Alice sees 3 raw, keeps 2" {
    alice = Profile(name="Alice", age=34);
    bob = Profile(name="Bob", age=41);
    carol = Profile(name="Carol", age=37);
    dave = Profile(name="Dave", age=17);
    rex = Profile(name="Rex", age=5, species="dog", is_adult=False);

    alice +>:FriendOf:+> bob;
    alice +>:FriendOf:+> carol;
    alice +>:FriendOf:+> dave;
    alice +>:FriendOf:+> rex;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = alice spawn Recommender();
    }
    out = buf.getvalue();

    assert res.owner == "Alice", f"owner should be Alice, got {res.owner}";
    assert res.raw_seen == 3, f"Alice should see 3 Profile neighbours (excluding Rex the pet), got {res.raw_seen}";
    assert res.kept == 2, f"Alice should keep 2 adult humans (Bob, Carol), got {res.kept}";
