import io;
import from contextlib { redirect_stdout }

test "sibling finder finds all siblings through shared parents" {
    rt = Root();

    hana = Person(name="Hana", birth_year=1960);
    luis = Person(name="Luis", birth_year=1962);
    mia = Person(name="Mia", birth_year=1988);
    noah = Person(name="Noah", birth_year=1991);
    ivy = Person(name="Ivy", birth_year=1995);

    hana +>: ParentOf() :+> mia;
    hana +>: ParentOf() :+> noah;
    luis +>: ParentOf() :+> noah;
    luis +>: ParentOf() :+> ivy;

    rt ++> hana ++> luis;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = rt spawn SiblingFinder();
    }
    out = buf.getvalue();

    assert "-- Sibling report --" in out, f"missing report header: {out}";

    # Hana has 2 children: Mia and Noah (via hana), plus Ivy (via luis only)
    # From Hana: walk up to Hana herself (parent of Mia), down via ParentOf -> Mia, Noah
    # From Mia: up to Hana, down to Noah
    # From Noah: up to Hana and Luis, down to Mia and Ivy -> siblings Mia, Ivy
    # From Ivy: up to Luis, down to Noah
    assert "Mia (1988) has sibling Noah (1991)" in out, f"missing Mia-Noah sibling: {out}";
    assert "Noah (1991) has sibling Mia (1988)" in out, f"missing Noah-Mia sibling: {out}";
    assert "Noah (1991) has sibling Ivy (1995)" in out, f"missing Noah-Ivy sibling: {out}";
    assert "Ivy (1995) has sibling Noah (1991)" in out, f"missing Ivy-Noah sibling: {out}";

    # Each parent has 2 children listed, so 2 sibling relations per child
    assert "Mia: 1 sibling(s)" in out, f"missing Mia count: {out}";
    assert "Noah: 2 sibling(s)" in out, f"missing Noah count: {out}";
    assert "Ivy: 1 sibling(s)" in out, f"missing Ivy count: {out}";

    # Hana and Luis themselves should not appear as siblings of themselves
    assert "Hana (1960) has sibling" not in out, f"Hana should not be listed as own sibling: {out}";
    assert "Luis (1962) has sibling" not in out, f"Luis should not be listed as own sibling: {out}";
}

