"""Tests for the DeepAuditor walker: depth-first traversal and >100 KB flagging."""

import io;
import from contextlib { redirect_stdout }


def build_tree {
    project = Folder(name="project");
    src = Folder(name="src");
    assets = Folder(name="assets");
    docs = Folder(name="docs");

    main_py = FileNode(name="main.py", kb=12);
    engine_py = FileNode(name="engine.py", kb=240);
    tiny_py = FileNode(name="tiny.py", kb=1);
    logo_png = FileNode(name="logo.png", kb=310);
    readme_md = FileNode(name="README.md", kb=4);
    notes_md = FileNode(name="notes.md", kb=500);

    root ++> project;
    project +>: Contains() :+> src;
    project +>: Contains() :+> assets;
    project +>: Contains() :+> readme_md;
    project +>: Contains() :+> docs;
    src +>: Contains() :+> main_py;
    src +>: Contains() :+> engine_py;
    src +>: Contains() :+> tiny_py;
    assets +>: Contains() :+> logo_png;
    docs +>: Contains() :+> notes_md;

    return project;
}

test "depth-first subdirectory fully explored before sibling" {
    project = build_tree();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn DeepAuditor();
    }
    out = buf.getvalue();

    # All children of src (main.py, engine.py, tiny.py) must appear
    # BEFORE the assets folder's entry line, proving src's subtree
    # was drained before project moved sideways to assets.
    src_block_end = out.find("tiny.py");
    assets_enter = out.find("enter assets/");
    readme_enter = out.find("enter docs/");
    assert src_block_end != -1, f"src subtree not fully visited: {out}";
    assert assets_enter != -1, f"assets entry missing: {out}";
    assert src_block_end < assets_enter, (
        f"src subtree not finished before assets; "
        f"tiny.py at {src_block_end}, enter assets at {assets_enter}\n{out}"
    );

    # Likewise docs must come AFTER assets (the sibling declared
    # after it in the visit order should still be deferred until
    # assets is done -- DFS guarantees leftmost subtree completes).
    logo_idx = out.find("logo.png");
    docs_idx = readme_enter;
    assert logo_idx != -1 and docs_idx != -1, f"missing markers: {out}";
    assert logo_idx < docs_idx, (
        f"assets subtree not finished before docs; "
        f"logo.png at {logo_idx}, enter docs at {docs_idx}\n{out}"
    );
}

test "only files over 100 KB are flagged LARGE" {
    project = build_tree();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn DeepAuditor();
    }
    out = buf.getvalue();

    # Files >100 KB get the LARGE tag in their per-file print line.
    assert "engine.py (240 KB) <-- LARGE" in out, (
        f"engine.py should be flagged LARGE: {out}"
    );
    assert "logo.png (310 KB) <-- LARGE" in out, (
        f"logo.png should be flagged LARGE: {out}"
    );
    assert "notes.md (500 KB) <-- LARGE" in out, (
        f"notes.md should be flagged LARGE: {out}"
    );

    # Files <=100 KB must NOT carry the LARGE tag.
    assert "main.py (12 KB)" in out, f"main.py line missing: {out}";
    assert "<-- LARGE" not in out.split("main.py")[1].split("\n")[0], (
        f"main.py (12 KB) wrongly flagged: {out}"
    );
    assert "<-- LARGE" not in out.split("tiny.py")[1].split("\n")[0], (
        f"tiny.py (1 KB) wrongly flagged: {out}"
    );
    assert "<-- LARGE" not in out.split("README.md")[1].split("\n")[0], (
        f"README.md (4 KB) wrongly flagged: {out}"
    );
}

test "big_files collector lists only oversized entries" {
    project = build_tree();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn DeepAuditor();
    }

    expected = [
        "engine.py (240 KB)",
        "logo.png (310 KB)",
        "notes.md (500 KB)"
    ];
    assert res.big_files == expected, (
        f"big_files mismatch: got {res.big_files}, expected {expected}"
    );
    assert len(res.big_files) == 3, (
        f"expected exactly 3 flagged files, got {len(res.big_files)}"
    );
}

test "enter lines are indented by nesting depth" {
    project = build_tree();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn DeepAuditor();
    }
    out = buf.getvalue();

    # project/ is depth 1 (no indent), src/ assets/ docs/ are depth 2.
    assert "enter project/" in out, f"project entry missing: {out}";
    assert "  enter src/" in out, f"src entry not indented one level: {out}";
    assert "  enter assets/" in out, f"assets entry not indented one level: {out}";
    assert "  enter docs/" in out, f"docs entry not indented one level: {out}";

    # No deeper directories exist, so no 4-space indent should appear.
    assert "    enter" not in out, (
        f"unexpected deeper indent in trail: {out}"
    );
}

test "boundary file at exactly 100 KB is not flagged" {
    project = Folder(name="project");
    boundary = FileNode(name="boundary.bin", kb=100);
    oversized = FileNode(name="huge.bin", kb=101);
    project +>: Contains() :+> boundary;
    project +>: Contains() :+> oversized;
    root ++> project;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn DeepAuditor();
    }
    out = buf.getvalue();

    # 100 KB is the threshold; the spec says "larger than 100 KB",
    # so exactly 100 must NOT be flagged, 101 must be.
    boundary_line = [ln for ln in out.split("\n") if "boundary.bin" in ln][0];
    huge_line = [ln for ln in out.split("\n") if "huge.bin" in ln][0];
    assert "<-- LARGE" not in boundary_line, (
        f"100 KB boundary file wrongly flagged: {boundary_line}"
    );
    assert "<-- LARGE" in huge_line, (
        f"101 KB file not flagged: {huge_line}"
    );
    assert res.big_files == ["huge.bin (101 KB)"], (
        f"big_files wrong at boundary: {res.big_files}"
    );
}

