"""Tests for the Auditor walker: depth-first trail, FLAG threshold, and ordering."""

import io;
import from contextlib { redirect_stdout }


def build_project {
    project = Folder(name="project");
    src = Folder(name="src");
    docs = Folder(name="docs");
    extras = Folder(name="assets");

    root +>:Contains:+> project;
    project +>:Contains:+> src;
    project +>:Contains:+> docs;
    project +>:Contains:+> extras;

    src +>:Contains:+> File(name="main.jac", size=2048);
    src +>:Contains:+> File(name="huge.bin", size=512000);
    src +>:Contains:+> File(name="util.jac", size=8192);

    docs +>:Contains:+> File(name="readme.md", size=4096);
    docs +>:Contains:+> File(name="guide.md", size=1536);

    extras +>:Contains:+> File(name="tiny.txt", size=128);
    extras +>:Contains:+> File(name="big.log", size=204800);

    return [project, src, docs, extras];
}


test "flagged files exceed 100KB threshold" {
    build_project();

    buf = io.StringIO();
    out_str = "";
    a = Auditor();
    with redirect_stdout(buf) {
        root spawn a;
        out_str = buf.getvalue();
    }

    # huge.bin (512000 B) and big.log (204800 B) must be flagged.
    assert "[FILE] huge.bin (512000 B) [FLAG]" in out_str, f"huge.bin not flagged: {out_str}";
    assert "[FILE] big.log (204800 B) [FLAG]" in out_str, f"big.log not flagged: {out_str}";
    # Files under the threshold must NOT be flagged.
    assert "[FILE] main.jac (2048 B) [ok]" in out_str, f"main.jac mislabeled: {out_str}";
    assert "[FILE] tiny.txt (128 B) [ok]" in out_str, f"tiny.txt mislabeled: {out_str}";
}


test "every folder is entered before moving to the next sibling" {
    build_project();

    buf = io.StringIO();
    out_str = "";
    a = Auditor();
    with redirect_stdout(buf) {
        root spawn a;
        out_str = buf.getvalue();
    }

    # Depth-first: src must be fully entered AND exited before docs is entered.
    src_enter = out_str.find("-- entering src");
    src_exit = out_str.find("[DIR]  src -- exiting");
    docs_enter = out_str.find("-- entering docs");

    assert src_enter >= 0, f"src never entered: {out_str}";
    assert src_exit > src_enter, f"src exit missing: {out_str}";
    assert docs_enter > src_exit, (
        f"docs entered before src finished (DFS violated): "
        f"src_exit={src_exit}, docs_enter={docs_enter}\n{out_str}"
    );

    # Same guarantee for docs -> assets.
    docs_exit = out_str.find("[DIR]  docs -- exiting");
    assets_enter = out_str.find("-- entering assets");
    assert docs_exit > 0 and assets_enter > docs_exit, (
        f"assets entered before docs finished: "
        f"docs_exit={docs_exit}, assets_enter={assets_enter}\n{out_str}"
    );
}


test "trail list mirrors dive order with correct indentation" {
    build_project();

    a = Auditor();
    root spawn a;

    # Trail must contain every folder + every file in DFS order.
    names_in_trail = [t.strip().split()[-1].rstrip("()") for t in a.trail if t.strip()];

    # Index lookups confirm strict order: src subtree is fully traversed
    # before docs, and docs before assets.
    def first_idx(name: str) -> int {
        for (i, t) in enumerate(a.trail) {
            if name in t {
                return i;
            }
        }
        return -1;
    }

    src_idx = first_idx("src");
    huge_idx = first_idx("huge.bin");
    util_idx = first_idx("util.jac");
    docs_idx = first_idx("docs");
    assets_idx = first_idx("assets");

    assert src_idx >= 0 and huge_idx > src_idx and util_idx > huge_idx, (
        f"src subtree out of order: {a.trail}"
    );
    assert docs_idx > util_idx, (
        f"docs must come after src fully traversed: {a.trail}"
    );
    assert assets_idx > first_idx("guide.md"), (
        f"assets must come after docs fully traversed: {a.trail}"
    );

    # Indentation must grow with depth (src is one level deeper than project).
    src_line = [t for t in a.trail if "[DIR]  src" in t][0];
    project_line = [t for t in a.trail if "[DIR]  project" in t][0];
    assert src_line.startswith("  ") and not project_line.startswith("  "), (
        f"depth indent wrong: project={project_line!r}, src={src_line!r}"
    );
}


