import from contextlib { redirect_stdout }

def trace_capture {
    buf = io.StringIO();
    root spawn Tracer();
    with redirect_stdout(buf) {
        root spawn Tracer();
    }
    return buf.getvalue();
}

test "wave headers printed in order" {
    root ++> Person(name="Alice", infected=True);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Tracer();
    }
    out = buf.getvalue();
    w1 = out.find("--- Wave 1");
    w2 = out.find("--- Wave 2");
    w3 = out.find("--- Wave 3");
    assert w1 != -1, f"missing Wave 1: {out}";
    assert w2 != -1, f"missing Wave 2: {out}";
    assert w3 != -1, f"missing Wave 3: {out}";
    assert w1 < w2 < w3, f"waves out of order: w1={w1} w2={w2} w3={w3}";
}

test "level by level BFS ordering" {
    p0 = Person(name="Alice", infected=True);
    p1 = Person(name="Bob");
    p2 = Person(name="Carol");
    p3 = Person(name="Dave");
    p4 = Person(name="Eve");
    p5 = Person(name="Frank");
    p6 = Person(name="Grace");
    root ++> p0;
    p0 +>:Contact(weight=1):+> p1;
    p0 +>:Contact(weight=1):+> p2;
    p1 +>:Contact(weight=2):+> p3;
    p1 +>:Contact(weight=2):+> p4;
    p2 +>:Contact(weight=2):+> p5;
    p4 +>:Contact(weight=3):+> p6;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Tracer();
    }
    out = buf.getvalue();
    # Wave 1: Alice
    assert "Contacting Alice (initial exposure)" in out, f"missing wave 1 contact: {out}";
    # Wave 2 contacts must appear before Wave 3 contacts.
    bob_pos = out.find("Contacting Bob");
    carol_pos = out.find("Contacting Carol");
    dave_pos = out.find("Contacting Dave");
    eve_pos = out.find("Contacting Eve");
    frank_pos = out.find("Contacting Frank");
    grace_pos = out.find("Contacting Grace");
    assert bob_pos != -1 and carol_pos != -1, f"missing wave 2 contacts: {out}";
    assert dave_pos != -1 and eve_pos != -1 and frank_pos != -1 and grace_pos != -1, f"missing wave 3 contacts: {out}";
    # All wave-2 contacts before any wave-3 contact.
    assert bob_pos < dave_pos, f"Bob should come before Dave: {out}";
    assert bob_pos < eve_pos, f"Bob should come before Eve: {out}";
    assert bob_pos < frank_pos, f"Bob should come before Frank: {out}";
    assert bob_pos < grace_pos, f"Bob should come before Grace: {out}";
    assert carol_pos < dave_pos, f"Carol should come before Dave: {out}";
    assert carol_pos < eve_pos, f"Carol should come before Eve: {out}";
    assert carol_pos < frank_pos, f"Carol should come before Frank: {out}";
    assert carol_pos < grace_pos, f"Carol should come before Grace: {out}";
}

