"""Tests for wave-by-wave contact tracing."""

import io;
import from contextlib { redirect_stdout }

test "wave 0 starts with patient zero" {
    root ++> Person(name="Patient Zero");
    root +>:Contact(day=1):+> Person(name="Alice");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        WaveRunner() spawn root;
    }
    out = buf.getvalue();

    assert "Wave 0" in out, f"expected Wave 0 in output: {out!r}";
    assert "Patient Zero" in out, f"expected Patient Zero in output: {out!r}";
    assert "--- Contact trace (wave by wave) ---" in out, f"missing header: {out!r}";
}

test "exposed persons carry the wave they were discovered in" {
    p0 = Person(name="Patient Zero");
    p1 = Person(name="Alice");
    p2 = Person(name="Bob");

    root +>:Contact(day=1):+> p0;
    p0 +>:Contact(day=1):+> p1;
    p0 +>:Contact(day=1):+> p2;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        WaveRunner() spawn root;
    }
    out = buf.getvalue();

    assert "Wave 0: Patient Zero exposed" in out, f"missing wave 0 line: {out!r}";
    assert "Wave 1: Alice exposed" in out, f"missing Alice wave 1: {out!r}";
    assert "Wave 1: Bob exposed" in out, f"missing Bob wave 1: {out!r}";

    # wave 2 should NOT appear — Alice/Bob are leaves with no outgoing contacts
    assert "Wave 2" not in out, f"unexpected wave 2 in output: {out!r}";
}

test "second wave only begins after first wave finishes" {
    p0 = Person(name="Patient Zero");
    p1 = Person(name="Alice");
    p3 = Person(name="Carol");
    p4 = Person(name="Dave");

    # tree: root -> P0 (w0) -> P1 (w1) -> P3,P4 (w2)
    root +>:Contact(day=1):+> p0;
    p0 +>:Contact(day=1):+> p1;
    p1 +>:Contact(day=2):+> p3;
    p1 +>:Contact(day=2):+> p4;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        WaveRunner() spawn root;
    }
    out = buf.getvalue();

    assert "Wave 0: Patient Zero exposed" in out, f"missing wave 0: {out!r}";
    assert "Wave 1: Alice exposed" in out, f"missing wave 1: {out!r}";
    assert "Wave 2: Carol exposed" in out, f"missing Carol wave 2: {out!r}";
    assert "Wave 2: Dave exposed" in out, f"missing Dave wave 2: {out!r}";

    # Wave ordering: P0 line must appear before Alice, Alice before Carol/Dave
    idx_p0 = out.find("Patient Zero");
    idx_alice = out.find("Alice exposed");
    idx_carol = out.find("Carol exposed");
    idx_dave = out.find("Dave exposed");
    assert idx_p0 < idx_alice, f"wave 0 should print before wave 1: {out!r}";
    assert idx_alice < idx_carol, f"wave 1 should print before wave 2 (Carol): {out!r}";
    assert idx_alice < idx_dave, f"wave 1 should print before wave 2 (Dave): {out!r}";
}

test "multi-fan-out then deeper chain still waves correctly" {
    # root -> P0 -> P1, P2 -> P3, P4, P5, P6
    # and P3 -> P5 (a re-contact). P5 should still appear once and at
    # the earliest wave it is first reached (wave 2 via P2).
    p0 = Person(name="Patient Zero");
    p1 = Person(name="Alice");
    p2 = Person(name="Bob");
    p3 = Person(name="Carol");
    p4 = Person(name="Dave");
    p5 = Person(name="Eve");
    p6 = Person(name="Frank");

    root +>:Contact(day=1):+> p0;
    p0 +>:Contact(day=1):+> p1;
    p0 +>:Contact(day=1):+> p2;
    p1 +>:Contact(day=2):+> p3;
    p1 +>:Contact(day=2):+> p4;
    p2 +>:Contact(day=2):+> p5;
    p2 +>:Contact(day=2):+> p6;
    p3 +>:Contact(day=3):+> p5;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        WaveRunner() spawn root;
    }
    out = buf.getvalue();

    expected_lines = [
        "Wave 0: Patient Zero exposed",
        "Wave 1: Alice exposed",
        "Wave 1: Bob exposed",
        "Wave 2: Carol exposed",
        "Wave 2: Dave exposed",
        "Wave 2: Eve exposed",
        "Wave 2: Frank exposed",
    ];
    for line in expected_lines {
        assert line in out, f"missing expected line {line!r} in {out!r}";
    }

    # Eve is reached at wave 2 via Bob; the P3->P5 contact at wave 3
    # must NOT cause a second "Eve exposed" line.
    assert out.count("Eve exposed") == 1, f"Eve should be exposed exactly once: {out!r}";
}

test "graph connectivity matches the contact network" {
    p0 = Person(name="Patient Zero");
    p1 = Person(name="Alice");
    p2 = Person(name="Bob");
    p3 = Person(name="Carol");

    root +>:Contact(day=1):+> p0;
    p0 +>:Contact(day=1):+> p1;
    p0 +>:Contact(day=1):+> p2;
    p1 +>:Contact(day=2):+> p3;

    # root has exactly one Contact edge (to P0)
    assert len([root -->]) == 1, f"root should have 1 child: {[root -->]}";

    # P0 has two Contact edges
    assert len([p0 -->]) == 2, f"P0 should have 2 children: {[p0 -->]}";

    # Run the tracer and confirm each person is marked infected
    buf = io.StringIO();
    with redirect_stdout(buf) {
        WaveRunner() spawn root;
    }

    assert p0.infected, "Patient Zero should be marked infected";
    assert p1.infected, "Alice should be marked infected";
    assert p2.infected, "Bob should be marked infected";
    assert p3.infected, "Carol should be marked infected";

    assert p0.wave == 0, f"P0 wave should be 0, got {p0.wave}";
    assert p1.wave == 1, f"P1 wave should be 1, got {p1.wave}";
    assert p2.wave == 1, f"P2 wave should be 1, got {p2.wave}";
    assert p3.wave == 2, f"P3 wave should be 2, got {p3.wave}";
}

"""Regression tests for the pipeline tracer program."""

import io;
import from contextlib { redirect_stdout }

test "tracer logs each valve along the route" {
    root ++> Valve(name="Intake", pressure=4.2);
    intake = [root -->][0];
    intake +>: Pipe(capacity=100) :+> Valve(name="Splitter", pressure=3.1);
    splitter = [intake ->:Pipe:->][0];
    splitter +>: Pipe(capacity=40) :+> Valve(name="FilterA", pressure=2.0);
    filter_a = [splitter ->:Pipe:->][0];
    filter_a +>: Pipe(capacity=10) :+> Valve(name="Cap", pressure=1.1);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Tracer();
    }
    out = buf.getvalue();

    assert "pressure 4.2 bar at valve Intake" in out, f"missing Intake pressure line: {out}";
    assert "pressure 3.1 bar at valve Splitter" in out, f"missing Splitter pressure line: {out}";
    assert "pressure 2.0 bar at valve FilterA" in out, f"missing FilterA pressure line: {out}";
    assert "pressure 1.1 bar at valve Cap" in out, f"missing Cap pressure line: {out}";
    assert res.route == ["Intake", "Splitter", "FilterA", "Cap"], f"route order wrong: {res.route}";
}

test "tracer notes the dead end gracefully without raising" {
    root ++> Valve(name="Intake", pressure=4.2);
    intake = [root -->][0];
    intake +>: Pipe(capacity=100) :+> Valve(name="Cap", pressure=1.1);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Tracer();
    }
    out = buf.getvalue();

    assert "dead end at Cap" in out, f"missing dead-end notice for Cap: {out}";
    assert res.dead_ends == 1, f"expected 1 dead end, got {res.dead_ends}";
    assert "Route: Intake -> Cap" in out, f"summary route wrong: {out}";
    assert "Dead ends hit: 1" in out, f"summary dead-end count wrong: {out}";
}

test "tracer walks past dead ends to reach downstream valves" {
    root ++> Valve(name="Intake", pressure=4.2);
    intake = [root -->][0];
    intake +>: Pipe(capacity=80) :+> Valve(name="Stub", pressure=3.5);
    intake +>: Pipe(capacity=80) :+> Valve(name="Main", pressure=3.4);
    main = [intake ->:Pipe:->][1];
    main +>: Pipe(capacity=30) :+> Valve(name="Filter", pressure=2.1);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Tracer();
    }
    out = buf.getvalue();

    assert "dead end at Stub" in out, f"missing dead-end notice for Stub: {out}";
    assert "dead end at Filter" in out, f"missing dead-end notice for Filter: {out}";
    assert res.dead_ends == 2, f"expected 2 dead ends, got {res.dead_ends}";
    assert "Stub" in res.route, f"Stub should appear in route: {res.route}";
    assert "Filter" in res.route, f"Filter should appear in route: {res.route}";
    assert "Dead ends hit: 2" in out, f"summary dead-end count wrong: {out}";
}

test "tracer reports zero dead ends when every valve has a downstream pipe" {
    root ++> Valve(name="Intake", pressure=4.2);
    intake = [root -->][0];
    intake +>: Pipe(capacity=100) :+> Valve(name="Splitter", pressure=3.1);
    splitter = [intake ->:Pipe:->][0];
