"""Tests for the water pipeline tracer."""

import io;
import from contextlib { redirect_stdout }

def build_sample_graph {
    intake = Valve(name="Intake", kind="intake");
    valve_a = Valve(name="Junction-A", kind="junction");
    valve_b = Valve(name="Junction-B", kind="junction");
    stub_c = Valve(name="Stub-C", kind="stub");
    stub_d = Valve(name="Stub-D", kind="stub");

    root ++> intake
        +>:Pipe(label="p1"):+> valve_a
        +>:Pipe(label="p2"):+> valve_b
        +>:Pipe(label="p3"):+> stub_c;

    intake +>:Pipe(label="p4"):+> stub_d;

    return intake;
}

test "sample graph: route contains all reachable valves" {
    intake = build_sample_graph();

    buf = io.StringIO();
    tracer = Tracer();
    with redirect_stdout(buf) {
        res = intake spawn tracer;
    }

    assert "Intake" in res.route, f"route missing Intake: {res.route}";
    assert "Junction-A" in res.route, f"route missing Junction-A: {res.route}";
    assert "Junction-B" in res.route, f"route missing Junction-B: {res.route}";
    assert "Stub-C" in res.route, f"route missing Stub-C: {res.route}";
    assert "Stub-D" in res.route, f"route missing Stub-D: {res.route}";
}

test "sample graph: counts both capped stub dead ends" {
    intake = build_sample_graph();

    buf = io.StringIO();
    tracer = Tracer();
    with redirect_stdout(buf) {
        res = intake spawn tracer;
    }

    assert res.dead_ends == 2, f"expected 2 dead ends, got {res.dead_ends}";
}

test "sample graph: capped stub dead end is reported with marker" {
    intake = build_sample_graph();

    buf = io.StringIO();
    tracer = Tracer();
    with redirect_stdout(buf) {
        res = intake spawn tracer;
    }
    out = buf.getvalue();

    assert "dead end at capped stub Stub-C" in out, f"missing Stub-C dead end message: {out}";
    assert "dead end at capped stub Stub-D" in out, f"missing Stub-D dead end message: {out}";
}

test "junction with no outgoing pipe is also a dead end" {
    # A lone junction (no outgoing Pipe) should still be reported as a dead end,
    # but NOT counted as a capped stub.
    intake = Valve(name="Intake", kind="intake");
    lonely = Valve(name="Lonely-Junction", kind="junction");
    root ++> intake +>:Pipe(label="p1"):+> lonely;

    buf = io.StringIO();
    tracer = Tracer();
    with redirect_stdout(buf) {
        res = intake spawn tracer;
    }
    out = buf.getvalue();

    assert res.dead_ends == 1, f"expected 1 dead end for no-outgoing junction, got {res.dead_ends}";
    assert "dead end at Lonely-Junction (no outgoing pipe)" in out, f"missing junction dead end msg: {out}";
    assert "capped stub Lonely-Junction" not in out, f"lonely junction should NOT be labeled capped stub: {out}";
}

test "intake with no pipes at all is a dead end with empty downstream" {
    # Pure edge case: intake alone with nothing else.
    intake = Valve(name="Intake", kind="intake");
    root ++> intake;

    buf = io.StringIO();
    tracer = Tracer();
    with redirect_stdout(buf) {
        res = intake spawn tracer;
    }
    out = buf.getvalue();

    # Route should contain just the intake.
    assert res.route == ["Intake"], f"expected route ['Intake'], got {res.route}";
    # Intake with no pipes should be reported as a dead end.
    assert res.dead_ends == 1, f"expected 1 dead end for pipe-less intake, got {res.dead_ends}";
    assert "dead end at Intake (no outgoing pipe)" in out, f"missing intake dead end msg: {out}";
}

"""Tests for the Pipeline tracer walker."""

import io;
import from contextlib { redirect_stdout }

test "intake to capped leaf via b records dead end" {
    root ++> Valve(label="Intake");
    intake = [root -->][0];
    a = Valve(label="Junction-A");
    b = Valve(label="Junction-B");
    cap = Valve(label="Cap-Branch", capped=True);
    intake +>:Pipe(diameter="12in"):+> a;
    a +>:Pipe(diameter="8in"):+> b;
    b +>:Pipe(diameter="4in"):+> cap;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        tracer = Tracer();
        root spawn tracer;
    }
    out = buf.getvalue();

    assert "[DEAD END] capped stub at Cap-Branch" in out, f"expected dead-end marker, got: {out}";
    assert tracer.route == ["Intake", "Junction-A", "Junction-B", "Cap-Branch"], f"route was {tracer.route}";
    assert tracer.dead_ends == 1, f"dead_ends was {tracer.dead_ends}";
}

test "fully capped intake is a single dead end with no further traversal" {
    root ++> Valve(label="Intake", capped=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        tracer = Tracer();
        root spawn tracer;
    }
    out = buf.getvalue();

    assert "[DEAD END] capped stub at Intake" in out, f"expected dead-end marker, got: {out}";
    assert tracer.route == ["Intake"], f"route was {tracer.route}";
    assert tracer.dead_ends == 1, f"dead_ends was {tracer.dead_ends}";
}

test "branching pipe to a leaf with no outgoing edge is not a dead end" {
    root ++> Valve(label="Intake");
    intake = [root -->][0];
    leaf = Valve(label="OpenLeaf");
    intake +>:Pipe(diameter="12in"):+> leaf;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        tracer = Tracer();
        root spawn tracer;
    }
    out = buf.getvalue();

    assert "[DEAD END]" not in out, f"unexpected dead-end marker: {out}";
    assert tracer.route == ["Intake", "OpenLeaf"], f"route was {tracer.route}";
    assert tracer.dead_ends == 0, f"dead_ends was {tracer.dead_ends}";
    assert len([root -->]) == 1, "intake should still have its single outgoing pipe";
}

test "full demo graph hits two dead ends across two branches" {
    intake = Valve(label="Intake");
    a = Valve(label="Junction-A");
    b = Valve(label="Junction-B");
    c = Valve(label="Junction-C");
