"""Test annex for Pipeline tracer."""

import io;
import from contextlib { redirect_stdout }

def run_tracer(graph_root) {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = graph_root spawn Tracer();
    }
    return (buf.getvalue(), res);
}

test "tracer prints labels of every valve it traverses" {
    intake = Valve(label="Intake");
    junction_a = Valve(label="Junction-A");
    junction_b = Valve(label="Junction-B");
    main_out = Valve(label="Main-Outlet");
    root ++> intake
