"""Test annex for the pipeline Tracer walker."""

import io;
import from contextlib { redirect_stdout }

# Helper to capture the printed route/dead-ends summary plus any inline messages.
def run_tracer(graph_root) {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = graph_root spawn Tracer();
    }
    return (buf.getvalue(), res);
}

test "linear chain reaches capped end and prints summary" {
    root ++> Valve(label="Intake")
        ++> Valve(label="Junction-A")
        ++> Valve(label="Capped-North", capped=True);
    (out, res) = run_tracer(root);

    assert "Dead end at Capped-North" in out, f"expected capped marker, got {out}";
    assert "Route: Intake -> Junction-A -> Capped-North" in out, f"missing route: {out}";
    assert "Dead ends hit: 1" in out, f"missing summary: {out}";

    assert res.dead_ends == 1, f"expected 1 dead end, got {res.dead_ends}";
    assert res.route == ["Intake", "Junction-A", "Capped-North"], f"bad route: {res.route}";
}

test "capped dead end does not stall walker" {
    # A single capped valve must terminate gracefully with a recorded route.
    root ++> Valve(label="Intake")
        ++> Valve(label="Stub", capped=True);
    (out, res) = run_tracer(root);

    assert "Dead end at Stub" in out, f"no dead-end notice: {out}";
    assert "Route: Intake -> Stub" in out, f"route missing: {out}";
    assert "Dead ends hit: 1" in out, f"summary missing: {out}";
    assert res.dead_ends == 1, f"count wrong: {res.dead_ends}";
}

test "non-capped terminal valve is not counted as dead end" {
    # A valve with no children and capped=False is an unvisited terminal stub
    # in this program: no capped marker, dead_ends stays at 0.
    root ++> Valve(label="Intake")
        ++> Valve(label="Open-End", capped=False);
    (out, res) = run_tracer(root);

    assert "Dead end at Open-End" not in out, f"unexpected dead-end marker: {out}";
    assert "Dead ends hit: 0" in out, f"expected zero dead ends: {out}";
    assert "Route: Intake -> Open-End" in out, f"route missing: {out}";
    assert res.dead_ends == 0, f"count wrong: {res.dead_ends}";
    assert res.route == ["Intake", "Open-End"], f"route wrong: {res.route}";
}

test "two capped branches yield two dead ends in order" {
    # Mirror the demo graph: two capped stubs reachable from the intake chain.
    root ++> Valve(label="Intake")
        ++> Valve(label="Junction-A")
        ++> Valve(label="Branch-1")
        ++> Valve(label="Junction-B")
        ++> Valve(label="Capped-North", capped=True)
        ++> Valve(label="Junction-C")
        ++> Valve(label="Capped-South", capped=True);
    (out, res) = run_tracer(root);

    assert "Dead end at Capped-North" in out, f"missing first marker: {out}";
    assert "Dead end at Capped-South" in out, f"missing second marker: {out}";
    assert "Dead ends hit: 2" in out, f"summary wrong: {out}";

    assert res.dead_ends == 2, f"expected 2, got {res.dead_ends}";
    assert "Capped-North" in res.route, f"north not in route: {res.route}";
    assert "Capped-South" in res.route, f"south not in route: {res.route}";

    # Confirm the graph was actually built as a single chain.
    assert len([root-->]) == 1, f"intake should have one direct child, got {len([root-->])}";
}

test "intake with no outgoing pipe records just the start" {
