    assert "flow -> Reservoir" in out, f"missing Reservoir flow line: {out}";
    assert "[DEAD END]" not in out, f"unexpected dead end in linear chain: {out}";

    assert res.route == ["Intake", "Junction-A", "Junction-B", "Reservoir"],
        f"unexpected route: {res.route}";
    assert res.dead_ends == [], f"expected no dead ends, got {res.dead_ends}";
