test "tracer walks full branching pipeline and summarizes dead ends" {
    intake = Valve(name="Intake");
    junction_a = Valve(name="Junction-A");
    junction_b = Valve(name="Junction-B");
    capped_north = Valve(name="NorthStub", capped=True);
    capped_south = Valve(name="SouthStub", capped=True);
    reservoir = Valve(name="Reservoir");

    root ++> intake ++> junction_a ++> junction_b;
    junction_a ++> capped_north;
    junction_b ++> capped_south;
    junction_b ++> reservoir;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Tracer();
    }
    out = buf.getvalue();

    # Tracer walks the chain as built: Intake -> Junction-A -> Junction-B.
    # Junction-B has two outgoing edges; Tracer visits the first ([-->] picks
    # one) and must terminate on whichever it picks -- capped_north (capped)
    # or reservoir (no outgoing past). In either case the walk stops there,
    # never reaching the OTHER child of Junction-B.
    assert "[DEAD END]" in out, f"expected at least one dead end marker: {out}";
    assert res.route[0] == "Intake", f"route must start at Intake: {res.route}";
    assert res.route[1] == "Junction-A", f"route must pass Junction-A: {res.route}";
    assert res.route[2] == "Junction-B", f"route must pass Junction-B: {res.route}";

    # Termination: the walker stopped at the visited child. The dead end
    # recorded must be a stub node, not the reservoir.
    assert len(res.dead_ends) == 1,
        f"expected exactly one dead end on this branch, got {res.dead_ends}";
    assert res.dead_ends[0] in ["NorthStub", "SouthStub", "Reservoir"],
        f"unexpected dead end: {res.dead_ends}";
}

