"""Tests for the build-system diamond deduplication auditor."""

import io;
import from contextlib { redirect_stdout }

# Helper: build the diamond DAG and return the nodes + root.
def make_diamond {
    app = Task(name="build-app", minutes=5);
    web = Task(name="compile-web", minutes=8);
    api = Task(name="compile-api", minutes=12);
    core = Task(name="link-core", minutes=20);

    root ++> app;
    app +>: Needs() :+> web;
    app +>: Needs() :+> api;
    web +>: Needs() :+> core;
    api +>: Needs() :+> core;

    return [app, web, api, core];
}

test "diamond: core counted exactly once" {
    nodes = make_diamond();
    app = nodes[0];
    web = nodes[1];
    api = nodes[2];
    core = nodes[3];

    # Sanity check the diamond shape before running the walker.
    assert len([root-->]) == 1, f"root should have one direct child, got {len([root-->])}";
    assert len([app-->]) == 2, f"app should have 2 dependents, got {len([app-->])}";
    assert core in [web ->:Needs:->], "web should depend on core";
    assert core in [api ->:Needs:->], "api should depend on core";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Auditor();
    }
    out = buf.getvalue();

    # The shared library must be audited once even though two paths reach it.
    assert res.total_minutes == 5 + 8 + 12 + 20, f"got total {res.total_minutes}";
    assert len(res.seen) == 4, f"expected 4 unique tasks, got {len(res.seen)}";
    assert jid(core) in res.seen, "core should be in the seen set";
    assert "auditing link-core" in out, f"core must be audited; out={out!r}";
    assert "already audited via another path" in out, f"diamond re-entry should be reported; out={out!r}";
    assert res.double_enqueue_avoided == True, "the seen-guard should have fired";
}

test "linear chain: every task counted, no diamond" {
    a = Task(name="a", minutes=3);
    b = Task(name="b", minutes=7);
    c = Task(name="c", minutes=11);

    root ++> a;
    a +>: Needs() :+> b;
    b +>: Needs() :+> c;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Auditor();
    }
    out = buf.getvalue();

    assert res.total_minutes == 3 + 7 + 11, f"got total {res.total_minutes}";
    assert len(res.seen) == 3, f"got {len(res.seen)} unique tasks";
    assert res.double_enqueue_avoided == False, "no diamond in a linear chain";
    assert "already audited via another path" not in out, f"no re-entry expected; out={out!r}";
    assert "3 unique task(s)" in out, f"summary missing; out={out!r}";
}

test "deep diamond: three parents share one dependency" {
    top = Task(name="top", minutes=2);
    left = Task(name="left", minutes=4);
    mid = Task(name="mid", minutes=6);
    right = Task(name="right", minutes=8);
    shared = Task(name="shared-lib", minutes=50);

    root ++> top;
    top +>: Needs() :+> left;
    top +>: Needs() :+> mid;
    top +>: Needs() :+> right;
    left +>: Needs() :+> shared;
    mid +>: Needs() :+> shared;
    right +>: Needs() :+> shared;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Auditor();
    }
    out = buf.getvalue();

    # Three independent paths each enqueue `shared`; only the first counts it.
    assert res.total_minutes == 2 + 4 + 6 + 8 + 50, f"got total {res.total_minutes}";
    assert len(res.seen) == 5, f"expected 5 unique tasks, got {len(res.seen)}";
    assert jid(shared) in res.seen, "shared must be in seen";
    assert out.count("auditing shared-lib") == 1, f"shared must be audited exactly once; out={out!r}";
    assert out.count("already audited via another path") == 2, f"two re-entries expected; out={out!r}";
    assert res.double_enqueue_avoided == True, "seen-guard must fire for the deep diamond";
}

test "diamond + extra independent subtree" {
    # Diamond side (shared=core), plus a sibling subtree that doesn't share.
    app = Task(name="build-app", minutes=5);
    web = Task(name="compile-web", minutes=8);
