import io;
import from contextlib { redirect_stdout }

# Build the diamond-shaped dependency graph described in the program:
# app -> ui  -> core_lib
#         \-> net -> core_lib
# app -> packager -> core_lib
# core_lib and packager are shared (diamond deduplication targets).

def make_diamond() -> tuple {
    app = BuildTask(title="compile_app", minutes=10);
    ui = BuildTask(title="compile_ui", minutes=15);
    net = BuildTask(title="compile_net", minutes=20);
    core_lib = BuildTask(title="build_core_lib", minutes=30);
    packager = BuildTask(title="package_release", minutes=5);
    root ++> app;
    app +>:DependsOn:+> ui;
    app +>:DependsOn:+> net;
    app +>:DependsOn:+> packager;
    ui +>:DependsOn:+> core_lib;
    net +>:DependsOn:+> core_lib;
    packager +>:DependsOn:+> core_lib;
    return (root, app, ui, net, core_lib, packager);
}

test "diamond counts each task exactly once and sums minutes" {
    (rt, app, ui, net, core_lib, packager) = make_diamond();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = BuildAuditor();
        rt spawn auditor;
    }
    out = buf.getvalue();
    # 5 unique tasks, total minutes = 10 + 15 + 20 + 30 + 5 = 80
    assert auditor.total_minutes == 80, f"expected 80 total minutes, got {auditor.total_minutes}";
    assert len(auditor.path) == 5, f"expected 5 unique tasks audited, got {len(auditor.path)}";
    assert "build_core_lib" in auditor.path, f"core_lib missing from path: {auditor.path}";
    assert "compile_app" in auditor.path, f"app missing from path: {auditor.path}";
    assert "compile_ui" in auditor.path, f"ui missing from path: {auditor.path}";
    assert "compile_net" in auditor.path, f"net missing from path: {auditor.path}";
    assert "package_release" in auditor.path, f"packager missing from path: {auditor.path}";
    assert "Audit complete: 5 unique tasks, 80 total build minutes" in out, f"missing summary: {out}";
}

test "shared core_lib is reported as skipped on second visit" {
    (rt, app, ui, net, core_lib, packager) = make_diamond();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = BuildAuditor();
        rt spawn auditor;
    }
    out = buf.getvalue();
    # core_lib is reachable via ui, net, and packager — only first visit audits it.
    assert "auditing: build_core_lib (+30 min)" in out, f"first audit of core_lib missing: {out}";
    skip_count = out.count("skip (already audited): build_core_lib");
    assert skip_count == 2, f"expected 2 skip messages for core_lib (net, packager paths), got {skip_count}: {out}";
}

test "no duplicate titles recorded in audited_titles" {
    (rt, app, ui, net, core_lib, packager) = make_diamond();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = BuildAuditor();
        rt spawn auditor;
    }
    # audited_titles is the dedup bookkeeping list — every entry must be unique.
    assert len(auditor.audited_titles) == 5, f"expected 5 audited titles, got {auditor.audited_titles}";
    assert len(set(auditor.audited_titles)) == 5, f"duplicate titles present: {auditor.audited_titles}";
    assert auditor.already_audited("build_core_lib") == True, "already_audited should return True after visit";
    assert auditor.already_audited("nonexistent_task") == False, "already_audited should return False for unseen title";
}

test "starting banner and path order printed" {
    (rt, app, ui, net, core_lib, packager) = make_diamond();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = BuildAuditor();
        rt spawn auditor;
    }
    out = buf.getvalue();
    assert "Starting build dependency audit" in out, f"missing start banner: {out}";
    # path order records the audit order; the first task audited must be compile_app
