    assert auditor.path[0] == "compile_app", f"expected compile_app first, got {auditor.path[0]}";
    list_str = out.split("Path order: ", 1)[1].split("\n", 1)[0];
    assert list_str.count("'build_core_lib'") == 1, f"core_lib appears multiple times in printed path: {list_str}";
}

