"""Tests for the warehouse inventory audit walker."""

import io;
import from contextlib { redirect_stdout }

test "Auditor assigns stable unique ids and persists every item" {
    root ++> Item(sku="WID-1", stock=10);
    root ++> Item(sku="WID-2", stock=5)
        ++> Item(sku="WID-3", stock=0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Auditor();
    }
    out = buf.getvalue();

    items = [root-->];
    assert len(items) == 3, f"expected 3 root children, got {len(items)}";

    for it in items {
        assert it.persisted is True, f"item {it.sku} was not persisted";
        assert it.stable_id.startswith("INV-"), (
            f"item {it.sku} got id {it.stable_id}, missing INV- prefix"
        );
        assert it.sku in it.stable_id, (
            f"item {it.sku} stable_id {it.stable_id} missing sku"
        );
    }

    # Stable id format: INV-<sku>-<id(here)>. Verify exact format.
    for it in items {
        expected_suffix = f"-{id(it)}";
        assert it.stable_id.endswith(expected_suffix), (
            f"item {it.sku} stable_id {it.stable_id} "
            f"does not end with {expected_suffix}"
        );
    }

    # Each item must have a distinct stable_id (unique).
    ids = [];
    for it in items {
        ids.append(it.stable_id);
    }
    assert len(set(ids)) == 3, f"stable_ids not unique: {ids}";

    # Output must announce the audit and persist each item.
    assert "Auditing warehouse inventory from root" in out, (
        f"missing audit start banner: {out}"
    );
    assert "persisted WID-1" in out, f"WID-1 not persisted in output: {out}";
    assert "persisted WID-2" in out, f"WID-2 not persisted in output: {out}";
    assert "persisted WID-3" in out, f"WID-3 not persisted in output: {out}";
}

test "Reporter dumps graph structure with persisted state visible" {
    root ++> Item(sku="RPT-1", stock=99);
