test "Chain graph: every link is audited and reported" {
    root ++> Item(sku="CH-1", stock=10)
        ++> Item(sku="CH-2", stock=20)
        ++> Item(sku="CH-3", stock=30);

    assert len([root-->]) == 1, (
        f"root should have exactly 1 direct child in a chain, "
        f"got {len([root-->])}"
    );

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Auditor();
        root spawn Reporter();
    }
    out = buf.getvalue();

    for sku in ["CH-1", "CH-2", "CH-3"] {
        assert f"persisted {sku}" in out, f"{sku} not audited: {out}";
        assert f"sku={sku}" in out, f"{sku} not in dump: {out}";
        assert "persisted=True" in [l for l in out.splitlines()
                                    if f"sku={sku}" in l][0], (
            f"{sku} persisted flag wrong in dump"
        );
    }

    # Walked end-to-end: CH-3's child must have been reached.
    end = [root-->][0];
    deep = [end-->];
    while len(deep) > 0 {
        end = deep[0];
        deep = [end-->];
    }
    assert end.sku == "CH-3", f"walk did not reach chain end: {end.sku}";
    assert end.persisted is True, "chain tail not persisted";
    assert end.stable_id != "", "chain tail missing stable_id";
}

test "Fan-out graph: all direct root children are audited" {
    root ++> Item(sku="FAN-A", stock=1);
    root ++> Item(sku="FAN-B", stock=2);
    root ++> Item(sku="FAN-C", stock=3);
    root ++> Item(sku="FAN-D", stock=4);

    assert len([root-->]) == 4, (
        f"root should have 4 direct children, got {len([root-->])}"
    );

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Auditor();
    }
    out = buf.getvalue();

    for sku in ["FAN-A", "FAN-B", "FAN-C", "FAN-D"] {
        assert f"persisted {sku}" in out, f"{sku} not audited: {out}";
    }

    items = [root-->];
    persisted_count = 0;
    for it in items {
        if it.persisted {
            persisted_count += 1;
        }
    }
    assert persisted_count == 4, (
        f"only {persisted_count}/4 items persisted"
    );
}

"""Tests for the professional networking introduction-chain program."""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

def build_sample_network {
    alice  = Person(name="Alice",  role="PM",        company="Acme");
    bob    = Person(name="Bob",    role="Engineer",  company="Acme");
    carol  = Person(name="Carol",  role="Designer",  company="Acme");
    dave   = Person(name="Dave",   role="CTO",       company="Beta");
    eve    = Person(name="Eve",    role="Recruiter", company="Beta");
    frank  = Person(name="Frank",  role="Investor",  company="Gamma");
    grace  = Person(name="Grace",  role="Founder",   company="Gamma");

    alice +>:Knows(context="same team",   strength=3):+> bob;
    alice +>:Knows(context="project lead", strength=2):+> carol;
    bob   +>:Knows(context="alumni",       strength=2):+> dave;
    carol +>:Knows(context="conference",   strength=1):+> eve;
    dave  +>:Knows(context="advisor",      strength=3):+> frank;
    eve   +>:Knows(context="portfolio",    strength=2):+> grace;
    frank +>:Knows(context="co-founder",   strength=3):+> grace;

    root ++> alice;
    return [alice, bob, carol, dave, eve, frank, grace];
}

def find_name(nodes: list, name: str) {
    for n in nodes {
        if n.name == name {
            return n;
        }
    }
    return None;
}

# ---------------------------------------------------------------------------
# Tests
# ---------------------------------------------------------------------------

test "shortest chain on sample network reaches Grace in 4 hops" {
    nodes = build_sample_network();
    alice = find_name(nodes, "Alice");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        searcher = Connector(target_name="Grace");
        alice spawn searcher;
        reporter = ChainReporter(
            start_name="Alice",
            target_name="Grace",
            parent=searcher.parent,
        );
        reporter spawn root;
    }
    out = buf.getvalue();

    assert searcher.found, "Connector should locate Grace in the sample network";
    assert reporter.path[0] == "Alice", f"chain should start at Alice, got {reporter.path[0]}";
    assert reporter.path[-1] == "Grace", f"chain should end at Grace, got {reporter.path[-1]}";
    assert len(reporter.path) == 5, f"shortest chain must be 4 hops (5 people), got {len(reporter.path)}";
    assert "0. Alice  (start)" in out, f"missing start marker in output: {out}";
    assert "4. Grace  (target)" in out, f"missing target marker in output: {out}";
    assert "Shortest introduction chain from Alice to Grace" in out, f"missing header in output: {out}";
}

test "parent map records only BFS-tree predecessors" {
    nodes = build_sample_network();
    alice = find_name(nodes, "Alice");

    searcher = Connector(target_name="Grace");
    alice spawn searcher;

    assert searcher.found, "target Grace must be reached";
    # Every recorded parent should be a different node that actually appears
    # in the graph (no None / no spurious entries).
    all_names = ["Alice", "Bob", "Carol", "Dave", "Eve", "Frank", "Grace"];
    for (child, par) in searcher.parent.items() {
        assert child in all_names, f"unknown child in parent map: {child}";
        assert par in all_names, f"unknown parent in parent map: {par}";
        assert child != par, f"self-parent recorded for {child}";
    }
    # The immediate predecessor of Grace in the shortest path is Frank
    # (length-4 path Alice -> Bob -> Dave -> Frank -> Grace); BFS guarantees
    # the recorded parent is a valid one-hop introducer.
    assert searcher.parent.get("Grace") in ["Frank", "Eve"], (
        f"Grace's BFS parent should be Frank or Eve, got {searcher.parent.get('Grace')}"
    );
}

test "reports no chain when target is unreachable" {
    # Build a network with two disconnected components; nobody in Alice's
    # component can reach "Zoe".
    alice = Person(name="Alice", role="PM",     company="Acme");
    bob   = Person(name="Bob",   role="Eng",    company="Acme");
    zoe   = Person(name="Zoe",   role="Analyst", company="Delta");
    yann  = Person(name="Yann",  role="PM",     company="Delta");

    alice +>:Knows(context="team"):+> bob;
    zoe  +>:Knows(context="team"):+> yann;

    root ++> alice;
    root ++> zoe;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        searcher = Connector(target_name="Zoe");
        alice spawn searcher;
        reporter = ChainReporter(
            start_name="Alice",
            target_name="Zoe",
            parent=searcher.parent,
        );
        reporter spawn root;
    }
    out = buf.getvalue();

    assert not searcher.found, "Zoe is unreachable from Alice, found must be False";
    assert "No introduction chain from Alice to Zoe" in out, (
        f"missing unreachable-chain message: {out}"
    );
}

test "direct connection produces a two-person chain" {
    # When start and target are linked by a single Knows edge, the chain
    # has exactly two entries.
    alice = Person(name="Alice", role="PM",      company="Acme");
    bob   = Person(name="Bob",   role="Engineer", company="Acme");

    alice +>:Knows(context="same team", strength=3):+> bob;
