    assert searcher.found, "Bob must be reachable directly from Alice";
    assert reporter.path == ["Alice", "Bob"], (
        f"direct connection should yield a 2-person chain, got {reporter.path}"
    );
    assert "0. Alice  (start)" in out, f"missing start marker: {out}";
    assert "1. Bob  (target)" in out, f"missing target marker: {out}";
}

test "start equals target yields a single-person chain" {
    alice = Person(name="Alice", role="PM", company="Acme");
    bob   = Person(name="Bob",   role="Eng", company="Acme");
    alice +>:Knows(context="team"):+> bob;
