"""Tests for the professional networking Connector walker."""

import io;
import from contextlib { redirect_stdout }

# Helper: build the sample network from the program.
def build_sample() {
    alice = Person(name="Alice", role="Engineer");
    bob = Person(name="Bob", role="Designer");
    carol = Person(name="Carol", role="PM");
    dave = Person(name="Dave", role="Founder");
    eve = Person(name="Eve", role="Investor");
    frank = Person(name="Frank", role="Recruiter");

    alice +>:Knows:+> bob;
    bob +>:Knows:+> carol;
    carol +>:Knows:+> dave;
    dave +>:Knows:+> eve;
    alice +>:Knows:+> frank;
    frank +>:Knows:+> eve;

    root ++> alice;
    return [alice, bob, carol, dave, eve, frank];
}

# Helper: run a Connector walker on `start` targeting `target_name`,
# returning the captured stdout.
def run_connector(start: Person, target_name: str) {
    buf = io.StringIO();
    conn = Connector(target=target_name);
    with redirect_stdout(buf) {
        res = start spawn conn;
    }
    return [buf.getvalue(), res];
}

test "shortest chain Alice to Eve via Frank" {
    [alice, _bob, _carol, _dave, _eve, _frank] = build_sample();
    [out, res] = run_connector(alice, "Eve");
    assert res.found == True, f"expected found=True, got {res.found}";
    assert out == "Introduction chain: Alice -> Frank -> Eve\n",
        f"unexpected output: {out!r}";
    # Path length should be 3 (start, hop, target).
    assert len(res.path) == 3,
        f"expected 3 names in path, got {res.path}";
    assert res.path[0] == "Alice", f"path should start at Alice, got {res.path}";
    assert res.path[-1] == "Eve", f"path should end at Eve, got {res.path}";
}

test "shortest chain Alice to Dave goes through Bob and Carol" {
    [alice, _bob, _carol, _dave, _eve, _frank] = build_sample();
    [out, res] = run_connector(alice, "Dave");
    assert res.found == True, f"expected found=True, got {res.found}";
    # Shortest path is Alice -> Bob -> Carol -> Dave (3 hops, 4 names),
    # NOT the longer route Alice -> Frank -> Eve -> Dave.
    assert out == "Introduction chain: Alice -> Bob -> Carol -> Dave\n",
        f"unexpected output: {out!r}";
    assert len(res.path) == 4,
        f"expected 4 names, got {res.path}";
}

test "direct neighbor Bob is one hop from Alice" {
    [alice, _bob, _carol, _dave, _eve, _frank] = build_sample();
    [out, res] = run_connector(alice, "Bob");
    assert res.found == True, f"expected found=True, got {res.found}";
    assert out == "Introduction chain: Alice -> Bob\n",
        f"unexpected output: {out!r}";
    assert len(res.path) == 2, f"expected 2 names, got {res.path}";
}

test "searching from a non-root person still works" {
    [_alice, bob, _carol, _dave, _eve, _frank] = build_sample();
    [out, res] = run_connector(bob, "Eve");
    assert res.found == True, f"expected found=True, got {res.found}";
    # From Bob, the shortest route to Eve is Bob -> Carol -> Dave -> Eve.
    assert out == "Introduction chain: Bob -> Carol -> Dave -> Eve\n",
        f"unexpected output: {out!r}";
    assert len(res.path) == 4, f"expected 4 names, got {res.path}";
}

test "unreachable target leaves found False and prints nothing" {
    [alice, _bob, carol, dave, _eve, _frank] = build_sample();
    # Carol has no outgoing Knows edges to anyone named "Zara".
    [out, res] = run_connector(carol, "Zara");
    assert res.found == False, f"expected found=False, got {res.found}";
    assert out == "", f"expected no output, got {out!r}";
    # Walker still records the starting node in path.
    assert len(res.path) == 1, f"expected path of length 1, got {res.path}";
    assert res.path[0] == "Carol",
        f"expected path to start with Carol, got {res.path}";
}

