"""Tests for the vending-machine FSM walker."""

import io;
import from contextlib { redirect_stdout }

# --- helpers ---------------------------------------------------------------

def _build_machine {
    # Fresh FSM per test. States are detached so transitions point at the
    # same instances we link into the graph (no aliasing surprises).
    idle = State(name="idle");
    waiting = State(name="waiting");
    vend = State(name="vend");

    idle.transitions["coin"] = waiting;
    waiting.transitions["button"] = vend;
    vend.transitions["coin"] = waiting;
    vend.transitions["button"] = vend;

    root ++> idle ++> waiting ++> vend;
    return [idle, waiting, vend];
}

def _run(start: State, inputs: list) -> str {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        ctrl = Controller(inputs=list(inputs));
        start spawn ctrl;
    }
    return buf.getvalue().strip();
}

# --- tests -----------------------------------------------------------------

test "demo sequence ends back in vend after second dispense" {
    (idle, waiting, vend) = _build_machine();
    out = _run(idle, ["coin", "button", "coin", "button"]);
    expected = " | ".join(["idle", "--coin-->", "waiting", "--button-->",
                           "vend", "--coin-->", "waiting", "--button-->",
                           "vend"]);
    assert out == expected, f"demo path mismatch: {out!r}";
}

test "unknown input stops the walk at the current state" {
    (idle, waiting, vend) = _build_machine();
    # 'refund' has no transition from idle -> walker disengages after
    # recording the idle landing.
    out = _run(idle, ["refund"]);
    assert out == "idle", f"expected fail-closed stop at idle, got {out!r}";
}

test "empty input list records start state and stops" {
    (idle, waiting, vend) = _build_machine();
    out = _run(idle, []);
    assert out == "idle", f"empty input should stop at start, got {out!r}";
}

test "graph shape: three states chained from root" {
    (idle, waiting, vend) = _build_machine();
    # root ++> idle ++> waiting ++> vend => root has exactly one direct
    # child; the chain itself has three nodes.
    assert len([root-->]) == 1, f"root should fan to one child, got {len([root-->])}";
    assert idle in [root-->], "root must link to idle";
    assert waiting in [idle-->], "idle must link to waiting";
    assert vend in [waiting-->], "waiting must link to vend";
    assert len([idle-->]) == 1 and len([waiting-->]) == 1, "chain nodes have one outgoing link";
}

test "button self-loop on vend keeps the walk alive" {
    (idle, waiting, vend) = _build_machine();
    # Two consecutive buttons while in vend: second button is a no-op
    # transition vend->vend, so path stays on 'vend'.
    out = _run(idle, ["coin", "button", "button"]);
    expected = " | ".join(["idle", "--coin-->", "waiting",
                           "--button-->", "vend", "--button-->", "vend"]);
    assert out == expected, f"vend self-loop path wrong: {out!r}";
}

"""Test annex for org chart payroll rollup.

Each test builds its own graph and spawns a PayrollAuditor on it. Output
is captured via redirect_stdout so we can assert against the printed
subtree rollups.
"""

import io;
import from contextlib { redirect_stdout }

# Helper to build the canonical sample org from the program. Returns
# (root, ceo, vp_eng, vp_sales, eng_lead, eng1, eng2, sales1).
def build_sample_org() -> tuple {
    ceo = Employee(name="Alice (CEO)", salary=250000.0);
    vp_eng = Employee(name="Bob (VP Eng)", salary=180000.0);
    vp_sales = Employee(name="Carla (VP Sales)", salary=170000.0);
    eng_lead = Employee(name="Dan (Eng Lead)", salary=140000.0);
    eng1 = Employee(name="Eve (Eng1)", salary=120000.0);
    eng2 = Employee(name="Frank (Eng2)", salary=115000.0);
    sales1 = Employee(name="Grace (Sales1)", salary=95000.0);

    rt = Root();
    rt ++> ceo;
    ceo +>:ReportsTo:+> vp_eng;
    ceo +>:ReportsTo:+> vp_sales;
    vp_eng +>:ReportsTo:+> eng_lead;
    eng_lead +>:ReportsTo:+> eng1;
    eng_lead +>:ReportsTo:+> eng2;
    vp_sales +>:ReportsTo:+> sales1;
    return (rt, ceo, vp_eng, vp_sales, eng_lead, eng1, eng2, sales1);
}

test "CEO rollup aggregates entire org including all branches" {
    (rt, ceo, vp_eng, vp_sales, eng_lead, eng1, eng2, sales1) = build_sample_org();
    res = rt spawn PayrollAuditor();

    # Whole org: 7 employees total, sum of all salaries.
    expected_total = 250000.0 + 180000.0 + 170000.0 + 140000.0 + 120000.0 + 115000.0 + 95000.0;
    assert ceo.headcount == 7, f"CEO headcount should be 7, got {ceo.headcount}";
    assert ceo.subtree_payroll == expected_total, (
        f"CEO payroll should be {expected_total}, got {ceo.subtree_payroll}"
    );
    assert res.reports[-1].name == "Alice (CEO)", (
        f"last reported node should be CEO, got {res.reports[-1].name}"
    );
}

test "each manager's rollup includes their own salary" {
    (rt, ceo, vp_eng, vp_sales, eng_lead, eng1, eng2, sales1) = build_sample_org();
    rt spawn PayrollAuditor();

    # VP Eng subtree: self + lead + eng1 + eng2.
    assert vp_eng.headcount == 4, f"VP Eng headcount should be 4, got {vp_eng.headcount}";
    assert vp_eng.subtree_payroll == 180000.0 + 140000.0 + 120000.0 + 115000.0, (
        f"VP Eng payroll mismatch: got {vp_eng.subtree_payroll}"
    );

    # VP Sales subtree: self + sales1.
    assert vp_sales.headcount == 2, f"VP Sales headcount should be 2, got {vp_sales.headcount}";
    assert vp_sales.subtree_payroll == 170000.0 + 95000.0, (
        f"VP Sales payroll mismatch: got {vp_sales.subtree_payroll}"
    );

    # Eng Lead subtree: self + eng1 + eng2.
    assert eng_lead.headcount == 3, f"Eng Lead headcount should be 3, got {eng_lead.headcount}";
    assert eng_lead.subtree_payroll == 140000.0 + 120000.0 + 115000.0, (
        f"Eng Lead payroll mismatch: got {eng_lead.subtree_payroll}"
    );
}

test "leaf employees have headcount 1 and payroll equal to own salary" {
    (rt, ceo, vp_eng, vp_sales, eng_lead, eng1, eng2, sales1) = build_sample_org();
    rt spawn PayrollAuditor();

    assert eng1.headcount == 1, f"Eng1 headcount should be 1, got {eng1.headcount}";
