    }
    out = buf.getvalue();

    assert "18 min total" in out, f"expected total 5+10+3=18 min: {out}";
    assert "3 of 3 tasks" in out, f"expected 3 of 3 tasks: {out}";
    assert "1. a" in out, f"a should be first: {out}";
    assert "2. b" in out, f"b should be second: {out}";
    assert "3. c" in out, f"c should be third: {out}";
}

test "fan-out prereq shared by two dependents" {
    base = Task(name="base", duration=7);
    left = Task(name="left", duration=4);
    right = Task(name="right", duration=6);

    root ++> base;
    root ++> left;
    root ++> right;

    base +>: Needs() :+> left;
    base +>: Needs() :+> right;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Scheduler();
    }
    out = buf.getvalue();

    assert "3 of 3 tasks" in out, f"expected 3 of 3 tasks: {out}";
    assert "17 min total" in out, f"expected total 7+4+6=17 min: {out}";
    assert "1. base" in out, f"base must come first (shared prereq): {out}";

    idx_left = out.find("left");
    idx_right = out.find("right");
    idx_base = out.find("base");
    assert idx_base < idx_left, f"base must precede left: {out}";
    assert idx_base < idx_right, f"base must precede right: {out}";
}

