}

test "diamond dependency schedules all tasks exactly once" {
    top = Task(name="top", duration=5);
    left = Task(name="left", duration=5);
    right = Task(name="right", duration=5);
    bottom = Task(name="bottom", duration=5);

    root ++> top;
    root ++> left;
    root ++> right;
    root ++> bottom;

    top +>: Needs() :+> left;
    top +>: Needs() :+> right;
    left +>: Needs() :+> bottom;
    right +>: Needs() :+> bottom;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Scheduler();
    }
    out = buf.getvalue();

    assert "4 of 4 tasks" in out, f"all four tasks should be scheduled: {out}";
    assert "20 min total" in out, f"expected 4*5=20 min: {out}";
    assert "Dependency cycle" not in out, f"diamond is acyclic: {out}";

    # top must precede its descendants; bottom must follow them.
    idx_top = out.find("top");
    idx_left = out.find("left");
    idx_right = out.find("right");
    idx_bottom = out.find("bottom");
    assert idx_top < idx_left, f"top before left: {out}";
    assert idx_top < idx_right, f"top before right: {out}";
    assert idx_left < idx_bottom, f"left before bottom: {out}";
    assert idx_right < idx_bottom, f"right before bottom: {out}";
}

"""Test annex for AncestorCensus walker."""

import io;
import from contextlib { redirect_stdout }

# ---------- helpers ----------

def run_walker(child_nodes: list) {
    buf = io.StringIO();
    rt = root;
    for c in child_nodes {
        rt ++> c;
    }
    with redirect_stdout(buf) {
        res = rt spawn AncestorCensus();
    }
    return buf.getvalue();
}

# ---------- tests ----------

test "three generation family prints parents and grandparents labeled correctly" {
    # Replicate the canonical 3-gen family from the demo.
    grandpa1 = Person(name="Arthur", birth_year=1940);
    grandma1 = Person(name="Beatrice", birth_year=1942);
    grandpa2 = Person(name="Cyrus", birth_year=1938);
    grandma2 = Person(name="Delia", birth_year=1941);

    parent1 = Person(name="Ethan", birth_year=1970);
    parent2 = Person(name="Fiona", birth_year=1972);
    parent3 = Person(name="George", birth_year=1975);
    parent4 = Person(name="Hazel", birth_year=1977);

    child1 = Person(name="Iris", birth_year=2000);
    child2 = Person(name="Jules", birth_year=2002);

    parent1 +>:ChildOf(birth_order=1):+> grandpa1;
    parent1 +>:ChildOf(birth_order=2):+> grandma1;
    parent2 +>:ChildOf(birth_order=1):+> grandpa1;
    parent2 +>:ChildOf(birth_order=2):+> grandma2;
    parent3 +>:ChildOf(birth_order=1):+> grandpa2;
    parent3 +>:ChildOf(birth_order=2):+> grandma1;
    parent4 +>:ChildOf(birth_order=1):+> grandpa2;
    parent4 +>:ChildOf(birth_order=2):+> grandma2;

    child1 +>:ChildOf:+> parent1;
    child1 +>:ChildOf:+> parent2;
    child2 +>:ChildOf:+> parent3;
    child2 +>:ChildOf:+> parent4;

    out = run_walker([child1, child2]);

    assert "Ancestor generations:" in out, f"missing header: {out}";
    assert "  parents: " in out, f"missing parents label: {out}";
    assert "  grandparents: " in out, f"missing grandparents label: {out}";
    # Parents generation must contain all four parent names.
    assert "Ethan" in out, f"missing Ethan: {out}";
    assert "Fiona" in out, f"missing Fiona: {out}";
    assert "George" in out, f"missing George: {out}";
    assert "Hazel" in out, f"missing Hazel: {out}";
    # Grandparents generation must contain all four grandparent names.
    assert "Arthur" in out, f"missing Arthur: {out}";
    assert "Beatrice" in out, f"missing Beatrice: {out}";
    assert "Cyrus" in out, f"missing Cyrus: {out}";
    assert "Delia" in out, f"missing Delia: {out}";
}

test "parents generation appears before grandparents generation" {
    parent = Person(name="Ethan", birth_year=1970);
    grandparent = Person(name="Arthur", birth_year=1940);
    child = Person(name="Iris", birth_year=2000);

    parent +>:ChildOf:+> grandparent;
    child +>:ChildOf:+> parent;

    out = run_walker([child]);

    p_idx = out.find("  parents: ");
    g_idx = out.find("  grandparents: ");
    assert p_idx != -1, f"missing parents line: {out}";
    assert g_idx != -1, f"missing grandparents line: {out}";
    assert p_idx < g_idx, f"parents should print before grandparents: {out}";
