test "walker fields record exactly two generations of names" {
    grandparent = Person(name="Arthur", birth_year=1940);
    parent = Person(name="Ethan", birth_year=1970);
    child = Person(name="Iris", birth_year=2000);

    parent +>:ChildOf:+> grandparent;
    child +>:ChildOf:+> parent;

    rt = root;
    rt ++> child;
    res = rt spawn AncestorCensus();

    # Walker's `generations` field captures the per-gen name lists.
    gens = res.generations;
    assert len(gens) == 2, f"expected 2 generations, got {len(gens)}: {gens}";
    # First generation recorded = parents.
    assert "Ethan" in gens[0], f"parents gen missing Ethan: {gens[0]}";
    # Second generation recorded = grandparents.
    assert "Arthur" in gens[1], f"grandparents gen missing Arthur: {gens[1]}";
