test "child link direction is walked against toward ancestors" {
    # Confirm a child has ChildOf edges OUT to its parents (the link
    # direction the walker must walk against), and not vice versa.
    parent = Person(name="Ethan", birth_year=1970);
    grandparent = Person(name="Arthur", birth_year=1940);
    child = Person(name="Iris", birth_year=2000);

    parent +>:ChildOf:+> grandparent;
    child +>:ChildOf:+> parent;

    # child has outgoing ChildOf edges to its parent.
    child_parents = [child ->:ChildOf:->];
    assert len(child_parents) == 1, f"child should have 1 outgoing ChildOf: {len(child_parents)}";
    assert child_parents[0].name == "Ethan", f"wrong parent: {child_parents[0].name}";

    # Parent does NOT have outgoing ChildOf edges going downward to child.
    parent_kids = [parent ->:ChildOf:->];
    assert len(parent_kids) == 1, f"parent should only have one ChildOf (upward): {len(parent_kids)}";
    assert parent_kids[0].name == "Arthur", f"parent's ChildOf should point up to Arthur: {parent_kids[0].name}";
}

test "four generation family extends labeling to great-grandparents" {
    # Build 4 generations so the walker's labeling falls through to the
    # "great-grandparents (gen N)" branch.
    ggp1 = Person(name="Arthur", birth_year=1910);
    ggp2 = Person(name="Beatrice", birth_year=1912);
    gp1 = Person(name="Ethan", birth_year=1940);
    gp2 = Person(name="Fiona", birth_year=1942);
    p1 = Person(name="Iris", birth_year=1970);
    p2 = Person(name="Jules", birth_year=1972);
    c = Person(name="Kid", birth_year=2000);

    gp1 +>:ChildOf:+> ggp1;
    gp2 +>:ChildOf:+> ggp2;
    p1 +>:ChildOf:+> gp1;
    p2 +>:ChildOf:+> gp2;
    c +>:ChildOf:+> p1;
    c +>:ChildOf:+> p2;

    rt = root;
    rt ++> c;
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = rt spawn AncestorCensus();
    }
    out = buf.getvalue();

    assert "  parents: " in out, f"missing parents label: {out}";
    assert "  grandparents: " in out, f"missing grandparents label: {out}";
