}

"""Test annex for the checkout walker.

Each test builds its own cart from scratch and spawns Checkout() on it,
capturing stdout to verify the itemized receipt matches the expected
shipping rules per product subtype.
"""

import io;
import from contextlib { redirect_stdout }

def run_checkout(cart: Cart) -> str {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        cart spawn Checkout();
    }
    return buf.getvalue();
}

test "paper book charges per-unit shipping" {
    root ++> Cart(owner="A");
    cart = [root -->][?:Cart][0];
    cart +>: Contains(qty=3) :+> Book(
        sku="BK-1", unit_price=10.0,
        title="Old Tome", author="Anon", fmt="paper",
    );
    cart +>: Contains(qty=1) :+> Book(
        sku="BK-2", unit_price=10.0,
        title="Thin Pamphlet", author="Anon", fmt="paper",
    );
    out = run_checkout(cart);
    assert "Receipt for A:" in out, f"missing header: {out}";
    assert "Old Tome (paper) x3" in out, f"line1 desc missing: {out}";
    assert "Thin Pamphlet (paper) x1" in out, f"line2 desc missing: {out}";
    # paper shipping: 2.0 * qty summed = 2*3 + 2*1 = 8.0
    # subtotal: 30 + 10 = 40; total = 48
    assert "$    30.0" in out, f"line1 total missing: {out}";
    assert "$    10.0" in out, f"line2 total missing: {out}";
    assert "$    40.0" in out, f"subtotal missing: {out}";
    assert "$     8.0" in out, f"shipping should be 8.0 (2/qty), got: {out}";
    assert "$    48.0" in out, f"total missing: {out}";
}

test "digital book ships free" {
    root ++> Cart(owner="B");
    cart = [root -->][?:Cart][0];
    cart +>: Contains(qty=5) :+> Book(
        sku="BK-D1", unit_price=7.5,
        title="Ebook Bundle", author="M. Chen", fmt="digital",
    );
    out = run_checkout(cart);
    assert "Ebook Bundle (digital) x5" in out, f"missing digital line: {out}";
    # subtotal: 37.5; shipping: 0
    assert "$    37.5" in out, f"subtotal missing: {out}";
    assert "$     0.0" in out, f"digital should ship free: {out}";
    assert "$    37.5" in out, f"total equals subtotal: {out}";
}

test "electronics charges flat handling fee regardless of quantity" {
    root ++> Cart(owner="C");
    cart = [root -->][?:Cart][0];
    cart +>: Contains(qty=2) :+> Electronics(
        sku="EL-1", unit_price=200.0,
        model="Headset", warranty_years=2,
    );
    out = run_checkout(cart);
    assert "Headset (2yr warranty) x2" in out, f"missing electronics line: {out}";
    # subtotal: 400; shipping: flat 4.99 (not per-qty)
    assert "$   400.0" in out, f"subtotal missing: {out}";
    assert "$    4.99" in out, f"electronics handling fee should be 4.99: {out}";
    assert "$   404.99" in out, f"total missing: {out}";
}

test "clothing under threshold charges shipping, over threshold is free" {
    root ++> Cart(owner="D");
    cart = [root -->][?:Cart][0];
    # under threshold: 2 * 30 = 60 < 100 -> shipping 5.99
    cart +>: Contains(qty=2) :+> Clothing(
        sku="CL-1", unit_price=30.0,
        label="Tee", size="M",
    );
    # over threshold: 2 * 80 = 160 >= 100 -> shipping 0
    cart +>: Contains(qty=2) :+> Clothing(
        sku="CL-2", unit_price=80.0,
        label="Jacket", size="L",
    );
    out = run_checkout(cart);
    assert "Tee size M x2" in out, f"missing Tee line: {out}";
    assert "Jacket size L x2" in out, f"missing Jacket line: {out}";
    # subtotal: 60 + 160 = 220; shipping: 5.99
    assert "$   220.0" in out, f"subtotal missing: {out}";
    assert "$    5.99" in out, f"only under-threshold item should ship: {out}";
    assert "$   225.99" in out, f"total missing: {out}";
}

test "mixed cart subtotal matches sum of line totals" {
    root ++> Cart(owner="E");
    cart = [root -->][?:Cart][0];
    cart +>: Contains(qty=1) :+> Book(
        sku="BK-P", unit_price=20.0,
        title="Paperback", author="X", fmt="paper",
    );
    cart +>: Contains(qty=1) :+> Book(
        sku="BK-D", unit_price=5.0,
        title="Ebook", author="X", fmt="digital",
    );
    cart +>: Contains(qty=1) :+> Electronics(
        sku="EL-X", unit_price=50.0,
        model="Cable", warranty_years=1,
    );
    cart +>: Contains(qty=1) :+> Clothing(
        sku="CL-X", unit_price=200.0,
        label="Coat", size="XL",
    );
    out = run_checkout(cart);
    # subtotal: 20 + 5 + 50 + 200 = 275
    # shipping: 2 (paper) + 0 (digital) + 4.99 (electronics) + 0 (clothing>=100) = 6.99
    # total: 281.99
    assert "Receipt for E:" in out, f"missing header: {out}";
    assert "$   275.0" in out, f"subtotal should be 275: {out}";
    assert "$    6.99" in out, f"shipping should be 6.99: {out}";
    assert "$   281.99" in out, f"total should be 281.99: {out}";
    # owner name appears only in header, not on each line
    assert out.count("Receipt for E:") == 1, f"header printed once: {out}";
}

