test "checkout produces correct receipt for a mixed cart" {
    root ++> PaperBook(name="The Pragmatic Coder", price=29.95, weight_lb=1.4);
    root ++> DigitalBook(name="Functional Patterns (eBook)", price=19.99, file_size_mb=8.2);
