    root ++> Clothing(name="Crewneck Sweater", price=45.00, size="L");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        cashier = Checkout();
        res = root spawn cashier;
    }

    lines = res.lines;
    assert len(lines) == 4, f"expected 4 receipt lines, got {len(lines)}: {lines}";

    # Subtotal must equal the sum of all item prices.
    assert res.subtotal == 29.95 + 19.99 + 89.00 + 45.00, f"subtotal wrong: {res.subtotal}";

    # Per-product shipping rules (verified independently):
    #   PaperBook:    2.50 + 0.75 * 1.4 = 3.55
    #   DigitalBook:  0.00
    #   Electronics:  9.99
    #   Clothing:     4.99
    expected_shipping = (2.50 + 0.75 * 1.4) + 0.0 + 9.99 + 4.99;
    assert res.shipping == expected_shipping, f"shipping wrong: got {res.shipping}, expected {expected_shipping}";

    # Each item's handling note must match its concrete product type.
    paper_line    = [l for l in lines if "Pragmatic Coder" in l][0];
    digital_line  = [l for l in lines if "Functional Patterns" in l][0];
    elec_line     = [l for l in lines if "Wireless Earbuds" in l][0];
    clothing_line = [l for l in lines if "Crewneck Sweater" in l][0];

    assert "boxed" in paper_line, f"PaperBook handling_note missing: {paper_line}";
    assert "instant download" in digital_line, f"DigitalBook handling_note missing: {digital_line}";
    assert "insured" in elec_line and "adult signature" in elec_line, f"Electronics handling_note missing: {elec_line}";
    assert "polybagged" in clothing_line, f"Clothing handling_note missing: {clothing_line}";

    # Each receipt line must include its printed price.
    assert "$29.95" in paper_line, f"price not formatted on paper line: {paper_line}";
    assert "$19.99" in digital_line, f"price not formatted on digital line: {digital_line}";
    assert "$89.00" in elec_line, f"price not formatted on electronics line: {elec_line}";
    assert "$45.00" in clothing_line, f"price not formatted on clothing line: {clothing_line}";

    total = res.subtotal + res.shipping;
    assert total == 183.94 + expected_shipping, f"total wrong: {total}";
}

