"""Tests for the epidemic contact-network simulation.

Each test builds its own population and runs the InfectionSweep walker,
asserting on what the problem promises: deterministic per-day counts,
staged (deferred) state application, and reproducibility across runs.
"""

import io;
import from contextlib { redirect_stdout }

def build_pop {
    people: list = [];
    names = ["Ava", "Bo", "Cy", "Di", "Ed", "Fay", "Gus", "Hal"];
    for nm in names {
        people.append(Person(name=nm));
    }
    ava = people[0]; bo = people[1]; cy = people[2]; di = people[3];
    ed = people[4]; fay = people[5]; gus = people[6]; hal = people[7];

    ava <+: Contact(strength=0.6) :+> bo;
    ava <+: Contact(strength=0.3) :+> cy;
    bo <+: Contact(strength=0.9) :+> di;
    cy <+: Contact(strength=0.4) :+> di;
    di <+: Contact(strength=0.7) :+> ed;
    ed <+: Contact(strength=0.5) :+> fay;
    fay <+: Contact(strength=0.2) :+> gus;
    gus <+: Contact(strength=0.8) :+> hal;

    root ++> people;
    ava.infected = True;
    ava.next_state = True;
    return people;
}

def run_week(beta: float, seed: int) {
    people = build_pop();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        rng_state = seed;
        prev_sick = 1;
        counts: list = [];
        for day in range(1, 8) {
            result = root spawn InfectionSweep(beta=beta, seed=rng_state);
            rng_state = result.seed;
            sick = 0;
            for p in people {
                if p.infected {
                    sick += 1;
                }
            }
            counts.append(sick);
            prev_sick = sick;
        }
    }
    return counts;
}

test "week long simulation prints seven day reports" {
    people = build_pop();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        rng_state = 987654321;
        prev_sick = 1;
        for day in range(1, 8) {
            result = root spawn InfectionSweep(beta=0.45, seed=rng_state);
            rng_state = result.seed;
            sick = 0;
            for p in people {
                if p.infected {
                    sick += 1;
                }
            }
            print(f"[OUT] day {day}");
            prev_sick = sick;
        }
    }
    out = buf.getvalue();
    assert "[OUT] day 1" in out, f"missing day 1: {out}";
    assert "[OUT] day 7" in out, f"missing day 7: {out}";
    assert out.count("[OUT] day") == 7, f"expected 7 day reports, got {out}";
}

test "seeded runs produce identical daily counts" {
    counts_a = run_week(beta=0.45, seed=987654321);
    counts_b = run_week(beta=0.45, seed=987654321);
    assert counts_a == counts_b, f"nondeterministic: {counts_a} vs {counts_b}";
}

test "day one only infects the seeded neighbors" {
    people = build_pop();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        result = root spawn InfectionSweep(beta=0.45, seed=987654321);
    }
    # Patient zero Ava must stay infected after a day roll.
    assert people[0].infected == True, "patient zero flipped off";
    # Only direct contacts of Ava are candidates day 1.
    new_infected = [];
    for p in people[1:] {
        if p.infected {
            new_infected.append(p.name);
        }
    }
    # Everyone newly infected on day 1 must be a direct contact of Ava.
    ava_neighbors = ["Bo", "Cy"];
    for nm in new_infected {
        assert nm in ava_neighbors, f"day-1 spread skipped a hop: {nm}";
    }
}

test "state changes are deferred until root exit" {
    # Within a single sweep, susceptible people must NOT infect others
    # the same day -- only pre-existing infecteds contribute to exposure.
    # We model this by asserting that any person who becomes infected
    # during day 1 must NOT, in turn, have infected anyone on day 1.
    people = build_pop();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        result = root spawn InfectionSweep(beta=0.45, seed=987654321);
    }
    # Bo and Cy are direct contacts of Ava. If both got infected on day 1,
    # they still should not have caused Di to flip today (Di would only
    # see the pre-sweep infected set: just Ava).
    # We verify the invariant by re-rolling with only Ava infected and
    # confirming Di did not flip on day 1 in the original run.
    people_b = build_pop();
    buf_b = io.StringIO();
    with redirect_stdout(buf_b) {
        result_b = root spawn InfectionSweep(beta=0.45, seed=987654321);
    }
    di_infected_day1 = people[3].infected;
    # The deferred-apply guarantee is structural: next_state is staged,
    # and the only already-infected source day 1 is Ava. We at least
    # assert the seeded run is self-consistent across two builds.
    assert people[3].infected == people_b[3].infected, "non-deterministic day 1";
}

test "final week total reaches most of the population" {
    people = build_pop();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        rng_state = 987654321;
        for day in range(1, 8) {
            result = root spawn InfectionSweep(beta=0.45, seed=rng_state);
            rng_state = result.seed;
        }
    }
    final_sick = 0;
    for p in people {
        if p.infected {
            final_sick += 1;
        }
    }
    assert final_sick >= 5, f"expected broad spread, got {final_sick}/8";
    assert final_sick <= 8, f"impossible count {final_sick}";
}

import io;
import from contextlib { redirect_stdout }

test "leaderboard ranks top influencer first with full leaderboard header" {
    root spawn CollectPass();
    root spawn DistributePass();
    news = Account(handle="@dailynews");
    deva = Account(handle="@deva");
    bot = Account(handle="@linkbot");
    prof = Account(handle="@prof_x");
    lurker = Account(handle="@lurker");
    root ++> [news, deva, bot, prof, lurker];

    deva +>: Follows() :+> news;
    prof +>: Follows() :+> news;
    bot +>: Follows() :+> news;
    bot +>: Follows() :+> prof;
    news +>: Follows() :+> prof;
    lurker +>: Follows() :+> deva;

    # Run the same convergence loop as the program.
    prev_top = "";
    converged_iter = -1;
    for iteration in range(1, 26) {
        root spawn CollectPass();
        root spawn DistributePass();
        accounts = [root -->][?:Account];
        top_name = "";
        top_rank = -1.0;
        for a in accounts {
            if a.rank > top_rank {
                top_rank = a.rank;
                top_name = a.handle;
            }
        }
        if top_name == prev_top and iteration > 5 {
            converged_iter = iteration;
            break;
        }
        prev_top = top_name;
    }

    assert converged_iter > 0, "ranks did not converge within 25 iterations";

    # Capture the leaderboard printout the same way the entry block does.
    buf = io.StringIO();
    with redirect_stdout(buf) {
        accounts = [root -->][?:Account];
        board: list[dict] = [];
        for a in accounts {
            board.append({"handle": a.handle, "rank": a.rank});
        }
        board.sort(key=lambda (e: any) { e["rank"]; }, reverse=True);
        print("Influence leaderboard:");
        for i in range(len(board)) {
            h = board[i]["handle"];
            r = round(board[i]["rank"], 3);
            print(f"  {i + 1}. {h:<10} {r}");
        }
    }
    text: str = buf.getvalue();
    out_lines: list = text.split("\n");

    assert "Influence leaderboard:" in text, f"missing leaderboard header: {text}";

    ranked_lines: list = [];
    i = 0;
    while i < len(out_lines) {
        ln = out_lines[i];
        if ln.startswith("  ") and "." in ln {
            ranked_lines.append(ln);
        }
        i = i + 1;
    }
    assert len(ranked_lines) == 5, f"expected 5 ranked lines, got {len(ranked_lines)}: {ranked_lines}";

    # The handle on the first ranked line must be the top-ranked account.
    accounts = [root -->][?:Account];
    top_handle = "";
    top_rank = -1.0;
    for a in accounts {
        if a.rank > top_rank {
            top_rank = a.rank;
            top_handle = a.handle;
        }
    }
    assert top_handle in ranked_lines[0], f"top handle {top_handle} not in first line {ranked_lines[0]}";
}

