"""Tests for the maze solver: depth-first traversal from entrance to exit."""

import io;
import from contextlib { redirect_stdout }

test "solver finds entrance then exit on 3x3 grid" {
    c00 = Cell(row=0, col=0, is_entrance=True, label="(0,0) ENTRANCE");
    c01 = Cell(row=0, col=1, label="(0,1)");
    c02 = Cell(row=0, col=2, is_exit=True, label="(0,2) EXIT");
    c10 = Cell(row=1, col=0, label="(1,0)");
    c11 = Cell(row=1, col=1, label="(1,1)");
    c12 = Cell(row=1, col=2, label="(1,2)");
    c20 = Cell(row=2, col=0, label="(2,0)");
    c21 = Cell(row=2, col=1, label="(2,1)");
    c22 = Cell(row=2, col=2, label="(2,2)");

    root ++> c00;
    root ++> c01;
    root ++> c02;
    root ++> c10;
    root ++> c11;
    root ++> c12;
    root ++> c20;
    root ++> c21;
    root ++> c22;

    c00 +>:Open:+> c01;
    c00 +>:Open:+> c10;
    c01 +>:Open:+> c02;
    c01 +>:Open:+> c11;
    c10 +>:Open:+> c11;
    c11 +>:Open:+> c12;
    c11 +>:Open:+> c21;
    c12 +>:Open:+> c02;
    c20 +>:Open:+> c21;
    c21 +>:Open:+> c22;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = c00 spawn MazeSolver();
    }
    out = buf.getvalue();

    assert "Starting depth-first maze traversal from entrance to exit..." in out, f"missing start banner: {out}";
    assert "Reached exit at (0,2) EXIT!" in out, f"missing exit announcement: {out}";
    assert "Route taken:" in out, f"missing route header: {out}";
    assert "  -> (0,0) ENTRANCE" in out, f"entrance not first on route: {out}";
    assert "  -> (0,2) EXIT" in out, f"exit not on route: {out}";
    assert res.found, "walker should mark found after reaching exit";
    assert "(0,0) ENTRANCE" in res.path_taken, f"entrance missing from path_taken: {res.path_taken}";
    assert res.path_taken[0] == "(0,0) ENTRANCE", f"entrance must be first step, got {res.path_taken}";
    assert res.path_taken[-1] == "(0,2) EXIT", f"exit must be last step, got {res.path_taken}";
}

test "solver marks all visited cells along its traversed path" {
    c00 = Cell(row=0, col=0, is_entrance=True, label="(0,0)");
    c01 = Cell(row=0, col=1, label="(0,1)");
    c02 = Cell(row=0, col=2, is_exit=True, label="(0,2)");
    c10 = Cell(row=1, col=0, label="(1,0)");
    c11 = Cell(row=1, col=1, label="(1,1)");
    c12 = Cell(row=1, col=2, label="(1,2)");

    root ++> c00;
    root ++> c01;
    root ++> c02;
    root ++> c10;
    root ++> c11;
    root ++> c12;

    c00 +>:Open:+> c01;
    c00 +>:Open:+> c10;
    c01 +>:Open:+> c02;
    c01 +>:Open:+> c11;
    c10 +>:Open:+> c11;
    c11 +>:Open:+> c12;
    c12 +>:Open:+> c02;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = c00 spawn MazeSolver();
    }

    assert res.found, "solver should find the exit";
    for step in res.path_taken {
        assert step != "", f"path contained empty label, full path: {res.path_taken}";
    }
    assert len(res.path_taken) >= 2, f"path must include entrance and exit, got {res.path_taken}";
}

test "solver pushes deeper before backing up (depth-first)" {
    # Linear corridor: entrance -> A -> B -> C -> exit.
    # Depth-first should visit each in order; backing up only happens on dead-ends.
    entrance = Cell(row=0, col=0, is_entrance=True, label="entrance");
    a = Cell(row=0, col=1, label="a");
    b = Cell(row=0, col=2, label="b");
    c = Cell(row=1, col=0, label="c");
    exit_cell = Cell(row=1, col=1, is_exit=True, label="exit");

    root ++> entrance;
    root ++> a;
    root ++> b;
    root ++> c;
    root ++> exit_cell;

    entrance +>:Open:+> a;
    a +>:Open:+> b;
    b +>:Open:+> c;
    c +>:Open:+> exit_cell;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = entrance spawn MazeSolver();
    }
    out = buf.getvalue();

    assert res.found, "solver must reach the exit";
    assert res.path_taken == ["entrance", "a", "b", "c", "exit"], f"linear DFS path wrong: {res.path_taken}";
    assert "Reached exit at exit!" in out, f"exit announcement missing: {out}";
}

test "solver backs up when reaching dead end" {
    # Entrance -> branch: one path is a dead end, other reaches exit.
    # The solver takes the first neighbor; if dead-end, it pops that step and continues.
    entrance = Cell(row=0, col=0, is_entrance=True, label="entrance");
    dead = Cell(row=1, col=0, label="dead");
    mid = Cell(row=0, col=1, label="mid");
    exit_cell = Cell(row=0, col=2, is_exit=True, label="exit");

    root ++> entrance;
    root ++> dead;
    root ++> mid;
    root ++> exit_cell;

    entrance +>:Open:+> dead;
    entrance +>:Open:+> mid;
    mid +>:Open:+> exit_cell;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = entrance spawn MazeSolver();
    }
    out = buf.getvalue();

    assert res.found, "solver must find exit even after dead-end";
    assert "dead" not in res.path_taken, f"dead end must be popped from path, got: {res.path_taken}";
    assert res.path_taken == ["entrance", "mid", "exit"], f"expected entrance->mid->exit, got {res.path_taken}";
    assert "Reached exit at exit!" in out, f"exit not announced: {out}";
}

test "no exit reachable from entrance means found stays False" {
    # Entrance connected only to a dead end; no path to exit.
    entrance = Cell(row=0, col=0, is_entrance=True, label="entrance");
    dead = Cell(row=0, col=1, label="dead");
    isolated_exit = Cell(row=5, col=5, is_exit=True, label="far_exit");

    root ++> entrance;
    root ++> dead;
    root ++> isolated_exit;

    entrance +>:Open:+> dead;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = entrance spawn MazeSolver();
    }
    out = buf.getvalue();

    assert not res.found, f"solver should not mark found when exit unreachable, path: {res.path_taken}";
    assert "Reached exit at" not in out, f"should not announce exit, got: {out}";
}

