    buf = io.StringIO();
    with redirect_stdout(buf) {
        b = root +>: Boards() :+> Board(name="gamma");
        r1 = root spawn create_task(title="do thing", assignee="kim");
        r2 = root spawn create_task(title="other", assignee="raj");
