        done_rep = root spawn complete_task(task_id=task_id);
    }
    out = buf.getvalue();
    assert "[OUT]" in out, f"missing OUT marker: {out}";
    assert len(done_rep.reports) == 1, f"expected 1 report, got {len(done_rep.reports)}";
