test "board_stats aggregates totals, completion rate, per-assignee" {
    # Build a board, 4 tasks (3 assigned, 1 unassigned), 2 done, 1 deleted.
    # Expected: total=3, completed=2, open=1, rate=200/3*100, by_assignee
    # counts reflect the surviving 3 tasks.
    buf = io.StringIO();
    with redirect_stdout(buf) {
        b = root +>: Boards() :+> Board(name="epsilon");
        ids = [];
        for spec in [("a", "kim"), ("b", "kim"), ("c", ""), ("d", "raj")] {
            r = root spawn create_task(title=spec[0], assignee=spec[1]);
            ids.append(r.reports[0]["created"]);
        }
        root spawn complete_task(task_id=ids[0]);
        root spawn complete_task(task_id=ids[1]);
        root spawn delete_task(task_id=ids[3]);
        stats = root spawn board_stats();
    }
    out = buf.getvalue();
    assert "[OUT]" in out, f"missing OUT marker: {out}";
    assert "[OUT]stats:" in out, f"no stats print: {out}";
    assert len(stats.reports) == 1, f"expected 1 stats report, got {len(stats.reports)}";
    s = stats.reports[0];
    # Totals reflect survivors only (3 remain after the delete).
    assert s["total"] == 3, f"total should be 3, got {s['total']}";
    assert s["completed"] == 2, f"completed should be 2, got {s['completed']}";
    assert s["open"] == 1, f"open should be 1, got {s['open']}";
    # completion_rate is a percentage (float); 2/3 * 100.
    expected_rate = 2 / 3 * 100;
    assert abs(s["completion_rate"] - expected_rate) < 1e-9, f"rate: {s['completion_rate']}";
    # kim has both of the done tasks; unassigned bucket owns task c.
    ba = s["by_assignee"];
    assert ba.get("kim") == 2, f"kim count: {ba}";
    assert ba.get("unassigned") == 1, f"unassigned count: {ba}";
    assert "raj" not in ba, f"raj should be absent (deleted): {ba}";
}

