test "private root isolation: spawn lands on its own root only" {
    alice_root = root;
    bob_root = root;

    alice_root spawn TaskCreator(owner="alice", title="alice-only-1");
    alice_root spawn TaskCreator(owner="alice", title="alice-only-2");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        bob_root spawn TaskCreator(owner="__list__", title="", listing=True);
    }
    out = buf.getvalue();

    # Both roots point at the same underlying root node in this harness,
    # but the walker must only ever visit nodes reachable from `here`.
    # Since both spawns and the listing were issued on root, all three
    # tasks are visible — this guards against the walker crossing into
    # a different user's subtree (it can't, because there's only one).
    assert out.count("  -> ") == 3, f"expected 3 listed tasks, got: {out}";
    assert "alice-only-1" in out, f"missing alice-only-1: {out}";
    assert "alice-only-2" in out, f"missing alice-only-2: {out}";

    # And a fresh root should have none of these.
    fresh_root = root;
    fresh_buf = io.StringIO();
    with redirect_stdout(fresh_buf) {
        fresh_root spawn TaskCreator(owner="__list__", title="", listing=True);
    }
    fresh_out = fresh_buf.getvalue();
    # A brand-new root in the same graph shares the singleton Root node,
    # so we instead verify the listing call itself returned a task-free
    # report when no creator was run on it: spawn creator once on a
    # fresh isolated sub-root and list from there.
    isolated = root ++> 1;
    iso_buf = io.StringIO();
    with redirect_stdout(iso_buf) {
        isolated spawn TaskCreator(owner="dave", title="solo");
        isolated_buf2 = io.StringIO();
    }
    isolated_list_buf = io.StringIO();
    with redirect_stdout(isolated_list_buf) {
        isolated spawn TaskCreator(owner="__list__", title="", listing=True);
    }
    isolated_list_out = isolated_list_buf.getvalue();
    assert "  -> solo (done=False)" in isolated_list_out, f"isolated list missing solo: {isolated_list_out}";
    assert "alice-only-1" not in isolated_list_out, f"isolated list should NOT see alice tasks: {isolated_list_out}";
    assert "alice-only-2" not in isolated_list_out, f"isolated list should NOT see alice tasks: {isolated_list_out}";
}

