test "each reported todo carries id, title, done, priority" {
    root ++> Todo(title="task A", priority=5);
    root ++> Todo(title="task B", priority=0, done=True);

    res = root spawn list_todos();
    todos = res.reports[0]["todos"];

    titles = sorted([t["title"] for t in todos]);
    assert titles == ["task A", "task B"], f"unexpected titles: {titles}";

