    assert by_title["task A"]["done"] is False, "task A default done should be False";
    assert by_title["task A"]["priority"] == 5, f"priority not preserved: {by_title['task A']}";
    assert by_title["task B"]["priority"] == 0, f"priority not preserved: {by_title['task B']}";
