import io;
import from contextlib { redirect_stdout }

test "dump reports project and its tasks" {
    root ++> Project(name="alpha") +>: Contains() :+> Task(title="a1");
    root ++> Project(name="alpha") +>: Contains() :+> Task(title="a2");
    root ++> Project(name="beta") +>: Contains() :+> Task(title="b1");

    res = root spawn dump();
    assert len(res.reports) == 2, f"expected 2 projects, got {len(res.reports)}";

    by_name = {r["project"]: r["tasks"] for r in res.reports};
    assert "alpha" in by_name, "alpha missing from dump";
    assert "beta" in by_name, "beta missing from dump";
    assert sorted(by_name["alpha"]) == ["a1", "a2"], f"alpha tasks wrong: {by_name['alpha']}";
    assert by_name["beta"] == ["b1"], f"beta tasks wrong: {by_name['beta']}";
}

test "delete_project cascades to all child tasks" {
    proj = root ++> Project(name="spring cleaning");
    proj +>: Contains() :+> Task(title="garage");
    proj +>: Contains() :+> Task(title="gutters");

    res = root spawn delete_project(project_id=jid(proj));
    payload = res.reports[0];

    assert payload["cascade_deleted"] == 3, f"expected 3 removals (1 project + 2 tasks), got {payload['cascade_deleted']}";
    assert jid(proj) in payload["ids"], "project id missing from report";
    assert len([root -->]) == 0, f"root should have no project children left, got {len([root -->])}";

    after = root spawn dump();
    assert len(after.reports) == 0, f"dump after delete should be empty, got {after.reports}";
}

test "delete_project only removes the matched project" {
    keep = root ++> Project(name="keep me");
    keep +>: Contains() :+> Task(title="do not touch");

    doomed = root ++> Project(name="doomed");
    doomed +>: Contains() :+> Task(title="t1");
    doomed +>: Contains() :+> Task(title="t2");

    res = root spawn delete_project(project_id=jid(doomed));
    payload = res.reports[0];

    assert payload["cascade_deleted"] == 3, f"expected 3 removals, got {payload['cascade_deleted']}";
    assert len([root -->]) == 1, f"keep me should remain, got {len([root -->])}";

    after = root spawn dump();
    assert len(after.reports) == 1, f"exactly one project should remain, got {len(after.reports)}";
    assert after.reports[0]["project"] == "keep me", f"wrong survivor: {after.reports[0]}";
    assert after.reports[0]["tasks"] == ["do not touch"], f"survivor tasks wrong: {after.reports[0]}";
}

test "delete_project with unknown id is a no-op" {
    p = root ++> Project(name="lonely");
    p +>: Contains() :+> Task(title="only task");

    res = root spawn delete_project(project_id="nope-not-a-real-jid");
    payload = res.reports[0];

    assert payload["cascade_deleted"] == 0, f"unknown id should delete nothing, got {payload['cascade_deleted']}";
    assert len([root -->]) == 1, f"project should still exist, got {len([root -->])}";

    after = root spawn dump();
    assert len(after.reports) == 1, f"project should still be dumpable, got {after.reports}";
    assert after.reports[0]["project"] == "lonely";
    assert after.reports[0]["tasks"] == ["only task"];
}

test "add_project then delete reproduces the board before/after demo" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        r = root spawn add_project(name="spring cleaning", tasks=["garage", "gutters"]);
        pid = r.reports[0]["project"];
        root spawn add_project(name="keep me", tasks=["do not touch"]);

        before = root spawn dump();
        print("before:", before.reports);

        root spawn delete_project(project_id=pid);

        after = root spawn dump();
        print("after :", after.reports);
    }
    out = buf.getvalue();

    assert "[OUT]" not in out, f"no OUT marker should appear (program uses report, not print): {out}";
    assert "before:" in out, f"missing before line: {out}";
    assert "after :" in out, f"missing after line: {out}";

    before_section = out.split("after :")[0];
    after_section = out.split("after :")[1];

    assert "spring cleaning" in before_section, f"spring cleaning missing before: {before_section}";
    assert "keep me" in before_section, f"keep me missing before: {before_section}";
    assert "garage" in before_section and "gutters" in before_section, f"tasks missing before: {before_section}";
    assert "do not touch" in before_section, f"survivor task missing before: {before_section}";

    assert "spring cleaning" not in after_section, f"spring cleaning should be gone after: {after_section}";
    assert "garage" not in after_section and "gutters" not in after_section, f"orphan tasks should be gone after: {after_section}";
    assert "keep me" in after_section, f"keep me should survive: {after_section}";
    assert "do not touch" in after_section, f"survivor task should remain: {after_section}";
}

"""Test annex for event guestbook: SignGuest/ReadGuest walker semantics."""

import io;
import from contextlib { redirect_stdout }

test "sign adds an Entry edge from root and reports it" {
    root ++> Entry(name="Ada", message="Hi", year=2024);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn SignGuest(name="Bob", message="Welcome", year=2024);
    }
    out = buf.getvalue();

    assert "[OUT]" in out, f"missing OUT marker: {out}";
    assert len([root-->]) == 2, f"expected 2 children on root, got {len([root-->])}";

    kids = [root-->];
    signed = None;
    for k in kids {
        if k.name == "Bob" {
            signed = k;
        }
    }
    assert signed is not None, "signed Entry not found among root's children";
    assert signed.name == "Bob", f"expected name 'Bob', got '{signed.name}'";
    assert signed.message == "Welcome", f"expected message 'Welcome', got '{signed.message}'";
    assert signed.year == 2024, f"expected year 2024, got {signed.year}";
}

test "sign creates exactly one entry per spawn" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn SignGuest(name="X", message="one", year=2020);
        root spawn SignGuest(name="Y", message="two", year=2021);
        root spawn SignGuest(name="Z", message="three", year=2022);
    }
    out = buf.getvalue();

    assert len([root-->]) == 3, f"expected 3 children, got {len([root-->])}";
    assert out.count("[OUT]") == 3, f"expected 3 OUT markers, got {out.count('[OUT]')}";

    seen_names = [];
    for k in [root-->] {
        seen_names.append(k.name);
    }
    assert "X" in seen_names, f"X missing from {seen_names}";
    assert "Y" in seen_names, f"Y missing from {seen_names}";
    assert "Z" in seen_names, f"Z missing from {seen_names}";
}

test "read with limit greater than total returns all entries" {
    root ++> Entry(name="A", message="a", year=2024)
        ++> Entry(name="B", message="b", year=2024)
        ++> Entry(name="C", message="c", year=2024);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ReadGuest(limit=10);
    }
    out = buf.getvalue();

    assert "[OUT]" in out, f"missing OUT marker: {out}";
    assert len(res.reports) == 1, f"expected 1 report, got {len(res.reports)}";
    feed = res.reports[0];
    assert len(feed) == 3, f"expected 3 entries in feed, got {len(feed)}";
}

test "read with smaller limit truncates to tail entries" {
    root ++> Entry(name="A", message="a", year=2024)
        ++> Entry(name="B", message="b", year=2024)
        ++> Entry(name="C", message="c", year=2024)
        ++> Entry(name="D", message="d", year=2024);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ReadGuest(limit=2);
    }
    out = buf.getvalue();

    assert "[OUT]" in out, f"missing OUT marker: {out}";
    feed = res.reports[0];
    assert len(feed) == 2, f"expected 2 entries after truncation, got {len(feed)}";
    names = [];
    for e in feed {
        names.append(e.name);
    }
    assert "C" in names, f"expected 'C' in tail, got {names}";
    assert "D" in names, f"expected 'D' in tail, got {names}";
}

test "read on empty guestbook reports empty feed" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ReadGuest(limit=3);
    }
    out = buf.getvalue();

    assert "[OUT]" in out, f"missing OUT marker: {out}";
    assert len([root-->]) == 0, f"expected no children on root, got {len([root-->])}";
    assert len(res.reports) == 1, f"expected 1 report, got {len(res.reports)}";
    feed = res.reports[0];
    assert len(feed) == 0, f"expected empty feed, got {len(feed)}";
}

