"""Test annex for the guestbook walker program."""

import io;
import from contextlib { redirect_stdout }


test "SignGuest reports entry fields and visits children" {
    root ++> GuestbookEntry(author="Ada", message="Loved the keynote!", signed_at="2025-04-01T10:00")
        ++> GuestbookEntry(author="Lin", message="Great turnout this year.", signed_at="2025-04-01T10:15")
        ++> GuestbookEntry(author="Mo", message="See you next spring.", signed_at="2025-04-01T10:30");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn SignGuest(
            author="Kai",
            message="First sign via walker.",
            signed_at="2025-04-01T11:00"
        );
    }

    out = buf.getvalue();
    assert "Guestbook ready for a new signature." in out, f"missing greet banner: {out}";

    assert len(res.reports) == 3, f"expected 3 reports, got {len(res.reports)}";

    first = res.reports[0];
    assert first["author"] == "Ada", f"first author wrong: {first}";
    assert first["message"] == "Loved the keynote!", f"first message wrong: {first}";
    assert first["signed_at"] == "2025-04-01T10:00", f"first signed_at wrong: {first}";

    third = res.reports[2];
    assert third["author"] == "Mo", f"third author wrong: {third}";
