test "SignGuest walker has the same three fields exposed as GuestbookEntry" {
    fields_on_entry = {"author", "message", "signed_at"};
    fields_on_walker = {"author", "message", "signed_at"};

    assert fields_on_entry == fields_on_walker, "SignGuest must mirror GuestbookEntry fields for jac start body mapping";

    root ++> GuestbookEntry(author="Ada", message="Loved the keynote!", signed_at="2025-04-01T10:00")
        ++> GuestbookEntry(author="Lin", message="Great turnout this year.", signed_at="2025-04-01T10:15")
        ++> GuestbookEntry(author="Mo", message="See you next spring.", signed_at="2025-04-01T10:30");

    buf = io.StringIO();
