        res = root spawn SignGuest(
            author="Kai",
            message="First sign via walker.",
            signed_at="2025-04-01T11:00"
        );
    }

    keys_per_report = [tuple(sorted(r.keys())) for r in res.reports];
    expected = tuple(sorted(["author", "message", "signed_at"]));
