"""Test annex for the reader half of the micro-blog."""

import io;
import from contextlib { redirect_stdout }

node Post {
    has text: str;
    has author: str;
}

edge Posted { }

walker:pub publish_post {
    has text: str;
    has author: str = "anon";

    can run with Root entry {
        fresh = root.shared +>: Posted() :+> Post(text=self.text, author=self.author);
        grant(fresh, level=AccessLevel.READ);
    }
}

walker:pub read_feed {
    can run with Root entry {
        # Traversal from the shared commons; order follows creation order.
        posts = [p for p in [root.shared ->:Posted:->][?:Post]];
        report [{"author": p.author, "text": p.text} for p in posts];
    }
}

test "read_feed returns posts in creation order with author and text" {
    buf = io.StringIO();
    root spawn publish_post(text="first!", author="ada");
    root spawn publish_post(text="second post", author="ben");
    root spawn publish_post(text="a quiet third", author="cy");

    with redirect_stdout(buf) {
        result = root spawn read_feed();
    }
    out = buf.getvalue();

    first = result.reports[0];
    second = result.reports[1];
    third = result.reports[2];

    assert first["author"] == "ada", f"first author wrong: {first}";
    assert first["text"] == "first!", f"first text wrong: {first}";
    assert second["author"] == "ben", f"second author wrong: {second}";
    assert second["text"] == "second post", f"second text wrong: {second}";
    assert third["author"] == "cy", f"third author wrong: {third}";
    assert third["text"] == "a quiet third", f"third text wrong: {third}";

    # Creation order must be preserved.
    order = [r["author"] for r in result.reports];
    assert order == ["ada", "ben", "cy"], f"wrong order: {order}";
}

test "read_feed on empty shared commons returns empty reports" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        result = root spawn read_feed();
    }
    assert len(result.reports) == 0, f"expected no reports, got {result.reports}";
}

test "read_feed works for anonymous callers without any auth step" {
    # The problem states listing posts needs no auth. We simply spawn the
    # walker directly on root, with no prior permission grants.
    buf = io.StringIO();
    root spawn publish_post(text="hello world", author="dora");

    with redirect_stdout(buf) {
        result = root spawn read_feed();
    }
    out = buf.getvalue();

    assert len(result.reports) == 1, f"expected 1 report, got {result.reports}";
    assert result.reports[0]["author"] == "dora", f"author wrong: {result.reports[0]}";
    assert result.reports[0]["text"] == "hello world", f"text wrong: {result.reports[0]}";
}

test "publish_post defaults author to anon when omitted" {
    buf = io.StringIO();
    root spawn publish_post(text="anon hello");

    with redirect_stdout(buf) {
        result = root spawn read_feed();
    }
    out = buf.getvalue();

    assert len(result.reports) == 1, f"expected 1 report, got {result.reports}";
    assert result.reports[0]["author"] == "anon", f"default author wrong: {result.reports[0]}";
    assert result.reports[0]["text"] == "anon hello", f"text wrong: {result.reports[0]}";
}

test "posts live on the shared subgraph via Posted edges" {
    # The problem says the feed walks the SHARED public graph, not the
    # caller's private root. publish_post links under root.shared via
    # Posted edges, so read_feed must discover exactly those.
    root spawn publish_post(text="shared one", author="erin");
    root spawn publish_post(text="shared two", author="fran");

    # The shared node should have two Post children reachable via Posted.
    reachable = [root.shared ->:Posted:->][?:Post];
    assert len(reachable) == 2, f"shared graph wrong, got {[n.text for n in reachable]}";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        result = root spawn read_feed();
    }
    out = buf.getvalue();

    texts = [r["text"] for r in result.reports];
    assert texts == ["shared one", "shared two"], f"feed order wrong: {texts}";
}

"""Test annex for the micro-blog reader."""

import io;
