"""Test annex for Task dashboard walker."""

import io;
import from contextlib { redirect_stdout }


def make_root {
    r = root;
    r ++> Task(title="Wire up auth", done=True, points=5, planned_points=5)
       ++> Task(title="Build dashboard", done=True, points=8, planned_points=8)
       ++> Task(title="Write docs", done=False, points=0, planned_points=3)
       ++> Task(title="Polish UI", done=False, points=0, planned_points=2);
    return r;
}


def make_mixed_root {
    r = root;
    r ++> Task(title="Backfill data", done=True, points=13, planned_points=21)
       ++> Task(title="Write tests", done=False, points=0, planned_points=8)
       ++> Task(title="Code review", done=False, points=0, planned_points=2);
    return r;
}


test "dashboard reports counts and rates for mixed completion" {
    rt = make_root();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        rt spawn Dashboard();
    }
    out = buf.getvalue();

    assert "\"total\": 4" in out, f"missing total=4: {out}";
    assert "\"completed\": 2" in out, f"missing completed=2: {out}";
    assert "\"pending\": 2" in out, f"missing pending=2: {out}";
    assert "\"completion_rate\": 0.5" in out, f"expected rate 0.5: {out}";
    assert "\"points_burned\": 13" in out, f"burned should sum completed points (5+8): {out}";
    assert "\"points_planned\": 18" in out, f"planned should sum all planned (5+8+3+2): {out}";
}


test "pending task contributes planned but not burned" {
