}

test "auditor guards division by zero for empty account" {
    root ++> Account(name="newco");

    a = Auditor();
    root spawn a;
    r = a.report;
    assert r["account"] == "newco", f"account wrong: {r['account']}";
    assert r["total"] == 0, f"total should be 0, got {r['total']}";
    assert r["completed"] == 0, f"completed should be 0, got {r['completed']}";
    assert r["pending"] == 0, f"pending should be 0, got {r['pending']}";
    # Fail-closed / no-crash: rate must be a usable number, not blow up.
    assert r["completion_rate"] == 0, f"rate must default to 0 when total=0, got {r['completion_rate']}";
    assert r["story_points_burned"] == 0, f"burned should be 0, got {r['story_points_burned']}";
    assert r["story_points_planned"] == 0, f"planned should be 0, got {r['story_points_planned']}";
}

test "auditor reports single pending task" {
    root ++> Account(name="solo") ++>
        Task(title="only one", completed=False, story_points=7);

    a = Auditor();
    root spawn a;
    r = a.report;
    assert r["total"] == 1, f"total should be 1, got {r['total']}";
    assert r["completed"] == 0, f"completed should be 0, got {r['completed']}";
    assert r["pending"] == 1, f"pending should be 1, got {r['pending']}";
    assert r["completion_rate"] == 0, f"rate should be 0, got {r['completion_rate']}";
    assert r["story_points_burned"] == 0, f"burned should be 0, got {r['story_points_burned']}";
    assert r["story_points_planned"] == 7, f"planned should be 7, got {r['story_points_planned']}";
}

test "auditor only counts tasks under its target account" {
    root ++> Account(name="target") ++>
        Task(title="t1", completed=True, story_points=4) ++>
        Task(title="t2", completed=False, story_points=6);
    # A sibling account on the same root must NOT be counted.
    root ++> Account(name="other") ++>
        Task(title="ignore me", completed=True, story_points=100) ++>
        Task(title="ignore me too", completed=False, story_points=200);

    a = Auditor();
    root spawn a;
    r = a.report;
    assert r["account"] == "target", f"wrong account reported: {r['account']}";
    assert r["total"] == 2, f"total should be 2 (only target's tasks), got {r['total']}";
    assert r["completed"] == 1, f"completed should be 1, got {r['completed']}";
    assert r["pending"] == 1, f"pending should be 1, got {r['pending']}";
    assert r["story_points_burned"] == 4, f"burned should be 4, got {r['story_points_burned']}";
    assert r["story_points_planned"] == 6, f"planned should be 6, got {r['story_points_planned']}";
}
